    fn apply_classic_command_line(&mut self, classic: &ClassicCommandLine) -> Result<()> {
        self.classic_command_line = classic.clone();
        self.classic_record_stream_activation_pending = false;
        self.initial_definition_seed = Some(classic_command_line_definition_modules(
            &load_native_config_bytes(self.app_paths.as_ref()),
            &classic.definition_files,
        ));
        if !classic.player_files.is_empty() {
            self.configured_client_player_selection = self
                .app_paths
                .as_ref()
                .map(|paths| snapshot_effective_client_player_selection(paths, classic))
                .transpose()?;
        }
        self.apply_classic_game_option_overrides();
        self.auto_open_update_dialog =
            classic.update_requested || classic.incoming_update.is_some();

        if let Some(screen) = classic.startup_screen.as_deref() {
            tracing::warn!(
                screen,
                "classic /startup screen selection is not implemented in clonk-app"
            );
        }
        Ok(())
    }

    fn console_lobby_active(&self) -> bool {
        self.league_player_auth_lobby_active()
    }

    fn console_game_initialization_active(&self) -> bool {
        self.loading_state.is_some()
            || self.auto_start_classic_command_line_scenario
            || self.classic_direct_reference_query.is_some()
            || self.startup_network_connection.is_some()
            || self.pending_network_join.is_some()
            || self.staged_network_host_scenario.is_some()
            || self.lobby_preload_task.is_some()
            || self.lobby_preload_artifact.is_some()
            || self.network_start_wait.is_some()
            || self.pending_network_join_data.is_some()
            || self.pending_client_start_status.is_some()
    }

    fn console_game_active(&self) -> bool {
        self.mode == AppMode::Running
            || self.console_lobby_active()
            || self.console_game_initialization_active()
            || (self.boot_loading.is_none()
                && (self.network.is_some()
                    || self.network_mode.is_some()
                    || self.network_lobby.is_some()
                    || self.classic_host_lobby.is_some()))
    }

    fn console_startup_active(&self) -> bool {
        matches!(self.mode, AppMode::Menu | AppMode::Loading) && !self.console_game_active()
    }

    fn close_console_game(&mut self) {
        let boot_still_loading = self.boot_loading.is_some();
        let network_game_active = self.network.is_some()
            || self.network_mode.is_some()
            || self.network_lobby.is_some()
            || self.classic_host_lobby.is_some()
            || self.startup_network_connection.is_some()
            || self.classic_direct_reference_query.is_some()
            || self.pending_network_join.is_some()
            || self.staged_network_host_scenario.is_some()
            || self.lobby_preload_task.is_some()
            || self.lobby_preload_artifact.is_some()
            || self.network_start_wait.is_some()
            || self.pending_network_join_data.is_some()
            || self.pending_client_start_status.is_some();
        self.auto_start_sandbox = false;
        self.auto_start_classic_command_line_scenario = false;
        self.classic_direct_reference_query = None;
        if network_game_active {
            // `show_main_menu` owns the complete native network teardown for
            // a lobby. Async console startup can be between lobby views, so
            // select that teardown path before clearing the round.
            self.startup_view = StartupView::NetworkLobby;
        }
        self.return_to_menu();
        if boot_still_loading {
            self.mode = AppMode::Loading;
        }
    }

    fn configured_console_lobby_countdown(&self) -> i32 {
        self.staged_network_host_scenario
            .as_ref()
            .map(|staged| staged.lobby.countdown_seconds)
            .or_else(|| {
                native_config_text(
                    &load_native_config_bytes(self.app_paths.as_ref()),
                    "Lobby",
                    "CountdownTime",
                )
                .and_then(|value| value.trim().parse::<i32>().ok())
            })
            .unwrap_or(DEFAULT_LOBBY_COUNTDOWN_SECONDS)
    }

    fn process_console_lobby_start(&mut self, line: &str) -> Result<()> {
        if !matches!(self.network_mode, Some(NetworkMode::Host(_))) {
            let message = self.classic_lobby_resource_text("IDS_MSG_CMD_HOSTONLY", "Host only!");
            tracing::warn!(%message, command = line, "console lobby command rejected");
            self.append_lobby_command_log(message);
            return Ok(());
        }

        let countdown_seconds = match line.find(' ') {
            None => self.configured_console_lobby_countdown(),
            Some(space) => {
                let parameter = line[space..].trim_start_matches(' ');
                match legacy_sscanf_decimal_prefix(&clonk_script::c4_string_bytes(parameter))
                    .filter(|seconds| *seconds >= 0)
                {
                    Some(seconds) => seconds,
                    None => {
                        let message = self.classic_lobby_resource_text(
                            "IDS_MSG_CMD_START_USAGE",
                            "Usage: /start [timer]",
                        );
                        tracing::warn!(%message, command = line, "console lobby command rejected");
                        self.append_lobby_command_log(message);
                        return Ok(());
                    }
                }
            }
        };

        // C4Network2::StartLobbyCountdown replaces an existing timer.
        self.abort_network_lobby_countdown();
        self.start_console_lobby_countdown_with(countdown_seconds)?;
        Ok(())
    }

    fn developer_console_editing(&self) -> bool {
        self.console_mode && self.developer_console_editing_enabled
    }

    fn developer_console_strings(&self) -> ConsoleStrings {
        let mut strings = ConsoleStrings::default();
        for (target, key, fallback) in [
            (&mut strings.default_caption, "IDS_CNS_CONSOLE", "Console"),
            (&mut strings.menu_file, "IDS_MNU_FILE", "File"),
            (
                &mut strings.menu_components,
                "IDS_MNU_COMPONENTS",
                "Components",
            ),
            (&mut strings.menu_player, "IDS_MNU_PLAYER", "Player"),
            (&mut strings.menu_viewport, "IDS_MNU_VIEWPORT", "Viewport"),
            (&mut strings.menu_net, "IDS_MNU_NET", "Host"),
            (&mut strings.file_open, "IDS_MNU_OPEN", "Open..."),
            (
                &mut strings.file_open_with_players,
                "IDS_MNU_OPENWPLRS",
                "Open with players...",
            ),
            (
                &mut strings.file_save_scenario,
                "IDS_MNU_SAVESCENARIO",
                "Save scenario",
            ),
            (
                &mut strings.file_save_scenario_as,
                "IDS_MNU_SAVESCENARIOAS",
                "Save scenario as...",
            ),
            (&mut strings.file_save_game, "IDS_MNU_SAVEGAME", "Save game"),
            (
                &mut strings.file_save_game_as,
                "IDS_MNU_SAVEGAMEAS",
                "Save game as...",
            ),
            (&mut strings.file_record, "IDS_MNU_RECORD", "Record"),
            (&mut strings.file_close, "IDS_MNU_CLOSE", "Close"),
            (&mut strings.file_quit, "IDS_MNU_QUIT", "Quit"),
            (&mut strings.component_objects, "IDS_BTN_OBJECTS", "Objects"),
            (&mut strings.component_script, "IDS_MNU_SCRIPT", "Script"),
            (&mut strings.component_title, "IDS_MNU_TITLE", "Title"),
            (&mut strings.component_info, "IDS_MNU_INFO", "Info"),
            (&mut strings.player_join, "IDS_MNU_JOIN", "Join"),
            (&mut strings.viewport_new, "IDS_MNU_NEW", "New"),
            (&mut strings.help_about, "IDS_MENU_ABOUT", "About..."),
        ] {
            *target = self.runtime_resource_text(key, fallback);
        }
        strings
    }

    fn developer_console_view_model(&self) -> ConsoleViewModel {
        let strings = self.developer_console_strings();
        // Native C4Console sets fGameOpen only after Game.Init returns. Keep
        // save/close/component controls disabled throughout Rust's async load.
        let game_open = self.mode == AppMode::Running;
        let network_enabled = self.network.is_some();
        let network_host =
            network_enabled && matches!(self.network_mode, Some(NetworkMode::Host(_)));
        let editing = self.developer_console_editing();
        let players = self.developer_console_player_menu_entries(editing);
        let clients = self.developer_console_net_menu_entries();
        let completions = developer_console_completion_entries(
            &self.engine.console_script_completion_catalog(),
            DeveloperConsoleCompletionStyle::Gtk,
        )
        .into_iter()
        .filter_map(|entry| match entry {
            DeveloperConsoleCompletionEntry::Function(function) => Some(function),
            DeveloperConsoleCompletionEntry::Separator => None,
        })
        .collect();
        let current_scenario_path = self
            .active_scenario
            .as_ref()
            .and_then(|scenario| scenario.path.clone())
            .or_else(|| {
                self.loading_state
                    .as_ref()
                    .and_then(|loading| loading.scenario.path.clone())
            });
        let caption = current_scenario_path
            .as_deref()
            .and_then(Path::file_name)
            .map(|name| name.to_string_lossy().into_owned())
            .unwrap_or_else(|| strings.default_caption.clone());
        ConsoleViewModel {
            strings,
            caption,
            current_scenario_path,
            game_open,
            lobby_active: self.console_lobby_active(),
            editing,
            halted: !matches!(self.mode, AppMode::Running)
                || if self.network.is_some() {
                    self.runtime_network_is_paused()
                } else {
                    self.runtime_halt_active()
                },
            runtime_record_possible: self.developer_console_runtime_record_possible(),
            network_enabled,
            network_host,
            players,
            clients,
            completions,
            edit_mode: self.developer_console_edit_mode,
            cursor_text: self.status_text.clone(),
            frame: self.engine.frame(),
            script_counter: self.engine.scenario_script_counter(),
            time_seconds: self.engine.game_time(),
            frames_per_second: self.frames_per_second,
        }
    }

    fn sync_developer_console_view(&mut self) -> bool {
        if !self.console_mode {
            return false;
        }
        if self.control_playback.is_some() {
            self.developer_console_editing_enabled = false;
        }
        let view = self.developer_console_view_model();
        self.developer_console.set_view_model(view)
    }

    fn drain_console_log_capture(&mut self) {
        let Some(capture) = self.console_log_capture.as_ref() else {
            return;
        };
        let output = capture.take();
        if !output.is_empty() {
            self.developer_console.out(&output);
        }
    }

    fn show_developer_console_message(
        &mut self,
        message: String,
        follow_up: Option<String>,
    ) -> std::result::Result<(), EngineError> {
        self.push_message_dialog(
            clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                message,
                "LegacyClonk",
                clonk_frontend::message_dialog::MessageDialogIcon::Standard(44),
            ),
            MessageDialogContinuation::DeveloperConsoleNotice { follow_up },
        )?;
        Ok(())
    }

    fn open_developer_console_game(
        &mut self,
        scenario: PathBuf,
        player_files: Vec<PathBuf>,
    ) -> Result<()> {
        // C4Console::OpenGame calls Console::Default before any game
        // initialization and therefore resets only the edit cursor mode.
        self.developer_console_edit_mode = ConsoleEditMode::Play;
        if self.console_game_active() {
            self.close_console_game();
        }
        let mut arguments = Vec::with_capacity(1 + player_files.len());
        arguments.push(scenario.into_os_string());
        arguments.extend(player_files.into_iter().map(PathBuf::into_os_string));
        let mut classic = parse_classic_command_line(&arguments);
        classic.console = true;
        self.apply_classic_command_line(&classic)?;
        self.launch_classic_command_line_join()?;
        self.launch_classic_command_line_scenario()?;
        Ok(())
    }

    fn developer_console_player_save_options(&self) -> (bool, bool, String) {
        let graphics = load_options_graphics_state(self.app_paths.as_ref());
        let rank_name = self
            .save_description_language_table
            .as_ref()
            .and_then(|table| table.entries.get("IDS_MSG_RANK"))
            .map(|value| clonk_script::c4_string_from_bytes(value))
            .unwrap_or_else(|| "Rank".to_string());
        (
            graphics.add_new_crew_portraits,
            graphics.save_default_portraits,
            rank_name,
        )
    }

    fn synchronized_player_profile_path(
        &self,
        info: &clonk_engine::ControlPlayerInfoEntry,
    ) -> Option<PathBuf> {
        if let Some(path) = self.local_player_profile_paths.get(&info.id) {
            return Some(path.clone());
        }
        if let Some(path) = info.resource.as_ref().and_then(|resource| {
            self.admission_resources
                .complete_path(resource.id)
                .map(Path::to_path_buf)
        }) {
            return Some(path);
        }
        if let Some(path) = self
            .startup_player_files
            .iter()
            .find(|player| {
                clonk_script::c4_string_bytes(&player.file_name)
                    .eq_ignore_ascii_case(info.filename.as_bytes())
            })
            .map(|player| player.path.clone())
        {
            return Some(path);
        }

        let configured = path_from_group_name_bytes(info.filename.as_bytes());
        if configured.as_os_str().is_empty() {
            // A filename-less info has no profile to synchronize. Native
            // C4Player::Save fails on its empty Filename at EraseItem/
            // C4Group_MoveItem (C4Player.cpp:454-456) without ever touching
            // the installation; resolving "" against the install root would
            // name the install root itself as the profile to rewrite.
            return None;
        }
        if configured.exists() {
            return Some(configured);
        }
        self.app_paths
            .as_ref()
            .map(|paths| paths.install_root().join(configured))
            .filter(|path| path.exists())
    }

    /// Persist the application-owned half of
    /// `C4PlayerList::SynchronizeLocalFiles`. The engine has already applied
    /// `C4Player::LocalSync`'s time checkpoint at this boundary.
    fn persist_synchronized_local_player_files(&mut self) -> bool {
        tracing::info!("synchronizing local player files");
        let local_client_id = self
            .network
            .as_ref()
            .and_then(|network| i32::try_from(network.local_client_id()).ok())
            .unwrap_or_else(|| self.offline_local_client_id());
        let league = self.network_is_league;
        let max_players = self.engine.max_players();
        let candidates = self
            .engine
            .players()
            .map(|player| {
                (
                    player.id(),
                    player.player_info_id(),
                    synchronized_player_file_policy(
                        player.status(),
                        player.is_script_player(),
                        player.at_client().get(),
                        local_client_id,
                        league,
                        max_players,
                    ),
                )
            })
            .collect::<Vec<_>>();
        let maker = self.process_group_maker.as_bytes().to_vec();
        let (add_new_crew_portraits, save_default_portraits, player_rank_name_default) =
            self.developer_console_player_save_options();
        let options = clonk_engine::LiveC4PlayerSaveOptions {
            savegame: false,
            store_tiny: false,
            add_new_crew_portraits,
            save_default_portraits,
            player_rank_name_default: &player_rank_name_default,
        };
        let mut success = true;

        for (player_number, info_id, policy) in candidates {
            let local_control = match policy {
                SynchronizedPlayerFilePolicy::Skip => continue,
                SynchronizedPlayerFilePolicy::BlockedRemote => {
                    success = false;
                    continue;
                }
                SynchronizedPlayerFilePolicy::Persist { local_control } => local_control,
            };
            if !local_control {
                // Native permanently strips missing-definition crew before
                // opening its temporary remote group. Keep that mutation
                // even when Rust-only provenance lookup fails afterward.
                clonk_engine::strip_unresolved_remote_crew_for_synchronization(
                    &mut self.engine,
                    player_number,
                );
            }
            let Some(info) = self.control_player_infos.get(info_id).cloned() else {
                tracing::warn!(player_number, info_id, "cannot save player without PlayerInfo");
                success = false;
                continue;
            };
            let Some(path) = self.synchronized_player_profile_path(&info) else {
                tracing::warn!(
                    player_number,
                    info_id,
                    filename = %info.filename.to_string_lossy(),
                    "cannot resolve synchronized player profile path"
                );
                success = false;
                continue;
            };
            let saved = (|| -> Result<()> {
                // C4Player::Save ignores a failed source copy before opening
                // its temporary group with create enabled. Consequently a
                // local profile removed after admission is recreated from
                // the live core and roster instead of becoming ineligible.
                let original = if local_control && path.exists() {
                    Some(
                        open_group_path_for_folder_map(&path)
                            .with_context(|| format!("open player profile {}", path.display()))?,
                    )
                } else {
                    None
                };
                let synchronized = clonk_engine::serialize_live_c4_player_for_synchronization(
                    &mut self.engine,
                    player_number,
                    info.filename.as_bytes(),
                    &maker,
                    local_control,
                    original.as_ref(),
                    options,
                )
                .with_context(|| format!("serialize player profile {}", path.display()))?;
                let mut group = if let Some(original) = original.as_ref() {
                    developer_console_save::overlay_live_player_group_with_cleanup(
                        original,
                        &synchronized.group,
                        &synchronized.crew_cleanup,
                    )?
                } else {
                    // Remote profiles and missing local profiles both start
                    // from the freshly serialized group. Remote saves use
                    // fStoreTiny=true; local saves retain the full payload.
                    synchronized.group
                };
                if !self.process_group_maker.as_bytes().is_empty() {
                    group.set_maker_bytes_recursively(self.process_group_maker.as_bytes());
                }
                // Native snapshots fOfficial after serializing and before
                // Derive, then consults that same value after the move.
                let official_derivation = self.engine.is_control_host();
                let derivation = self.network.as_ref().and_then(|network| {
                    let resource = info.resource.as_ref()?;
                    let resource_id = self.admission_resources.derivation_target(resource.id)?;
                    let ownership = if local_control {
                        clonk_network::ResourceFileOwnership::Persistent
                    } else {
                        clonk_network::ResourceFileOwnership::Temporary
                    };
                    match network.begin_resource_derive(resource_id, path.clone(), ownership) {
                        Ok(derivation) => Some((derivation, ownership)),
                        Err(error) => {
                            // C4Player::Save proceeds when Derive returns null;
                            // the failed rescue only makes this update
                            // unavailable as an official network resource.
                            tracing::warn!(
                                player_number,
                                info_id,
                                resource_id,
                                path = %path.display(),
                                %error,
                                "failed to protect player resource before synchronization"
                            );
                            None
                        }
                    }
                });
                persist_console_save_group(&group, &path, local_control && path.is_dir())
                    .with_context(|| format!("persist player profile {}", path.display()))?;
                if official_derivation {
                    if let (Some(network), Some((derivation, ownership))) =
                        (self.network.as_ref(), derivation)
                    {
                        match network.finish_resource_derive(derivation) {
                            Ok(core) => self.admission_resources.register_finished_derivation(
                                &core,
                                path.clone(),
                                ownership,
                            ),
                            Err(error) => {
                                // FinishDerive's result is ignored by
                                // C4Player::Save; the profile itself has
                                // already been saved.
                                tracing::warn!(
                                    player_number,
                                    info_id,
                                    path = %path.display(),
                                    %error,
                                    "failed to publish synchronized player resource derivation"
                                );
                            }
                        }
                    }
                }
                Ok(())
            })();
            if let Err(error) = saved {
                tracing::warn!(
                    player_number,
                    info_id,
                    path = %path.display(),
                    %error,
                    "failed to synchronize player profile"
                );
                success = false;
            }
        }
        success
    }

    fn developer_console_save_parameters(&self) -> Result<Vec<u8>> {
        let seed = self
            .live_save_seed
            .as_ref()
            .ok_or_else(|| anyhow!("live save parameter seed is unavailable"))?;
        let mut parameters = seed.parameters.clone();
        parameters.random_seed = (self.engine.random_seed() as u32) as i32;
        parameters.startup_player_count = self.engine.startup_player_count().unwrap_or_else(|| {
            i32::try_from(self.control_player_infos.nonremoved_player_count()).unwrap_or(i32::MAX)
        });
        parameters.max_players = self
            .engine
            .max_players()
            .unwrap_or(seed.scenario_defaults.max_players);
        parameters.use_fair_crew = self.engine.use_fair_crew();
        parameters.fair_crew_forced = self.engine.fair_crew_forced();
        parameters.fair_crew_strength = self.engine.fair_crew_strength();
        parameters.allow_debug = self.engine.allow_debug();
        parameters.is_network_game = self.network.is_some();
        parameters.control_rate = self.engine.control_rate();
        parameters.auto_frame_skip = self.auto_frame_skip;
        parameters.player_infos = self.recording_player_info_snapshot();
        parameters.clients =
            clonk_network::JoinClientRegistrySnapshot::new(self.control_clients.snapshot());
        clonk_network::serialize_initial_network_parameters(&parameters, &seed.scenario_defaults)
            .context("serialize live save Parameters.txt")
    }

    fn classic_save_description(
        &self,
        title: &[u8],
        definition_modules: &[Vec<u8>],
        kind: ClassicSaveDescriptionKind,
    ) -> (Vec<u8>, Vec<u8>) {
        let table = self.save_description_language_table.as_ref();
        let resource_bytes = |key: &str, _fallback: &str| {
            let Some(table) = table else {
                return b"Language string table not loaded.".to_vec();
            };
            let Some(value) = table.entries.get(key) else {
                return format!("[Undefined: {key}]").into_bytes();
            };
            value.clone()
        };

        // C4Language::Init overwrites Config.General.LanguageCharset from the
        // active resource table. Keep legacy code-page bytes opaque; only the
        // ASCII charset identifier is interpreted here.
        let charset_name = table
            .and_then(|table| table.entries.get("IDS_LANG_CHARSET"))
            .and_then(|value| std::str::from_utf8(value).ok())
            .unwrap_or_default();
        let charset_code = classic_rtf_charset_code(&charset_name);
        let language = self.save_description_language.clone();
        let mut title = clonk_script::c4_string_from_bytes(title);
        Markup::strip_markup(&mut title);
        let title = clonk_script::c4_string_bytes(&title);
        let now = classic_calendar_time_now();
        let (date_key, date_fallback) = match kind {
            ClassicSaveDescriptionKind::Record => (
                "IDS_DESC_DATEREC",
                "Recording from %i.%i.%i %02d:%02d.",
            ),
            ClassicSaveDescriptionKind::Savegame if self.network.is_some() => (
                "IDS_DESC_DATENET",
                "Network game from %i.%i.%i %02d:%02d.",
            ),
            ClassicSaveDescriptionKind::Savegame => {
                ("IDS_DESC_DATE", "Game saved %i.%i.%i %02d:%02d.")
            }
        };
        let date_template = resource_bytes(date_key, date_fallback);
        let mut lines = vec![(
            developer_console_save::format_resource_integers(
                &date_template,
                &[now.day, now.month, now.year, now.hour, now.minute],
            ),
            true,
        )];

        let game_time = self.engine.game_time();
        if game_time != 0 {
            let duration = resource_bytes(
                "IDS_DESC_DURATION",
                "Playing time: %02d:%02d:%02d.",
            );
            lines.push((
                developer_console_save::format_resource_integers(
                    &duration,
                    &[
                        game_time / 3_600,
                        (game_time % 3_600) / 60,
                        game_time % 60,
                    ],
                ),
                true,
            ));
        }

        if matches!(kind, ClassicSaveDescriptionKind::Record) {
            let build = format!("{CLASSIC_ENGINE_BUILD:03}");
            let version = resource_bytes("IDS_DESC_VERSION", "Engine version: %s");
            lines.push((
                developer_console_save::format_resource_strings(
                    &version,
                    &[build.as_bytes()],
                ),
                true,
            ));
        }

        if !definition_modules.is_empty() {
            let mut definitions = resource_bytes("IDS_DESC_DEFSPECS", "Object definitions: ");
            for (index, module) in definition_modules.iter().enumerate() {
                if index != 0 {
                    definitions.extend_from_slice(b", ");
                }
                let relative = developer_console_definition_description_path(
                    module,
                    self.app_paths.as_ref(),
                );
                for byte in relative {
                    if byte == b'\\' {
                        definitions.push(b'\\');
                    }
                    definitions.push(byte);
                }
            }
            lines.push((definitions, true));
        }

        if matches!(kind, ClassicSaveDescriptionKind::Record) && self.network_is_league {
            let league = resource_bytes("IDS_PRC_LEAGUE", "Using league '%s'");
            lines.push((
                developer_console_save::format_resource_strings(
                    &league,
                    &[self.network_league_name.as_slice()],
                ),
                true,
            ));
        }

        if self.network.is_some() {
            let mut clients = resource_bytes("IDS_DESC_CLIENTS", "Clients: ");
            for (index, client) in self.control_clients.snapshot().iter().enumerate() {
                if index != 0 {
                    clients.extend_from_slice(b", ");
                }
                clients.extend_from_slice(client.name.as_bytes());
            }
            lines.push((clients, true));
        }

        let (_, packets) = self.control_player_infos.retained_rows_snapshot();
        let has_retained_players = packets.iter().any(|(_, _, players)| !players.is_empty());
        let players = packets
            .iter()
            .flat_map(|(_, _, players)| players)
            .filter(|player| {
                player.is_joined()
                    && player.flags & clonk_engine::PLAYER_INFO_FLAG_INVISIBLE == 0
            })
            .collect::<Vec<_>>();
        if has_retained_players {
            let label = resource_bytes("IDS_DESC_PLRS", "Players: ");
            let team_configuration = self.engine.team_configuration();
            if team_configuration.active && !team_configuration.auto_generate_teams {
                lines.push((label, true));
                let mut known_team_ids = HashSet::new();
                for team in self.engine.teams() {
                    known_team_ids.insert(team.id);
                    let members = players
                        .iter()
                        .copied()
                        .filter(|player| player.team == team.id)
                        .collect::<Vec<_>>();
                    if members.is_empty() {
                        continue;
                    }
                    let mut line = clonk_script::c4_string_bytes(&team.name);
                    line.extend_from_slice(b": ");
                    append_description_player_names(&mut line, &members);
                    lines.push((line, true));
                }
                let unassigned = players
                    .iter()
                    .copied()
                    .filter(|player| !known_team_ids.contains(&player.team))
                    .collect::<Vec<_>>();
                if !unassigned.is_empty() {
                    let mut line = Vec::new();
                    append_description_player_names(&mut line, &unassigned);
                    lines.push((line, true));
                }
            } else {
                let mut line = label;
                append_description_player_names(&mut line, &players);
                lines.push((line, !players.is_empty()));
            }
        }

        let mut filename = b"Desc".to_vec();
        filename.extend_from_slice(&language);
        filename.extend_from_slice(b".rtf");
        (
            filename,
            developer_console_save::serialize_savegame_description(
                &title,
                charset_code,
                &lines,
            ),
        )
    }

    fn developer_console_savegame_description(
        &self,
        title: &str,
        definition_modules: &[Vec<u8>],
    ) -> (Vec<u8>, Vec<u8>) {
        self.classic_save_description(
            &clonk_script::c4_string_bytes(title),
            definition_modules,
            ClassicSaveDescriptionKind::Savegame,
        )
    }

    fn save_developer_console_game(
        &mut self,
        kind: ConsoleSaveKind,
        requested_target: Option<&Path>,
    ) -> Result<bool> {
        self.save_native_c4_game(kind, requested_target, true, None)
    }

    fn save_main_menu_slot_game(
        &mut self,
        requested_target: &Path,
        title_png: Option<&[u8]>,
    ) -> Result<bool> {
        self.save_native_c4_game(
            ConsoleSaveKind::Savegame,
            Some(requested_target),
            false,
            title_png,
        )
    }

    fn save_native_c4_game(
        &mut self,
        kind: ConsoleSaveKind,
        requested_target: Option<&Path>,
        retarget_active_scenario: bool,
        title_png: Option<&[u8]>,
    ) -> Result<bool> {
        anyhow::ensure!(
            self.mode == AppMode::Running,
            "cannot save while no game is running"
        );
        let active = self
            .active_scenario
            .clone()
            .ok_or_else(|| anyhow!("active scenario metadata is unavailable"))?;
        let mut source_path = if retarget_active_scenario {
            active.path.clone()
        } else {
            self.live_save_seed
                .as_ref()
                .map(|seed| seed.scenario_source_path.clone())
                .or_else(|| active.path.clone())
        }
        .ok_or_else(|| anyhow!("active scenario has no filesystem path"))?;
        let retained_origin = (!retarget_active_scenario).then(|| {
            self.live_save_seed
                .as_ref()
                .map(|seed| seed.scenario_origin.clone())
                .unwrap_or_else(|| {
                    record_scenario_origin(
                        &source_path,
                        self.app_paths.as_ref(),
                        &active.identifier,
                    )
                })
        });

        // FileSave's overwrite guard precedes SaveGame's host/child guards;
        // FileSaveAs deliberately bypasses it by copying to a fresh target.
        if retarget_active_scenario
            && kind == ConsoleSaveKind::Savegame
            && requested_target.is_none()
        {
            let source = open_group_path_for_folder_map(&source_path)
                .with_context(|| format!("open {}", source_path.display()))?;
            if !ScenarioLoaderHead::load_from_group(&source)?.is_save_game() {
                self.show_developer_console_message(
                    self.runtime_resource_text(
                        "IDS_CNS_NOGAMEOVERSCEN",
                        "You should not overwrite the original scenario file with a save game.",
                    ),
                    None,
                )?;
                return Ok(false);
            }
        }

        let mut destination = requested_target
            .map(Path::to_path_buf)
            .unwrap_or_else(|| source_path.clone());
        if requested_target.is_some() && destination.extension().is_none() {
            destination.set_extension("c4s");
        }

        if requested_target.is_some() {
            if !retarget_active_scenario
                && cpp_loader_items_identical(&source_path, &destination)?
            {
                anyhow::bail!(
                    "cannot save the running scenario over itself: {}",
                    destination.display()
                );
            }
            if !retarget_active_scenario {
                match fs::symlink_metadata(&destination) {
                    Ok(_) => remove_file_or_directory(&destination).with_context(|| {
                        format!("erase previous quick-save slot {}", destination.display())
                    })?,
                    Err(error) if error.kind() == io::ErrorKind::NotFound => {}
                    Err(error) => {
                        return Err(error).with_context(|| {
                            format!("inspect quick-save slot {}", destination.display())
                        });
                    }
                }
            }
            // FileSaveAs closes the current group, copies the complete source
            // with C4Group_CopyItem, changes ScenarioFilename/caption, and
            // reopens the copy *before* SaveGame applies its host guard.
            // Preserve unpacked directories just as CopyDirectory does.
            if retarget_active_scenario {
                if let Some(active) = self.active_scenario.as_mut() {
                    active.identifier = destination.to_string_lossy().into_owned();
                    active.path = Some(destination.clone());
                    active.source_paths = vec![destination.clone()];
                }
                if let Some(seed) = self.live_save_seed.as_mut() {
                    seed.scenario_source_path = destination.clone();
                    seed.scenario_origin = record_scenario_origin(
                        &destination,
                        self.app_paths.as_ref(),
                        &active.identifier,
                    );
                }
                self.classic_command_line.scenario = Some(destination.clone());
            }
            let copy_result = (|| -> Result<()> {
                let source = open_group_path_for_folder_map(&source_path).with_context(|| {
                    format!("open source scenario {}", source_path.display())
                })?;
                let copy = MutableGroup::from_group(&source).with_context(|| {
                    format!("copy source scenario {}", source_path.display())
                })?;
                persist_console_save_group(
                    &copy,
                    &destination,
                    retarget_active_scenario && source_path.is_dir(),
                )
                .with_context(|| format!("copy scenario to {}", destination.display()))
            })();
            if let Err(error) = copy_result {
                tracing::error!(%error, target = %destination.display(), "native C4Group save copy failed");
                if !retarget_active_scenario {
                    return Err(error);
                }
                let target = destination.to_string_lossy();
                let message = format_resource_string(
                    self.runtime_resource_text(
                        "IDS_CNS_SAVEASERROR",
                        "Error while saving the scenario to %s.",
                    ),
                    &[&target],
                );
                self.show_developer_console_message(message, None)?;
                return Ok(false);
            }
            source_path = destination.clone();
        }

        if self.network.is_some() && !matches!(self.network_mode, Some(NetworkMode::Host(_))) {
            self.show_developer_console_message(
                self.runtime_resource_text(
                    "IDS_GAME_NOCLIENTSAVE",
                    "Network games may be saved by the host only.",
                ),
                None,
            )?;
            return Ok(false);
        }
        if requested_target.is_none() {
            let (_, children) = scenario_logical_storage(&source_path)?;
            if !children.is_empty() {
                let filename = source_path
                    .file_name()
                    .map(|name| name.to_string_lossy().into_owned())
                    .unwrap_or_else(|| source_path.to_string_lossy().into_owned());
                let message = format_resource_string(
                    self.runtime_resource_text(
                        "IDS_CNS_NOCHILDSAVE",
                        "%s is located in a group folder.\nScenarios cannot be saved in closed group folders.",
                    ),
                    &[&filename],
                );
                self.show_developer_console_message(message, None)?;
                return Ok(false);
            }
        }
        let source = open_group_path_for_folder_map(&source_path)
            .with_context(|| format!("open source scenario {}", source_path.display()))?;
        let save_title_components = if kind == ConsoleSaveKind::Savegame {
            if self.engine.frame() == 0 {
                ["Title.bmp", "Title.png"]
                    .into_iter()
                    .filter_map(|name| source.read_file(name).ok().map(|payload| (name, payload)))
                    .collect::<Vec<_>>()
            } else {
                title_png
                    .map(|payload| vec![("Title.png", payload.to_vec())])
                    .unwrap_or_default()
            }
        } else {
            Vec::new()
        };
        let mut group = MutableGroup::from_group(&source)
            .with_context(|| format!("copy source scenario {}", source_path.display()))?;
        let preserve_folder_group = source_path.is_dir();
        let mut folder_save_journal = if preserve_folder_group {
            developer_console_save::FolderSaveJournal::default()
        } else {
            developer_console_save::FolderSaveJournal::disabled()
        };
        if !self.process_group_maker.is_empty() {
            // Closing an owned C4Group stamps the process-global maker on
            // the root header even when the save later reports failure.
            group.set_maker_bytes(self.process_group_maker.as_bytes());
        }
        let copied_material_group_is_file = matches!(
            group.entry_kind("Material.c4g"),
            Some(
                MutableGroupEntryKind::File | MutableGroupEntryKind::UnopenableChildGroup
            )
        );

        if kind == ConsoleSaveKind::Savegame {
            if let Some(network) = self.network.as_ref() {
                if let Err(error) = network.submit_queued_synchronize(
                    self.local_control_submission_tick(),
                    true,
                    false,
                ) {
                    // Native unconditionally continues after adding the
                    // synchronization control to its queue.
                    tracing::warn!(%error, "failed to queue savegame player synchronization");
                }
            } else {
                // C4GameSaveSavegame::OnSaving synchronizes offline players
                // even when the running game is a replay.
                self.engine.checkpoint_local_player_files_for_save();
                // Native ignores this aggregate result and proceeds with the
                // savegame even if one profile could not be synchronized.
                let _ = self.persist_synchronized_local_player_files();
            }
        }

        let definition_modules = match self.active_definition_load.as_ref() {
            Some(ScenarioDefinitionLoad::Seed { modules, .. })
            | Some(ScenarioDefinitionLoad::Fixed { modules, .. }) => modules.clone(),
            None => Vec::new(),
        };
        let description_definition_modules = if self
            .active_description_definition_modules
            .is_empty()
            && !definition_modules.is_empty()
        {
            // State-only embedders may seed the historical String vector
            // directly. Its C4 byte projection remains the exact fallback
            // whenever no filesystem-derived byte cache exists.
            definition_modules
                .iter()
                .map(|module| clonk_script::c4_string_bytes(module))
                .collect()
        } else {
            self.active_description_definition_modules.clone()
        };
        let native_config = load_native_config_bytes(self.app_paths.as_ref());
        let (definition_executable_path, definition_path) =
            game_save_definition_paths(self.app_paths.as_ref(), &native_config);
        let title = self
            .host_join_snapshot
            .as_ref()
            .map(|snapshot| native_bytes_as_legacy_text(snapshot.parameters.title.as_bytes()))
            .or_else(|| {
                self.live_save_seed
                    .as_ref()
                    .map(|seed| native_bytes_as_legacy_text(seed.scenario_title.as_bytes()))
            })
            .unwrap_or_else(|| active.title.clone());
        let origin = retained_origin.unwrap_or_else(|| {
            record_scenario_origin(&destination, self.app_paths.as_ref(), &active.identifier)
        });
        let destination_name = destination.to_string_lossy().into_owned();
        let force_exact_landscape = self
            .engine
            .landscape()
            .is_some_and(|landscape| landscape.mode() == clonk_engine::LANDSCAPE_MODE_EXACT);
        let landscape_is_static = self
            .engine
            .landscape()
            .is_some_and(|landscape| landscape.mode() == clonk_engine::LANDSCAPE_MODE_STATIC);
        let policy = match kind {
            ConsoleSaveKind::Scenario => clonk_engine::LiveC4SavePolicy::Scenario {
                force_exact_landscape,
            },
            ConsoleSaveKind::Savegame => clonk_engine::LiveC4SavePolicy::Savegame {
                target_group_name: &destination_name,
            },
        };
        // Exact SaveCore writes Parameters.txt before Scenario.txt.
        if kind == ConsoleSaveKind::Savegame {
            let parameters = self.developer_console_save_parameters()?;
            folder_save_journal.put_file(
                "Parameters.txt",
                &parameters,
                developer_console_save::FolderSaveAddFailure::Fatal,
            );
            group
                .add_file("Parameters.txt", parameters)
                .context("write live save Parameters.txt")?;
        }
        let save = match self
            .engine
            .serialize_live_c4_save_with_policy(
                clonk_engine::LiveC4SaveSpec {
                    title: &title,
                    definition_modules: &definition_modules,
                    definition_executable_path: &definition_executable_path,
                    definition_path: &definition_path,
                    origin: &origin,
                    music_enabled: self.runtime_music_enabled,
                    copied_material_group_is_file,
                    title_component: clonk_engine::LiveC4ComponentHost::Unmodified,
                    info_component: clonk_engine::LiveC4ComponentHost::Unmodified,
                    script_component: clonk_engine::LiveC4ComponentHost::Unmodified,
                },
                policy,
            )
        {
            Ok(save) => save,
            Err(error) => {
                if let Some(partial) = error.pre_landscape_components() {
                    let apply_result =
                        developer_console_save::apply_live_save_pre_landscape_to_group_recorded(
                            &mut group,
                            policy,
                            partial,
                            &mut folder_save_journal,
                        );
                    if !self.process_group_maker.is_empty() {
                        group.set_maker_bytes_recursively(self.process_group_maker.as_bytes());
                    }
                    let persist_result = persist_live_console_save_group(
                        &group,
                        &destination,
                        preserve_folder_group,
                        &folder_save_journal,
                        self.process_group_maker.as_bytes(),
                    );
                    apply_result?;
                    persist_result?;
                }
                return Err(error).context("serialize live C4 scenario state");
            }
        };

        let mutation_result = (|| -> Result<()> {
            developer_console_save::apply_live_save_runtime_components_to_group_recorded(
                &mut group,
                policy,
                &save,
                landscape_is_static,
                &mut folder_save_journal,
            )?;

            let clients = self.control_clients.snapshot();
            let player_infos = self.recording_player_info_snapshot();
            let restore_plan = runtime_join_save::set_as_live_save_restore_infos(
                &clients,
                &player_infos,
                self.network.is_some(),
                policy.player_policy(),
            );
            // C4PlayerInfoList::Save deletes the old entry before compiling.
            group.remove_entry("SavePlayerInfos.txt");
            folder_save_journal.delete_entry("SavePlayerInfos.txt");
            if !restore_plan.restore_infos.clients.is_empty() {
                let save_player_infos =
                    clonk_network::encode_player_info_list_ini(&restore_plan.restore_infos)
                        .context("serialize SavePlayerInfos.txt")?;
                developer_console_save::add_live_save_player_infos_after_delete_to_group_recorded(
                    &mut group,
                    &save_player_infos,
                    &mut folder_save_journal,
                )?;
            }

            let maker = self.process_group_maker.as_bytes().to_vec();
            let (add_new_crew_portraits, save_default_portraits, player_rank_name_default) =
                self.developer_console_player_save_options();
            let player_options = clonk_engine::LiveC4PlayerSaveOptions {
                savegame: true,
                // C4PlayerList converts GetCreateSmallFile into
                // fStoreOnOriginal before calling C4Player::Save. Every
                // embedded player type therefore passes false.
                store_tiny: false,
                add_new_crew_portraits,
                save_default_portraits,
                player_rank_name_default: &player_rank_name_default,
            };
            let runtime_players = self
                .engine
                .players()
                .map(|player| (player.id(), player.player_info_id()))
                .collect::<Vec<_>>();
            let mut remaining_targets = restore_plan.player_groups;
            for (game_number, player_info_id) in runtime_players {
                let Some(index) = remaining_targets
                    .iter()
                    .position(|target| target.player_info_id == player_info_id)
                else {
                    continue;
                };
                let target = remaining_targets.remove(index);
                let player_group =
                    clonk_engine::serialize_live_c4_player_with_options_and_enumeration(
                        &self.engine,
                        game_number,
                        target.filename.as_bytes(),
                        &maker,
                        player_options,
                        &save.value_enumeration,
                    )
                    .with_context(|| {
                        format!(
                            "serialize player info {} (game player {})",
                            target.player_info_id, game_number
                        )
                    })?;
                developer_console_save::add_live_save_player_group_recorded(
                    &mut group,
                    runtime_join_save::SerializedRuntimeJoinPlayerGroup {
                        filename: target.filename,
                        group: player_group,
                    },
                    &mut folder_save_journal,
                )?;
            }
            // C4PlayerList::Save ignores stale restore rows without a live
            // player, then SaveDesc runs after all player children.
            if kind == ConsoleSaveKind::Savegame {
                let (description_name, description) = self
                    .developer_console_savegame_description(
                        &title,
                        &description_definition_modules,
                    );
                folder_save_journal.put_file(
                    &description_name,
                    &description,
                    developer_console_save::FolderSaveAddFailure::Ignore,
                );
                if let Err(error) = group.add_file_bytes(description_name, description) {
                    // C4GameSave::Save deliberately ignores SaveDesc failure
                    // and continues with the remaining save components.
                    tracing::warn!(%error, "failed to write live save description");
                }
            }
            for (name, payload) in save_title_components {
                folder_save_journal.put_file(
                    name,
                    &payload,
                    developer_console_save::FolderSaveAddFailure::Ignore,
                );
                if let Err(error) = group.add_file(name, payload) {
                    // SaveGameTitle failure is logged but never makes the
                    // enclosing C4GameSaveSavegame fail.
                    tracing::warn!(%error, component = name, "failed to write live save title");
                }
            }
            Ok(())
        })();
        if let Err(error) = mutation_result {
            if !self.process_group_maker.is_empty() {
                group.set_maker_bytes_recursively(self.process_group_maker.as_bytes());
            }
            persist_live_console_save_group(
                &group,
                &destination,
                preserve_folder_group,
                &folder_save_journal,
                self.process_group_maker.as_bytes(),
            )
                .context("persist partially completed live save")?;
            return Err(error);
        }
        if !self.process_group_maker.is_empty() {
            group.set_maker_bytes_recursively(self.process_group_maker.as_bytes());
        }
        persist_live_console_save_group(
            &group,
            &destination,
            preserve_folder_group,
            &folder_save_journal,
            self.process_group_maker.as_bytes(),
        )?;
        if retarget_active_scenario {
            let success = match kind {
                ConsoleSaveKind::Scenario => {
                    self.runtime_resource_text("IDS_CNS_SCENARIOSAVED", "Scenario saved.")
                }
                ConsoleSaveKind::Savegame => {
                    self.runtime_resource_text("IDS_CNS_GAMESAVED", "Game saved.")
                }
            };
            self.developer_console.out(&success);
        }
        Ok(true)
    }

    fn choose_developer_console_paths(request: &ConsolePathRequest) -> Vec<PathBuf> {
        let mut dialog = rfd::FileDialog::new().set_title(&request.title);
        if let Some(path) = request.suggested_path.as_deref() {
            if let Some(parent) = path.parent() {
                dialog = dialog.set_directory(parent);
            }
            if let Some(name) = path.file_name() {
                dialog = dialog.set_file_name(name.to_string_lossy());
            }
        }
        if !request.extensions.is_empty() {
            dialog = dialog.add_filter(request.filter_label.as_str(), &request.extensions);
        }
        if request.save {
            dialog.save_file().into_iter().collect()
        } else if request.allow_multiple {
            dialog.pick_files().unwrap_or_default()
        } else {
            dialog.pick_file().into_iter().collect()
        }
    }

    fn dispatch_developer_console_actions(
        &mut self,
        mut actions: Vec<DeveloperConsoleAction>,
    ) -> Result<()> {
        while let Some(action) = actions.pop() {
            match action {
                DeveloperConsoleAction::RequestPath(request) => {
                    let paths = Self::choose_developer_console_paths(&request);
                    let follow_up = self
                        .developer_console
                        .respond_path_request(request.token, paths);
                    actions.extend(follow_up.into_iter().rev());
                }
                DeveloperConsoleAction::OpenGame {
                    scenario,
                    player_files,
                } => {
                    if let Err(error) = self.open_developer_console_game(scenario, player_files) {
                        tracing::error!(%error, "developer-console game open failed");
                        // FileOpen intentionally ignores OpenGame(false).
                        // Clear partial async/bootstrap state and leave the
                        // persistent developer window alive.
                        self.close_console_game();
                    }
                }
                DeveloperConsoleAction::Save { kind, target } => {
                    let result = self.save_developer_console_game(kind, target.as_deref());
                    let attempted = !matches!(&result, Ok(false));
                    let save_error = result.err().map(|error| {
                        tracing::error!(%error, ?kind, target = ?target, "developer-console save failed");
                        if let Some(target) = target.as_deref() {
                            let target = target.to_string_lossy();
                            format_resource_string(
                                self.runtime_resource_text(
                                    "IDS_CNS_SAVEASERROR",
                                    "Error while saving the scenario to %s.",
                                ),
                                &[&target],
                            )
                        } else {
                            self.runtime_resource_text(
                                "IDS_CNS_SAVERROR",
                                "Error while saving the scenario.",
                            )
                        }
                    });
                    if kind == ConsoleSaveKind::Scenario
                        && attempted
                        && self.script_created_objects
                    {
                        let warning = format!(
                            "{}{}",
                            self.runtime_resource_text(
                                "IDS_CNS_SCRIPTCREATEDOBJECTS",
                                "This scenario's script has created objects on initialization. "
                            ),
                            self.runtime_resource_text(
                                "IDS_CNS_WARNDOUBLE",
                                "In order to avoid double creation, the script's 'Initialize' function should be modified."
                            )
                        );
                        self.script_created_objects = false;
                        self.show_developer_console_message(warning, save_error)?;
                    } else if let Some(message) = save_error {
                        self.show_developer_console_message(message, None)?;
                    }
                }
                DeveloperConsoleAction::RequestRuntimeRecord => {
                    if let Err(error) = self.developer_console_request_runtime_record() {
                        self.developer_console.out(&error);
                    }
                }
                DeveloperConsoleAction::CloseGame => self.close_console_game(),
                DeveloperConsoleAction::QuitApplication => self.request_exit(),
                DeveloperConsoleAction::Play => self.set_runtime_pause(false),
                DeveloperConsoleAction::Halt => self.set_runtime_pause(true),
                DeveloperConsoleAction::TogglePause => self.toggle_runtime_pause(),
                DeveloperConsoleAction::SetEditMode(mode) => {
                    self.developer_console_edit_mode = mode;
                }
                DeveloperConsoleAction::SubmitInput(input) => {
                    let editing = self.developer_console_editing();
                    self.process_developer_console_input(&input, editing)?;
                }
                DeveloperConsoleAction::JoinPlayers(paths) => {
                    let editing = self.developer_console_editing();
                    if let Err(error) = self.developer_console_join_players(&paths, editing) {
                        self.developer_console.out(&error);
                    }
                }
                DeveloperConsoleAction::EliminatePlayer(player) => {
                    let editing = self.developer_console_editing();
                    if let Err(error) = self.developer_console_quit_player(player, editing) {
                        self.developer_console.out(&error);
                    }
                }
                DeveloperConsoleAction::KickClient(client) => {
                    if let Err(error) = self.developer_console_kick_client(client) {
                        self.developer_console.out(&error);
                    }
                }
                DeveloperConsoleAction::NewViewport(player) => {
                    let owner = player.unwrap_or(OWNER_NONE);
                    let _ = self.create_physical_viewport(
                        owner,
                        owner == OWNER_NONE,
                        self.mode == AppMode::Running,
                        true,
                    );
                }
                DeveloperConsoleAction::EditObjects => {
                    self.developer_console.out("Objects component selected");
                }
                DeveloperConsoleAction::EditScript => {
                    self.developer_console.out("Script component selected");
                }
                DeveloperConsoleAction::EditTitle => {
                    self.developer_console.out("Title component selected");
                }
                DeveloperConsoleAction::EditInfo => {
                    self.developer_console.out("Info component selected");
                }
                DeveloperConsoleAction::ShowAbout => {
                    self.developer_console.out("LegacyClonk developer console");
                }
            };
        }
        Ok(())
    }

    fn finish_console_shutdown(&mut self) {
        self.finish_recording();
        self.finalize_pending_league_end_for_teardown();
    }

    fn process_console_command(&mut self, line: &str) -> Result<()> {
        if line == "/quit" {
            self.request_exit();
            return Ok(());
        }

        let lobby_active = self.console_lobby_active();
        if line == "/close" && self.console_game_active() {
            self.close_console_game();
            return Ok(());
        }

        if lobby_active && line.starts_with("/start") {
            return self.process_console_lobby_start(line);
        }

        if self.console_startup_active() {
            if let Some(parameters) = line.strip_prefix("/open ") {
                let classic = parse_classic_command_line(&parse_classic_console_parameters(
                    parameters,
                ));
                self.apply_classic_command_line(&classic)?;
                self.launch_classic_command_line_join()?;
                self.launch_classic_command_line_scenario()?;
            }
            return Ok(());
        }

        if self.console_game_active() {
            self.process_console_message_input(line);
        }
        Ok(())
    }

    fn apply_classic_game_option_overrides(&mut self) {
        self.scenario_game_options.set_server_signup(
            self.classic_command_line.master_server_signup,
            self.classic_command_line.league_server_signup,
        );
        if let Some(fair_crew) = self.classic_command_line.fair_crew {
            self.startup_view_flags.fair_crew = fair_crew;
            self.scenario_game_options
                .set_lobby_fair_crew(fair_crew, false);
        }
        if let Some(password) = self.classic_command_line.password.as_ref() {
            self.scenario_game_options.set_password(password.clone());
        }
        if let Some(comment) = self.classic_command_line.comment.as_ref() {
            self.scenario_game_options.set_comment(comment.clone());
        }
        if let Some(runtime_join) = self.classic_command_line.runtime_join {
            self.runtime_network_join_allowed = Some(runtime_join);
        }
    }

    fn classic_command_line_definition_load(&self) -> ScenarioDefinitionLoad {
        let modules = self.initial_definition_seed.clone().unwrap_or_default();
        let definition_root =
            self.app_paths
                .as_ref()
                .and_then(|paths| match startup_definition_paths(paths) {
                    Ok(paths) => paths.active_custom_root,
                    Err(error) => {
                        tracing::error!(
                            %error,
                            "failed to read General.DefinitionPath for command-line scenario"
                        );
                        None
                    }
                });
        ScenarioDefinitionLoad::Seed {
            modules,
            definition_root,
        }
    }

    fn launch_classic_command_line_join(&mut self) -> Result<(), EngineError> {
        let Some(address) = self.classic_command_line.direct_join.clone() else {
            return Ok(());
        };
        // Explicit Rust `--host`/`--join` modes keep their existing precedence.
        if self.network_mode.is_some() {
            return Ok(());
        }
        if self.startup_network_connection.is_some()
            || self.classic_direct_reference_query.is_some()
        {
            self.status_text = "A network connection is already in progress".to_string();
            return Ok(());
        }
        if let Err(error) = self.freeze_configured_client_players_for_game() {
            self.status_text = format!("Unable to load configured players: {error}");
            return Ok(());
        }
        self.prepare_network_join_game_state();
        self.startup_game_search = None;

        let (sender, receiver) = mpsc::channel();
        let player_name = self.player_name.clone();
        let app_paths = self.app_paths.clone();
        let group_maker = self
            .configured_client_player_selection
            .as_ref()
            .map(|selection| selection.group_maker().clone());
        let classic = self.classic_command_line.clone();
        let reference_config = load_reference_query_settings(app_paths.as_ref());
        let connect_target = address.clone();
        let spawn = thread::Builder::new()
            .name("lc-classic-direct-join".to_string())
            .spawn(move || {
                let result = (|| {
                    let endpoint = classic_direct_reference_endpoint(&address, app_paths.as_ref())
                        .map_err(|error| {
                            NetworkStartError::Other(format!(
                                "invalid reference-server address: {error:#}"
                            ))
                        })?;
                    let reference =
                        query_first_classic_reference(endpoint, &reference_config)?;
                    let settings = classic_client_settings_for_reference(
                        &reference,
                        player_name,
                        app_paths.as_ref(),
                        group_maker,
                        &classic,
                    )
                    .map_err(|error| {
                        NetworkStartError::Other(format!(
                            "unable to apply direct-join settings: {error:#}"
                        ))
                    })?;
                    Ok(ClassicDirectReferenceQueryResult {
                        settings,
                        password_needed: reference.password_needed,
                    })
                })();
                let _ = sender.send(result);
            });
        match spawn {
            Ok(_) => {
                self.classic_direct_reference_query =
                    Some(ClassicDirectReferenceQuery { receiver });
                self.status_text = format!("Querying network game at {connect_target}...");
            }
            Err(error) => {
                self.status_text = format!("Unable to start reference query: {error}");
            }
        }
        Ok(())
    }

    fn poll_classic_direct_reference_query(&mut self) -> Result<(), EngineError> {
        // The query can finish before async boot resources. Keep its result
        // queued until boot relinquishes `Loading`; opening a password prompt
        // or an error dialog earlier would strand the boot worker forever.
        if self.boot_loading.is_some() {
            return Ok(());
        }
        let Some(query) = self.classic_direct_reference_query.as_ref() else {
            return Ok(());
        };
        let result = match query.receiver.try_recv() {
            Ok(result) => result,
            Err(TryRecvError::Empty) => return Ok(()),
            Err(TryRecvError::Disconnected) => Err(NetworkStartError::Other(
                "reference query worker disconnected before reporting a game".to_string(),
            )),
        };
        self.classic_direct_reference_query = None;
        self.status_text.clear();
        match result {
            Ok(result) => {
                self.pending_network_join = Some(result.settings);
                if result.password_needed && self.classic_command_line.password.is_none() {
                    self.mode = AppMode::Menu;
                    self.open_network_join_password_dialog()?;
                } else {
                    self.launch_pending_network_join()?;
                }
            }
            Err(error) => {
                self.finish_startup_network_failure(
                    StartupNetworkPurpose::Join,
                    format!("Unable to query network game: {error}"),
                )?;
            }
        }
        Ok(())
    }

    fn launch_classic_command_line_scenario(&mut self) -> Result<()> {
        if self.classic_command_line.direct_join.is_some() {
            return Ok(());
        }
        let scenario = self
            .classic_command_line
            .scenario
            .clone()
            .filter(|path| !path.as_os_str().is_empty());
        let record_stream = self
            .classic_command_line
            .record_stream
            .clone()
            .filter(|path| !path.as_os_str().is_empty());
        if scenario.is_none() && record_stream.is_none() {
            return Ok(());
        }
        if record_stream.is_some() {
            self.classic_record_stream_activation_pending = true;
        }
        if self.boot_loading.is_some() {
            self.auto_start_classic_command_line_scenario = true;
            return Ok(());
        }
        let path = if let Some(stream_path) = record_stream {
            let converted = classic_record_stream::convert_classic_record_stream(
                &stream_path,
                self.process_group_maker.as_bytes(),
            )
            .with_context(|| {
                format!(
                    "Could not process record stream data {}",
                    stream_path.display()
                )
            })?;
            self.classic_command_line.scenario = Some(converted.clone());
            converted
        } else {
            scenario.expect("a non-stream command-line scenario was checked above")
        };
        let scenario = FrontendScenario::from_command_line(&path);
        let definition_load = self.classic_command_line_definition_load();
        let replay_disables_network = if self.classic_command_line.network_active == Some(true) {
            self.scenario_loader_head_for_start(&scenario)
                .map_err(|error| anyhow!(error.to_string()))?
                .is_some_and(|head| head.is_replay())
        } else {
            false
        };
        if replay_disables_network {
            tracing::error!(
                "{}",
                self.runtime_resource_text(
                    "IDS_PRC_NONETREPLAY",
                    "Cannot play back records while in network mode."
                )
            );
        }
        if self.classic_command_line.network_active == Some(true) && !replay_disables_network {
            self.stage_network_host_scenario(scenario, definition_load);
            Ok(())
        } else {
            self.start_scenario_with_definition_load(scenario, definition_load)?;
            Ok(())
        }
    }

    fn configure_native_startup_fonts(&mut self, scale: f32, point_filtering: bool) {
        match LoaderRenderConfig::new(scale, point_filtering) {
            Ok(config) => {
                self.loader_render_config = Some(config);
                self.loader_render_error = None;
            }
            Err(error) => {
                self.loader_render_config = None;
                self.loader_render_error = Some(error.to_string());
            }
        }
        if scale <= 0.0 || !scale.is_finite() {
            self.native_startup_fonts = None;
            return;
        }
        let Some(source) = self.assets.startup_native_font_source.clone() else {
            self.native_startup_fonts = None;
            return;
        };
        let fonts = clonk_frontend::clonk_fonts::build_native_font_set_face(
            &source.bytes,
            source.face_index,
            scale,
        );
        match fonts {
            Ok(fonts) => {
                self.native_startup_fonts = Some(Arc::new(fonts));
                self.mark_menu_dirty();
            }
            Err(error) => {
                tracing::warn!(%error, scale, "failed to build scale-native startup fonts");
                self.native_startup_fonts = None;
            }
        }
    }

    fn native_font_cache_for_source(
        &self,
        source: Option<&ClassicNativeFontSource>,
    ) -> Option<Arc<clonk_frontend::clonk_fonts::NativeClonkFontSet>> {
        let scale = self.loader_render_config?.application_scale();
        if scale <= 0.0 || !scale.is_finite() {
            return None;
        }
        let source = source?;
        match clonk_frontend::clonk_fonts::build_native_font_set_face(
            &source.bytes,
            source.face_index,
            scale,
        ) {
            Ok(fonts) => Some(Arc::new(fonts)),
            Err(error) => {
                tracing::warn!(%error, scale, "failed to build scale-native active fonts");
                None
            }
        }
    }

    fn can_defer_native_main_menu_text(&self, scale: f32) -> bool {
        self.mode == AppMode::Menu
            && self.startup_view == StartupView::MainMenu
            && !self.startup_dialog_fade_active()
            && self.message_dialogs.is_empty()
            && self.context_menu.is_none()
            && !self.startup_element_tooltip_pending()
            && self
                .native_startup_fonts
                .as_ref()
                .is_some_and(|fonts| (fonts.scale() - scale).abs() < f32::EPSILON)
    }

    fn can_defer_native_loader_text(&self, scale: f32) -> bool {
        self.mode == AppMode::Loading
            && self.message_dialogs.is_empty()
            && !self
                .network_start_wait
                .as_ref()
                .is_some_and(|wait| wait.visible)
            && scale > 0.0
            && scale.is_finite()
            && self
                .loader_render_config
                .is_some_and(|config| config.application_scale() == scale)
            && self
                .native_startup_fonts
                .as_ref()
                .is_some_and(|fonts| fonts.scale() == scale)
    }

    fn can_defer_native_game_messages(&self, scale: f32) -> bool {
        self.mode == AppMode::Running
            && scale > 0.0
            && scale.is_finite()
            // The physical commit point is after the filtered logical frame.
            // Keep C4Viewport/C4GUI z-order authoritative whenever a layer
            // that C++ draws after game messages is visible.
            && self.ingame_selection_frame().is_none()
            && !self.runtime_help_visible
            && !self.runtime_halt_active()
            && self
                .runtime_flash_message
                .as_ref()
                .is_none_or(|message| message.remaining_draws == 0)
            && self.runtime_client_list.is_none()
            && self.network_chart_dialog.is_none()
            && self.scoreboard_dialog.is_none()
            && self.game_over_dialog.is_none()
            && self.game_option_input_dialog.is_none()
            && self.message_dialogs.is_empty()
            && self.context_menu.is_none()
            && self
                .native_startup_fonts
                .as_ref()
                .is_some_and(|fonts| fonts.scale() == scale)
    }

    fn can_present_ordered_native_text(&self, scale: f32) -> bool {
        let ordered_loading_overlay = self.mode == AppMode::Loading
            && (!self.message_dialogs.is_empty()
                || self
                    .network_start_wait
                    .as_ref()
                    .is_some_and(|wait| wait.visible))
            && self
                .loader_render_config
                .is_some_and(|config| config.application_scale() == scale);
        (matches!(self.mode, AppMode::Menu | AppMode::Running) || ordered_loading_overlay)
            && scale > 0.0
            && scale.is_finite()
            && self
                .native_startup_fonts
                .as_ref()
                .is_some_and(|fonts| (fonts.scale() - scale).abs() < f32::EPSILON)
    }

    fn begin_native_text_capture(&mut self, clear_to_transparent: bool) {
        let surface = self.graphics.surface_mut();
        surface.clear_clip();
        if clear_to_transparent && !self.retained_gpu_ordered_capture_active {
            surface.fill(Color::transparent());
        }
        surface.begin_clonk_text_capture();
        if self.retained_gpu_ordered_capture_active {
            debug_assert!(!surface.is_gpu_scene_capture_active());
            surface.begin_gpu_scene_capture();
        }
    }

    fn finish_native_base_batch(&mut self, frame: &mut [u8], plan: &mut NativePresentationPlan) {
        let surface = self.graphics.surface_mut();
        let text = surface.take_clonk_text_capture();
        let gpu_recorder = surface.take_gpu_scene_capture();
        if gpu_recorder.is_none() {
            if surface.pixels().len() == frame.len() {
                frame.copy_from_slice(surface.pixels());
            } else {
                copy_surface(surface.pixels(), surface.width(), surface.height(), frame);
            }
        }
        plan.batches.push(NativePresentationBatch {
            logical_layer: None,
            clip: None,
            native_loader_text: false,
            text,
            fonts: None,
            gpu_recorder,
        });
    }

    fn finish_native_overlay_batch(&mut self, plan: &mut NativePresentationPlan) {
        Self::capture_native_overlay_batch(self.graphics.surface_mut(), plan, None);
    }

    fn capture_native_overlay_batch(
        surface: &mut Surface,
        plan: &mut NativePresentationPlan,
        isolated_clip: Option<Rect>,
    ) {
        let text = surface.take_clonk_text_capture();
        let gpu_recorder = surface.take_gpu_scene_capture();
        // Additive passes can contribute RGB while preserving a transparent
        // destination alpha. Retain those bytes for ordered replay too.
        let has_raster = gpu_recorder.is_none()
            && surface.pixels().iter().any(|byte| *byte != 0);
        let has_gpu_commands = gpu_recorder
            .as_ref()
            .is_some_and(|recorder| !recorder.is_empty());
        if has_raster || has_gpu_commands || !text.is_empty() {
            let clip = isolated_clip.filter(|clip| {
                has_raster
                    && !text.is_empty()
                    && text
                        .iter()
                        .all(|command| command.clip == Some(*clip))
            });
            plan.batches.push(NativePresentationBatch {
                logical_layer: has_raster.then(|| surface.pixels().to_vec()),
                clip,
                native_loader_text: false,
                text,
                fonts: None,
                gpu_recorder,
            });
        }
    }

    fn commit_pending_native_base(&mut self, frame: &mut [u8]) {
        let mut plan = self.pending_native_presentation.take().unwrap_or_default();
        self.finish_native_base_batch(frame, &mut plan);
        self.pending_native_presentation = Some(plan);
    }

    fn commit_pending_native_loader_base(&mut self, frame: &mut [u8]) {
        self.commit_pending_native_base(frame);
        self.pending_native_presentation
            .as_mut()
            .and_then(|plan| plan.batches.last_mut())
            .expect("loader base batch was just committed")
            .native_loader_text = true;
    }

    fn commit_pending_native_overlay(&mut self) {
        let mut plan = self.pending_native_presentation.take().unwrap_or_default();
        self.finish_native_overlay_batch(&mut plan);
        self.pending_native_presentation = Some(plan);
    }

    fn next_native_overlay_parts(
        graphics: &mut GraphicsSystem,
        pending_native_presentation: &mut Option<NativePresentationPlan>,
        retained_gpu_capture: bool,
    ) {
        Self::next_native_overlay_parts_with_clip(
            graphics,
            pending_native_presentation,
            None,
            retained_gpu_capture,
        );
    }

    fn next_native_overlay_parts_with_clip(
        graphics: &mut GraphicsSystem,
        pending_native_presentation: &mut Option<NativePresentationPlan>,
        isolated_clip: Option<Rect>,
        retained_gpu_capture: bool,
    ) {
        let mut plan = pending_native_presentation.take().unwrap_or_default();
        {
            let surface = graphics.surface_mut();
            Self::capture_native_overlay_batch(surface, &mut plan, isolated_clip);
        }
        *pending_native_presentation = Some(plan);
        let surface = graphics.surface_mut();
        surface.clear_clip();
        if !retained_gpu_capture {
            surface.fill(Color::transparent());
        }
        surface.begin_clonk_text_capture();
        if retained_gpu_capture {
            debug_assert!(!surface.is_gpu_scene_capture_active());
            surface.begin_gpu_scene_capture();
        }
    }

    fn next_pending_native_overlay(&mut self) {
        Self::next_native_overlay_parts(
            &mut self.graphics,
            &mut self.pending_native_presentation,
            self.retained_gpu_ordered_capture_active,
        );
    }

    fn next_pending_native_overlay_with_clip(&mut self, isolated_clip: Rect) {
        Self::next_native_overlay_parts_with_clip(
            &mut self.graphics,
            &mut self.pending_native_presentation,
            Some(isolated_clip),
            self.retained_gpu_ordered_capture_active,
        );
    }

    fn replay_pending_native_presentation(
        &mut self,
        composer: &mut clonk_scaling::OrderedFrameComposer<'_>,
    ) -> Result<()> {
        let Some(plan) = self.pending_native_presentation.take() else {
            return Ok(());
        };
        let _renderer_config = clonk_frontend::activate_advanced_renderer_config(
            self.graphics.advanced_renderer_config(),
        );
        let NativePresentationPlan {
            batches,
            monitor_gamma,
        } = plan;
        let default_fonts = self
            .native_startup_fonts
            .as_deref()
            .context("scale-native font bundle disappeared before presentation")?;
        let startup_gamma = self.startup_fragment_gamma();
        for batch in batches {
            if let Some(layer) = batch.logical_layer {
                let target = composer.begin_layer();
                anyhow::ensure!(
                    layer.len() == target.len(),
                    "native presentation layer has {} bytes, expected {}",
                    layer.len(),
                    target.len()
                );
                target.copy_from_slice(&layer);
                if let Some(clip) = batch.clip {
                    composer.composite_layer_with_clip(clip);
                } else {
                    composer.composite_layer();
                }
            }
            if batch.native_loader_text {
                let loader = self.loader_screen.as_ref().ok_or_else(|| {
                    self.loader_boundary("selected classic loader disappeared before presentation")
                })?;
                composer
                    .draw_native(|physical, geometry| -> Result<()> {
                        let (width, height) = geometry.physical_size();
                        let mut surface = RgbaSurfaceViewMut::new(width, height, physical)?;
                        let (logical_width, logical_height) = geometry.logical_size();
                        loader.render_native_text_to(
                            &mut surface,
                            default_fonts,
                            logical_width,
                            logical_height,
                            Some(&startup_gamma),
                        )?;
                        Ok(())
                    })
                    .map_err(|error| self.loader_boundary(error.to_string()))?;
            }
            if batch.text.is_empty() {
                continue;
            }
            let fonts = batch.fonts.as_deref().unwrap_or(default_fonts);
            composer.draw_native(|physical, geometry| -> Result<()> {
                let (width, height) = geometry.physical_size();
                let mut surface = RgbaSurfaceViewMut::new(width, height, physical)?;
                fonts.draw_captured_text_to(&mut surface, &batch.text, geometry.logical_size());
                Ok(())
            })?;
        }
        if let Some(gamma) = monitor_gamma {
            composer.draw_native(|physical, _| gamma.apply_to_rgba_bytes(physical));
        }
        Ok(())
    }

    fn classic_loader_render_preconditions_ready(&self) -> bool {
        if self.loader_error.is_some()
            || self.loader_render_error.is_some()
            || self.loader_screen.is_none()
        {
            return false;
        }
        let Some(config) = self.loader_render_config else {
            return false;
        };
        config.application_scale() == 1.0
            || self
                .native_startup_fonts
                .as_ref()
                .is_some_and(|fonts| fonts.scale() == config.application_scale())
    }

    fn sync_scenario_game_option_bounds(&mut self) {
        let Some(fonts) = self.assets.clonk_fonts.as_deref() else {
            return;
        };
        let surface = self.graphics.surface();
        let bounds = if let Some(lobby) = self.classic_host_lobby.as_ref() {
            lobby
                .controller
                .layout(surface.width() as i32, surface.height() as i32, fonts)
                .game_option_strip
        } else if let Some(lobby) = self.network_lobby.as_mut() {
            lobby.sync_classic_controller();
            lobby
                .controller
                .layout(surface.width() as i32, surface.height() as i32, fonts)
                .game_option_strip
        } else {
            startup_scensel_game_option_bounds(
                surface.width() as i32,
                surface.height() as i32,
                fonts,
            )
        };
        self.scenario_game_options.set_bounds(bounds);
    }

    fn sync_network_lobby_game_option_state(&mut self) {
        if self.classic_host_lobby.is_some() {
            // The exact host lobby owns the retained strip lifecycle.
            return;
        }
        let Some((is_host, countdown)) = self
            .network_lobby
            .as_ref()
            .map(|lobby| (lobby.is_host, lobby.countdown.is_some()))
        else {
            return;
        };
        let context = if is_host {
            GameOptionContext::LobbyHost
        } else {
            GameOptionContext::LobbyClient
        };

        let league = self.network_is_league;
        let fair_crew = self.engine.use_fair_crew();
        let fair_crew_strength = self.engine.fair_crew_strength();
        let fair_crew_forced = self.engine.fair_crew_forced();
        if self.scenario_game_options.context() != context {
            let mut values = self.scenario_game_options.values().clone();
            values.lobby_is_league = league;
            values.fair_crew = fair_crew;
            values.fair_crew_strength = fair_crew_strength;
            values.lobby_fair_crew_forced = fair_crew_forced;
            values.countdown = countdown;
            self.scenario_game_options = GameOptionButtons::new(context, values);
        } else {
            self.scenario_game_options.set_lobby_league(league);
            self.scenario_game_options.set_lobby_fair_crew_state(
                fair_crew,
                fair_crew_strength,
                fair_crew_forced,
            );
            self.scenario_game_options.set_countdown(countdown);
        }
        self.sync_scenario_game_option_bounds();
    }

    /// The reconstructed (non-exact-host) network lobby adapter is receiving
    /// startup input.
    fn joined_network_lobby_active(&self) -> bool {
        self.mode == AppMode::Menu
            && self.startup_view == StartupView::NetworkLobby
            && self.classic_host_lobby.is_none()
            && self.network_lobby.is_some()
    }


    fn sync_scenario_game_option_constraint(&mut self) {
        let constraint = scenario_fair_crew_constraint(self.menu_state.selected_scenario());
        self.scenario_game_options
            .set_selector_fair_crew_constraint(constraint);
    }

    fn startup_network_transition_active(&self) -> bool {
        self.mode != AppMode::Running && self.startup_network_connection.is_some()
    }

    fn startup_network_join_progress_active(&self) -> bool {
        self.startup_network_connection
            .as_ref()
            .is_some_and(|connection| connection.purpose == StartupNetworkPurpose::Join)
            && self.message_dialogs.iter().any(|dialog| {
                matches!(
                    dialog.continuation,
                    MessageDialogContinuation::StartupNetworkConnectProgress
                )
            })
    }

    fn startup_network_transition_blocks_input(&self) -> bool {
        self.startup_network_transition_active() && !self.startup_network_join_progress_active()
    }

    fn startup_dialog_fade_active(&self) -> bool {
        self.mode == AppMode::Menu && self.startup_dialog_fade.is_some()
    }

    fn classic_host_lobby_active(&self) -> bool {
        self.mode == AppMode::Menu
            && self.startup_view == StartupView::NetworkLobby
            && self.classic_host_lobby.is_some()
    }

    fn note_classic_lobby_non_pointer_input(&mut self) {
        if self.mode != AppMode::Menu || self.startup_view != StartupView::NetworkLobby {
            return;
        }
        if let Some(lobby) = self.classic_host_lobby.as_mut() {
            lobby.controller.note_non_pointer_input();
        } else if let Some(lobby) = self.network_lobby.as_mut() {
            lobby.sync_classic_controller();
            lobby.controller.note_non_pointer_input();
        } else {
            return;
        }
        self.scenario_game_options.note_non_pointer_input();
    }

    fn has_or_will_have_network_lobby(&self) -> bool {
        self.network.is_some()
            && matches!(self.mode, AppMode::Menu)
            && (self.network_lobby.is_some() || self.classic_host_lobby.is_some())
    }

    fn league_player_auth_settings(&self) -> clonk_network::LeagueAuthRequestHead {
        if let Some(auth) = self.league_auth_session.as_ref() {
            return auth.clone();
        }
        match self.network_mode.as_ref() {
            Some(NetworkMode::Client(settings)) => settings.league_auth.clone(),
            Some(NetworkMode::Host(_)) | None => {
                load_league_auth_settings(self.app_paths.as_ref())
            }
        }
    }

    fn current_league_server_name(&self) -> String {
        if let Some(NetworkMode::Host(HostSettings {
            prepared: Some(prepared),
            ..
        })) = self.network_mode.as_ref()
        {
            return prepared
                .league_config()
                .map(|league| league_server_name(&league.endpoint))
                .unwrap_or_default();
        }
        if let Some(join_data) = self.pending_network_join_data.as_ref() {
            return league_server_name(&legacy_presentation_text(
                join_data.parameters.league_address.as_bytes(),
            ));
        }
        retained_client_league_server_name(self.network_mode.as_ref())
    }

    fn set_league_player_auth_settings(&mut self, auth: clonk_network::LeagueAuthRequestHead) {
        if let Some(NetworkMode::Client(settings)) = self.network_mode.as_mut() {
            settings.league_auth = auth.clone();
        }
        if let Some(paths) = self.app_paths.as_ref() {
            if let Err(error) = persist_league_account_preference(paths, &auth.account) {
                tracing::warn!(%error, "failed to persist league account preference");
            }
        }
        self.league_auth_session = Some(auth);
    }

    fn league_login_prompt_required(&self) -> bool {
        self.league_player_auth_settings().password.is_empty()
            || !load_league_auto_login(self.app_paths.as_ref())
    }

    fn league_signup_strings(&self) -> clonk_frontend::league_signup::LeagueSignupStrings {
        clonk_frontend::league_signup::LeagueSignupStrings {
            caption_on_server: self.runtime_resource_text(
                "IDS_DLG_LEAGUESIGNUPON",
                "League Login on %s",
            ),
            login_message: self.runtime_resource_text(
                "IDS_MSG_PASSWORDFORPLAYER",
                "League login for player %s:",
            ),
            registration_message: self.runtime_resource_text(
                "IDS_MSG_LEAGUE_REGISTRATION",
                "Player %s: This is your first login at the league. Your can specify your desired league user name and league password below.",
            ),
            account_label: self.runtime_resource_text(
                "IDS_CTL_LEAGUE_ACCOUNT",
                "League user name:",
            ),
            password_checkbox: self.runtime_resource_text(
                "IDS_CTL_LEAGUE_CHK_PLRPW",
                "Specify league password",
            ),
            password_checkbox_tooltip: self.runtime_resource_text(
                "IDS_DESC_LEAGUECHECKPASSWORD",
                "Enable to enter your own password. If you do not enter a password of your own, the personal WebCode will be used which is already stored on this system.",
            ),
            password_label: self.runtime_resource_text(
                "IDS_CTL_LEAGUE_PLRPW",
                "League password:",
            ),
            password_confirmation_label: self.runtime_resource_text(
                "IDS_CTL_LEAGUE_PLRPW2",
                "League password (repeat):",
            ),
            ok: self.runtime_resource_text("IDS_DLG_OK", "&OK"),
            cancel: self.runtime_resource_text("IDS_DLG_CANCEL", "Cancel"),
            close_tooltip: self.runtime_resource_text("IDS_MNU_CLOSE", "Close"),
            invalid_entry_caption: self
                .runtime_resource_text("IDS_DLG_INVALIDENTRY", "Invalid Entry"),
            missing_account: self.runtime_resource_text(
                "IDS_MSG_LEAGUEMISSINGUSERNAME",
                "Please enter a user name!",
            ),
            invalid_account: self.runtime_resource_text(
                "IDS_MSG_LEAGUEINVALIDUSERNAME",
                "The user name contains invalid characters.",
            ),
            account_too_short: self.runtime_resource_text(
                "IDS_MSG_LEAGUEUSERNAMETOOSHORT",
                "The user name is too short.",
            ),
            missing_password: self.runtime_resource_text(
                "IDS_MSG_LEAGUEMISSINGPASSWORD",
                "Please enter a password!",
            ),
            password_mismatch: self.runtime_resource_text(
                "IDS_MSG_LEAGUEMISMATCHPASSWORD",
                "Repeated password mismatch. Please re-enter password!",
            ),
            cancelled_caption: self
                .runtime_resource_text("IDS_DLG_LEAGUESIGNUP", "League Login"),
            cancelled_message: self.runtime_resource_text(
                "IDS_MSG_LEAGUESIGNUPCANCELLED",
                "League login for player %s cancelled. Without login this player can not take part in this round!",
            ),
        }
    }

    fn open_league_signup_dialog(
        &mut self,
        mode: clonk_frontend::league_signup::LeagueSignupMode,
        auth: clonk_network::LeagueAuthRequestHead,
        continuation: LeaguePlayerAuthContinuation,
    ) -> Result<(), EngineError> {
        self.guard_classic_global_gui_bootstrap()?;
        Self::guard_gui_overlay_result(
            "C4LeagueSignupDialog",
            self.assets
                .league_signup_resources()
                .context("exact C4LeagueSignupDialog resource set is absent")
                .and_then(|resources| resources.validate()),
        )?;
        let player_name = Self::league_auth_continuation_player_name(&continuation);
        let server_name = Self::league_auth_continuation_server_name(&continuation).to_owned();
        let account_preference = match mode {
            clonk_frontend::league_signup::LeagueSignupMode::Login => {
                legacy_presentation_text(auth.account.as_bytes())
            }
            clonk_frontend::league_signup::LeagueSignupMode::Registration => {
                legacy_presentation_text(load_network_nick(self.app_paths.as_ref()).as_bytes())
            }
        };
        let password_preference = match mode {
            clonk_frontend::league_signup::LeagueSignupMode::Login => {
                legacy_presentation_text(auth.password.as_bytes())
            }
            clonk_frontend::league_signup::LeagueSignupMode::Registration => String::new(),
        };
        let config =
            clonk_frontend::league_signup::LeagueSignupConfig::new(player_name, server_name, mode)
                .with_preferences(account_preference, password_preference);
        let pointer_position = self.running_pointer_position;
        self.close_context_menu_silently();
        self.cancel_underlying_interaction();
        self.league_signup_consumed_keys.clear();
        self.league_signup_pointer_capture = false;
        // MouseInput carries no coordinates. Retain the application's last
        // pointer so a stationary cursor can click the newly opened dialog.
        self.league_signup_pointer_position = pointer_position;
        self.league_signup_dialog = Some(PendingLeagueSignupDialog {
            controller: clonk_frontend::league_signup::LeagueSignupController::new(
                config,
                self.league_signup_strings(),
            ),
            auth,
            continuation,
        });
        self.mark_menu_dirty();
        Ok(())
    }

    fn process_league_signup_actions(
        &mut self,
        actions: Vec<clonk_frontend::league_signup::LeagueSignupAction>,
    ) -> Result<(), EngineError> {
        use clonk_frontend::league_signup::{LeagueSignupAction, LeagueSignupMode};

        let sounds = self
            .league_signup_dialog
            .as_mut()
            .map(|dialog| dialog.controller.take_sound_events())
            .unwrap_or_default();
        for sound in sounds {
            self.play_ui_sound(match sound {
                clonk_frontend::league_signup::LeagueSignupSound::ArrowHit => "ArrowHit",
                clonk_frontend::league_signup::LeagueSignupSound::Click => "Click",
            });
        }
        if !actions.is_empty() {
            self.mark_menu_dirty();
        }
        for action in actions {
            match action {
                LeagueSignupAction::FocusChanged(_)
                | LeagueSignupAction::TextChanged { .. }
                | LeagueSignupAction::PasswordEnabledChanged(_) => {}
                LeagueSignupAction::OpenEditContextMenu(request) => {
                    let field = request.field;
                    let entries = request
                        .items
                        .into_iter()
                        .map(|item| {
                            let (label_key, tooltip_key) = match item.command {
                                clonk_frontend::league_signup::LeagueSignupEditContextCommand::Cut => {
                                    ("IDS_DLG_CUT", "IDS_DLGTIP_CUT")
                                }
                                clonk_frontend::league_signup::LeagueSignupEditContextCommand::Copy => {
                                    ("IDS_DLG_COPY", "IDS_DLGTIP_COPY")
                                }
                                clonk_frontend::league_signup::LeagueSignupEditContextCommand::Paste => {
                                    ("IDS_DLG_PASTE", "IDS_DLGTIP_PASTE")
                                }
                                clonk_frontend::league_signup::LeagueSignupEditContextCommand::Clear => {
                                    ("IDS_DLG_CLEAR", "IDS_DLGTIP_CLEAR")
                                }
                                clonk_frontend::league_signup::LeagueSignupEditContextCommand::SelectAll => {
                                    ("IDS_DLG_SELALL", "IDS_DLGTIP_SELALL")
                                }
                            };
                            ContextMenuEntry::new(startup_resource_string(
                                self.app_paths.as_ref(),
                                label_key,
                                &item.label,
                            ))
                            .with_tooltip(startup_resource_string(
                                self.app_paths.as_ref(),
                                tooltip_key,
                                &item.tooltip,
                            ))
                            .with_icon(ContextMenuIcon::None)
                            .with_action(AppContextMenuCommand::LeagueSignupEdit {
                                field,
                                command: item.command,
                            })
                        })
                        .collect();
                    self.open_context_menu_at(entries, request.anchor)?;
                }
                LeagueSignupAction::ClipboardTransfer { field, text, cut } => {
                    match arboard::Clipboard::new()
                        .and_then(|mut clipboard| clipboard.set_text(text))
                    {
                        Ok(()) if cut => {
                            let layout = self.league_signup_layout();
                            let fonts = self.assets.clonk_fonts.clone();
                            let follow_up = layout
                                .as_ref()
                                .zip(fonts.as_deref())
                                .and_then(|(layout, fonts)| {
                                    self.league_signup_dialog.as_mut().map(|dialog| {
                                        dialog.controller.confirm_clipboard_cut(
                                            field,
                                            layout,
                                            &fonts.text,
                                        )
                                    })
                                })
                                .unwrap_or_default();
                            self.process_league_signup_actions(follow_up)?;
                        }
                        Ok(()) => {}
                        Err(error) => {
                            tracing::warn!(%error, "failed to copy league-signup edit text");
                        }
                    }
                }
                LeagueSignupAction::ValidationFailed(failure) => {
                    self.league_signup_pointer_capture = false;
                    if let Some(dialog) = self.league_signup_dialog.as_mut() {
                        dialog.controller.cancel_interaction();
                    }
                    self.push_message_dialog(
                        clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                            failure.message,
                            failure.caption,
                            clonk_frontend::message_dialog::MessageDialogIcon::ERROR,
                        ),
                        MessageDialogContinuation::None,
                    )?;
                }
                LeagueSignupAction::Submitted(submission) => {
                    let Some(pending) = self.league_signup_dialog.take() else {
                        break;
                    };
                    self.league_signup_pointer_capture = false;
                    let mut auth = pending.auth;
                    let mode = pending.controller.mode();
                    match mode {
                        LeagueSignupMode::Login => {
                            auth.account = LegacyCString::from_bytes(submission.account)
                                .expect("validated league account cannot contain NUL");
                            auth.password =
                                LegacyCString::from_bytes(submission.password.unwrap_or_default())
                                    .expect("validated league password cannot contain NUL");
                            auth.new_account = LegacyCString::default();
                            auth.new_password = LegacyCString::default();
                            self.set_league_player_auth_settings(auth.clone());
                        }
                        LeagueSignupMode::Registration => {
                            auth.new_account = LegacyCString::from_bytes(submission.account)
                                .expect("validated league account cannot contain NUL");
                            auth.new_password = submission.password.map_or_else(
                                || auth.password.clone(),
                                |password| {
                                    LegacyCString::from_bytes(password)
                                        .expect("validated league password cannot contain NUL")
                                },
                            );
                        }
                    }
                    let _ = self.begin_league_player_auth_exchange(
                        pending.continuation,
                        auth,
                        mode,
                    )?;
                    break;
                }
                LeagueSignupAction::Aborted { caption, message } => {
                    let Some(pending) = self.league_signup_dialog.take() else {
                        break;
                    };
                    self.league_signup_pointer_capture = false;
                    self.cancelled_league_signup_continuation = Some(pending.continuation);
                    self.push_message_dialog(
                        clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                            message,
                            caption,
                            clonk_frontend::message_dialog::MessageDialogIcon::NOTIFY,
                        ),
                        MessageDialogContinuation::LeagueSignupCancelled,
                    )?;
                    break;
                }
            }
        }
        Ok(())
    }

    fn league_auth_continuation_has_current(
        continuation: &LeaguePlayerAuthContinuation,
    ) -> bool {
        match continuation {
            LeaguePlayerAuthContinuation::InitialClient { request, index, .. }
            | LeaguePlayerAuthContinuation::RuntimePlayer { request, index, .. } => {
                *index < request.players.len()
            }
            LeaguePlayerAuthContinuation::StartupHost { players, index, .. } => {
                *index < players.len()
            }
        }
    }

    fn league_auth_continuation_player_name(
        continuation: &LeaguePlayerAuthContinuation,
    ) -> String {
        let player = match continuation {
            LeaguePlayerAuthContinuation::InitialClient { request, index, .. }
            | LeaguePlayerAuthContinuation::RuntimePlayer { request, index, .. } => {
                &request.players[*index]
            }
            LeaguePlayerAuthContinuation::StartupHost { players, index, .. } => &players[*index],
        };
        legacy_presentation_text(control_player_effective_name(player))
    }

    fn league_auth_continuation_server_name(
        continuation: &LeaguePlayerAuthContinuation,
    ) -> &str {
        match continuation {
            LeaguePlayerAuthContinuation::InitialClient { server_name, .. }
            | LeaguePlayerAuthContinuation::RuntimePlayer { server_name, .. }
            | LeaguePlayerAuthContinuation::StartupHost { server_name, .. } => server_name,
        }
    }

    fn advance_league_auth_continuation(continuation: &mut LeaguePlayerAuthContinuation) {
        match continuation {
            LeaguePlayerAuthContinuation::InitialClient { index, .. }
            | LeaguePlayerAuthContinuation::RuntimePlayer { index, .. }
            | LeaguePlayerAuthContinuation::StartupHost { index, .. } => *index += 1,
        }
    }

    fn reject_league_auth_continuation_player(
        continuation: &mut LeaguePlayerAuthContinuation,
    ) {
        match continuation {
            LeaguePlayerAuthContinuation::InitialClient { request, index, .. }
            | LeaguePlayerAuthContinuation::RuntimePlayer { request, index, .. } => {
                request.players.swap_remove(*index);
            }
            LeaguePlayerAuthContinuation::StartupHost { players, index, .. } => {
                players.swap_remove(*index);
            }
        }
    }

    fn apply_league_auth_response(
        continuation: &mut LeaguePlayerAuthContinuation,
        response: &clonk_network::LeagueAuthResponse,
    ) -> bool {
        match continuation {
            LeaguePlayerAuthContinuation::InitialClient { request, index, .. }
            | LeaguePlayerAuthContinuation::RuntimePlayer { request, index, .. } => {
                response.apply_player_auth(&mut request.players[*index])
            }
            LeaguePlayerAuthContinuation::StartupHost { players, index, .. } => {
                response.apply_player_auth(&mut players[*index])
            }
        }
    }

    fn finish_league_auth_continuation(
        &mut self,
        continuation: LeaguePlayerAuthContinuation,
    ) -> LeaguePlayerAuthStatus {
        match continuation {
            LeaguePlayerAuthContinuation::InitialClient { request, .. } => {
                let submitted = self.network.as_ref().is_some_and(|network| {
                    network
                        .submit_player_info_update(request)
                        .inspect_err(
                            |error| tracing::error!(%error, "failed to submit initial PlayerInfo"),
                        )
                        .is_ok()
                });
                if self.pending_network_join_data.is_some() {
                    self.initial_lobby_status_ack_pending = submitted
                        && self
                            .pending_network_join_data
                            .as_ref()
                            .is_some_and(|join_data| {
                                join_data.status.state == clonk_network::NETWORK_STATE_LOBBY
                            });
                    self.acknowledge_initial_lobby_status_if_ready();
                }
                LeaguePlayerAuthStatus::Completed(submitted)
            }
            LeaguePlayerAuthContinuation::StartupHost {
                mode,
                manager,
                selected_scenario,
                purpose,
                players,
                ..
            } => {
                let (sender, receiver) = mpsc::channel();
                if sender.send(Ok((mode, manager))).is_err() {
                    return LeaguePlayerAuthStatus::Completed(false);
                }
                let mut connection =
                    StartupNetworkConnection::new(receiver, selected_scenario, purpose);
                connection.authenticated_league_players = Some(players);
                self.startup_network_connection = Some(connection);
                LeaguePlayerAuthStatus::Completed(true)
            }
            LeaguePlayerAuthContinuation::RuntimePlayer {
                request,
                host,
                alternate_resource_id,
                alternate_color,
                ..
            } => {
                if request.players.is_empty() {
                    return LeaguePlayerAuthStatus::Completed(false);
                }
                let completed = self
                    .finish_runtime_network_player_add(
                        request,
                        host,
                        alternate_resource_id,
                        alternate_color,
                    )
                    .inspect_err(|error| {
                        tracing::error!(%error, "failed to finish authenticated runtime player add")
                    })
                    .is_ok();
                LeaguePlayerAuthStatus::Completed(completed)
            }
        }
    }

    fn begin_league_player_auth_exchange(
        &mut self,
        mut continuation: LeaguePlayerAuthContinuation,
        auth: clonk_network::LeagueAuthRequestHead,
        mode: clonk_frontend::league_signup::LeagueSignupMode,
    ) -> Result<LeaguePlayerAuthStatus, EngineError> {
        if self.pending_league_player_auth.is_some() {
            tracing::warn!("refusing to replace an in-flight league player authentication");
            return Ok(LeaguePlayerAuthStatus::Completed(false));
        }
        if !Self::league_auth_continuation_has_current(&continuation) {
            return Ok(self.finish_league_auth_continuation(continuation));
        }
        let exchange = match &continuation {
            LeaguePlayerAuthContinuation::InitialClient { request, index, .. }
            | LeaguePlayerAuthContinuation::RuntimePlayer { request, index, .. } => {
                match self.network.as_ref() {
                    Some(network) => network.begin_authenticate_league_player(
                        auth.clone(),
                        &request.players[*index],
                    ),
                    None => Ok(None),
                }
            }
            LeaguePlayerAuthContinuation::StartupHost {
                manager,
                players,
                index,
                ..
            } => manager.begin_authenticate_league_player(auth.clone(), &players[*index]),
        };
        let exchange = match exchange {
            Ok(Some(exchange)) => exchange,
            Ok(None) => {
                Self::reject_league_auth_continuation_player(&mut continuation);
                return self.continue_league_player_auth(continuation);
            }
            Err(error) => {
                tracing::warn!(%error, "failed to begin league player authentication");
                Self::reject_league_auth_continuation_player(&mut continuation);
                return self.continue_league_player_auth(continuation);
            }
        };
        let player = Self::league_auth_continuation_player_name(&continuation);
        let server = Self::league_auth_continuation_server_name(&continuation).to_string();
        let message = format_resource_string(
            self.runtime_resource_text(
                "IDS_MSG_TRYLEAGUESIGNUP",
                "League login for player %s on %s...",
            ),
            &[&player, &server],
        );
        let caption = self.runtime_resource_text("IDS_DLG_LEAGUESIGNUP", "League Login");
        self.push_message_dialog(
            clonk_frontend::message_dialog::MessageDialogState::new(
                message,
                caption,
                clonk_frontend::message_dialog::MessageDialogButtons::CANCEL,
                clonk_frontend::message_dialog::MessageDialogIcon::Standard(3),
                clonk_frontend::message_dialog::MessageDialogSize::Regular,
                false,
            ),
            MessageDialogContinuation::LeaguePlayerAuthWait,
        )?;
        self.pending_league_player_auth = Some(PendingLeaguePlayerAuth {
            continuation,
            stage: PendingLeaguePlayerAuthStage::Waiting(exchange),
            auth,
            mode,
        });
        Ok(LeaguePlayerAuthStatus::Pending)
    }

    fn continue_league_player_auth(
        &mut self,
        continuation: LeaguePlayerAuthContinuation,
    ) -> Result<LeaguePlayerAuthStatus, EngineError> {
        if self.pending_league_player_auth.is_some() || self.league_signup_dialog.is_some() {
            tracing::warn!("refusing to replace an in-flight league player authentication");
            return Ok(LeaguePlayerAuthStatus::Completed(false));
        }
        if !Self::league_auth_continuation_has_current(&continuation) {
            return Ok(self.finish_league_auth_continuation(continuation));
        }
        let auth = self.league_player_auth_settings();
        if self.league_login_prompt_required() {
            self.open_league_signup_dialog(
                clonk_frontend::league_signup::LeagueSignupMode::Login,
                auth,
                continuation,
            )?;
            return Ok(LeaguePlayerAuthStatus::Pending);
        }
        self.begin_league_player_auth_exchange(
            continuation,
            auth,
            clonk_frontend::league_signup::LeagueSignupMode::Login,
        )
    }

    fn begin_startup_host_league_auth(
        &mut self,
        mode: NetworkMode,
        manager: NetworkManager,
        selected_scenario: Option<(String, String)>,
        purpose: StartupNetworkPurpose,
    ) -> Result<LeaguePlayerAuthStatus, EngineError> {
        let (players, server_name) = match &mode {
            NetworkMode::Host(HostSettings {
                prepared: Some(prepared),
                ..
            }) => (
                prepared
                    .pending_initial_league_players()
                    .unwrap_or_default()
                    .to_vec(),
                prepared
                    .league_config()
                    .map(|league| league_server_name(&league.endpoint))
                    .unwrap_or_default(),
            ),
            NetworkMode::Host(_) | NetworkMode::Client(_) => (Vec::new(), String::new()),
        };
        self.continue_league_player_auth(LeaguePlayerAuthContinuation::StartupHost {
            mode,
            manager,
            selected_scenario,
            purpose,
            players,
            index: 0,
            server_name,
        })
    }

    fn dismiss_league_player_auth_wait(&mut self) {
        let Some(index) = self.message_dialogs.iter().rposition(|dialog| {
            matches!(
                dialog.continuation,
                MessageDialogContinuation::LeaguePlayerAuthWait
            )
        }) else {
            return;
        };
        self.remove_message_dialog_at(index);
        self.mark_menu_dirty();
    }

    fn clear_pending_league_player_auth(&mut self) {
        self.pending_league_player_auth = None;
        let mut removed = false;
        while let Some(index) = self.message_dialogs.iter().rposition(|dialog| {
            matches!(
                dialog.continuation,
                MessageDialogContinuation::LeaguePlayerAuthWait
                    | MessageDialogContinuation::LeaguePlayerAuthWelcome
                    | MessageDialogContinuation::LeaguePlayerAuthError
                    | MessageDialogContinuation::LeaguePlayerAuthCancelled
            )
        }) {
            self.remove_message_dialog_at(index);
            removed = true;
        }
        if removed {
            self.mark_menu_dirty();
        }
    }

    fn reopen_league_player_auth_form(
        &mut self,
        mut pending: PendingLeaguePlayerAuth,
    ) -> Result<(), EngineError> {
        // C4Network2::LeaguePlrAuth clears only the process-global password
        // after the error/cancellation modal closes. Its loop keeps the
        // local Password value for registration's no-custom-password
        // fallback, while a login retry starts with an empty password edit.
        self.clear_remembered_league_password();
        pending.auth.new_account = LegacyCString::default();
        pending.auth.new_password = LegacyCString::default();
        if pending.mode == clonk_frontend::league_signup::LeagueSignupMode::Login {
            pending.auth.password = LegacyCString::default();
        }
        self.open_league_signup_dialog(
            pending.mode,
            pending.auth,
            pending.continuation,
        )
    }

    fn push_league_player_check_error(&mut self, message: String) -> Result<(), EngineError> {
        self.push_message_dialog(
            clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                message,
                self.runtime_resource_text("IDS_DLG_ERROR", "Error"),
                clonk_frontend::message_dialog::MessageDialogIcon::ERROR,
            ),
            MessageDialogContinuation::None,
        )
    }

    fn poll_league_player_auth(&mut self) -> Result<(), EngineError> {
        let Some(pending) = self.pending_league_player_auth.as_ref() else {
            return Ok(());
        };
        let PendingLeaguePlayerAuthStage::Waiting(exchange) = &pending.stage else {
            return Ok(());
        };
        let Some(result) = exchange.try_complete() else {
            return Ok(());
        };
        let mut pending = self
            .pending_league_player_auth
            .take()
            .expect("polled league Auth state exists");
        self.dismiss_league_player_auth_wait();
        match result {
            Ok(response)
                if response.is_register()
                    && pending.mode
                        == clonk_frontend::league_signup::LeagueSignupMode::Login =>
            {
                if !response.account.is_empty() {
                    pending.auth.account = response.account;
                }
                pending.auth.new_account = LegacyCString::default();
                pending.auth.new_password = LegacyCString::default();
                self.open_league_signup_dialog(
                    clonk_frontend::league_signup::LeagueSignupMode::Registration,
                    pending.auth,
                    pending.continuation,
                )?;
            }
            Ok(response)
                if Self::apply_league_auth_response(
                    &mut pending.continuation,
                    &response,
                ) =>
            {
                if pending.mode
                    == clonk_frontend::league_signup::LeagueSignupMode::Registration
                    && !response.account.is_empty()
                {
                    pending.auth.account.clone_from(&response.account);
                }
                if load_league_auto_login(self.app_paths.as_ref()) {
                    Self::advance_league_auth_continuation(&mut pending.continuation);
                    let _ = self.continue_league_player_auth(pending.continuation)?;
                    return Ok(());
                }
                let player = Self::league_auth_continuation_player_name(&pending.continuation);
                let server =
                    Self::league_auth_continuation_server_name(&pending.continuation).to_string();
                let message = if response.message.is_empty() {
                    if response.account.is_empty() {
                        format_resource_string(
                            self.runtime_resource_text(
                                "IDS_MSG_LEAGUEPLAYERSIGNUP",
                                "Player: %s|Server: %s",
                            ),
                            &[&player, &server],
                        )
                    } else {
                        let account = legacy_presentation_text(response.account.as_bytes());
                        format_resource_string(
                            self.runtime_resource_text(
                                "IDS_MSG_LEAGUEPLAYERSIGNUPAS",
                                "Player: %s|League user name: %s|Server: %s",
                            ),
                            &[&player, &account, &server],
                        )
                    }
                } else {
                    legacy_presentation_text(response.message.as_bytes())
                };
                pending.stage = PendingLeaguePlayerAuthStage::Decision;
                self.push_message_dialog(
                    clonk_frontend::message_dialog::MessageDialogState::new(
                        message,
                        self.runtime_resource_text(
                            "IDS_DLG_LEAGUESIGNUPCONFIRM",
                            "Confirm League Login",
                        ),
                        clonk_frontend::message_dialog::MessageDialogButtons::OK_CANCEL,
                        clonk_frontend::message_dialog::MessageDialogIcon::Extended(8),
                        clonk_frontend::message_dialog::MessageDialogSize::Regular,
                        false,
                    ),
                    MessageDialogContinuation::LeaguePlayerAuthWelcome,
                )?;
                self.pending_league_player_auth = Some(pending);
            }
            Ok(response) => {
                if pending.mode
                    == clonk_frontend::league_signup::LeagueSignupMode::Registration
                    && !response.account.is_empty()
                {
                    pending.auth.account.clone_from(&response.account);
                }
                pending.auth.new_account = LegacyCString::default();
                pending.auth.new_password = LegacyCString::default();
                let server_message = if response.is_success() && response.auid.is_empty() {
                    self.runtime_resource_text(
                        "IDS_MSG_LEAGUESERVERREPLYWITHOUTA",
                        "League server reply without authentication-id!",
                    )
                } else {
                    legacy_presentation_text(response.message.as_bytes())
                };
                let message = format_resource_string(
                    self.runtime_resource_text(
                        "IDS_MSG_LEAGUESERVERMSG",
                        "League server reply: %s",
                    ),
                    &[&server_message],
                );
                pending.stage = PendingLeaguePlayerAuthStage::Decision;
                self.push_message_dialog(
                    clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                        message,
                        self.runtime_resource_text(
                            "IDS_DLG_LEAGUESIGNUPFAILED",
                            "League Login Failed",
                        ),
                        clonk_frontend::message_dialog::MessageDialogIcon::ERROR,
                    ),
                    MessageDialogContinuation::LeaguePlayerAuthError,
                )?;
                self.pending_league_player_auth = Some(pending);
            }
            Err(error) => {
                let message = format_resource_string(
                    self.runtime_resource_text(
                        "IDS_MSG_LEAGUESERVERMSG",
                        "League server reply: %s",
                    ),
                    &[&error.to_string()],
                );
                pending.stage = PendingLeaguePlayerAuthStage::Decision;
                self.push_message_dialog(
                    clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                        message,
                        self.runtime_resource_text(
                            "IDS_DLG_LEAGUESIGNUPFAILED",
                            "League Login Failed",
                        ),
                        clonk_frontend::message_dialog::MessageDialogIcon::ERROR,
                    ),
                    MessageDialogContinuation::LeaguePlayerAuthError,
                )?;
                self.pending_league_player_auth = Some(pending);
            }
        }
        Ok(())
    }

    fn finalize_prepared_host_players(
        &mut self,
        manager: &NetworkManager,
        prepared: &mut prepared_host_bootstrap::PreparedHostBootstrap,
        is_league: bool,
        authenticated_league_players: Option<Vec<clonk_engine::ControlPlayerInfoEntry>>,
    ) -> Result<(), String> {
        let auth = self.league_player_auth_settings();
        let league = prepared
            .host_config()
            .initial_join_snapshot
            .as_ref()
            .map(|snapshot| synchronized_league_name(&snapshot.parameters))
            .and_then(clonk_engine::LegacyCString::from_bytes)
            .unwrap_or_default();
        let already_authenticated = authenticated_league_players;
        let mut players = already_authenticated.clone().unwrap_or_else(|| {
            prepared
                .pending_initial_league_players()
                .unwrap_or_default()
                .to_vec()
        });
        // JoinLocalPlayer obtains AUIDs before ID allocation, team assignment,
        // or attribute conflict resolution.
        if is_league && already_authenticated.is_none() {
            retain_player_infos_with_cpp_swap_remove(&mut players, |player| {
                match manager.authenticate_league_player(auth.clone(), player) {
                    Ok(true) => true,
                    Ok(false) => false,
                    Err(error) => {
                        tracing::warn!(name = ?player.name, %error, "host league player authentication failed");
                        false
                    }
                }
            });
        }
        let mut oracle = ProcessInitialHostTeamAssignmentOracle::new(
            self.generated_team_name_template.clone(),
        );
        let refusal_template = self.runtime_resource_text(
            "IDS_MSG_LEAGUEJOINREFUSED",
            "League server has refused the join of player %s: %s",
        );
        let mut check_errors = Vec::new();
        let finalized = prepared
            .finalize_initial_league_players(
                players,
                &mut oracle,
                // The callback runs after full host normalization. Restore
                // script rows are appended only after it returns.
                |player| {
                    if !is_league {
                        return true;
                    }
                    match manager.check_league_player(&league, player) {
                        Ok(network::LeaguePlayerCheck::Accepted) => true,
                        Ok(network::LeaguePlayerCheck::Unavailable) => false,
                        Ok(network::LeaguePlayerCheck::Rejected(message)) => {
                            let player_name = legacy_presentation_text(player.name.as_bytes());
                            let message = legacy_presentation_text(message.as_bytes());
                            check_errors.push(format_resource_string(
                                refusal_template.clone(),
                                &[&player_name, &message],
                            ));
                            false
                        }
                        Err(error) => {
                            tracing::warn!(player_id = player.id, %error, "host league player check failed");
                            check_errors.push(error.to_string());
                            false
                        }
                    }
                },
            );
        for message in check_errors {
            self.push_league_player_check_error(message)
                .map_err(|error| error.to_string())?;
        }
        finalized.map_err(|error| error.to_string())?;
        Ok(())
    }

    /// `C4Network2::isLobbyActive` is false as soon as a non-lobby status is
    /// installed, even while the UI still renders its transition screen.
    fn league_player_auth_lobby_active(&self) -> bool {
        if self.mode != AppMode::Menu
            || self
                .pending_client_start_status
                .is_some_and(|status| status.state != clonk_network::NETWORK_STATE_LOBBY)
            || self
                .runtime_network_status_barrier
                .is_some_and(|pending| pending.status.state != clonk_network::NETWORK_STATE_LOBBY)
        {
            return false;
        }
        self.network_lobby.is_some() || self.classic_host_lobby_active()
    }

    fn set_scensel_dialog_focus(&mut self, focus: ScenselDialogFocus) {
        self.menu_state.set_dialog_focus(focus);
        if focus != ScenselDialogFocus::Options {
            self.scenario_game_options.set_focused_button(None);
        }
    }

    fn scensel_focus_snapshot(&self) -> ScenselFocusSnapshot {
        ScenselFocusSnapshot {
            dialog: self.menu_state.dialog_focus(),
            option: self.scenario_game_options.focused_button(),
        }
    }

    fn restore_scensel_focus(&mut self, snapshot: ScenselFocusSnapshot) {
        self.set_scensel_dialog_focus(snapshot.dialog);
        if snapshot.dialog == ScenselDialogFocus::Options {
            self.scenario_game_options.set_focused_button(snapshot.option);
        }
    }

    fn abort_scenario_rename(&mut self) -> bool {
        let had_rename = self.menu_state.rename_edit.is_some();
        if let Some(previous_focus) = self.menu_state.abort_renaming() {
            self.restore_scensel_focus(previous_focus);
        }
        had_rename
    }

    fn restore_scensel_rename_pointer_focus(&mut self) {
        let focus = self.scensel_rename_pointer_focus;
        if self.mode == AppMode::Menu && self.startup_view == StartupView::ScenarioBrowser {
            if let Some(focus) = focus {
                self.restore_scensel_focus(focus);
            }
        }
    }

    fn activate_scensel_after_gamepad_low_rename_abort(&mut self) -> Result<(), EngineError> {
        if !self.abort_scenario_rename() {
            return Ok(());
        }
        if self.menu_state.current_map().is_some() {
            self.start_selected_map_scenario_from_ui()
        } else {
            self.handle_menu_input(|menu| menu.menu().handle_key_down(KeyCode::Enter))?;
            self.handle_menu_input(|menu| menu.menu().handle_key_up(KeyCode::Enter))
        }
    }

    fn focus_scensel_option_edge(&mut self, backwards: bool) {
        let button = if backwards {
            self.scenario_game_options
                .context()
                .buttons()
                .last()
                .copied()
        } else {
            self.scenario_game_options
                .context()
                .buttons()
                .first()
                .copied()
        };
        self.menu_state
            .set_dialog_focus(ScenselDialogFocus::Options);
        self.scenario_game_options.set_focused_button(button);
    }

    /// Recursive `C4GUI::Dialog::AdvanceFocus` around the game-option child.
    /// Search -> List -> Back -> optional Definitions -> Options -> Open.
    fn advance_scensel_dialog_focus(&mut self, backwards: bool) {
        let focus = if self.scenario_game_options.focused_button().is_some() {
            ScenselDialogFocus::Options
        } else {
            self.menu_state.dialog_focus()
        };
        let definitions = self.menu_state.definition_checkbox_enabled;
        match (focus, backwards) {
            (ScenselDialogFocus::Search, false) => {
                self.set_scensel_dialog_focus(ScenselDialogFocus::List)
            }
            (ScenselDialogFocus::Search, true) => {
                self.set_scensel_dialog_focus(ScenselDialogFocus::Open)
            }
            (ScenselDialogFocus::List, false) => {
                self.set_scensel_dialog_focus(ScenselDialogFocus::Back)
            }
            (ScenselDialogFocus::List, true) => {
                self.set_scensel_dialog_focus(ScenselDialogFocus::Search)
            }
            (ScenselDialogFocus::Back, false) if definitions => {
                self.set_scensel_dialog_focus(ScenselDialogFocus::Definitions)
            }
            (ScenselDialogFocus::Back, false) => self.focus_scensel_option_edge(false),
            (ScenselDialogFocus::Back, true) => {
                self.set_scensel_dialog_focus(ScenselDialogFocus::List)
            }
            (ScenselDialogFocus::Definitions, false) => self.focus_scensel_option_edge(false),
            (ScenselDialogFocus::Definitions, true) => {
                self.set_scensel_dialog_focus(ScenselDialogFocus::Back)
            }
            (ScenselDialogFocus::Options, false) => {
                self.set_scensel_dialog_focus(ScenselDialogFocus::Open)
            }
            (ScenselDialogFocus::Options, true) if definitions => {
                self.set_scensel_dialog_focus(ScenselDialogFocus::Definitions)
            }
            (ScenselDialogFocus::Options, true) => {
                self.set_scensel_dialog_focus(ScenselDialogFocus::Back)
            }
            (ScenselDialogFocus::Open, false) => {
                self.set_scensel_dialog_focus(ScenselDialogFocus::Search)
            }
            (ScenselDialogFocus::Open, true) => self.focus_scensel_option_edge(true),
        }
    }

