    fn resize(&mut self, width: u32, height: u32) -> Result<()> {
        self.reject_classic_global_gui_bootstrap()?;
        let restart_same_dialog_fade = self.startup_dialog_fade.as_ref().and_then(|fade| {
            (fade.outgoing == Some(fade.incoming)).then_some(fade.incoming)
        });
        self.startup_dialog_fade = None;
        self.close_context_menu_silently();
        // Native resize tears down/repositions dialog elements and therefore
        // clears CMouse's owned hover element. A retained screen coordinate
        // must not acquire whichever control moves underneath it.
        self.startup_tooltip.pointer_left();
        self.release_message_dialog_pointer_elements();
        self.menu_frame_cache = None;
        self.context_menu_pointer_capture = None;
        if let Some(dialog) = self.league_signup_dialog.as_mut() {
            dialog.controller.cancel_interaction();
            dialog.controller.reset_location();
        }
        self.league_signup_consumed_keys.clear();
        self.league_signup_pointer_capture = false;
        self.league_signup_pointer_position = None;
        if let Some(dialog) = self.game_option_input_dialog.as_mut() {
            dialog.controller.cancel_interaction();
        }
        self.scenario_game_options.cancel_interaction();
        self.game_option_input_consumed_keys.clear();
        self.game_option_consumed_keys.clear();
        self.game_option_input_pointer_capture = None;
        self.game_option_input_pointer_position = None;
        self.game_option_input_last_click = None;
        self.game_option_pointer_capture = false;
        self.running_pointer_position = None;
        self.ingame_menu_close_pointer_capture = None;
        self.script_menu_close_pointer_capture = None;
        self.scoreboard_pointer_left();
        self.cancel_network_chart_pointer_capture();
        self.menu_title_drag = None;
        for menu in self.ingame_menu.by_player.values_mut() {
            menu.reset_location();
        }
        for state in self.script_menu_presentations.values_mut() {
            reset_script_menu_presentation_location(state);
        }
        self.mark_menu_dirty();
        let cursor_atlas = self.current_cursor_atlas();
        let hud_graphics = self.current_hud_graphics();
        let game_palette = self.current_game_palette();
        let liquid_animation = self.current_liquid_animation();
        let mut graphics = GraphicsSystem::new(
            width,
            height,
            self.fallback_ground,
            &self.scenario_label,
            self.assets.font_arc(),
            Arc::clone(&self.sprite_cache),
            cursor_atlas,
            hud_graphics,
        );
        graphics.inherit_liquid_animation_cycle(&self.graphics);
        graphics.inherit_pending_observer_scroll(&self.graphics);
        graphics.inherit_debug_draw_state(&self.graphics);
        graphics.inherit_runtime_sprite_filtering(&self.graphics);
        graphics.inherit_advanced_renderer_config(&self.graphics);
        graphics.set_clonk_fonts(self.assets.clonk_fonts.clone());
        graphics.set_game_palette(game_palette);
        graphics.set_liquid_animation(liquid_animation);
        graphics.surface_mut().fill(Color::opaque(16, 28, 52));
        self.graphics = graphics;
        self.sync_scenario_game_option_bounds();
        self.graphics.set_sky(self.sky.clone());
        self.graphics
            .set_material_texture_surfaces(Arc::clone(&self.material_texture_images));
        self.graphics
            .set_material_render_info(Arc::clone(&self.material_render_info));

        // Startup models are constructed before boot relinquishes Loading.
        // macOS may apply the real fullscreen size during that interval, so
        // keep their retained geometry in sync in every mode. Otherwise the
        // first Main frame (including buttons and its two footer labels) uses
        // the smaller pre-fullscreen coordinates even though GraphicsSystem
        // already owns the final surface.
        let width_f = width as f32;
        let height_f = height as f32;
        self.menu_state.menu().resize(width_f, height_f);
        self.menu_state.set_pointer_position(None);
        self.main_menu_state.resize(width_f, height_f);
        self.main_menu_state.set_pointer_position(None);

        if self.mode == AppMode::Menu {
            if let Some(dialog) = self.startup_network_dialog.as_mut() {
                dialog.resize(width as i32, height as i32);
                dialog.pointer_left();
            }
            if let Some(dialog) = self.startup_player_dialog.as_mut() {
                if let (Some(fonts), Some(book)) = (
                    self.assets.clonk_fonts.as_deref(),
                    self.assets.plrsel_book_fonts.as_deref(),
                ) {
                    dialog.resize_with_fonts(width as i32, height as i32, fonts, book);
                } else {
                    dialog.resize(width as i32, height as i32);
                }
                dialog.pointer_left();
            }
            if let Some(pending) = self.startup_player_properties_dialog.as_mut() {
                pending.controller.resize(width as i32, height as i32);
                pending.controller.pointer_left();
            }
            if let (Some(dialog), Some(fonts), Some(book)) = (
                self.startup_options_dialog.as_mut(),
                self.assets.clonk_fonts.as_deref(),
                self.assets.options_book_fonts.as_deref(),
            ) {
                dialog.resize(width as i32, height as i32, fonts, book);
                dialog.pointer_left();
            }
            if let Some(pending) = self.startup_options_advanced_dialog.as_mut() {
                pending.controller.resize(width as i32, height as i32);
                pending.controller.cancel_interaction();
            }
            if let (Some(dialog), Some(fonts)) = (
                self.startup_about_dialog.as_mut(),
                self.assets.clonk_fonts.as_deref(),
            ) {
                dialog.resize(width as i32, height as i32, fonts);
                dialog.pointer_left();
            }
            if let Some(lobby) = self.network_lobby.as_mut() {
                lobby.update_layout(width_f, height_f);
                lobby.pointer_left();
            }
            self.cancel_classic_lobby_interaction();
            if let Some(controller) = self.definition_selector.as_mut() {
                controller.cancel_interaction();
            }
        }
        if let Some(dialog) = self.runtime_client_list.as_mut() {
            dialog.pointer_left();
        }
        if self.external_irc_dialog_visible {
            if let Some(dialog) = self.external_irc_dialog.as_mut() {
                dialog.resize(width as i32, height as i32);
                dialog.set_chat_bounds_override(Some(
                    clonk_frontend::startup_netdlg::NetDlgController::standalone_chat_bounds(
                        width as i32,
                        height as i32,
                    ),
                ));
                dialog.pointer_left();
            }
        }
        if let Some(dialog) = restart_same_dialog_fade {
            self.begin_startup_dialog_fade(dialog);
        }
        Ok(())
    }

    fn apply_material_library(&mut self) {
        self.engine
            .set_mission_access_store(self.mission_access.clone());
        self.engine
            .set_show_commands_request_store(self.show_commands_requests.clone());
        self.engine
            .set_control_key_names(configured_control_key_names(&self.bindings));
        self.engine
            .set_control_host(!matches!(self.network_mode.as_ref(), Some(NetworkMode::Client(_))));
        self.engine.set_needed_material_resource_strings(
            self.needed_material_need.clone(),
            self.needed_material_none.clone(),
        );
        self.engine
            .set_object_no_dig_resource_string(self.object_no_dig.clone());
        {
            let [undefined, no_construction, no_room, no_level, no_other] =
                self.construction_check_feedback.clone();
            self.engine.set_construction_check_resource_strings(
                undefined,
                no_construction,
                no_room,
                no_level,
                no_other,
            );
        }
        if let Some(names) = self.default_rank_names.as_ref() {
            self.engine.set_default_rank_names(names.clone());
        }
        if let Some(materials) = self.material_library.as_ref() {
            self.engine.set_materials((**materials).clone());
        } else {
            self.engine.set_materials(MaterialSet::default());
        }
    }

    fn apply_material_library_to(&self, engine: &mut Engine) {
        engine.set_mission_access_store(self.mission_access.clone());
        engine.set_show_commands_request_store(self.show_commands_requests.clone());
        engine.set_control_key_names(configured_control_key_names(&self.bindings));
        engine
            .set_control_host(!matches!(self.network_mode.as_ref(), Some(NetworkMode::Client(_))));
        engine.set_needed_material_resource_strings(
            self.needed_material_need.clone(),
            self.needed_material_none.clone(),
        );
        engine.set_object_no_dig_resource_string(self.object_no_dig.clone());
        {
            let [undefined, no_construction, no_room, no_level, no_other] =
                self.construction_check_feedback.clone();
            engine.set_construction_check_resource_strings(
                undefined,
                no_construction,
                no_room,
                no_level,
                no_other,
            );
        }
        if let Some(names) = self.default_rank_names.as_ref() {
            engine.set_default_rank_names(names.clone());
        }
        if let Some(materials) = self.material_library.as_ref() {
            engine.set_materials((**materials).clone());
        } else {
            engine.set_materials(MaterialSet::default());
        }
        engine.set_standard_names(self.standard_names.clone());
        self.install_global_scripts_to(engine);
    }

    /// Installs the System.c4g global scripts (the C++ `Game.ScriptEngine`
    /// scripts) into a fresh game engine.
    fn install_global_scripts_to(&self, engine: &mut Engine) {
        if self.system_scripts.is_empty() {
            return;
        }
        let loaded = engine.install_global_scripts(&self.system_scripts);
        tracing::debug!(scripts = loaded, "installed System.c4g global scripts");
    }

    fn update_sprite_cache(&mut self) {
        self.sprite_cache = Arc::new(self.object_sprites.clone());
        self.graphics
            .set_object_sprites(Arc::clone(&self.sprite_cache));
    }

    fn ensure_local_player_registered(&mut self) -> Result<(), EngineError> {
        if self.engine.player(self.local_owner).is_some() {
            return Ok(());
        }
        let control = self.local_controls.initialize(LocalControlInit {
            owner: self.local_owner,
            preferred_set: 0,
            prefers_mouse: true,
            gamepads_enabled: self.gamepads_enabled,
            replay: false,
            disable_mouse: !self.mouse_control_allowed,
        });
        let config = PlayerConfig::new(self.local_owner, self.player_name.clone());
        if let Err(error) = self
            .engine
            .register_player_with_runtime_control(config, control.runtime_control())
        {
            self.remove_local_control_assignment(self.local_owner);
            return Err(error);
        }
        self.mouse_control = self.local_controls.mouse_owner().is_some();
        Ok(())
    }

    /// `C4Game::JoinPlayer` for the standalone app's local player
    /// (C4Game.cpp:3511-3534 -> C4PlayerList::Join, C4PlayerList.cpp:
    /// 271-318): joins through the engine's C4Player::Init/ScenarioInit
    /// port, so the scenario's [PlayerN] ready crew is placed
    /// (PlaceReadyCrew, C4Player.cpp:481-570), InitializePlayer is
    /// broadcast (C4Player.cpp:769-775) and the cursor lands on the
    /// hi-rank crew member (FinalInit -> AdjustCursorCommand,
    /// C4Player.cpp:794). The joined number becomes the local owner
    /// (C4PlayerList::GetFreeNumber, C4PlayerList.cpp:189-201).
    fn join_local_player(&mut self) -> Result<(), EngineError> {
        if self.engine.player(self.local_owner).is_some() {
            return Ok(());
        }
        let retained_player_info_core = self
            .selected_player_file
            .as_ref()
            .map(|player| player.exact_info_core());
        let (
            name,
            color_dw,
            pref_color,
            pref_position,
            crew,
            control_style,
            auto_context_menu,
            preferred_control,
            prefers_mouse,
            score,
            rounds,
            rounds_won,
            rounds_lost,
            total_playing_time,
        ) = self
            .selected_player_file
            .as_ref()
            .map(|player| {
                let name = if self.player_name == "Player" {
                    player.name.clone()
                } else {
                    self.player_name.clone()
                };
                (
                    name,
                    player.pref_color_dw & 0x00ff_ffff,
                    player.pref_color,
                    player.pref_position,
                    player.crew.clone(),
                    player.pref_control_style,
                    player.pref_auto_context_menu,
                    player.pref_control,
                    player.pref_mouse,
                    player.score,
                    player.rounds,
                    player.rounds_won,
                    player.rounds_lost,
                    player.total_playing_time,
                )
            })
            .unwrap_or_else(|| {
                // The C++ new-player dialog opts fresh players into
                // Jump'n'Run controls (C4StartupPlrSelDlg.cpp:1103-1113).
                (
                    self.player_name.clone(),
                    0xff,
                    0,
                    0,
                    Vec::new(),
                    true,
                    true,
                    0,
                    true,
                    0,
                    0,
                    0,
                    0,
                    0,
                )
            });
        let predicted_owner = self.engine.next_player_number();
        let control = self.local_controls.initialize(LocalControlInit {
            owner: predicted_owner,
            preferred_set: preferred_control,
            prefers_mouse,
            gamepads_enabled: self.gamepads_enabled,
            replay: false,
            disable_mouse: !self.mouse_control_allowed,
        });
        let config = JoinPlayerConfig {
            name,
            player_info_id: 0,
            score,
            rounds,
            rounds_won,
            rounds_lost,
            total_playing_time,
            team: None,
            color_dw,
            pref_color,
            pref_position,
            crew,
            startup_player_count: 1,
            control_style,
            auto_context_menu,
        };
        let join_result = if let Some(core) = retained_player_info_core {
            self.engine.join_player_with_profile_core(
                config,
                clonk_engine::PlayerAtClient::HOST,
                "Local",
                None,
                control.runtime_control(),
                core,
            )
        } else {
            self.engine
                .join_player_with_runtime_control(config, control.runtime_control())
        };
        let joined = match join_result {
            Ok(joined) => joined,
            Err(error) => {
                self.remove_local_control_assignment(predicted_owner);
                return Err(error);
            }
        };
        debug_assert_eq!(joined.number(), predicted_owner);
        self.local_owner = joined.number();
        self.mouse_control = self.local_controls.mouse_owner().is_some();
        if matches!(
            joined,
            clonk_engine::JoinPlayerOutcome::AwaitingTeamSelection { .. }
        ) {
            self.open_initial_team_selection(joined.number());
        }
        Ok(())
    }

    fn derive_ground_height(engine: &Engine, fallback: i32) -> i32 {
        let fallback = fallback.max(0);
        engine
            .landscape()
            .and_then(|landscape| {
                landscape
                    .surface()
                    .iter()
                    .copied()
                    .filter(|height| *height >= 0)
                    .max()
            })
            .unwrap_or(fallback)
    }

    fn rebuild_definition_sprites(&mut self) {
        let mut sprites = self.assets.base_sprite_map().clone();
        let particle_sprites = particle_sprite_map(&self.engine);
        let mut rotateable_definitions = HashSet::new();
        let mut debug_geometry = HashMap::new();
        for definition_id in self.engine.definition_ids() {
            if self.engine.definition_rotateable(definition_id) != 0 {
                rotateable_definitions.insert(definition_id.to_string());
            }
            let actions = self
                .engine
                .definition_action_graphics(definition_id)
                .unwrap_or_default();

            let default_key = sprite_map_key(definition_id, None);
            let graphics_scale = self.engine.definition_graphics_scale(definition_id);
            let shape_facet = self.engine.definition_shape_rect(definition_id);
            let fire_top = self.engine.definition_fire_top(definition_id);
            let rotateable = self.engine.definition_rotateable(definition_id);
            let line = self.engine.definition_line(definition_id);
            let stretch_growth = self.engine.definition_stretch_growth(definition_id);
            let top_face = self.engine.definition_top_face(definition_id);
            debug_geometry.insert(
                definition_id.to_string(),
                DefinitionDebugGeometry {
                    name: self
                        .engine
                        .definition_name(definition_id)
                        .map(str::to_string),
                    entrance: self.engine.definition_entrance_rect(definition_id),
                    collection: self.engine.definition_collection_rect(definition_id),
                    solid_mask: self.engine.definition_solid_mask(definition_id),
                },
            );
            if let Some(image) = self.engine.definition_sprite_image(definition_id, None) {
                let width = image.width();
                let height = image.height();
                let mask = image
                    .color_mask()
                    .map(|mask| ColorByOwnerMask::new(width, height, mask));
                let pixels = image.into_pixels();
                sprites.insert(
                    default_key.clone(),
                    DefinitionSprite {
                        graphics_scale,
                        shape: shape_facet,
                        fire_top,
                        rotateable,
                        line,
                        stretch_growth,
                        top_face,
                        image: ImageData::from_arc(width, height, pixels),
                        actions: actions.clone(),
                        color_mask: mask,
                    },
                );
            } else if let Some(image) = self.engine.definition_picture_image(definition_id) {
                let width = image.width();
                let height = image.height();
                let mask = image
                    .color_mask()
                    .map(|mask| ColorByOwnerMask::new(width, height, mask));
                sprites.insert(
                    default_key.clone(),
                    DefinitionSprite {
                        graphics_scale,
                        shape: shape_facet,
                        fire_top,
                        rotateable,
                        line,
                        stretch_growth,
                        top_face,
                        image: ImageData::from_arc(width, height, image.into_pixels()),
                        actions: actions.clone(),
                        color_mask: mask,
                    },
                );
            } else if let Some(existing) = sprites.get_mut(&default_key) {
                existing.graphics_scale = graphics_scale;
                existing.actions = actions.clone();
                existing.shape = shape_facet;
                existing.fire_top = fire_top;
                existing.rotateable = rotateable;
                existing.line = line;
                existing.stretch_growth = stretch_growth;
                existing.top_face = top_face;
            }

            for variant in self.engine.definition_sprite_variant_names(definition_id) {
                if let Some(image) = self
                    .engine
                    .definition_sprite_image(definition_id, Some(&variant))
                {
                    let width = image.width();
                    let height = image.height();
                    let mask = image
                        .color_mask()
                        .map(|mask| ColorByOwnerMask::new(width, height, mask));
                    let pixels = image.into_pixels();
                    let key = sprite_map_key(definition_id, Some(&variant));
                    sprites.insert(
                        key,
                        DefinitionSprite {
                            graphics_scale,
                            shape: shape_facet,
                            fire_top,
                            rotateable,
                            line,
                            stretch_growth,
                            top_face,
                            image: ImageData::from_arc(width, height, pixels),
                            actions: actions.clone(),
                            color_mask: mask,
                        },
                    );
                }
            }
        }
        self.graphics
            .set_rotateable_definitions(rotateable_definitions);
        self.graphics.set_definition_debug_geometry(debug_geometry);
        self.graphics
            .set_particle_sprites(Arc::new(particle_sprites));
        if sprites != self.object_sprites {
            self.object_sprites = sprites;
            self.update_sprite_cache();
        }
    }

    /// Fills the C4ObjectInfo-backed crew fields (`pObj->Info`): name, rank
    /// and rank name. The cursor label above the flashing mark draws from
    /// these (C4Game::DrawCursors, src/C4Game.cpp:1873-1887) — independent of
    /// the ShowPortraits flag gating [`Self::populate_crew_portraits`].
    fn populate_crew_infos(&self, players: &mut [PlayerOverlay]) {
        for player in players.iter_mut() {
            for crew in player.crew.iter_mut() {
                if let Some(info) = self.engine.crew_object_info(crew.object_id) {
                    crew.info_name = Some(c4_presentation_text(&info.name));
                    crew.rank = info.rank;
                    crew.rank_name = Some(info.rank_name.clone());
                }
            }
        }
    }

    /// Prepare the object-name half of `C4Object::DrawTopFace`. Geometry,
    /// viewport clipping and the final player-color draw stay in the frontend,
    /// while the app resolves C4ObjectInfo/definition names and the
    /// process-local invisible-player flag.
    fn crew_name_overlays(&self, viewports: &[ViewportInput<'_>]) -> Vec<CrewNameOverlay> {
        if (!self.display_flags.player_names && !self.display_flags.clonk_names)
            || self.engine.film_replay()
        {
            return Vec::new();
        }

        let mut viewers = Vec::new();
        for viewport in viewports {
            if !viewers.contains(&viewport.owner) {
                viewers.push(viewport.owner);
            }
        }

        self.snapshot
            .objects
            .iter()
            .filter(|object| {
                object.status == clonk_engine::ObjectStatus::Normal
                    && object.ocf & clonk_engine::ocf::CREW_MEMBER != 0
                    && object.container.is_none()
            })
            .filter_map(|object| {
                let owner = self.engine.player(object.owner)?;
                let invisible = self
                    .control_player_infos
                    .get(owner.player_info_id())
                    .is_some_and(|info| {
                        info.flags & clonk_engine::PLAYER_INFO_FLAG_INVISIBLE != 0
                    });
                if invisible {
                    return None;
                }

                let player_name = c4_presentation_text(owner.name());
                let clonk_name = object
                    .custom_name
                    .as_deref()
                    .filter(|name| !name.is_empty())
                    .or_else(|| {
                        self.engine
                            .crew_object_info(object.id)
                            .map(|info| info.name.as_str())
                    })
                    .or_else(|| self.engine.definition_name(&object.definition_id))
                    .unwrap_or(object.definition_id.as_str());
                let clonk_name = c4_presentation_text(clonk_name);
                let text = match (
                    self.display_flags.player_names,
                    self.display_flags.clonk_names,
                ) {
                    (true, true) => format!("{clonk_name} ({player_name})"),
                    (true, false) => player_name,
                    (false, true) => clonk_name,
                    (false, false) => unreachable!("empty display-name flags returned above"),
                };

                let visible_to = viewers
                    .iter()
                    .copied()
                    .filter(|viewer| {
                        if *viewer == object.owner {
                            return false;
                        }
                        let Some(viewer_player) = self.engine.player(*viewer) else {
                            return *viewer == OWNER_NONE;
                        };
                        !viewer_player.is_hostile_towards(object.owner)
                            && !owner.is_hostile_towards(*viewer)
                    })
                    .collect::<Vec<_>>();
                (!visible_to.is_empty()).then_some(CrewNameOverlay {
                    object_id: object.id,
                    text,
                    visible_to,
                })
            })
            .collect()
    }

    /// Fills the presentation half of the crew overlays: the selected info
    /// portrait (C4ObjectInfo::Draw, src/C4ObjectInfo.cpp:308-320), the crew
    /// name and rank (src/C4ObjectInfo.cpp:330-370) and the def rank symbols
    /// (src/C4ObjectInfo.cpp:334-341).
    fn populate_crew_portraits(&self, players: &mut [PlayerOverlay]) {
        // Config.Graphics.ShowPortraits from the Display menu
        // (C4MainMenu.cpp:872) gates only the portrait branch.
        let show_portraits = self.display_flags.portraits;
        let mut portrait_cache: HashMap<(String, String), Option<CursorPortraitImages>> =
            HashMap::new();
        let mut rank_cache: HashMap<String, Option<ImageData>> = HashMap::new();

        for player in players.iter_mut() {
            for crew in player.crew.iter_mut() {
                let current_portrait = self
                    .engine
                    .crew_object_info(crew.object_id)
                    .and_then(|info| {
                        crew.label = c4_presentation_text(&info.name);
                        crew.rank = info.rank;
                        info.portraits.current.clone()
                    });
                let Some(object) = self.snapshot.object(crew.object_id) else {
                    crew.portrait = None;
                    crew.portrait_owner_overlay = None;
                    crew.portrait_owner_color = u32::MAX;
                    continue;
                };

                let definition_id = object.definition_id.clone();
                let owner_color = cursor_portrait_owner_color(&self.snapshot, object.owner);
                let portrait = if show_portraits {
                    current_portrait.and_then(|portrait| {
                        let source = portrait.source?;
                        portrait_cache
                            .entry((source.clone(), portrait.name.clone()))
                            .or_insert_with(|| {
                                self.engine
                                    .definition_named_portrait_graphics_image(
                                        &source,
                                        &portrait.name,
                                    )
                                    .map(cursor_portrait_images)
                            })
                            .clone()
                    })
                } else {
                    None
                };
                crew.portrait = portrait.as_ref().map(|portrait| portrait.base.clone());
                crew.portrait_owner_overlay =
                    portrait.and_then(|portrait| portrait.owner_overlay);
                crew.portrait_owner_color = owner_color;
                crew.rank_symbols = rank_cache
                    .entry(definition_id.clone())
                    .or_insert_with(|| {
                        self.engine
                            .definition_rank_symbols_image(&definition_id)
                            .map(|image| {
                                ImageData::from_arc(image.width(), image.height(), image.pixels())
                            })
                    })
                    .clone();
                crew.rank_symbol_count = self
                    .engine
                    .definition_rank_symbol_count(&definition_id);
            }
        }
    }

    fn handle_text_input(&mut self, character: char) -> Result<(), EngineError> {
        self.guard_classic_global_gui_bootstrap()?;
        self.startup_tooltip.note_non_pointer_input();
        self.note_classic_lobby_non_pointer_input();
        if let Some(dialog) = self.runtime_client_list.as_mut() {
            dialog.note_non_pointer_input();
        }
        if self.mode == AppMode::Menu {
            self.menu_frame_cache = None;
        }
        if self.startup_network_transition_blocks_input() {
            return Ok(());
        }
        if !self.message_dialogs.is_empty() && !self.running_chat_active() {
            return Ok(());
        }
        if self.league_signup_dialog.is_some() {
            if self.context_menu.is_none() {
                let mut encoded = [0_u8; 4];
                let text = character.encode_utf8(&mut encoded);
                let layout = self.league_signup_layout();
                let fonts = self.assets.clonk_fonts.clone();
                let actions = self
                    .league_signup_dialog
                    .as_mut()
                    .map(|dialog| match (layout.as_ref(), fonts.as_deref()) {
                        (Some(layout), Some(fonts)) => dialog
                            .controller
                            .handle_text_input_with_layout(text, layout, &fonts.text),
                        _ => dialog.controller.handle_text_input(text),
                    })
                    .unwrap_or_default();
                self.process_league_signup_actions(actions)?;
            }
            return Ok(());
        }
        if self
            .runtime_client_list
            .as_ref()
            .is_some_and(|dialog| dialog.is_info_only())
        {
            return Ok(());
        }
        if self.external_irc_dialog_visible && self.context_menu.is_some() {
            return Ok(());
        }
        if self.external_irc_dialog_visible
            && (!matches!(self.mode, AppMode::Running)
                || self.runtime_default_dialog_is_top(RuntimeDefaultDialog::ExternalIrc))
        {
            let Some(fonts) = self.assets.clonk_fonts.clone() else {
                return Ok(());
            };
            let mut encoded = [0_u8; 4];
            let text = character.encode_utf8(&mut encoded);
            let actions = self
                .external_irc_dialog
                .as_mut()
                .map(|dialog| dialog.handle_text_input(text, &fonts.text))
                .unwrap_or_default();
            self.process_network_dialog_actions(actions)?;
            self.mark_menu_dirty();
            return Ok(());
        }
        if self.startup_options_advanced_dialog.is_some() {
            let mut encoded = [0_u8; 4];
            let text = character.encode_utf8(&mut encoded);
            if let Some(pending) = self.startup_options_advanced_dialog.as_mut() {
                pending.controller.handle_text_input(text);
            }
            self.mark_menu_dirty();
            return Ok(());
        }
        if self.startup_player_properties_dialog.is_some() {
            let mut encoded = [0_u8; 4];
            let text = character.encode_utf8(&mut encoded);
            let actions = self
                .startup_player_properties_dialog
                .as_mut()
                .map(|pending| pending.controller.handle_text_input(text))
                .unwrap_or_default();
            self.process_startup_player_properties_actions(actions);
            self.mark_menu_dirty();
            return Ok(());
        }
        if self.game_option_input_dialog.is_some()
            && self.context_menu.is_none()
            && (self.running_chat_controller().is_none() || self.running_chat_keyboard_active())
        {
            let Some(layout) = self.game_option_input_layout() else {
                return Ok(());
            };
            let Some(fonts) = self.assets.clonk_fonts.clone() else {
                return Ok(());
            };
            let mut encoded = [0_u8; 4];
            let input = character.encode_utf8(&mut encoded);
            let actions = self
                .game_option_input_dialog
                .as_mut()
                .map(|dialog| {
                    dialog
                        .controller
                        .handle_text_input(input, &layout, &fonts.text)
                })
                .unwrap_or_default();
            return self.finish_game_option_input_dialog_actions(actions);
        }
        if self.definition_selector.is_some() {
            return Ok(());
        }
        if let Some(menu) = self.context_menu.as_mut() {
            menu.note_non_pointer_input();
            // C4GUI::Screen routes text to pContext before the focused
            // control. ContextMenu::CharIn itself does not dispatch hotkeys;
            // those come from the KEY_Any key binding on physical key-down.
            return Ok(());
        }
        if self.mode != AppMode::Menu || character.is_ascii_control() {
            return Ok(());
        }
        if self.startup_dialog_fade_active() {
            return Ok(());
        }
        if self.classic_host_lobby_active() {
            let mut encoded = [0_u8; 4];
            let text = character.encode_utf8(&mut encoded).to_string();
            let actions = self
                .classic_host_lobby
                .as_mut()
                .map(|lobby| lobby.controller.text_input(text))
                .unwrap_or_default();
            return self.process_classic_lobby_actions(actions);
        }
        if self.startup_view == StartupView::NetworkLobby {
            let mut encoded = [0_u8; 4];
            let text = character.encode_utf8(&mut encoded).to_string();
            let actions = self
                .network_lobby
                .as_mut()
                .map(|lobby| {
                    lobby.sync_classic_controller();
                    lobby.controller.text_input(text)
                })
                .unwrap_or_default();
            return self.process_joined_lobby_controller_actions(actions);
        }
        if self.startup_view == StartupView::ScenarioBrowser
            && self.menu_state.rename_edit.is_some()
        {
            let mut encoded = [0_u8; 4];
            if let Some(rename) = self.menu_state.rename_edit.as_mut() {
                rename.edit.insert_text(character.encode_utf8(&mut encoded));
            }
            self.mark_menu_dirty();
            return Ok(());
        }
        if self.startup_view == StartupView::ScenarioBrowser && self.menu_state.search_focused() {
            let mut encoded = [0_u8; 4];
            self.menu_state
                .insert_search_text(character.encode_utf8(&mut encoded));
            self.mark_menu_dirty();
            return Ok(());
        }
        if self.startup_view == StartupView::ScenarioBrowser {
            if self.scenario_selector_discovery.is_some() {
                return Ok(());
            }
            self.handle_menu_input(|menu| menu.select_list_character(character))?;
            return Ok(());
        }
        if self.startup_view == StartupView::PlayerSelection
            && self.startup_crew_rename.is_some()
        {
            let mut encoded = [0_u8; 4];
            if let Some(rename) = self.startup_crew_rename.as_mut() {
                rename.edit.insert_text(character.encode_utf8(&mut encoded));
            }
            self.mark_menu_dirty();
            return Ok(());
        }
        if self.startup_view == StartupView::PlayerSelection {
            let actions = match self.startup_player_dialog.as_mut() {
                Some(dialog) if dialog.is_crew_mode() => dialog.handle_character(
                    character,
                    self.startup_crew_models.iter().map(|crew| crew.name.as_str()),
                ),
                Some(dialog) => dialog.handle_character(
                    character,
                    self.startup_player_models
                        .iter()
                        .map(|player| player.name.as_str()),
                ),
                None => Vec::new(),
            };
            if !actions.is_empty() {
                self.process_player_dialog_actions(actions)?;
                self.mark_menu_dirty();
            }
            return Ok(());
        }
        if self.startup_view != StartupView::NetworkGame {
            return Ok(());
        }
        self.mark_menu_dirty();
        let mut encoded = [0_u8; 4];
        let text = character.encode_utf8(&mut encoded);
        let fonts = self.assets.clonk_fonts.clone();
        let actions = fonts
            .as_deref()
            .and_then(|fonts| {
                self.startup_network_dialog
                    .as_mut()
                    .map(|dialog| dialog.handle_text_input(text, &fonts.text))
            })
            .unwrap_or_default();
        self.process_network_dialog_actions(actions)
    }

    fn copy_search_edit_selection(&mut self, cut: bool) {
        let result =
            transfer_edit_selection(&mut self.menu_state.search_edit, cut, |selected| {
                arboard::Clipboard::new()
                    .and_then(|mut clipboard| clipboard.set_text(selected.to_string()))
            });
        if let Err(err) = result {
            tracing::warn!(error = %err, "failed to copy scenario search text");
        }
    }

    fn paste_search_edit_clipboard(&mut self) -> Result<(), EngineError> {
        let text = match arboard::Clipboard::new().and_then(|mut clipboard| clipboard.get_text()) {
            Ok(text) => text,
            Err(err) => {
                tracing::warn!(error = %err, "failed to paste scenario search text");
                return Ok(());
            }
        };
        if apply_scensel_search_paste(&mut self.menu_state.search_edit, &text) {
            self.submit_scenario_search()?;
        }
        Ok(())
    }

    fn submit_scenario_search(&mut self) -> Result<(), EngineError> {
        // UpdateList destroys and recreates the visible row elements.
        self.startup_tooltip.pointer_left();
        self.menu_frame_cache = None;
        self.handle_menu_input(|menu| menu.submit_search())?;
        // An empty result emits no SelectionChanged action. Explicitly clear
        // selection-derived checkbox/ForcedNoCrew state in that case rather
        // than retaining the previously selected scenario's constraint.
        self.menu_state.sync_definition_checkbox_to_selection();
        self.sync_scenario_game_option_constraint();
        Ok(())
    }

    fn execute_scenario_search_context_command(
        &mut self,
        command: ScenselSearchContextCommand,
    ) -> Result<(), EngineError> {
        if self.mode != AppMode::Menu || self.startup_view != StartupView::ScenarioBrowser {
            tracing::error!(?command, "stale scenario search context command");
            return Ok(());
        }
        match command {
            ScenselSearchContextCommand::Cut => self.copy_search_edit_selection(true),
            ScenselSearchContextCommand::Copy => self.copy_search_edit_selection(false),
            ScenselSearchContextCommand::Paste => self.paste_search_edit_clipboard()?,
            ScenselSearchContextCommand::Clear => {
                self.menu_state.search_edit.delete_selection();
            }
            ScenselSearchContextCommand::SelectAll => {
                self.menu_state.search_edit.select_all();
            }
        }
        self.mark_menu_dirty();
        Ok(())
    }

    fn handle_modifiers_changed(&mut self, modifiers: ModifiersState) -> Result<(), EngineError> {
        self.guard_classic_global_gui_bootstrap()?;
        self.keyboard_modifiers = modifiers;
        Ok(())
    }

    fn scensel_search_char_pos(&self, point: GuiPoint, require_inside: bool) -> Option<usize> {
        if self.mode != AppMode::Menu
            || self.startup_view != StartupView::ScenarioBrowser
            || self.menu_state.current_map().is_some()
        {
            return None;
        }
        let fonts = self.assets.clonk_fonts.as_deref()?;
        let layout = clonk_frontend::startup_scensel::scen_sel_layout(
            self.graphics.surface().width() as i32,
            self.graphics.surface().height() as i32,
            fonts,
        );
        let edit = layout.search_edit;
        let inside = point.x >= edit.x as f32
            && point.x < (edit.x + edit.w) as f32
            && point.y >= edit.y as f32
            && point.y < (edit.y + edit.h) as f32;
        if require_inside && !inside {
            return None;
        }
        let control_x =
            point.x as i32 - (edit.x + 4) + self.menu_state.search_edit.horizontal_scroll;
        let text = self.menu_state.search_edit.text();
        let mut last_width = 0;
        for (start, character) in text.char_indices() {
            let end = start + character.len_utf8();
            let width = fonts.text.measure(&text[..end], false).0;
            if width - (width - last_width) / 2 >= control_x {
                return Some(start);
            }
            last_width = width;
        }
        Some(text.len())
    }

    fn handle_scensel_search_pointer_down(&mut self, point: GuiPoint) -> bool {
        let Some(position) = self.scensel_search_char_pos(point, true) else {
            return false;
        };
        self.set_scensel_dialog_focus(ScenselDialogFocus::Search);
        self.menu_state
            .search_edit
            .begin_pointer_selection(position);
        true
    }

    /// C4GUI middle-down repositions the caret on every platform, inserts
    /// the raw PRIMARY selection only where the platform supplies one, and
    /// neither focuses the edit nor starts a selection drag.
    fn handle_scensel_search_middle_down(
        &mut self,
        point: GuiPoint,
        primary_selection: Option<&str>,
    ) -> bool {
        let Some(position) = self.scensel_search_char_pos(point, true) else {
            return false;
        };
        let (previous, current, inserted) = {
            let edit = &mut self.menu_state.search_edit;
            let previous = edit.caret;
            edit.anchor = position;
            edit.caret = position;
            edit.drag_anchor = position;
            let inserted = primary_selection
                .is_some_and(|text| edit.insert_raw_text(text));
            (previous, edit.caret, inserted)
        };
        if inserted || previous != current {
            let Some(fonts) = self.assets.clonk_fonts.clone() else {
                return true;
            };
            let layout = clonk_frontend::startup_scensel::scen_sel_layout(
                self.graphics.surface().width() as i32,
                self.graphics.surface().height() as i32,
                &fonts,
            );
            let edit = &mut self.menu_state.search_edit;
            let cursor_x = fonts.text.measure(&edit.text[..edit.caret], false).0;
            let cursor_half = fonts.text.measure("\u{a6}", false).0 / 2;
            edit.scroll_cursor_in_view(cursor_x, layout.search_edit.w - 8, cursor_half);
        }
        true
    }

    fn handle_scensel_search_pointer_move(&mut self, point: GuiPoint) -> bool {
        if !self.menu_state.search_edit.dragging {
            return false;
        }
        if let Some(position) = self.scensel_search_char_pos(point, false) {
            self.menu_state.search_edit.drag_pointer_selection(position);
        }
        true
    }

    fn handle_scensel_search_pointer_up(&mut self, point: GuiPoint) -> bool {
        if !self.menu_state.search_edit.dragging {
            return false;
        }
        let position = self
            .scensel_search_char_pos(point, false)
            .unwrap_or(self.menu_state.search_edit.caret());
        self.menu_state.search_edit.end_pointer_selection(position);
        let inside = self.scensel_search_char_pos(point, true).is_some();
        let now = Instant::now();
        let double_click = inside
            && self
                .scensel_search_last_click
                .is_some_and(|last| now.duration_since(last) < Duration::from_millis(500));
        if double_click {
            self.menu_state.search_edit.select_word_at(position);
            self.scensel_search_last_click = None;
        } else {
            self.scensel_search_last_click = inside.then_some(now);
        }
        true
    }

    fn scensel_rename_char_pos(&self, point: GuiPoint, require_inside: bool) -> Option<usize> {
        if self.mode != AppMode::Menu || self.startup_view != StartupView::ScenarioBrowser {
            return None;
        }
        let fonts = self.assets.clonk_fonts.as_deref()?;
        let book = self.assets.book_fonts.as_deref()?;
        let rename = self.menu_state.rename_edit.as_ref()?;
        let row = self
            .menu_state
            .visible_entries()
            .iter()
            .position(|entry| entry.identifier == rename.identifier)?;
        let layout = clonk_frontend::startup_scensel::scen_sel_layout(
            self.graphics.surface().width() as i32,
            self.graphics.surface().height() as i32,
            fonts,
        );
        let item_height = clonk_frontend::startup_scensel::scen_list_item_height(&book.text);
        let pitch = item_height + 1;
        let edit_x = layout.list.x + 3 + item_height + 2;
        let edit_y = layout.list.y + 3 - self.menu_state.scenario_list_scroll()
            + i32::try_from(row).unwrap_or(i32::MAX).saturating_mul(pitch)
            + 2;
        let edit_w = layout.list.w - 6 - 16 - item_height - 4;
        let edit_h = fonts.text.line_height;
        let inside = point.x >= edit_x as f32
            && point.x < (edit_x + edit_w) as f32
            && point.y >= edit_y as f32
            && point.y < (edit_y + edit_h) as f32;
        if require_inside && !inside {
            return None;
        }
        let control_x =
            point.x as i32 - (edit_x + 2) + rename.edit.horizontal_scroll();
        let text = rename.edit.text();
        let mut last_width = 0;
        for (start, character) in text.char_indices() {
            let end = start + character.len_utf8();
            let width = fonts.text.measure(&text[..end], false).0;
            if width - (width - last_width) / 2 >= control_x {
                return Some(start);
            }
            last_width = width;
        }
        Some(text.len())
    }

    fn handle_scensel_rename_pointer_down(&mut self, point: GuiPoint) -> bool {
        let Some(position) = self.scensel_rename_char_pos(point, true) else {
            return false;
        };
        if let Some(rename) = self.menu_state.rename_edit.as_mut() {
            rename.edit.begin_pointer_selection(position);
        }
        true
    }

    fn handle_scensel_rename_pointer_move(&mut self, point: GuiPoint) -> bool {
        if !self
            .menu_state
            .rename_edit
            .as_ref()
            .is_some_and(|rename| rename.edit.is_dragging())
        {
            return false;
        }
        if let Some(position) = self.scensel_rename_char_pos(point, false) {
            if let Some(rename) = self.menu_state.rename_edit.as_mut() {
                rename.edit.drag_pointer_selection(position);
            }
        }
        true
    }

    fn handle_scensel_rename_pointer_up(&mut self, point: GuiPoint) -> bool {
        if !self
            .menu_state
            .rename_edit
            .as_ref()
            .is_some_and(|rename| rename.edit.is_dragging())
        {
            return false;
        }
        let position = self
            .scensel_rename_char_pos(point, false)
            .or_else(|| {
                self.menu_state
                    .rename_edit
                    .as_ref()
                    .map(|rename| rename.edit.caret())
            })
            .unwrap_or(0);
        let inside = self.scensel_rename_char_pos(point, true).is_some();
        let now = Instant::now();
        if let Some(rename) = self.menu_state.rename_edit.as_mut() {
            rename.edit.end_pointer_selection(position);
            let double_click = inside
                && rename
                    .last_click
                    .is_some_and(|last| now.duration_since(last) < Duration::from_millis(500));
            if double_click {
                rename.edit.select_word_at(position);
                rename.last_click = None;
            } else {
                rename.last_click = inside.then_some(now);
            }
        }
        true
    }

    fn startup_crew_rename_rect(&self) -> Option<clonk_frontend::classic_gui::IntRect> {
        let rename = self.startup_crew_rename.as_ref()?;
        let current = self.startup_crew_files.get(rename.index)?;
        if current.file_name != rename.file_name || current.player_path != rename.player_path {
            return None;
        }
        let dialog = self
            .startup_player_dialog
            .as_ref()
            .filter(|dialog| dialog.is_crew_mode())?;
        let layout = dialog.layout();
        let row = i32::try_from(rename.index).unwrap_or(i32::MAX);
        Some(clonk_frontend::classic_gui::IntRect {
            x: layout.list_viewport.x + (layout.item_height + 2) * 2,
            y: layout.list_viewport.y + layout.item_pitch.saturating_mul(row)
                - dialog.list_scroll_offset()
                + 2,
            w: (layout.item_width - (layout.item_height + 2) * 2 - 2).max(1),
            h: (layout.item_height - 4).max(1),
        })
    }

    fn startup_crew_rename_char_pos(
        &self,
        point: GuiPoint,
        require_inside: bool,
    ) -> Option<usize> {
        let rename = self.startup_crew_rename.as_ref()?;
        let dialog = self.startup_player_dialog.as_ref()?;
        let layout = dialog.layout();
        let rect = self.startup_crew_rename_rect()?;
        let inside_rect = point.x >= rect.x as f32
            && point.x < (rect.x + rect.w) as f32
            && point.y >= rect.y as f32
            && point.y < (rect.y + rect.h) as f32;
        let inside_viewport = point.x >= layout.list_viewport.x as f32
            && point.x < (layout.list_viewport.x + layout.list_viewport.w) as f32
            && point.y >= layout.list_viewport.y as f32
            && point.y < (layout.list_viewport.y + layout.list_viewport.h) as f32;
        if require_inside && !(inside_rect && inside_viewport) {
            return None;
        }
        let font = &self.assets.clonk_fonts.as_deref()?.text;
        Some(rename.edit.character_at_x(point.x, rect, font))
    }

    fn handle_startup_crew_rename_pointer_down(&mut self, point: GuiPoint) -> bool {
        let Some(position) = self.startup_crew_rename_char_pos(point, true) else {
            return false;
        };
        let now = Instant::now();
        if let Some(rename) = self.startup_crew_rename.as_mut() {
            let double_click = rename
                .last_click
                .is_some_and(|last| now.duration_since(last) < CPP_DOUBLE_CLICK_INTERVAL);
            if double_click {
                rename.edit.select_word_at(position);
                rename.last_click = None;
                rename.ignore_pointer_up = true;
            } else {
                rename.edit.begin_pointer_selection(position);
                rename.last_click = Some(now);
                rename.ignore_pointer_up = false;
            }
        }
        true
    }

    fn handle_startup_crew_rename_pointer_move(&mut self, point: GuiPoint) -> bool {
        if !self
            .startup_crew_rename
            .as_ref()
            .is_some_and(|rename| rename.edit.is_dragging())
        {
            return false;
        }
        if let Some(position) = self.startup_crew_rename_char_pos(point, false) {
            if let Some(rename) = self.startup_crew_rename.as_mut() {
                rename.edit.drag_pointer_selection(position);
            }
        }
        true
    }

    fn handle_startup_crew_rename_pointer_up(&mut self, point: GuiPoint) -> bool {
        if self
            .startup_crew_rename
            .as_mut()
            .is_some_and(|rename| std::mem::take(&mut rename.ignore_pointer_up))
        {
            return true;
        }
        if !self
            .startup_crew_rename
            .as_ref()
            .is_some_and(|rename| rename.edit.is_dragging())
        {
            return false;
        }
        let position = self
            .startup_crew_rename_char_pos(point, false)
            .or_else(|| {
                self.startup_crew_rename
                    .as_ref()
                    .map(|rename| rename.edit.caret())
            })
            .unwrap_or(0);
        if let Some(rename) = self.startup_crew_rename.as_mut() {
            rename.edit.end_pointer_selection(position);
        }
        true
    }

    fn handle_startup_crew_rename_middle_down(
        &mut self,
        point: GuiPoint,
        primary: Option<&str>,
    ) -> bool {
        let Some(position) = self.startup_crew_rename_char_pos(point, true) else {
            return false;
        };
        if let Some(rename) = self.startup_crew_rename.as_mut() {
            rename.edit.begin_pointer_selection(position);
            rename.edit.end_pointer_selection(position);
            if let Some(primary) = primary {
                rename.edit.insert_text(primary);
            }
        }
        true
    }

    fn scensel_scrollbar_spec(
        &self,
        target: ScenselScrollbarTarget,
    ) -> Option<ScenselScrollbarSpec> {
        if self.mode != AppMode::Menu
            || self.startup_view != StartupView::ScenarioBrowser
            || self.menu_state.current_map().is_some()
        {
            return None;
        }
        let fonts = self.assets.clonk_fonts.as_deref()?;
        let book_fonts = self.assets.book_fonts.as_deref()?;
        let layout = clonk_frontend::startup_scensel::scen_sel_layout(
            self.graphics.surface().width() as i32,
            self.graphics.surface().height() as i32,
            fonts,
        );
        let (rect, max_scroll, offset) = match target {
            ScenselScrollbarTarget::List => {
                let item_height =
                    clonk_frontend::startup_scensel::scen_list_item_height(&book_fonts.text);
                let max_scroll = self
                    .menu_state
                    .scenario_list_max_scroll(layout.list.h - 6, item_height + 1);
                (
                    layout.list_scrollbar,
                    max_scroll,
                    self.menu_state.scenario_list_scroll(),
                )
            }
            ScenselScrollbarTarget::Description => {
                let info = scensel_selection_info(&self.menu_state);
                let metrics = clonk_frontend::startup_scensel::selection_info_scroll_metrics(
                    &layout, book_fonts, &info,
                );
                (
                    clonk_frontend::startup_scensel::selection_info_scrollbar_rect(&layout),
                    metrics.max_scroll,
                    self.menu_state.selection_info_scroll,
                )
            }
        };
        (max_scroll > 0).then_some(ScenselScrollbarSpec {
            target,
            rect,
            max_scroll,
            offset: offset.clamp(0, max_scroll),
        })
    }

    fn scensel_scrollbar_spec_at(&self, point: GuiPoint) -> Option<ScenselScrollbarSpec> {
        [
            ScenselScrollbarTarget::List,
            ScenselScrollbarTarget::Description,
        ]
        .into_iter()
        .filter_map(|target| self.scensel_scrollbar_spec(target))
        .find(|spec| {
            point.x >= spec.rect.x as f32
                && point.x < (spec.rect.x + spec.rect.w) as f32
                && point.y >= spec.rect.y as f32
                && point.y < (spec.rect.y + spec.rect.h) as f32
        })
    }

    fn set_scensel_scrollbar_offset(
        &mut self,
        target: ScenselScrollbarTarget,
        offset: i32,
        max_scroll: i32,
    ) -> bool {
        let offset = offset.clamp(0, max_scroll);
        match target {
            ScenselScrollbarTarget::List => {
                self.menu_state.list_scroll_selection = Some(self.menu_state.menu.selected_index());
                if self.menu_state.scenario_list_scroll == offset {
                    false
                } else {
                    self.menu_state.scenario_list_scroll = offset;
                    true
                }
            }
            ScenselScrollbarTarget::Description => {
                if self.menu_state.selection_info_scroll == offset {
                    false
                } else {
                    self.menu_state.selection_info_scroll = offset;
                    true
                }
            }
        }
    }

    fn set_scensel_scrollbar_pin(&mut self, spec: ScenselScrollbarSpec, pin: i32) -> bool {
        let Some(offset) = scensel_scrollbar_offset_from_pin(pin, spec.max_scroll, spec.rect.h)
        else {
            return false;
        };
        self.set_scensel_scrollbar_offset(spec.target, offset, spec.max_scroll)
    }

    fn handle_scensel_scrollbar_down(&mut self, point: GuiPoint) -> bool {
        if self.scenario_selector_discovery.is_some() {
            return false;
        }
        let Some(spec) = self.scensel_scrollbar_spec_at(point) else {
            return false;
        };
        let Some(current_pin) =
            scensel_scrollbar_pin_from_offset(spec.offset, spec.max_scroll, spec.rect.h)
        else {
            return true;
        };
        let local_y = point.y as i32 - spec.rect.y;
        let (kind, pin) = if local_y < SCENSEL_SCROLLBAR_PART {
            (ScenselScrollbarInteractionKind::Arrow(-1), current_pin)
        } else if local_y >= spec.rect.h - SCENSEL_SCROLLBAR_PART {
            (ScenselScrollbarInteractionKind::Arrow(1), current_pin)
        } else {
            let Some(pin) = scensel_scrollbar_jump_pin(local_y, spec.rect.h) else {
                return true;
            };
            (ScenselScrollbarInteractionKind::Dragging, pin)
        };
        self.menu_state.scrollbar_interaction = Some(ScenselScrollbarInteraction {
            target: spec.target,
            kind,
            pin,
        });
        if kind == ScenselScrollbarInteractionKind::Dragging {
            self.set_scensel_scrollbar_pin(spec, pin);
            self.play_ui_sound("Command");
        } else {
            self.play_ui_sound("ArrowHit");
        }
        true
    }

    fn handle_scensel_scrollbar_move(&mut self, point: GuiPoint) -> bool {
        if self.scenario_selector_discovery.is_some() {
            self.menu_state.scrollbar_interaction = None;
            return false;
        }
        let Some(mut interaction) = self.menu_state.scrollbar_interaction else {
            return false;
        };
        let Some(spec) = self.scensel_scrollbar_spec(interaction.target) else {
            self.menu_state.scrollbar_interaction = None;
            return true;
        };
        match interaction.kind {
            ScenselScrollbarInteractionKind::Dragging => {
                if let Some(pin) =
                    scensel_scrollbar_jump_pin(point.y as i32 - spec.rect.y, spec.rect.h)
                {
                    interaction.pin = pin;
                    self.menu_state.scrollbar_interaction = Some(interaction);
                    self.set_scensel_scrollbar_pin(spec, pin);
                }
            }
            ScenselScrollbarInteractionKind::Arrow(_) => {
                let inside_x =
                    point.x >= spec.rect.x as f32 && point.x < (spec.rect.x + spec.rect.w) as f32;
                let local_y = point.y as i32 - spec.rect.y;
                interaction.kind = if inside_x && (0..SCENSEL_SCROLLBAR_PART).contains(&local_y) {
                    ScenselScrollbarInteractionKind::Arrow(-1)
                } else if inside_x
                    && local_y >= spec.rect.h - SCENSEL_SCROLLBAR_PART
                    && local_y < spec.rect.h
                {
                    ScenselScrollbarInteractionKind::Arrow(1)
                } else {
                    self.menu_state.scrollbar_interaction = None;
                    return true;
                };
                self.menu_state.scrollbar_interaction = Some(interaction);
            }
        }
        true
    }

    fn handle_scensel_scrollbar_up(&mut self, point: GuiPoint) -> bool {
        if self.scenario_selector_discovery.is_some() {
            self.menu_state.scrollbar_interaction = None;
            return false;
        }
        let Some(interaction) = self.menu_state.scrollbar_interaction.take() else {
            return false;
        };
        if interaction.kind == ScenselScrollbarInteractionKind::Dragging {
            if let Some(spec) = self.scensel_scrollbar_spec(interaction.target) {
                if let Some(pin) =
                    scensel_scrollbar_jump_pin(point.y as i32 - spec.rect.y, spec.rect.h)
                {
                    self.set_scensel_scrollbar_pin(spec, pin);
                }
            }
        }
        true
    }

    fn tick_scensel_scrollbar_arrow(&mut self) -> bool {
        let Some(mut interaction) = self.menu_state.scrollbar_interaction else {
            return false;
        };
        let ScenselScrollbarInteractionKind::Arrow(direction) = interaction.kind else {
            return false;
        };
        let Some(spec) = self.scensel_scrollbar_spec(interaction.target) else {
            self.menu_state.scrollbar_interaction = None;
            return false;
        };
        let Some(travel) = scensel_scrollbar_pin_travel(spec.rect.h) else {
            return false;
        };
        let pin = interaction.pin.saturating_add(direction).clamp(0, travel);
        if pin == interaction.pin {
            return false;
        }
        interaction.pin = pin;
        self.menu_state.scrollbar_interaction = Some(interaction);
        self.set_scensel_scrollbar_pin(spec, pin)
    }

    fn handle_scensel_list_navigation_key(
        &mut self,
        key: VirtualKeyCode,
        state: ElementState,
    ) -> Result<bool, EngineError> {
        if self.mode != AppMode::Menu
            || self.startup_view != StartupView::ScenarioBrowser
            || !matches!(
                key,
                VirtualKeyCode::Up
                    | VirtualKeyCode::Down
                    | VirtualKeyCode::Home
                    | VirtualKeyCode::End
                    | VirtualKeyCode::PageUp
                    | VirtualKeyCode::PageDown
            )
        {
            return Ok(false);
        }
        if state == ElementState::Released {
            return Ok(true);
        }
        if self.menu_state.current_map().is_some() {
            return Ok(true);
        }
        let Some(fonts) = self.assets.clonk_fonts.as_deref() else {
            return Ok(true);
        };
        let Some(book_fonts) = self.assets.book_fonts.as_deref() else {
            return Ok(true);
        };
        let layout = clonk_frontend::startup_scensel::scen_sel_layout(
            self.graphics.surface().width() as i32,
            self.graphics.surface().height() as i32,
            fonts,
        );
        let item_height = clonk_frontend::startup_scensel::scen_list_item_height(&book_fonts.text);
        let viewport_height = layout.list.h - 6;
        self.handle_menu_input(|menu| match key {
            VirtualKeyCode::Up => menu.move_list_selection_clamped(-1),
            VirtualKeyCode::Down => menu.move_list_selection_clamped(1),
            VirtualKeyCode::Home => menu.select_list_home(),
            VirtualKeyCode::End => menu.select_list_end(),
            VirtualKeyCode::PageUp => {
                menu.page_list_selection(-1, viewport_height, item_height + 1, item_height)
            }
            VirtualKeyCode::PageDown => {
                menu.page_list_selection(1, viewport_height, item_height + 1, item_height)
            }
            _ => Vec::new(),
        })?;
        Ok(true)
    }

    /// `C4GUI::ScrollWindow::MouseInput` scrolls by the SDL wheel delta;
    /// C4FullScreen converts one notch to 60 logical pixels
    /// (C4FullScreen.cpp:408; C4GuiContainers.cpp:612-620).
    fn handle_mouse_wheel(
        &mut self,
        delta: MouseScrollDelta,
        output_scale: f32,
    ) -> Result<(), EngineError> {
        self.guard_classic_global_gui_bootstrap()?;
        self.sync_scoreboard_before_running_pointer_input();
        self.startup_tooltip.note_pointer_wheel();
        if self.startup_network_transition_blocks_input() {
            return Ok(());
        }
        if self.network_chart_is_elevated_pointer_layer()
            && self.context_menu.is_none()
            && self
                .running_pointer_position
                .is_some_and(|point| self.network_chart_contains_point(point))
        {
            return Ok(());
        }
        let message_dialog_fallback_blocks_world =
            self.runtime_pointer_fallback_is_exclusive();
        let context_routed_before_running_dialogs = self.mode == AppMode::Running
            && self.context_menu.is_some()
            && !self.running_dialog_stack.is_empty();
        if context_routed_before_running_dialogs {
            let outcome = self.context_menu.as_mut().map(|menu| {
                let point = menu.pointer_position();
                menu.handle_pointer_down(point, ContextMenuPointerButton::Other)
            });
            if let Some(outcome) = outcome {
                let captured = outcome.captured && !outcome.pass_through;
                self.process_context_menu_outcome(outcome)?;
                if captured {
                    self.occlude_running_dialog_pointer_hovers();
                    return Ok(());
                }
            }
        }
        let mut top_default_target = None;
        if self.mode == AppMode::Running {
            if let Some(point) = self.running_pointer_position {
                for dialog_kind in self
                    .runtime_default_dialog_order_snapshot()
                    .into_iter()
                    .rev()
                {
                    if self.runtime_default_dialog_contains_point(dialog_kind, point)? {
                        top_default_target = Some(dialog_kind);
                        break;
                    }
                }
            }
        }
        if self.mode == AppMode::Running {
            let mut shared_target = self
                .running_pointer_position
                .map(|point| self.top_scoreboard_message_pointer_target(point, false))
                .transpose()?
                .flatten();
            if let Some(entry @ (RunningDialogStackEntry::Scoreboard
            | RunningDialogStackEntry::RuntimeClientList)) = shared_target
            {
                let split = self
                    .running_dialog_stack
                    .iter()
                    .position(|candidate| candidate.z_order() > 0)
                    .unwrap_or(self.running_dialog_stack.len());
                let entry_is_in_tail = self
                    .running_dialog_stack
                    .iter()
                    .rposition(|candidate| *candidate == entry)
                    .is_some_and(|position| position >= split);
                let shared_default = match entry {
                    RunningDialogStackEntry::Scoreboard => RuntimeDefaultDialog::Scoreboard,
                    RunningDialogStackEntry::RuntimeClientList => {
                        RuntimeDefaultDialog::ClientList
                    }
                    RunningDialogStackEntry::Message(_) | RunningDialogStackEntry::Chat => {
                        unreachable!("only default-z shared dialogs reach this branch")
                    }
                };
                if !entry_is_in_tail
                    && top_default_target.is_some_and(|target| target != shared_default)
                {
                    shared_target = None;
                }
            }
            match shared_target {
                Some(RunningDialogStackEntry::RuntimeClientList) => {
                    let native_delta = match delta {
                        MouseScrollDelta::LineDelta(_, y) => (y * 60.0).round() as i32,
                        MouseScrollDelta::PixelDelta(position) => {
                            (position.y / f64::from(output_scale.max(f32::EPSILON))).round() as i32
                        }
                    };
                    let geometry = self.runtime_client_list_input_geometry();
                    let point = self.running_pointer_position;
                    let changed = geometry
                        .zip(point)
                        .and_then(|((preferred, line_height), point)| {
                            self.runtime_client_list.as_mut().map(|dialog| {
                                dialog.handle_wheel(point, native_delta, preferred, line_height)
                            })
                        })
                        .unwrap_or(false);
                    if changed {
                        self.mark_menu_dirty();
                    }
                    self.suspend_ingame_pointer_for_gui();
                    self.cancel_ingame_mouse_gestures();
                    return Ok(());
                }
                Some(
                    RunningDialogStackEntry::Scoreboard
                    | RunningDialogStackEntry::Message(_)
                    | RunningDialogStackEntry::Chat,
                ) => {
                    self.suspend_ingame_pointer_for_gui();
                    self.cancel_ingame_mouse_gestures();
                    return Ok(());
                }
                None => {}
            }
        } else if !self.message_dialogs.is_empty() && self.running_chat_controller().is_none() {
            return Ok(());
        }
        if self.league_signup_dialog.is_some() {
            return Ok(());
        }
        let runtime_client_info_only = self
            .runtime_client_list
            .as_ref()
            .is_some_and(|dialog| dialog.is_info_only());
        if runtime_client_info_only {
            let native_delta = match delta {
                MouseScrollDelta::LineDelta(_, y) => (y * 60.0).round() as i32,
                MouseScrollDelta::PixelDelta(position) => {
                    (position.y / f64::from(output_scale.max(f32::EPSILON))).round() as i32
                }
            };
            if let (Some((preferred, line_height)), Some(point)) = (
                self.runtime_client_list_input_geometry(),
                self.running_pointer_position,
            ) {
                if let Some(dialog) = self.runtime_client_list.as_mut() {
                    let _ = dialog.handle_wheel(point, native_delta, preferred, line_height);
                }
                self.mark_menu_dirty();
            }
            return Ok(());
        }
        if self.external_irc_dialog_visible && !context_routed_before_running_dialogs {
            if let Some(menu) = self.context_menu.as_mut() {
                let point = menu.pointer_position();
                let outcome = menu.handle_pointer_down(point, ContextMenuPointerButton::Other);
                let captured = outcome.captured && !outcome.pass_through;
                self.process_context_menu_outcome(outcome)?;
                if captured {
                    return Ok(());
                }
            }
        }
        if self.external_irc_dialog_visible && !matches!(self.mode, AppMode::Running) {
            let native_delta = match delta {
                MouseScrollDelta::LineDelta(_, y) => (y * 60.0).round() as i32,
                MouseScrollDelta::PixelDelta(position) => {
                    (position.y / f64::from(output_scale.max(f32::EPSILON))).round() as i32
                }
            };
            let actions = self
                .external_irc_dialog
                .as_mut()
                .and_then(|dialog| {
                    dialog
                        .pointer_position()
                        .map(|point| dialog.handle_wheel(point, native_delta))
                })
                .unwrap_or_default();
            self.process_network_dialog_actions(actions)?;
            self.mark_menu_dirty();
            return Ok(());
        }
        if let Some(layout) = self.network_start_wait_layout() {
            let native_delta = match delta {
                MouseScrollDelta::LineDelta(_, y) => (y * 60.0).round() as i32,
                MouseScrollDelta::PixelDelta(position) => {
                    (position.y / f64::from(output_scale.max(f32::EPSILON))).round() as i32
                }
            };
            let scrolled = self.network_start_wait.as_mut().is_some_and(|wait| {
                wait.pointer.is_some_and(|point| {
                    wait.controller
                        .handle_wheel(point, native_delta, &layout)
                })
            });
            if scrolled {
                self.mark_menu_dirty();
            }
            return Ok(());
        }
        if self.startup_options_advanced_dialog.is_some() {
            let native_delta = match delta {
                MouseScrollDelta::LineDelta(_, y) => (y * 60.0).round() as i32,
                MouseScrollDelta::PixelDelta(position) => {
                    (position.y / f64::from(output_scale.max(f32::EPSILON))).round() as i32
                }
            };
            let changed = self
                .startup_options_advanced_dialog
                .as_mut()
                .is_some_and(|pending| pending.controller.handle_wheel(native_delta));
            if changed {
                self.mark_menu_dirty();
            }
            return Ok(());
        }
        if self.startup_player_properties_dialog.is_some() {
            let native_delta = match delta {
                MouseScrollDelta::LineDelta(_, y) => (y * 60.0).round() as i32,
                MouseScrollDelta::PixelDelta(position) => {
                    (position.y / f64::from(output_scale.max(f32::EPSILON))).round() as i32
                }
            };
            let changed = self
                .startup_player_properties_dialog
                .as_mut()
                .is_some_and(|pending| pending.controller.handle_wheel(native_delta));
            if changed {
                self.mark_menu_dirty();
            }
            return Ok(());
        }
        if self.definition_selector.is_some() {
            let amount = match delta {
                MouseScrollDelta::LineDelta(_, y) => (-y * 60.0).round() as i32,
                MouseScrollDelta::PixelDelta(position) => {
                    (-position.y / f64::from(output_scale.max(f32::EPSILON))).round() as i32
                }
            };
            let layout = self.definition_selector_layout();
            let point = self
                .definition_selector
                .as_ref()
                .and_then(|controller| controller.pointer_position());
            let actions = layout
                .as_ref()
                .zip(point)
                .and_then(|(layout, point)| {
                    self.definition_selector.as_mut().map(|controller| {
                        // Controller takes the native wheel sign; `amount`
                        // is already the desired scroll-window displacement.
                        controller.handle_wheel(point, -amount, layout)
                    })
                })
                .unwrap_or_default();
            self.finish_definition_selector_input(actions)?;
            self.mark_menu_dirty();
            return Ok(());
        }
        if !context_routed_before_running_dialogs {
            if let Some(menu) = self.context_menu.as_mut() {
                let point = menu.pointer_position();
                let outcome = menu.handle_pointer_down(point, ContextMenuPointerButton::Other);
                let captured = outcome.captured && !outcome.pass_through;
                self.process_context_menu_outcome(outcome)?;
                if captured {
                    return Ok(());
                }
            }
        }
        if self.game_option_input_dialog.is_some()
            && self.game_option_input_owns_running_pointer_event()
            && top_default_target.is_none()
        {
            return Ok(());
        }
        if matches!(self.mode, AppMode::Running) {
            let native_delta = match delta {
                MouseScrollDelta::LineDelta(_, y) => (y * 60.0).round() as i32,
                MouseScrollDelta::PixelDelta(position) => {
                    (position.y / f64::from(output_scale.max(f32::EPSILON))).round() as i32
                }
            };
            if let Some(point) = self.running_pointer_position {
                for dialog_kind in self
                    .runtime_default_dialog_order_snapshot()
                    .into_iter()
                    .rev()
                {
                    if !self.runtime_default_dialog_contains_point(dialog_kind, point)? {
                        continue;
                    }
                    match dialog_kind {
                        RuntimeDefaultDialog::ExternalIrc => {
                            let actions = self
                                .external_irc_dialog
                                .as_mut()
                                .map(|dialog| dialog.handle_wheel(point, native_delta))
                                .unwrap_or_default();
                            self.process_network_dialog_actions(actions)?;
                        }
                        RuntimeDefaultDialog::GameOver => {
                            let (width, height) = {
                                let surface = self.graphics.surface();
                                (surface.width(), surface.height())
                            };
                            if let Some(dialog) = self.game_over_dialog.as_mut() {
                                dialog.handle_pointer_move(point.x, point.y, width, height);
                                dialog.handle_wheel(native_delta, width, height);
                            }
                        }
                        RuntimeDefaultDialog::ClientList => {
                            if let Some((preferred, line_height)) =
                                self.runtime_client_list_input_geometry()
                            {
                                if let Some(dialog) = self.runtime_client_list.as_mut() {
                                    dialog.handle_wheel(
                                        point,
                                        native_delta,
                                        preferred,
                                        line_height,
                                    );
                                }
                            }
                        }
                        RuntimeDefaultDialog::NetworkChart
                        | RuntimeDefaultDialog::Scoreboard => {}
                    }
                    self.mark_menu_dirty();
                    return Ok(());
                }
            }
        }
        if message_dialog_fallback_blocks_world {
            return Ok(());
        }
        if self.startup_dialog_fade_active() {
            return Ok(());
        }
        if self.classic_host_lobby_active() {
            let amount = match delta {
                MouseScrollDelta::LineDelta(_, y) => (y * 60.0).round() as i32,
                MouseScrollDelta::PixelDelta(position) => {
                    (position.y / f64::from(output_scale.max(f32::EPSILON))).round() as i32
                }
            };
            return self.handle_classic_lobby_wheel(amount);
        }
        if self.mode == AppMode::Menu
            && self.startup_view == StartupView::NetworkLobby
            && self.network_lobby.is_some()
        {
            let amount = match delta {
                MouseScrollDelta::LineDelta(_, y) => (y * 60.0).round() as i32,
                MouseScrollDelta::PixelDelta(position) => {
                    (position.y / f64::from(output_scale.max(f32::EPSILON))).round() as i32
                }
            };
            if amount == 0 {
                return Ok(());
            }
            self.scenario_game_options.note_pointer_wheel();
            let (changed, scroll_window_captured) = match self.network_lobby.as_mut() {
                Some(lobby) => lobby.wheel_right_sheet(
                    amount,
                    self.graphics.surface(),
                    self.assets.as_ref(),
                    &self.scenario_game_options,
                )
                .map_err(|error| {
                    classic_parity_engine_error(report_classic_parity_boundary(
                        ClassicParityBoundary::GameLobby(
                            ClassicGameLobbyBoundary::Resources {
                                detail: error.to_string(),
                            },
                        ),
                    ))
                })?,
                None => (false, false),
            };
            if scroll_window_captured {
                // C4GUI::ScrollWindow consumes the wheel and clears the
                // screen's pMouseOver owner until a later pointer event.
                self.note_classic_lobby_non_pointer_input();
            }
            if changed || scroll_window_captured {
                self.mark_menu_dirty();
            }
            return Ok(());
        }
        if self.mode == AppMode::Running {
            let native_delta = match delta {
                MouseScrollDelta::LineDelta(_, y) => (y * 60.0).round() as i32,
                MouseScrollDelta::PixelDelta(position) => {
                    (position.y / f64::from(output_scale.max(f32::EPSILON))).round() as i32
                }
            };
            if let Some(point) = self.ingame_gui_pointer {
                if self.handle_ingame_menu_wheel(point, native_delta.saturating_neg()) {
                    return Ok(());
                }
                if self.handle_script_menu_wheel(point, native_delta.saturating_neg())? {
                    return Ok(());
                }
            }
            self.initialize_ingame_mouse_for_wheel();
            self.advance_ingame_mouse_caption_lifetime();
            if !self.mouse_control {
                self.restore_ingame_mouse_region_caption();
                return Ok(());
            }
            let Some(owner) = self.local_controls.mouse_owner() else {
                return Ok(());
            };
            let command = if native_delta > 0 {
                Some(clonk_engine::COM_WHEEL_UP)
            } else if native_delta < 0 {
                Some(clonk_engine::COM_WHEEL_DOWN)
            } else {
                None
            };
            if let Some(command) = command {
                self.dispatch_control_event_for_local_player(
                    owner,
                    ControlEvent::RawPlayerControl { command, data: 0 },
                )?;
            }
            return Ok(());
        }
        if self.mode == AppMode::Menu && self.startup_view == StartupView::PlayerSelection {
            let native_delta = match delta {
                MouseScrollDelta::LineDelta(_, y) => (y * 60.0).round() as i32,
                MouseScrollDelta::PixelDelta(position) => {
                    (position.y / f64::from(output_scale.max(f32::EPSILON))).round() as i32
                }
            };
            if native_delta == 0 {
                return Ok(());
            }
            let mut actions = Vec::new();
            let mut scrolled = false;
            if let Some(dialog) = self.startup_player_dialog.as_mut() {
                if let Some(point) = dialog.pointer_position() {
                    let before = dialog.list_scroll_offset();
                    actions = dialog.handle_wheel(point, native_delta);
                    scrolled = dialog.list_scroll_offset() != before;
                }
            }
            self.process_player_dialog_actions(actions)?;
            if scrolled {
                self.plrsel_last_click = None;
                self.mark_menu_dirty();
            }
            return Ok(());
        }
        if self.mode == AppMode::Menu && self.startup_view == StartupView::NetworkGame {
            let native_delta = match delta {
                MouseScrollDelta::LineDelta(_, y) => (y * 60.0).round() as i32,
                MouseScrollDelta::PixelDelta(position) => {
                    (position.y / f64::from(output_scale.max(f32::EPSILON))).round() as i32
                }
            };
            if native_delta == 0 {
                return Ok(());
            }
            let actions = self
                .startup_network_dialog
                .as_mut()
                .and_then(|dialog| {
                    dialog
                        .pointer_position()
                        .map(|point| dialog.handle_wheel(point, native_delta))
                })
                .unwrap_or_default();
            self.process_network_dialog_actions(actions)?;
            self.mark_menu_dirty();
            return Ok(());
        }
        if self.mode == AppMode::Menu && self.startup_view == StartupView::About {
            let delta = match delta {
                MouseScrollDelta::LineDelta(_, y) => (y * 60.0).round() as i32,
                MouseScrollDelta::PixelDelta(position) => {
                    (position.y / f64::from(output_scale.max(f32::EPSILON))).round() as i32
                }
            };
            if delta == 0 {
                return Ok(());
            }
            let fonts = self.assets.clonk_fonts.clone();
            let actions = fonts
                .as_deref()
                .and_then(|fonts| {
                    self.startup_about_dialog.as_mut().and_then(|dialog| {
                        dialog
                            .pointer_position()
                            .map(|point| dialog.handle_wheel(point, delta, fonts))
                    })
                })
                .unwrap_or_default();
            self.process_about_dialog_actions(actions)?;
            self.mark_menu_dirty();
            return Ok(());
        }
        if self.mode != AppMode::Menu || self.startup_view != StartupView::ScenarioBrowser {
            return Ok(());
        }
        if self.scenario_selector_discovery.is_some() {
            return Ok(());
        }
        let Some(point) = self.menu_state.pointer_position() else {
            return Ok(());
        };
        let (Some(fonts), Some(book_fonts)) = (
            self.assets.clonk_fonts.as_deref(),
            self.assets.book_fonts.as_deref(),
        ) else {
            return Ok(());
        };
        let layout = clonk_frontend::startup_scensel::scen_sel_layout(
            self.graphics.surface().width() as i32,
            self.graphics.surface().height() as i32,
            fonts,
        );
        let amount = match delta {
            MouseScrollDelta::LineDelta(_, y) => (-y * 60.0).round() as i32,
            MouseScrollDelta::PixelDelta(position) => {
                (-position.y / f64::from(output_scale.max(f32::EPSILON))).round() as i32
            }
        };
        if amount == 0 {
            return Ok(());
        }
        let contains = |rect: clonk_frontend::classic_gui::IntRect| {
            point.x >= rect.x as f32
                && point.x < (rect.x + rect.w) as f32
                && point.y >= rect.y as f32
                && point.y < (rect.y + rect.h) as f32
        };
        if let Some(map) = self.menu_state.current_map() {
            let transform = MapFolderTransform::for_map(
                map,
                &layout,
                self.graphics.surface().width(),
                self.graphics.surface().height(),
            );
            let info_rect = transform.rect(map.scenario_info_area);
            if !point_in_map_rect(point, &info_rect) {
                return Ok(());
            }
            self.startup_tooltip.pointer_left();
            let mut info_layout = layout;
            info_layout.selection_info = clonk_frontend::classic_gui::IntRect {
                x: info_rect.origin.x.round() as i32,
                y: info_rect.origin.y.round() as i32,
                w: info_rect.size.width.round() as i32,
                h: info_rect.size.height.round() as i32,
            };
            let metrics = {
                let info = scensel_selection_info(&self.menu_state);
                clonk_frontend::startup_scensel::selection_info_scroll_metrics(
                    &info_layout,
                    book_fonts,
                    &info,
                )
            };
            if self.menu_state.scroll_selection_info_by(amount, metrics) {
                self.mark_menu_dirty();
            }
            return Ok(());
        }
        if contains(layout.list) {
            self.startup_tooltip.pointer_left();
            let item_height = clonk_frontend::startup_scensel::scen_list_item_height(&book_fonts.text);
            let viewport_height = layout.list.h - 6;
            if self
                .menu_state
                .scroll_scenario_list_by(amount, viewport_height, item_height + 1)
            {
                self.mark_menu_dirty();
            }
            return Ok(());
        }
        if !contains(layout.selection_info) {
            return Ok(());
        }
        self.startup_tooltip.pointer_left();
        let metrics = {
            let info = scensel_selection_info(&self.menu_state);
            clonk_frontend::startup_scensel::selection_info_scroll_metrics(&layout, book_fonts, &info)
        };
        if self.menu_state.scroll_selection_info_by(amount, metrics) {
            self.mark_menu_dirty();
        }
        Ok(())
    }

    fn handle_startup_dialog_key(
        &mut self,
        key: KeyCode,
        state: ElementState,
    ) -> Result<bool, EngineError> {
        match self.startup_view {
            StartupView::NetworkGame => {
                let actions = self
                    .startup_network_dialog
                    .as_mut()
                    .map(|dialog| match state {
                        ElementState::Pressed => dialog.handle_key_down(key),
                        ElementState::Released => dialog.handle_key_up(key),
                    })
                    .unwrap_or_default();
                self.process_network_dialog_actions(actions)?;
            }
            StartupView::PlayerSelection => {
                let actions = self
                    .startup_player_dialog
                    .as_mut()
                    .map(|dialog| match state {
                        ElementState::Pressed => dialog.handle_key_down(key),
                        ElementState::Released => dialog.handle_key_up(key),
                    })
                    .unwrap_or_default();
                self.process_player_dialog_actions(actions)?;
            }
            StartupView::Options => {
                let actions = self
                    .startup_options_dialog
                    .as_mut()
                    .map(|dialog| match state {
                        ElementState::Pressed => dialog.handle_key_down(key),
                        ElementState::Released => dialog.handle_key_up(key),
                    })
                    .unwrap_or_default();
                self.process_options_dialog_actions(actions)?;
            }
            StartupView::About => {
                let actions = self
                    .startup_about_dialog
                    .as_mut()
                    .map(|dialog| match state {
                        ElementState::Pressed => dialog.handle_key_down(key),
                        ElementState::Released => dialog.handle_key_up(key),
                    })
                    .unwrap_or_default();
                self.process_about_dialog_actions(actions)?;
            }
            _ => return Ok(false),
        }
        Ok(true)
    }

    fn input_network_dialog(&self) -> Option<&clonk_frontend::startup_netdlg::NetDlgController> {
        if self.external_irc_dialog_visible {
            self.external_irc_dialog.as_ref()
        } else {
            self.startup_network_dialog.as_ref()
        }
    }

    fn input_network_dialog_mut(
        &mut self,
    ) -> Option<&mut clonk_frontend::startup_netdlg::NetDlgController> {
        if self.external_irc_dialog_visible {
            self.external_irc_dialog.as_mut()
        } else {
            self.startup_network_dialog.as_mut()
        }
    }

    fn handle_network_edit_key(
        &mut self,
        key: VirtualKeyCode,
        state: ElementState,
    ) -> Result<bool, EngineError> {
        use clonk_frontend::startup_netdlg::{
            NetDlgControl, NetDlgEditClipboardShortcut, NetDlgEditKey, NetDlgEditModifiers,
        };

        let embedded_network_chat =
            self.mode == AppMode::Menu && self.startup_view == StartupView::NetworkGame;
        if !self.external_irc_dialog_visible && !embedded_network_chat {
            return Ok(false);
        }
        if state == ElementState::Released && self.netdlg_edit_consumed_keys.remove(&key) {
            return Ok(true);
        }
        if state != ElementState::Pressed {
            return Ok(false);
        }

        let modifiers = self.keyboard_modifiers
            & (ModifiersState::ALT | ModifiersState::CTRL | ModifiersState::SHIFT);
        let edit_focused = self.input_network_dialog().is_some_and(|dialog| {
            matches!(
                dialog.focused_control(),
                NetDlgControl::JoinAddress | NetDlgControl::ChatInput
            )
        });
        // Both StartupNetBack and the Edit cursor bindings use exact modifier
        // masks. Modified Back/Left outside the edit, and Alt-modified ones
        // inside it, must not fall through to the modifier-blind GUI mapping.
        if matches!(key, VirtualKeyCode::Back | VirtualKeyCode::Left)
            && !modifiers.is_empty()
            && (!edit_focused || modifiers.contains(ModifiersState::ALT))
        {
            self.netdlg_edit_consumed_keys.insert(key);
            return Ok(true);
        }
        if !edit_focused {
            return Ok(false);
        }
        if key == VirtualKeyCode::Apps && modifiers.is_empty() {
            let outcome = self
                .input_network_dialog_mut()
                .map(|dialog| dialog.request_context_menu_from_key(clipboard_text_available()))
                .unwrap_or_default();
            if !outcome.captured {
                return Ok(false);
            }
            self.process_network_dialog_actions(outcome.actions)?;
            return Ok(true);
        }

        if modifiers.contains(ModifiersState::ALT) {
            return Ok(false);
        }
        let edit_key = match key {
            VirtualKeyCode::Left => Some(NetDlgEditKey::Left),
            VirtualKeyCode::Right => Some(NetDlgEditKey::Right),
            VirtualKeyCode::Home => Some(NetDlgEditKey::Home),
            VirtualKeyCode::End => Some(NetDlgEditKey::End),
            VirtualKeyCode::Back => Some(NetDlgEditKey::Backspace),
            VirtualKeyCode::Delete => Some(NetDlgEditKey::Delete),
            _ => None,
        };
        let shortcut = if modifiers == ModifiersState::CTRL {
            match key {
                VirtualKeyCode::C => Some(NetDlgEditClipboardShortcut::Copy),
                VirtualKeyCode::X => Some(NetDlgEditClipboardShortcut::Cut),
                VirtualKeyCode::V => Some(NetDlgEditClipboardShortcut::Paste),
                VirtualKeyCode::A => Some(NetDlgEditClipboardShortcut::SelectAll),
                _ => None,
            }
        } else {
            None
        };
        if edit_key.is_none() && shortcut.is_none() {
            return Ok(false);
        }

        let Some(fonts) = self.assets.clonk_fonts.clone() else {
            // The startup bootstrap guard reports missing fonts before this
            // route. Still consume the Edit-owned key rather than leaking it
            // to StartupNetBack if that invariant is broken.
            self.netdlg_edit_consumed_keys.insert(key);
            return Ok(true);
        };
        let clipboard = shortcut
            .filter(|shortcut| *shortcut == NetDlgEditClipboardShortcut::Paste)
            .and_then(|_| {
                arboard::Clipboard::new()
                    .and_then(|mut clipboard| clipboard.get_text())
                    .ok()
            });
        let outcome = self
            .input_network_dialog_mut()
            .map(|dialog| {
                if let Some(edit_key) = edit_key {
                    dialog.handle_edit_key_down(
                        edit_key,
                        NetDlgEditModifiers {
                            shift: modifiers.contains(ModifiersState::SHIFT),
                            control: modifiers.contains(ModifiersState::CTRL),
                        },
                        &fonts.text,
                    )
                } else {
                    dialog.handle_clipboard_shortcut(
                        shortcut.expect("checked clipboard shortcut"),
                        clipboard.as_deref(),
                        &fonts.text,
                    )
                }
            })
            .unwrap_or_default();
        if !outcome.captured {
            return Ok(false);
        }
        self.netdlg_edit_consumed_keys.insert(key);
        self.process_network_dialog_actions(outcome.actions)?;
        Ok(true)
    }

    fn handle_external_irc_dialog_key(
        &mut self,
        key: VirtualKeyCode,
        state: ElementState,
    ) -> Result<bool, EngineError> {
        if !self.external_irc_dialog_visible
            || (matches!(self.mode, AppMode::Running)
                && !self.runtime_default_dialog_is_top(RuntimeDefaultDialog::ExternalIrc))
        {
            return Ok(false);
        }
        let modifiers = self.keyboard_modifiers
            & (ModifiersState::ALT | ModifiersState::CTRL | ModifiersState::SHIFT);
        if key == VirtualKeyCode::Escape && modifiers.is_empty() {
            if state == ElementState::Pressed {
                self.hide_external_irc_dialog();
            }
            return Ok(true);
        }
        if self.handle_network_edit_key(key, state)? {
            return Ok(true);
        }
        let actions = if state == ElementState::Pressed
            && key == VirtualKeyCode::F4
            && modifiers == ModifiersState::CTRL
        {
            self.external_irc_dialog
                .as_mut()
                .map(clonk_frontend::startup_netdlg::NetDlgController::close_active_chat_sheet)
                .unwrap_or_default()
        } else if state == ElementState::Pressed
            && key == VirtualKeyCode::Tab
            && (modifiers == ModifiersState::CTRL
                || modifiers == (ModifiersState::CTRL | ModifiersState::SHIFT))
        {
            self.external_irc_dialog
                .as_mut()
                .map(|dialog| dialog.cycle_chat_sheet(modifiers.contains(ModifiersState::SHIFT)))
                .unwrap_or_default()
        } else if let Some(key) = map_key_code(key) {
            if key == KeyCode::Tab && !(modifiers.is_empty() || modifiers == ModifiersState::SHIFT)
            {
                Vec::new()
            } else {
                self.external_irc_dialog
                    .as_mut()
                    .map(|dialog| match state {
                        ElementState::Pressed => dialog.handle_key_down_with_tab_direction(
                            key,
                            modifiers == ModifiersState::SHIFT,
                        ),
                        ElementState::Released => dialog.handle_key_up(key),
                    })
                    .unwrap_or_default()
            }
        } else {
            Vec::new()
        };
        self.process_network_dialog_actions(actions)?;
        self.mark_menu_dirty();
        Ok(true)
    }

    fn handle_options_tab_key(
        &mut self,
        key: VirtualKeyCode,
        state: ElementState,
    ) -> Result<bool, EngineError> {
        if self.mode != AppMode::Menu
            || self.startup_view != StartupView::Options
            || key != VirtualKeyCode::Tab
        {
            return Ok(false);
        }
        let modifiers = self.keyboard_modifiers
            & (ModifiersState::ALT | ModifiersState::CTRL | ModifiersState::SHIFT);
        let route = if modifiers.is_empty() {
            Some((false, false))
        } else if modifiers == ModifiersState::SHIFT {
            Some((false, true))
        } else if modifiers == ModifiersState::CTRL {
            Some((true, false))
        } else if modifiers == (ModifiersState::CTRL | ModifiersState::SHIFT) {
            Some((true, true))
        } else {
            None
        };
        let Some((cycle_sheet, backwards)) = route else {
            // No other exact Alt/Ctrl/Shift mask owns GUIAdvanceFocus or the
            // tabular's Ctrl+Tab bindings. Consume it before the legacy
            // modifier-blind KeyCode mapping can invent a plain Tab.
            return Ok(true);
        };
        let actions = if state == ElementState::Pressed {
            self.startup_options_dialog
                .as_mut()
                .map(|dialog| {
                    if cycle_sheet {
                        dialog.handle_ctrl_tab(backwards)
                    } else {
                        dialog.handle_tab(backwards)
                    }
                })
                .unwrap_or_default()
        } else {
            Vec::new()
        };
        self.process_options_dialog_actions(actions)?;
        Ok(true)
    }

    fn handle_startup_tab_key(
        &mut self,
        key: VirtualKeyCode,
        state: ElementState,
    ) -> Result<bool, EngineError> {
        if self.mode != AppMode::Menu
            || key != VirtualKeyCode::Tab
            || !matches!(
                self.startup_view,
                StartupView::NetworkGame | StartupView::PlayerSelection | StartupView::About
            )
        {
            return Ok(false);
        }
        if self.startup_view == StartupView::PlayerSelection
            && self.startup_crew_rename.is_some()
        {
            // RenameEdit owns Tab as a focus-loss commit. Its FinishRename
            // restores the saved control and cancels this traversal.
            return Ok(false);
        }
        let modifiers = self.keyboard_modifiers
            & (ModifiersState::ALT | ModifiersState::CTRL | ModifiersState::SHIFT);
        if self.startup_view == StartupView::NetworkGame
            && (modifiers == ModifiersState::CTRL
                || modifiers == (ModifiersState::CTRL | ModifiersState::SHIFT))
            && self.startup_network_dialog.as_ref().is_some_and(|dialog| {
                dialog.mode() == clonk_frontend::startup_netdlg::NetDlgMode::Chat
                    && dialog.chat_page() == clonk_frontend::startup_netdlg::NetDlgChatPage::Chats
            })
        {
            let actions = if state == ElementState::Pressed {
                self.startup_network_dialog
                    .as_mut()
                    .map(|dialog| {
                        dialog.cycle_chat_sheet(modifiers.contains(ModifiersState::SHIFT))
                    })
                    .unwrap_or_default()
            } else {
                Vec::new()
            };
            self.process_network_dialog_actions(actions)?;
            return Ok(true);
        }
        let backwards = if modifiers.is_empty() {
            false
        } else if modifiers == ModifiersState::SHIFT {
            true
        } else {
            // C4GUI binds only exact Tab and Shift+Tab. Consume every other
            // modified Tab before the modifier-blind KeyCode mapping.
            return Ok(true);
        };
        if state == ElementState::Released {
            return Ok(true);
        }
        match self.startup_view {
            StartupView::NetworkGame => {
                let actions = self
                    .startup_network_dialog
                    .as_mut()
                    .map(|dialog| {
                        dialog.handle_key_down_with_tab_direction(KeyCode::Tab, backwards)
                    })
                    .unwrap_or_default();
                self.process_network_dialog_actions(actions)?;
            }
            StartupView::PlayerSelection => {
                let actions = self
                    .startup_player_dialog
                    .as_mut()
                    .map(|dialog| {
                        dialog.handle_key_down_with_tab_direction(KeyCode::Tab, backwards)
                    })
                    .unwrap_or_default();
                self.process_player_dialog_actions(actions)?;
            }
            StartupView::About => {
                let actions = self
                    .startup_about_dialog
                    .as_mut()
                    .map(|dialog| {
                        dialog.handle_key_down_with_tab_direction(KeyCode::Tab, backwards)
                    })
                    .unwrap_or_default();
                self.process_about_dialog_actions(actions)?;
            }
            _ => unreachable!("startup Tab view checked above"),
        }
        Ok(true)
    }

    fn handle_startup_hotkey(
        &mut self,
        key: VirtualKeyCode,
        state: ElementState,
    ) -> Result<bool, EngineError> {
        if self.mode != AppMode::Menu
            || self.game_over_dialog.is_some()
            || !matches!(
                self.startup_view,
                StartupView::MainMenu
                    | StartupView::PlayerSelection
                    | StartupView::Options
                    | StartupView::About
            )
        {
            return Ok(false);
        }
        let modifiers = self.keyboard_modifiers
            & (ModifiersState::ALT | ModifiersState::CTRL | ModifiersState::SHIFT);
        if modifiers != ModifiersState::ALT
            && modifiers != (ModifiersState::ALT | ModifiersState::SHIFT)
        {
            return Ok(modifiers.alt() && map_key_code(key).is_some());
        }
        // Plain dialog bindings compare the same exact modifier mask, so an
        // unmatched Alt key must not fall through to modifier-blind Rust
        // navigation. Key-up has no C++ mnemonic callback either.
        let suppress_plain_gui_key = map_key_code(key).is_some();
        if state != ElementState::Pressed {
            return Ok(suppress_plain_gui_key);
        }
        let Some(character) = startup_dialog_hotkey(key) else {
            return Ok(suppress_plain_gui_key);
        };
        let captured = match self.startup_view {
            StartupView::MainMenu => {
                let Some(actions) = self.main_menu_state.menu.handle_hotkey(character) else {
                    return Ok(suppress_plain_gui_key);
                };
                // Button::OnHotkey calls OnPress directly, bypassing the
                // SetDown/SetUp sounds used by pointer and focus activation.
                self.process_main_menu_actions_with_sound(actions, false)?;
                true
            }
            StartupView::PlayerSelection => {
                let Some(actions) = self
                    .startup_player_dialog
                    .as_mut()
                    .and_then(|dialog| dialog.handle_hotkey(character))
                else {
                    return Ok(suppress_plain_gui_key);
                };
                self.process_player_dialog_actions(actions)?;
                true
            }
            StartupView::Options => {
                if !self.startup_options_dialog_is_active() {
                    return Ok(suppress_plain_gui_key);
                }
                let Some(actions) = self
                    .startup_options_dialog
                    .as_mut()
                    .and_then(|dialog| dialog.handle_hotkey(character))
                else {
                    // Options has its own exact-Alt combo bindings below the
                    // mnemonic layer. Let an unmatched hotkey reach those;
                    // options_modified_gui_key_is_inert still suppresses every
                    // modifier-blind GUI fallback.
                    return Ok(false);
                };
                self.process_options_dialog_actions(actions)?;
                true
            }
            StartupView::About => {
                let Some(actions) = self
                    .startup_about_dialog
                    .as_mut()
                    .and_then(|dialog| dialog.handle_hotkey(character))
                else {
                    return Ok(suppress_plain_gui_key);
                };
                // See the Button::OnHotkey sound rule above.
                self.process_about_dialog_actions_with_sound(actions, false)?;
                true
            }
            _ => unreachable!("startup mnemonic view checked above"),
        };
        Ok(captured || suppress_plain_gui_key)
    }

    fn options_modified_gui_key_is_inert(&self, key: VirtualKeyCode) -> bool {
        if self.mode != AppMode::Menu
            || self.startup_view != StartupView::Options
            || key == VirtualKeyCode::Tab
            || map_key_code(key).is_none()
        {
            return false;
        }
        // C4KeyCodeEx matches the exact Alt/Ctrl/Shift mask for the Options
        // dialog bindings. Logo is not part of that mask, so Logo-only input
        // intentionally remains equivalent to the bare key.
        let modifiers = self.keyboard_modifiers
            & (ModifiersState::ALT | ModifiersState::CTRL | ModifiersState::SHIFT);
        if modifiers == ModifiersState::ALT
            && matches!(key, VirtualKeyCode::Down | VirtualKeyCode::Space)
            && self
                .startup_options_dialog
                .as_ref()
                .is_some_and(|dialog| {
                    matches!(
                        dialog.focused_program_control(),
                        Some(
                            clonk_frontend::startup_options_dlg::OptionsProgramFocusTarget::LanguageCombo
                                | clonk_frontend::startup_options_dlg::OptionsProgramFocusTarget::FontFaceCombo
                                | clonk_frontend::startup_options_dlg::OptionsProgramFocusTarget::FontSizeCombo
                        )
                    )
                })
        {
            return false;
        }
        !modifiers.is_empty()
    }

    fn handle_game_option_input_dialog_key(
        &mut self,
        key: VirtualKeyCode,
        state: ElementState,
    ) -> Result<bool, EngineError> {
        if self.game_option_input_dialog.is_none() {
            return Ok(false);
        }
        if self.running_chat_controller().is_some() && !self.running_chat_keyboard_active() {
            return Ok(false);
        }
        if self.context_menu.is_some() {
            return Ok(true);
        }
        let Some(layout) = self.game_option_input_layout() else {
            return Ok(true);
        };
        let Some(fonts) = self.assets.clonk_fonts.clone() else {
            tracing::error!("classic input dialog lost its required GUI fonts");
            return Ok(true);
        };
        let modifiers = InputDialogKeyModifiers {
            shift: self.keyboard_modifiers.shift(),
            control: self.keyboard_modifiers.ctrl(),
        };
        let c4_modifiers = self.keyboard_modifiers
            & (ModifiersState::ALT | ModifiersState::CTRL | ModifiersState::SHIFT);
        let hotkey_modifiers = c4_modifiers == ModifiersState::ALT
            || c4_modifiers == (ModifiersState::ALT | ModifiersState::SHIFT);
        let dialog_hotkey = hotkey_modifiers
            .then(|| context_menu_hotkey(key))
            .flatten();
        if hotkey_modifiers && dialog_hotkey.is_none() {
            return Ok(false);
        }
        if let Some(hotkey) = dialog_hotkey {
            if state == ElementState::Released {
                return Ok(false);
            }
            if !self
                .game_option_input_dialog
                .as_ref()
                .is_some_and(|dialog| dialog.controller.has_hotkey(hotkey))
            {
                return Ok(false);
            }
        }
        let clipboard_text = || {
            arboard::Clipboard::new()
                .and_then(|mut clipboard| clipboard.get_text())
                .ok()
        };
        let mut capture_release = false;
        let actions = if state == ElementState::Pressed
            && key == VirtualKeyCode::Apps
            && c4_modifiers.is_empty()
        {
            self.game_option_input_dialog
                .as_mut()
                .map(|dialog| {
                    dialog.controller.request_context_menu_from_key(
                        &layout,
                        clipboard_text_available(),
                        &InputDialogContextLabels::default(),
                    )
                })
                .map(|outcome| {
                    capture_release = outcome.capture_release;
                    outcome.actions
                })
                .unwrap_or_default()
        } else if state == ElementState::Pressed
            && c4_modifiers == ModifiersState::CTRL
            && matches!(
                key,
                VirtualKeyCode::A
                    | VirtualKeyCode::C
                    | VirtualKeyCode::V
                    | VirtualKeyCode::X
            )
        {
            let shortcut = match key {
                VirtualKeyCode::C => Some(InputDialogClipboardShortcut::Copy),
                VirtualKeyCode::X => Some(InputDialogClipboardShortcut::Cut),
                VirtualKeyCode::V => Some(InputDialogClipboardShortcut::Paste),
                VirtualKeyCode::A => Some(InputDialogClipboardShortcut::SelectAll),
                _ => None,
            };
            let shortcut = shortcut.expect("guarded classic edit shortcut");
            let clipboard = matches!(shortcut, InputDialogClipboardShortcut::Paste)
                .then(clipboard_text)
                .flatten();
            self.game_option_input_dialog
                .as_mut()
                .map(|dialog| {
                    dialog.controller.handle_clipboard_shortcut(
                        shortcut,
                        clipboard.as_deref(),
                        &layout,
                        &fonts.text,
                    )
                })
                .map(|outcome| {
                    capture_release = outcome.capture_release;
                    outcome.actions
                })
                .unwrap_or_default()
        } else if state == ElementState::Pressed {
            if !c4_modifiers.is_empty()
                && matches!(
                    key,
                    VirtualKeyCode::Return
                        | VirtualKeyCode::NumpadEnter
                        | VirtualKeyCode::Escape
                )
            {
                Vec::new()
            } else {
                let edit_key = match key {
                    VirtualKeyCode::Back => Some(InputDialogEditKey::Backspace),
                    VirtualKeyCode::Delete => Some(InputDialogEditKey::Delete),
                    VirtualKeyCode::Home => Some(InputDialogEditKey::Home),
                    VirtualKeyCode::End => Some(InputDialogEditKey::End),
                    VirtualKeyCode::Left => Some(InputDialogEditKey::Left),
                    VirtualKeyCode::Right => Some(InputDialogEditKey::Right),
                    _ => None,
                };
                if edit_key.is_some() && c4_modifiers.alt() {
                    Vec::new()
                } else if let Some(edit_key) = edit_key {
                    self.game_option_input_dialog
                        .as_mut()
                        .map(|dialog| {
                            dialog.controller.handle_edit_key_down(
                                edit_key,
                                modifiers,
                                &layout,
                                &fonts.text,
                            )
                        })
                        .unwrap_or_default()
                } else if hotkey_modifiers {
                    dialog_hotkey
                        .and_then(|hotkey| {
                            self.game_option_input_dialog
                                .as_mut()
                                .map(|dialog| dialog.controller.handle_hotkey(hotkey))
                        })
                        .unwrap_or_default()
                } else if let Some(gui_key) = map_key_code(key) {
                    self.game_option_input_dialog
                        .as_mut()
                        .map(|dialog| {
                            dialog.controller.route_key_down(
                                gui_key,
                                modifiers.shift,
                                &layout,
                                &fonts.text,
                            )
                        })
                        .map(|outcome| {
                            capture_release = outcome.capture_release;
                            outcome.actions
                        })
                        .unwrap_or_default()
                } else {
                    Vec::new()
                }
            }
        } else if let Some(gui_key) = map_key_code(key) {
            self.game_option_input_dialog
                .as_mut()
                .map(|dialog| dialog.controller.route_key_up(gui_key))
                .map(|outcome| outcome.actions)
                .unwrap_or_default()
        } else {
            Vec::new()
        };
        if state == ElementState::Pressed && capture_release {
            self.game_option_input_consumed_keys.insert(key);
        }
        self.finish_game_option_input_dialog_actions(actions)?;
        // C4GUI::Screen routes every key exclusively to the top modal. Some
        // edit/controller bindings intentionally report pass-through, but it
        // is pass-through within the modal dialog, never to ScenarioBrowser.
        Ok(true)
    }

    fn handle_league_signup_key(
        &mut self,
        key: VirtualKeyCode,
        state: ElementState,
    ) -> Result<bool, EngineError> {
        if self.league_signup_dialog.is_none() {
            return Ok(false);
        }
        if self.context_menu.is_some() {
            return Ok(true);
        }
        use clonk_frontend::league_signup::{
            LeagueSignupEditClipboardShortcut, LeagueSignupEditKey, LeagueSignupKeyModifiers,
        };
        let layout = self.league_signup_layout();
        let fonts = self.assets.clonk_fonts.clone();
        let c4_modifiers = self.keyboard_modifiers
            & (ModifiersState::ALT | ModifiersState::CTRL | ModifiersState::SHIFT);
        let modifiers = LeagueSignupKeyModifiers {
            shift: c4_modifiers.shift(),
            control: c4_modifiers.ctrl(),
        };
        let hotkey_modifiers = c4_modifiers == ModifiersState::ALT
            || c4_modifiers == (ModifiersState::ALT | ModifiersState::SHIFT);
        let actions = match state {
            ElementState::Pressed if hotkey_modifiers => context_menu_hotkey(key)
                .and_then(|character| {
                    self.league_signup_dialog
                        .as_mut()
                        .map(|dialog| dialog.controller.handle_hotkey(character))
                })
                .unwrap_or_default(),
            ElementState::Pressed
                if c4_modifiers == ModifiersState::CTRL
                    && matches!(
                        key,
                        VirtualKeyCode::A
                            | VirtualKeyCode::C
                            | VirtualKeyCode::X
                            | VirtualKeyCode::V
                    ) =>
            {
                let shortcut = match key {
                    VirtualKeyCode::A => Some(LeagueSignupEditClipboardShortcut::SelectAll),
                    VirtualKeyCode::C => Some(LeagueSignupEditClipboardShortcut::Copy),
                    VirtualKeyCode::X => Some(LeagueSignupEditClipboardShortcut::Cut),
                    VirtualKeyCode::V => Some(LeagueSignupEditClipboardShortcut::Paste),
                    _ => None,
                };
                let clipboard = (shortcut == Some(LeagueSignupEditClipboardShortcut::Paste))
                    .then(|| {
                        arboard::Clipboard::new()
                            .and_then(|mut clipboard| clipboard.get_text())
                            .ok()
                    })
                    .flatten();
                shortcut
                    .and_then(|shortcut| {
                        layout
                            .as_ref()
                            .zip(fonts.as_deref())
                            .and_then(|(layout, fonts)| {
                                self.league_signup_dialog.as_mut().map(|dialog| {
                                    dialog.controller.handle_clipboard_shortcut(
                                        shortcut,
                                        clipboard.as_deref(),
                                        layout,
                                        &fonts.text,
                                    )
                                })
                            })
                    })
                    .unwrap_or_default()
            }
            ElementState::Pressed if c4_modifiers.is_empty() && key == VirtualKeyCode::Apps => {
                layout
                    .as_ref()
                    .and_then(|layout| {
                        self.league_signup_dialog.as_ref().map(|dialog| {
                            dialog
                                .controller
                                .request_context_menu_from_key(clipboard_text_available(), layout)
                        })
                    })
                    .unwrap_or_default()
            }
            ElementState::Pressed if !c4_modifiers.alt() => {
                let edit_key = match key {
                    VirtualKeyCode::Back => Some(LeagueSignupEditKey::Backspace),
                    VirtualKeyCode::Delete => Some(LeagueSignupEditKey::Delete),
                    VirtualKeyCode::Home => Some(LeagueSignupEditKey::Home),
                    VirtualKeyCode::End => Some(LeagueSignupEditKey::End),
                    VirtualKeyCode::Left => Some(LeagueSignupEditKey::Left),
                    VirtualKeyCode::Right => Some(LeagueSignupEditKey::Right),
                    _ => None,
                };
                if let Some(edit_key) = edit_key {
                    self.league_signup_dialog
                        .as_mut()
                        .map(|dialog| match (layout.as_ref(), fonts.as_deref()) {
                            (Some(layout), Some(fonts)) => {
                                dialog.controller.handle_edit_key_with_layout(
                                    edit_key,
                                    modifiers,
                                    layout,
                                    &fonts.text,
                                )
                            }
                            _ => dialog.controller.handle_edit_key(edit_key, modifiers),
                        })
                        .unwrap_or_default()
                } else if let Some(gui_key) =
                    league_signup_dialog_key_code(key, c4_modifiers)
                {
                    self.league_signup_dialog
                        .as_mut()
                        .map(|dialog| dialog.controller.handle_key_down(gui_key, modifiers.shift))
                        .unwrap_or_default()
                } else {
                    Vec::new()
                }
            }
            ElementState::Released => league_signup_dialog_key_code(key, c4_modifiers)
                .and_then(|gui_key| {
                    self.league_signup_dialog
                        .as_mut()
                        .map(|dialog| dialog.controller.handle_key_up(gui_key))
                })
                .unwrap_or_default(),
            ElementState::Pressed => Vec::new(),
        };
        if state == ElementState::Pressed {
            self.league_signup_consumed_keys.insert(key);
        }
        self.process_league_signup_actions(actions)?;
        Ok(true)
    }

    fn handle_scenario_game_option_key(
        &mut self,
        key: VirtualKeyCode,
        state: ElementState,
    ) -> Result<bool, EngineError> {
        if self.mode != AppMode::Menu
            || self.startup_view != StartupView::ScenarioBrowser
            || self.game_option_input_dialog.is_some()
            || self.context_menu.is_some()
        {
            return Ok(false);
        }
        let release_latched =
            state == ElementState::Released && self.game_option_consumed_keys.remove(&key);
        let hotkey = context_menu_hotkey(key);
        let c4_modifiers = self.keyboard_modifiers
            & (ModifiersState::ALT | ModifiersState::CTRL | ModifiersState::SHIFT);
        if c4_modifiers.alt()
            && !c4_modifiers.ctrl()
            && hotkey.is_some_and(|hotkey| {
                self.scenario_game_options
                    .context()
                    .buttons()
                    .iter()
                    .any(|button| button.hotkey() == hotkey)
            })
        {
            if state == ElementState::Pressed {
                let actions = self
                    .scenario_game_options
                    .handle_hotkey(hotkey.expect("checked above"));
                self.finish_game_option_input(actions)?;
                self.game_option_consumed_keys.insert(key);
            }
            return Ok(true);
        }
        let Some(gui_key) = map_key_code(key) else {
            return Ok(release_latched);
        };
        let options_focused = self.scenario_game_options.focused_button().is_some();
        if gui_key == KeyCode::Tab && state == ElementState::Pressed {
            if options_focused {
                self.menu_state
                    .set_dialog_focus(ScenselDialogFocus::Options);
                let outcome = self
                    .scenario_game_options
                    .handle_key_down_with_tab_direction(
                        KeyCode::Tab,
                        self.keyboard_modifiers.shift(),
                    );
                self.finish_game_option_input(outcome.actions)?;
                self.game_option_consumed_keys.insert(key);
                return Ok(true);
            }
            self.advance_scensel_dialog_focus(self.keyboard_modifiers.shift());
            self.game_option_consumed_keys.insert(key);
            return Ok(true);
        }
        if !options_focused {
            return Ok(release_latched);
        }
        self.menu_state
            .set_dialog_focus(ScenselDialogFocus::Options);
        let outcome = match state {
            ElementState::Pressed => self.scenario_game_options.handle_key_down(gui_key),
            ElementState::Released => self.scenario_game_options.handle_key_up(gui_key),
        };
        if state == ElementState::Pressed && outcome.captured {
            self.game_option_consumed_keys.insert(key);
        }
        self.finish_game_option_input(outcome.actions)?;
        Ok(outcome.captured || release_latched)
    }

    fn reload_scenario_selector(
        &mut self,
        selected_identifier: Option<&str>,
        select_first_when_missing: bool,
        apply_live_search: bool,
    ) -> Result<(), EngineError> {
        self.cancel_scenario_selector_discovery();
        self.menu_state.scrollbar_interaction = None;
        let selected_identifier = selected_identifier.map(str::to_string);
        let Some(paths) = self.app_paths.clone() else {
            let entries = self
                .menu_state
                .stack
                .first()
                .map(|layer| layer.entries.clone())
                .unwrap_or_default();
            return self.apply_scenario_selector_entries(
                entries,
                selected_identifier,
                select_first_when_missing,
                apply_live_search,
                None,
            );
        };

        let (sender, receiver) = mpsc::channel();
        let cancel = Arc::new(AtomicBool::new(false));
        self.scenario_selector_discovery = Some(ScenarioSelectorDiscoveryState {
            receiver,
            cancel: Arc::clone(&cancel),
            progress_percent: 0,
            selected_identifier,
            select_first_when_missing,
            apply_live_search,
            retained_title: None,
        });
        thread::spawn(move || {
            let mut last_percent = 0_u8;
            let entries = load_frontend_scenarios_from_paths_with_progress(&paths, |percent| {
                if cancel.load(AtomicOrdering::Relaxed) {
                    return false;
                }
                if percent != last_percent {
                    last_percent = percent;
                    if sender
                        .send(ScenarioSelectorDiscoveryEvent::Progress(percent))
                        .is_err()
                    {
                        return false;
                    }
                }
                true
            });
            if let Some(entries) = entries {
                let _ = sender.send(ScenarioSelectorDiscoveryEvent::Finished(entries));
            }
        });
        self.mark_menu_dirty();
        Ok(())
    }

    fn apply_scenario_selector_entries(
        &mut self,
        mut entries: Vec<FrontendScenario>,
        selected_identifier: Option<String>,
        select_first_when_missing: bool,
        apply_live_search: bool,
        retained_title: Option<(String, String)>,
    ) -> Result<(), EngineError> {
        if let Some((identifier, title)) = retained_title {
            override_frontend_scenario_title(
                &mut entries,
                &identifier,
                &title,
                load_startup_alphabetical_sorting(self.app_paths.as_ref()),
            );
        }
        self.scenario_catalog = build_scenario_catalog(&entries);
        self.refresh_scenario_entry_enabled();
        self.handle_menu_input(move |menu| {
            menu.replace_discovered_entries(
                entries,
                selected_identifier.as_deref(),
                select_first_when_missing,
                apply_live_search,
            )
        })?;
        // Rebuilding the folder stack creates Book layers. Restore the
        // active folder's configured map style before syncing selection-
        // dependent controls so F5 does not silently leave FolderMap view.
        self.configure_current_folder_map();
        self.menu_state.sync_definition_checkbox_to_selection();
        self.sync_scenario_game_option_constraint();
        self.scensel_last_click = None;
        self.scensel_rename_pointer_focus = None;
        self.mark_menu_dirty();
        Ok(())
    }

    fn cancel_scenario_selector_discovery(&mut self) {
        if let Some(state) = self.scenario_selector_discovery.take() {
            state.cancel.store(true, AtomicOrdering::Relaxed);
        }
    }

    fn scenario_selector_loading_label(&self) -> Option<String> {
        let progress = self
            .scenario_selector_discovery
            .as_ref()
            .map(|state| state.progress_percent)?;
        let progress = progress.to_string();
        let template = self
            .startup_tooltip_resources
            .get("IDS_MSG_SCENARIODESC_LOADING")
            .cloned()
            .unwrap_or_else(|| "Loading... (%d%%)".to_string());
        Some(format_resource_string(template, &[&progress]).replace("%%", "%"))
    }

    fn poll_scenario_selector_discovery(&mut self) -> Result<(), EngineError> {
        let mut finished = None;
        let mut disconnected = false;
        loop {
            let Some(event) = self
                .scenario_selector_discovery
                .as_ref()
                .map(|state| state.receiver.try_recv())
            else {
                break;
            };
            match event {
                Ok(ScenarioSelectorDiscoveryEvent::Progress(percent)) => {
                    let state = self
                        .scenario_selector_discovery
                        .as_mut()
                        .expect("scenario discovery exists while polling");
                    let percent = state.progress_percent.max(percent.min(100));
                    if state.progress_percent != percent {
                        state.progress_percent = percent;
                        self.mark_menu_dirty();
                    }
                }
                Ok(ScenarioSelectorDiscoveryEvent::Finished(entries)) => {
                    finished = Some(entries);
                    break;
                }
                Err(TryRecvError::Empty) => break,
                Err(TryRecvError::Disconnected) => {
                    disconnected = true;
                    break;
                }
            }
        }

        if let Some(entries) = finished {
            let mut state = self
                .scenario_selector_discovery
                .take()
                .expect("finished scenario discovery retains its state");
            state.cancel.store(true, AtomicOrdering::Relaxed);
            if self.mode != AppMode::Menu || self.startup_view != StartupView::ScenarioBrowser {
                return Ok(());
            }
            let selected_identifier = state.selected_identifier.take();
            let retained_title = state.retained_title.take();
            return self.apply_scenario_selector_entries(
                entries,
                selected_identifier,
                state.select_first_when_missing,
                state.apply_live_search,
                retained_title,
            );
        }
        if disconnected {
            self.cancel_scenario_selector_discovery();
            self.status_text = "Scenario discovery interrupted".to_string();
            tracing::warn!("scenario discovery worker disconnected");
            self.mark_menu_dirty();
        }
        Ok(())
    }

    fn retain_renamed_scenario_title(
        &mut self,
        identifier: &str,
        title: &str,
    ) -> Result<(), EngineError> {
        if let Some(state) = self.scenario_selector_discovery.as_mut() {
            state.retained_title = Some((identifier.to_string(), title.to_string()));
            return Ok(());
        }
        let mut entries = self
            .menu_state
            .stack
            .first()
            .map(|layer| layer.entries.clone())
            .unwrap_or_default();
        let alphabetical_sorting =
            load_startup_alphabetical_sorting(self.app_paths.as_ref());
        if !override_frontend_scenario_title(
            &mut entries,
            identifier,
            title,
            alphabetical_sorting,
        ) {
            return Ok(());
        }
        self.scenario_catalog = build_scenario_catalog(&entries);
        self.refresh_scenario_entry_enabled();
        let identifier = identifier.to_string();
        self.handle_menu_input(move |menu| {
            menu.replace_discovered_entries(entries, Some(&identifier), true, false)
        })?;
        self.configure_current_folder_map();
        self.menu_state.sync_definition_checkbox_to_selection();
        self.sync_scenario_game_option_constraint();
        Ok(())
    }

    fn open_scenario_mission_access_dialog(&mut self) -> Result<(), EngineError> {
        self.guard_classic_global_gui_bootstrap()?;
        Self::guard_gui_overlay_result(
            "Mission Access input dialog",
            self.assets.input_dialog_resources().map(|_| ()),
        )?;
        self.close_context_menu_silently();
        self.scenario_game_options.cancel_interaction();
        let controller = InputDialogController::new(
            "Enter mission password:",
            "Mission Access",
            InputDialogIcon::OPTIONS,
        );
        self.startup_tooltip.pointer_left();
        self.game_option_input_dialog = Some(PendingGameOptionInputDialog {
            purpose: PendingInputDialogPurpose::ScenarioMissionAccess,
            controller,
        });
        self.game_option_input_consumed_keys.clear();
        self.game_option_input_pointer_capture = None;
        self.game_option_input_pointer_position = None;
        self.game_option_input_last_click = None;
        self.mark_menu_dirty();
        Ok(())
    }

    fn apply_scenario_mission_access(&mut self, input: &str) -> Result<(), EngineError> {
        let (remove, modules) = input
            .strip_prefix('-')
            .map_or((false, input), |modules| (true, modules));
        if modules.is_empty() {
            return Ok(());
        }
        let selected = self
            .menu_state
            .selected_scenario()
            .map(|entry| entry.identifier.clone());
        let value = self.mission_access.update_modules(modules, remove);
        if let Some(paths) = self.app_paths.as_ref() {
            if let Err(error) = persist_config_value(paths, "General", "MissionAccess", value) {
                tracing::warn!(%error, "failed to persist General.MissionAccess");
                self.status_text = format!("Unable to save mission access: {error}");
            }
        }
        // C4StartupScenSelDlg::UpdateList begins with AbortRenaming. Empty or
        // cancelled input never reaches this accepted/rebuild path.
        self.abort_scenario_rename();
        self.reload_scenario_selector(selected.as_deref(), true, true)
    }

    fn open_scenario_delete_dialog(&mut self) -> Result<(), EngineError> {
        self.menu_state.abort_renaming();
        let Some(selected) = self.menu_state.selected_scenario().cloned() else {
            return Ok(());
        };
        let distinct_sources = selected
            .source_paths
            .iter()
            .map(|source| scenario_root_key(source))
            .collect::<HashSet<_>>();
        if distinct_sources.len() > 1 {
            self.push_message_dialog(
                clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                    "Delete failure.",
                    "Delete",
                    clonk_frontend::message_dialog::MessageDialogIcon::ERROR,
                ),
                MessageDialogContinuation::None,
            )?;
            return Ok(());
        }
        let Some(path) = selected.path.clone() else {
            self.push_message_dialog(
                clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                    "Delete failure.",
                    "Delete",
                    clonk_frontend::message_dialog::MessageDialogIcon::ERROR,
                ),
                MessageDialogContinuation::None,
            )?;
            return Ok(());
        };
        let next_identifier = self
            .menu_state
            .visible_entries()
            .iter()
            .position(|entry| entry.identifier == selected.identifier)
            .and_then(|index| self.menu_state.visible_entries().get(index + 1))
            .map(|entry| entry.identifier.clone());
        let type_name = match selected.kind {
            ScenarioKind::Scenario => "Scenario",
            ScenarioKind::Folder
                if path
                    .extension()
                    .and_then(|extension| extension.to_str())
                    .is_some_and(|extension| extension.eq_ignore_ascii_case("c4f")) =>
            {
                "Scenario folder"
            }
            _ => "Directory",
        };
        let subject = format!("{type_name} {}", selected.title);
        let warning = if scenario_storage_is_original(&path) {
            format!("{subject} is an original file. Are your sure you want to delete it?")
        } else {
            format!("Delete {subject}?")
        };
        self.push_message_dialog(
            clonk_frontend::message_dialog::MessageDialogState::new(
                warning,
                "Delete",
                clonk_frontend::message_dialog::MessageDialogButtons::YES_NO,
                clonk_frontend::message_dialog::MessageDialogIcon::CONFIRM,
                clonk_frontend::message_dialog::MessageDialogSize::Regular,
                false,
            ),
            MessageDialogContinuation::DeleteScenario {
                path,
                next_identifier,
            },
        )
    }

    fn delete_scenario_and_refresh(
        &mut self,
        path: &Path,
        next_identifier: Option<&str>,
    ) -> Result<(), EngineError> {
        if let Err(error) = delete_scenario_storage(path) {
            tracing::warn!(%error, path = %path.display(), "failed to delete scenario entry");
            self.push_message_dialog(
                clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                    "Delete failure.",
                    "Delete",
                    clonk_frontend::message_dialog::MessageDialogIcon::ERROR,
                ),
                MessageDialogContinuation::None,
            )?;
            return Ok(());
        }
        self.reload_scenario_selector(next_identifier, false, false)
    }

    fn commit_scenario_rename(&mut self, focus_lost: bool) -> Result<(), EngineError> {
        let Some((identifier, original_title, action)) = self
            .menu_state
            .rename_edit
            .as_mut()
            .map(|rename| {
                (
                    rename.identifier.clone(),
                    rename.edit.label_text().to_string(),
                    if focus_lost {
                        rename.edit.focus_lost()
                    } else {
                        rename.edit.finish_input()
                    },
                )
            })
        else {
            return Ok(());
        };
        let RenameEditAction::Submit(title) = action else {
            self.abort_scenario_rename();
            self.mark_menu_dirty();
            return Ok(());
        };
        if title == original_title {
            self.menu_state.resolve_renaming(RenameEditResult::Deleted);
            self.set_scensel_dialog_focus(ScenselDialogFocus::List);
            self.mark_menu_dirty();
            return Ok(());
        }
        let scenario = self
            .scenario_catalog
            .get(&identifier)
            .cloned()
            .or_else(|| {
                self.menu_state
                    .visible_entries()
                    .iter()
                    .find(|entry| entry.identifier == identifier)
                    .cloned()
            });
        let result = (|| -> Result<String> {
            let scenario = scenario.ok_or_else(|| anyhow!("selected scenario is stale"))?;
            let path = scenario
                .path
                .as_deref()
                .ok_or_else(|| anyhow!("selected scenario has no storage path"))?;
            let distinct_sources = scenario
                .source_paths
                .iter()
                .map(|source| scenario_root_key(source))
                .collect::<HashSet<_>>();
            anyhow::ensure!(
                distinct_sources.len() <= 1,
                "merged scenario entries cannot be renamed safely"
            );
            let language = scenario_title_language(self.app_paths.as_ref());
            let destination =
                rename_scenario_storage(path, scenario.kind, &title, &language)?;
            let filename = destination
                .file_name()
                .and_then(|name| name.to_str())
                .ok_or_else(|| anyhow!("renamed scenario has no UTF-8 filename"))?;
            let parent = identifier.rsplit_once('/').map(|(parent, _)| parent);
            Ok(parent.map_or_else(|| filename.to_string(), |parent| format!("{parent}/{filename}")))
        })();
        match result {
            Ok(identifier) => {
                self.menu_state.resolve_renaming(RenameEditResult::Deleted);
                let refresh_result = self
                    .reload_scenario_selector(Some(&identifier), true, true)
                    .and_then(|()| self.retain_renamed_scenario_title(&identifier, &title));
                self.set_scensel_dialog_focus(ScenselDialogFocus::List);
                refresh_result?;
            }
            Err(error) => {
                tracing::warn!(%error, "failed to rename scenario entry");
                self.menu_state.resolve_renaming(RenameEditResult::Invalid);
                self.push_message_dialog(
                    clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                        error.to_string(),
                        "Rename failure",
                        clonk_frontend::message_dialog::MessageDialogIcon::ERROR,
                    ),
                    MessageDialogContinuation::None,
                )?;
            }
        }
        self.mark_menu_dirty();
        Ok(())
    }

    fn handle_scenario_rename_key(
        &mut self,
        key: VirtualKeyCode,
        state: ElementState,
    ) -> Result<bool, EngineError> {
        if self.menu_state.rename_edit.is_none() {
            return Ok(false);
        }
        let c4_modifiers = self.keyboard_modifiers
            & (ModifiersState::ALT | ModifiersState::CTRL | ModifiersState::SHIFT);
        if c4_modifiers.is_empty() && key == VirtualKeyCode::F5 {
            if state == ElementState::Pressed {
                self.abort_scenario_rename();
            }
            return Ok(false);
        }
        let alt_hotkey_modifiers = c4_modifiers == ModifiersState::ALT
            || c4_modifiers == (ModifiersState::ALT | ModifiersState::SHIFT);
        let matched_option_hotkey = alt_hotkey_modifiers
            && context_menu_hotkey(key).is_some_and(|hotkey| {
                hotkey == 'D'
                    || self
                        .scenario_game_options
                        .context()
                        .buttons()
                        .iter()
                        .any(|button| button.hotkey() == hotkey)
            });
        let mission_access_hotkey = key == VirtualKeyCode::M
            && c4_modifiers == ModifiersState::ALT
            && self.menu_state.current_map().is_none();
        if state == ElementState::Pressed && (matched_option_hotkey || mission_access_hotkey) {
            // Dialog hotkeys invoke controls directly; they do not move focus
            // out of RenameEdit. Let the matching selector control handle the
            // key while the inline edit remains active.
            return Ok(false);
        }
        let commits_on_focus_loss = state == ElementState::Pressed
            && ((key == VirtualKeyCode::F && c4_modifiers == ModifiersState::CTRL)
                || (key == VirtualKeyCode::Tab
                    && (c4_modifiers.is_empty() || c4_modifiers == ModifiersState::SHIFT)));
        if commits_on_focus_loss {
            self.commit_scenario_rename(true)?;
            // FinishRename restores/sets focus during OnLooseFocus, which
            // makes Dialog::SetFocus cancel the original transfer.
            return Ok(true);
        }
        if state == ElementState::Released {
            return Ok(true);
        }
        let ctrl = c4_modifiers.ctrl();
        let shift = c4_modifiers.shift();
        let cursor_modifiers = !c4_modifiers.alt();
        match key {
            VirtualKeyCode::F2 if c4_modifiers.is_empty() => {}
            VirtualKeyCode::Escape if c4_modifiers.is_empty() => {
                self.abort_scenario_rename();
            }
            VirtualKeyCode::Return | VirtualKeyCode::NumpadEnter if c4_modifiers.is_empty() => {
                self.commit_scenario_rename(false)?;
            }
            VirtualKeyCode::Back if cursor_modifiers => {
                if let Some(rename) = self.menu_state.rename_edit.as_mut() {
                    rename.edit.backspace(ctrl, shift);
                }
            }
            VirtualKeyCode::Delete if cursor_modifiers => {
                if let Some(rename) = self.menu_state.rename_edit.as_mut() {
                    rename.edit.delete(ctrl, shift);
                }
            }
            VirtualKeyCode::Left if cursor_modifiers => {
                if let Some(rename) = self.menu_state.rename_edit.as_mut() {
                    rename
                        .edit
                        .move_cursor(RenameEditCursorOperation::Left, ctrl, shift);
                }
            }
            VirtualKeyCode::Right if cursor_modifiers => {
                if let Some(rename) = self.menu_state.rename_edit.as_mut() {
                    rename
                        .edit
                        .move_cursor(RenameEditCursorOperation::Right, ctrl, shift);
                }
            }
            VirtualKeyCode::Home if cursor_modifiers => {
                if let Some(rename) = self.menu_state.rename_edit.as_mut() {
                    rename
                        .edit
                        .move_cursor(RenameEditCursorOperation::Home, ctrl, shift);
                }
            }
            VirtualKeyCode::End if cursor_modifiers => {
                if let Some(rename) = self.menu_state.rename_edit.as_mut() {
                    rename
                        .edit
                        .move_cursor(RenameEditCursorOperation::End, ctrl, shift);
                }
            }
            VirtualKeyCode::A if c4_modifiers == ModifiersState::CTRL => {
                if let Some(rename) = self.menu_state.rename_edit.as_mut() {
                    rename.edit.select_all();
                }
            }
            VirtualKeyCode::C if c4_modifiers == ModifiersState::CTRL => {
                let result = self
                    .menu_state
                    .rename_edit
                    .as_mut()
                    .map(|rename| {
                        transfer_edit_selection(&mut rename.edit, false, |selected| {
                            arboard::Clipboard::new().and_then(|mut clipboard| {
                                clipboard.set_text(selected.to_string())
                            })
                        })
                    });
                if let Some(Err(error)) = result {
                    tracing::warn!(%error, "failed to copy scenario rename text");
                }
            }
            VirtualKeyCode::X if c4_modifiers == ModifiersState::CTRL => {
                let result = self
                    .menu_state
                    .rename_edit
                    .as_mut()
                    .map(|rename| {
                        transfer_edit_selection(&mut rename.edit, true, |selected| {
                            arboard::Clipboard::new().and_then(|mut clipboard| {
                                clipboard.set_text(selected.to_string())
                            })
                        })
                    });
                if let Some(Err(error)) = result {
                    tracing::warn!(%error, "failed to cut scenario rename text");
                }
            }
            VirtualKeyCode::V if c4_modifiers == ModifiersState::CTRL => {
                match arboard::Clipboard::new().and_then(|mut clipboard| clipboard.get_text()) {
                    Ok(text) => {
                        if let Some(rename) = self.menu_state.rename_edit.as_mut() {
                            rename.edit.insert_text(&text);
                        }
                    }
                    Err(error) => tracing::warn!(%error, "failed to paste scenario rename text"),
                }
            }
            _ => {}
        }
        self.mark_menu_dirty();
        Ok(true)
    }

    fn handle_startup_crew_rename_key(
        &mut self,
        key: VirtualKeyCode,
        state: ElementState,
    ) -> Result<bool, EngineError> {
        if self.startup_view != StartupView::PlayerSelection
            || self.startup_crew_rename.is_none()
        {
            return Ok(false);
        }
        let modifiers = self.keyboard_modifiers
            & (ModifiersState::ALT | ModifiersState::CTRL | ModifiersState::SHIFT);
        if state == ElementState::Pressed
            && key == VirtualKeyCode::Apps
            && modifiers.is_empty()
        {
            if let Some(rect) = self.startup_crew_rename_rect() {
                let anchor = GuiPoint::new(
                    (rect.x + rect.w / 2) as f32,
                    (rect.y + rect.h / 2) as f32,
                );
                self.open_startup_crew_rename_context_menu(anchor)?;
            }
            return Ok(true);
        }
        if state == ElementState::Pressed
            && key == VirtualKeyCode::Tab
            && (modifiers.is_empty() || modifiers == ModifiersState::SHIFT)
        {
            self.commit_startup_crew_rename(true)?;
            return Ok(true);
        }
        if state == ElementState::Released {
            return Ok(true);
        }
        let ctrl = modifiers.ctrl();
        let shift = modifiers.shift();
        let cursor_modifiers = !modifiers.alt();
        match key {
            VirtualKeyCode::F2 if modifiers.is_empty() => {
                let index = self
                    .startup_crew_rename
                    .as_ref()
                    .map(|rename| rename.index)
                    .expect("active crew rename remains installed");
                self.abort_startup_crew_rename();
                self.start_startup_crew_rename(index)?;
            }
            VirtualKeyCode::Escape if modifiers.is_empty() => {
                self.abort_startup_crew_rename();
            }
            VirtualKeyCode::Return | VirtualKeyCode::NumpadEnter if modifiers.is_empty() => {
                self.commit_startup_crew_rename(false)?;
            }
            VirtualKeyCode::Back if cursor_modifiers => {
                if let Some(rename) = self.startup_crew_rename.as_mut() {
                    rename.edit.backspace(ctrl, shift);
                }
            }
            VirtualKeyCode::Delete if cursor_modifiers => {
                if let Some(rename) = self.startup_crew_rename.as_mut() {
                    rename.edit.delete(ctrl, shift);
                }
            }
            VirtualKeyCode::Left if cursor_modifiers => {
                if let Some(rename) = self.startup_crew_rename.as_mut() {
                    rename
                        .edit
                        .move_cursor(RenameEditCursorOperation::Left, ctrl, shift);
                }
            }
            VirtualKeyCode::Right if cursor_modifiers => {
                if let Some(rename) = self.startup_crew_rename.as_mut() {
                    rename
                        .edit
                        .move_cursor(RenameEditCursorOperation::Right, ctrl, shift);
                }
            }
            VirtualKeyCode::Home if cursor_modifiers => {
                if let Some(rename) = self.startup_crew_rename.as_mut() {
                    rename
                        .edit
                        .move_cursor(RenameEditCursorOperation::Home, ctrl, shift);
                }
            }
            VirtualKeyCode::End if cursor_modifiers => {
                if let Some(rename) = self.startup_crew_rename.as_mut() {
                    rename
                        .edit
                        .move_cursor(RenameEditCursorOperation::End, ctrl, shift);
                }
            }
            VirtualKeyCode::A if modifiers == ModifiersState::CTRL => {
                if let Some(rename) = self.startup_crew_rename.as_mut() {
                    rename.edit.select_all();
                }
            }
            VirtualKeyCode::C if modifiers == ModifiersState::CTRL => {
                let result = self.startup_crew_rename.as_mut().map(|rename| {
                    transfer_edit_selection(&mut rename.edit, false, |selected| {
                        arboard::Clipboard::new()
                            .and_then(|mut clipboard| clipboard.set_text(selected.to_string()))
                    })
                });
                if let Some(Err(error)) = result {
                    tracing::warn!(%error, "failed to copy startup crew rename text");
                }
            }
            VirtualKeyCode::X if modifiers == ModifiersState::CTRL => {
                let result = self.startup_crew_rename.as_mut().map(|rename| {
                    transfer_edit_selection(&mut rename.edit, true, |selected| {
                        arboard::Clipboard::new()
                            .and_then(|mut clipboard| clipboard.set_text(selected.to_string()))
                    })
                });
                if let Some(Err(error)) = result {
                    tracing::warn!(%error, "failed to cut startup crew rename text");
                }
            }
            VirtualKeyCode::V if modifiers == ModifiersState::CTRL => {
                match arboard::Clipboard::new().and_then(|mut clipboard| clipboard.get_text()) {
                    Ok(text) => {
                        if let Some(rename) = self.startup_crew_rename.as_mut() {
                            rename.edit.insert_text(&text);
                        }
                    }
                    Err(error) => {
                        tracing::warn!(%error, "failed to paste startup crew rename text")
                    }
                }
            }
            _ => {}
        }
        self.mark_menu_dirty();
        Ok(true)
    }

    fn handle_scenario_selector_override_key(
        &mut self,
        key: VirtualKeyCode,
        state: ElementState,
    ) -> Result<bool, EngineError> {
        if self.mode != AppMode::Menu
            || self.startup_view != StartupView::ScenarioBrowser
            || self.context_menu.is_some()
            || state != ElementState::Pressed
        {
            return Ok(false);
        }

        // These are PRIO_CtrlOverride bindings on C4StartupScenSelDlg.  In
        // particular, unmodified Delete outranks the normal-priority search
        // edit, and Alt+M outranks the Comment option mnemonic.  C4KeyCodeEx
        // compares the complete modifier mask, so modified F2/F5/Delete and
        // Ctrl+Alt+M are different keys.
        let c4_modifiers = self.keyboard_modifiers
            & (ModifiersState::ALT | ModifiersState::CTRL | ModifiersState::SHIFT);
        let no_modifiers = c4_modifiers.is_empty();
        let blocked_while_loading = (no_modifiers
            && (matches!(key, VirtualKeyCode::F5 | VirtualKeyCode::F2)
                || key == VirtualKeyCode::Delete && !self.menu_state.search_focused()))
            || (c4_modifiers == ModifiersState::ALT && key == VirtualKeyCode::M);
        if self.scenario_selector_discovery.is_some() {
            return Ok(blocked_while_loading);
        }
        let book_selection = self.menu_state.current_map().is_none()
            && self.menu_state.selected_scenario().is_some();
        match key {
            VirtualKeyCode::F5 if no_modifiers => {
                if self.scenario_selector_discovery.is_none() {
                    let selected = self
                        .menu_state
                        .selected_scenario()
                        .map(|entry| entry.identifier.clone());
                    self.reload_scenario_selector(selected.as_deref(), true, true)?;
                }
                Ok(true)
            }
            VirtualKeyCode::F2 if no_modifiers && book_selection => {
                let previous_focus = self.scensel_focus_snapshot();
                if self.menu_state.start_renaming_selected(previous_focus) {
                    self.scenario_game_options.set_focused_button(None);
                }
                self.mark_menu_dirty();
                Ok(true)
            }
            VirtualKeyCode::Delete if no_modifiers && book_selection => {
                self.open_scenario_delete_dialog()?;
                Ok(true)
            }
            VirtualKeyCode::M
                if c4_modifiers == ModifiersState::ALT
                    && self.menu_state.current_map().is_none() =>
            {
                self.open_scenario_mission_access_dialog()?;
                Ok(true)
            }
            _ => Ok(false),
        }
    }

    fn reconcile_network_stats_series(&mut self) {
        if self.network_stats.is_none() {
            return;
        }

        let clients = self
            .control_clients
            .snapshot()
            .into_iter()
            .filter_map(|client| {
                ClientId::try_from(client.client_id).ok().map(|client_id| {
                    (
                        client_id,
                        legacy_presentation_text(client.name.as_bytes()),
                    )
                })
            })
            .collect::<Vec<_>>();
        let client_ids = clients
            .iter()
            .map(|(client_id, _)| *client_id)
            .collect::<HashSet<_>>();
        let players = self
            .engine
            .players()
            .map(|player| {
                let color = player.color().map_or(0x00ff_ffff, |color| {
                    (u32::from(color.r) << 16)
                        | (u32::from(color.g) << 8)
                        | u32::from(color.b)
                });
                (player.id(), player.name().to_string(), color)
            })
            .collect::<Vec<_>>();
        let player_ids = players
            .iter()
            .map(|(player_id, _, _)| *player_id)
            .collect::<HashSet<_>>();
        let removed_clients = self
            .network_stats_clients
            .difference(&client_ids)
            .copied()
            .collect::<Vec<_>>();
        let removed_players = self
            .network_stats_players
            .difference(&player_ids)
            .copied()
            .collect::<Vec<_>>();

        let stats = self
            .network_stats
            .as_mut()
            .expect("network statistics presence checked above");
        for client_id in removed_clients {
            stats.remove_client(client_id);
        }
        for (client_id, name) in clients {
            if !self.network_stats_clients.contains(&client_id) {
                stats.register_client(client_id, name);
            }
        }
        for player_id in removed_players {
            stats.remove_player(player_id);
        }
        for (player_id, name, color) in players {
            if !self.network_stats_players.contains(&player_id) {
                stats.register_player(player_id, name, color);
            }
        }
        self.network_stats_clients = client_ids;
        self.network_stats_players = player_ids;
    }

    fn record_network_stats_control_frame(&mut self) {
        let control_rate = self.engine.control_rate();
        if !matches!(self.mode, AppMode::Running)
            || self.network_stats.is_none()
            || control_rate <= 0
            || self.engine.frame() % control_rate as u64 != 0
        {
            return;
        }
        self.reconcile_network_stats_series();
        let samples = self
            .engine
            .take_player_control_counts()
            .into_iter()
            .map(|(player_id, controls, actions)| PlayerControlSample {
                player_id,
                controls,
                actions,
            })
            .collect::<Vec<_>>();
        if let Some(stats) = self.network_stats.as_mut() {
            stats.record_control_frame(control_rate, samples);
        }
    }

    fn record_network_stats_frame(&mut self) {
        if !matches!(self.mode, AppMode::Running) || self.network_stats.is_none() {
            return;
        }
        let object_count = self
            .snapshot
            .objects
            .iter()
            // C4ObjectList::ObjectCount checks the raw nonzero Status field:
            // both Normal (1) and Inactive (2) objects are represented.
            .filter(|object| object.status != clonk_engine::ObjectStatus::Deleted)
            .count();
        if let Some(stats) = self.network_stats.as_mut() {
            stats.record_frame(i32::try_from(object_count).unwrap_or(i32::MAX));
        }
    }

    fn record_network_stats_second(&mut self) {
        if !matches!(self.mode, AppMode::Running) || self.network_stats.is_none() {
            return;
        }
        self.reconcile_network_stats_series();
        let mut message_pings = BTreeMap::<ClientId, i32>::new();
        if let Some(connections) = self
            .network
            .as_ref()
            .and_then(|network| network.runtime_connections().ok())
        {
            for connection in connections {
                if matches!(connection.usage.as_str(), "Msg" | "Data/Msg") {
                    // C4Network2Stats samples getMsgConn()->getLag()
                    // (src/C4Network2Stats.cpp:336-343).
                    message_pings
                        .entry(connection.client_id)
                        .or_insert(connection.lag_ms);
                }
            }
        }
        let pings = message_pings
            .into_iter()
            .map(|(client_id, lag_ms)| ClientPingSample {
                client_id,
                lag_ms: Some(lag_ms),
            })
            .collect::<Vec<_>>();
        if let Some(stats) = self.network_stats.as_mut() {
            let (input, output) = self.network.as_ref().map_or(
                (
                    ProtocolRateSample::new(0, 0),
                    ProtocolRateSample::new(0, 0),
                ),
                NetworkManager::protocol_rate_samples,
            );
            stats.record_second(self.frames_per_second, input, output, pings);
        }
    }

    fn network_chart_graph_snapshot(
        graph: clonk_network::NetworkStatsGraph<'_>,
        network_input_title: &str,
        network_output_title: &str,
    ) -> clonk_frontend::network_chart::NetworkChartGraphSnapshot {
        let series = (0..graph.series_count())
            .filter_map(|index| graph.series(index))
            .map(|series| {
                let start_time = series.start_time();
                let values = (start_time..series.end_time())
                    .map(|time| series.value(time))
                    .collect::<Vec<_>>();
                let title = match series.title() {
                    "Network input" => network_input_title,
                    "Network output" => network_output_title,
                    title => title,
                };
                clonk_frontend::network_chart::NetworkChartSeriesSnapshot::new(
                    title,
                    series.color(),
                    start_time,
                    values,
                )
            })
            .collect();
        clonk_frontend::network_chart::NetworkChartGraphSnapshot::new(graph.title(), series)
    }

    fn refresh_network_chart_dialog(&mut self) {
        let Some(aliases) = self.network_chart_dialog.as_ref().map(|dialog| {
            dialog
                .tab_names()
                .into_iter()
                .map(str::to_string)
                .collect::<Vec<_>>()
        }) else {
            return;
        };
        let network_input_title =
            self.runtime_resource_text("IDS_NET_INPUT", "Network Input");
        let network_output_title =
            self.runtime_resource_text("IDS_NET_OUTPUT", "Network Output");
        let Some(stats) = self.network_stats.as_mut() else {
            return;
        };
        stats.update();
        let snapshots = aliases
            .iter()
            .filter_map(|alias| {
                stats
                    .graph_by_name(alias)
                    .map(|graph| {
                        (
                            alias.clone(),
                            Self::network_chart_graph_snapshot(
                                graph,
                                &network_input_title,
                                &network_output_title,
                            ),
                        )
                    })
            })
            .collect::<Vec<_>>();
        if let Some(dialog) = self.network_chart_dialog.as_mut() {
            for (alias, graph) in snapshots {
                dialog.set_graph_snapshot(&alias, graph);
            }
        }
    }

    fn runtime_default_dialog_visible(&self, dialog: RuntimeDefaultDialog) -> bool {
        match dialog {
            RuntimeDefaultDialog::Scoreboard => self.scoreboard_dialog.is_some(),
            RuntimeDefaultDialog::NetworkChart => self.network_chart_dialog.is_some(),
            RuntimeDefaultDialog::ClientList => self.runtime_client_list.is_some(),
            RuntimeDefaultDialog::GameOver => self.game_over_dialog.is_some(),
            RuntimeDefaultDialog::ExternalIrc => self.external_irc_dialog_visible,
        }
    }

    /// Returns a complete bottom-to-top projection. The fallback entries keep
    /// older direct-state fixtures deterministic; production show/close paths
    /// populate the retained order explicitly.
    fn runtime_default_dialog_order_snapshot(&self) -> Vec<RuntimeDefaultDialog> {
        let mut order = self
            .runtime_default_dialog_order
            .iter()
            .copied()
            .filter(|dialog| self.runtime_default_dialog_visible(*dialog))
            .collect::<Vec<_>>();
        let fallback = if self.runtime_client_list_above_game_over {
            [
                RuntimeDefaultDialog::Scoreboard,
                RuntimeDefaultDialog::NetworkChart,
                RuntimeDefaultDialog::GameOver,
                RuntimeDefaultDialog::ClientList,
                RuntimeDefaultDialog::ExternalIrc,
            ]
        } else {
            [
                RuntimeDefaultDialog::Scoreboard,
                RuntimeDefaultDialog::NetworkChart,
                RuntimeDefaultDialog::ClientList,
                RuntimeDefaultDialog::GameOver,
                RuntimeDefaultDialog::ExternalIrc,
            ]
        };
        for dialog in fallback {
            if self.runtime_default_dialog_visible(dialog) && !order.contains(&dialog) {
                order.push(dialog);
            }
        }
        order
    }

    fn sync_runtime_default_dialog_compatibility(&mut self) {
        let order = self.runtime_default_dialog_order_snapshot();
        let client = order
            .iter()
            .position(|dialog| *dialog == RuntimeDefaultDialog::ClientList);
        let game_over = order
            .iter()
            .position(|dialog| *dialog == RuntimeDefaultDialog::GameOver);
        self.runtime_client_list_above_game_over =
            client.zip(game_over).is_some_and(|(client, game_over)| client > game_over);
    }

    fn show_or_raise_runtime_default_dialog(&mut self, dialog: RuntimeDefaultDialog) {
        let mut order = self.runtime_default_dialog_order_snapshot();
        order.retain(|candidate| *candidate != dialog);
        order.push(dialog);
        if self.network_chart_elevated
            && dialog != RuntimeDefaultDialog::NetworkChart
            && self.network_chart_dialog.is_some()
        {
            order.retain(|candidate| *candidate != RuntimeDefaultDialog::NetworkChart);
            order.push(RuntimeDefaultDialog::NetworkChart);
        }
        self.runtime_default_dialog_order = order;
        self.sync_runtime_default_dialog_compatibility();
    }

    fn activate_runtime_default_dialog(&mut self, dialog: RuntimeDefaultDialog) {
        match dialog {
            RuntimeDefaultDialog::Scoreboard => {
                self.activate_running_dialog_stack_only(RunningDialogStackEntry::Scoreboard);
            }
            RuntimeDefaultDialog::ClientList => {
                self.activate_running_dialog_stack_only(
                    RunningDialogStackEntry::RuntimeClientList,
                );
            }
            RuntimeDefaultDialog::NetworkChart
            | RuntimeDefaultDialog::GameOver
            | RuntimeDefaultDialog::ExternalIrc => {}
        }
        self.show_or_raise_runtime_default_dialog(dialog);
        if dialog == RuntimeDefaultDialog::NetworkChart {
            self.network_chart_elevated = !self.message_dialogs.is_empty()
                || self.running_chat_controller().is_some();
            if self.network_chart_elevated {
                self.message_dialog_active_index = None;
                self.set_running_chat_active(false);
            }
        } else {
            if self.network_chart_elevated {
                let mut order = self.runtime_default_dialog_order_snapshot();
                order.retain(|candidate| *candidate != dialog);
                order.push(dialog);
                self.runtime_default_dialog_order = order;
            }
            self.network_chart_elevated = false;
            self.sync_runtime_default_dialog_compatibility();
        }
    }

    fn hide_runtime_default_dialog(&mut self, dialog: RuntimeDefaultDialog) {
        let chart_was_elevated = dialog == RuntimeDefaultDialog::NetworkChart
            && self.network_chart_elevated;
        let chart_owned_input = chart_was_elevated && self.network_chart_elevated_owns_input();
        let mut order = self.runtime_default_dialog_order_snapshot();
        order.retain(|candidate| *candidate != dialog);
        self.runtime_default_dialog_order = order;
        if dialog == RuntimeDefaultDialog::NetworkChart {
            self.network_chart_elevated = false;
            if chart_owned_input {
                match self.running_active_dialog {
                    Some(RunningDialogStackEntry::Chat) if self.running_chat.is_some() => {
                        self.set_running_chat_active(true);
                    }
                    Some(RunningDialogStackEntry::Message(stack_id)) => {
                        self.message_dialog_active_index = self.running_message_index(stack_id);
                    }
                    _ => {
                        self.message_dialog_active_index = None;
                    }
                }
            }
        }
        self.sync_runtime_default_dialog_compatibility();
    }

    fn reset_runtime_default_dialog_order(&mut self) {
        self.runtime_default_dialog_order.clear();
        self.network_chart_elevated = false;
        if self.external_irc_dialog_visible {
            self.runtime_default_dialog_order
                .push(RuntimeDefaultDialog::ExternalIrc);
        }
        self.runtime_client_list_above_game_over = false;
    }

    fn runtime_default_dialog_is_top(&self, dialog: RuntimeDefaultDialog) -> bool {
        self.runtime_default_dialog_order_snapshot().last().copied() == Some(dialog)
    }

    fn runtime_top_default_dialog_is_exclusive(&self) -> bool {
        matches!(
            self.runtime_default_dialog_order_snapshot().last(),
            Some(RuntimeDefaultDialog::GameOver | RuntimeDefaultDialog::ExternalIrc)
        )
    }

    fn runtime_pointer_fallback_is_exclusive(&self) -> bool {
        if self.network_chart_elevated {
            return false;
        }
        if self.running_chat_controller().is_some()
            || self.top_message_dialog_is_exclusive()
        {
            return true;
        }
        self.message_dialogs.is_empty() && self.runtime_top_default_dialog_is_exclusive()
    }

    fn runtime_default_dialog_is_above(
        &self,
        upper: RuntimeDefaultDialog,
        lower: RuntimeDefaultDialog,
    ) -> bool {
        let order = self.runtime_default_dialog_order_snapshot();
        order.iter().position(|dialog| *dialog == upper).zip(
            order.iter().position(|dialog| *dialog == lower),
        ).is_some_and(|(upper, lower)| upper > lower)
    }

    fn toggle_network_chart(&mut self) {
        self.cancel_network_chart_pointer_capture();
        if self.network_chart_dialog.take().is_some() {
            self.hide_runtime_default_dialog(RuntimeDefaultDialog::NetworkChart);
            return;
        }
        self.reconcile_network_stats_series();
        let caption = self.runtime_resource_text("IDS_NET_STATISTICS", "Statistics");
        self.network_chart_dialog = Some(
            clonk_frontend::network_chart::NetworkChartDialog::new_with_caption(
                self.network.is_some(),
                caption,
            ),
        );
        self.show_or_raise_runtime_default_dialog(RuntimeDefaultDialog::NetworkChart);
        self.refresh_network_chart_dialog();
    }

    /// The chart is a non-exclusive shared-screen dialog. Only its explicit
    /// fullscreen Escape binding is reachable during play, and the callback
    /// is conditional on the chart still being the active top dialog.
    fn runtime_modal_above_network_chart(&self) -> bool {
        self.league_signup_dialog.is_some()
            || self.definition_selector.is_some()
            || self.startup_options_advanced_dialog.is_some()
            || self.startup_player_properties_dialog.is_some()
            || self
                .network_start_wait
                .as_ref()
                .is_some_and(|wait| wait.visible)
    }

    fn network_chart_is_active_dialog(&self) -> bool {
        matches!(self.mode, AppMode::Running)
            && self.network_chart_dialog.is_some()
            && self.runtime_default_dialog_is_top(RuntimeDefaultDialog::NetworkChart)
            && self.context_menu.is_none()
            && !self.runtime_modal_above_network_chart()
            && (self.network_chart_elevated_owns_input()
                || (self.message_dialogs.is_empty()
                    && self.game_option_input_dialog.is_none()))
    }

    fn network_chart_elevated_owns_input(&self) -> bool {
        self.network_chart_elevated
            && self.message_dialog_active_index.is_none()
            && !self.running_chat_active()
    }

    fn network_chart_renders_elevated(&self) -> bool {
        matches!(self.mode, AppMode::Running)
            && self.network_chart_elevated
            && self.network_chart_dialog.is_some()
            && self.runtime_default_dialog_is_top(RuntimeDefaultDialog::NetworkChart)
            && !self.runtime_modal_above_network_chart()
    }

    fn network_chart_is_elevated_pointer_layer(&self) -> bool {
        self.network_chart_renders_elevated() && self.context_menu.is_none()
    }

    fn network_chart_owns_stronger_escape(&self) -> bool {
        self.network_chart_is_active_dialog()
            && !self.local_player_key_binding_in_scope(VirtualKeyCode::Escape)
    }

    fn gamepad_player_button_in_scope(
        &self,
        slot: GamepadSlot,
        button: LegacyGamepadButton,
    ) -> bool {
        self.gamepad_bindings
            .control_candidates_for_button(
                slot.index(),
                button.index(),
                ElementState::Pressed,
            )
            .any(|(control_set, _)| {
                i32::try_from(control_set)
                    .ok()
                    .and_then(|control_set| self.local_controls.owner_for_set(control_set))
                    .and_then(|owner| self.engine.player(owner))
                    .is_some()
            })
    }

    fn gamepad_player_axis_in_scope(
        &self,
        slot: GamepadSlot,
        axis: LegacyGamepadAxis,
    ) -> bool {
        self.gamepad_bindings
            .control_candidates_for_axis(
                slot.index(),
                axis.index(),
                axis.high(),
                ElementState::Pressed,
            )
            .any(|(control_set, _)| {
                i32::try_from(control_set)
                    .ok()
                    .and_then(|control_set| self.local_controls.owner_for_set(control_set))
                    .and_then(|owner| self.engine.player(owner))
                    .is_some()
            })
    }

    fn handle_network_chart_key(
        &mut self,
        key: VirtualKeyCode,
        state: ElementState,
    ) -> bool {
        if self.network_chart_consumed_keys.contains(&key) {
            if state == ElementState::Released {
                self.network_chart_consumed_keys.remove(&key);
            }
            return true;
        }
        if key != VirtualKeyCode::Escape
            || !self.network_chart_owns_stronger_escape()
            || !(self.keyboard_modifiers
                & (ModifiersState::ALT | ModifiersState::CTRL | ModifiersState::SHIFT))
                .is_empty()
        {
            return false;
        }
        let action = self
            .network_chart_dialog
            .as_mut()
            .map(|dialog| {
                dialog.handle_key(KeyCode::Escape, state == ElementState::Pressed)
            })
            .unwrap_or(clonk_frontend::network_chart::NetworkChartDialogAction::Ignored);
        match action {
            clonk_frontend::network_chart::NetworkChartDialogAction::Ignored => false,
            clonk_frontend::network_chart::NetworkChartDialogAction::Handled
            | clonk_frontend::network_chart::NetworkChartDialogAction::Captured => {
                if state == ElementState::Pressed {
                    self.network_chart_consumed_keys.insert(key);
                }
                true
            }
            clonk_frontend::network_chart::NetworkChartDialogAction::Close => {
                self.cancel_network_chart_pointer_capture();
                self.network_chart_dialog = None;
                self.hide_runtime_default_dialog(RuntimeDefaultDialog::NetworkChart);
                self.network_chart_consumed_keys.insert(key);
                true
            }
        }
    }

    fn handle_network_chart_pointer_button(&mut self, state: ElementState) -> bool {
        if !matches!(self.mode, AppMode::Running) || self.network_chart_dialog.is_none() {
            self.cancel_network_chart_pointer_capture();
            return false;
        }
        let release_captured =
            state == ElementState::Released && self.network_chart_pointer_capture;
        let Some(point) = self.running_pointer_position else {
            if release_captured {
                self.cancel_network_chart_pointer_capture();
            }
            return release_captured;
        };
        let assets = Arc::clone(&self.assets);
        let Some(resources) = assets.network_chart_resources() else {
            return release_captured;
        };
        let preferred = scoreboard_preferred_rect(
            self.graphics
                .preferred_dialog_rect(self.mouse_control.then_some(self.local_owner)),
        );
        let action = self
            .network_chart_dialog
            .as_mut()
            .map(|dialog| match state {
                ElementState::Pressed => dialog.pointer_down(point, preferred, resources),
                ElementState::Released => dialog.pointer_up(point, preferred, resources),
            })
            .unwrap_or(clonk_frontend::network_chart::NetworkChartDialogAction::Ignored);
        let handled = release_captured
            || action != clonk_frontend::network_chart::NetworkChartDialogAction::Ignored;
        if action == clonk_frontend::network_chart::NetworkChartDialogAction::Close {
            self.network_chart_dialog = None;
            self.hide_runtime_default_dialog(RuntimeDefaultDialog::NetworkChart);
        }
        match state {
            ElementState::Pressed => {
                self.network_chart_pointer_capture =
                    action == clonk_frontend::network_chart::NetworkChartDialogAction::Captured
            }
            ElementState::Released => self.network_chart_pointer_capture = false,
        }
        if handled {
            self.cancel_ingame_mouse_gestures();
        }
        handled
    }

    fn cancel_network_chart_pointer_capture(&mut self) {
        self.network_chart_pointer_capture = false;
        if let Some(dialog) = self.network_chart_dialog.as_mut() {
            dialog.cancel_pointer_capture();
        }
    }

    fn handle_network_chart_pointer_move(&mut self, point: GuiPoint) -> bool {
        let (Some(dialog), Some(resources)) = (
            self.network_chart_dialog.as_mut(),
            self.assets.network_chart_resources(),
        ) else {
            return false;
        };
        let preferred = scoreboard_preferred_rect(
            self.graphics
                .preferred_dialog_rect(self.mouse_control.then_some(self.local_owner)),
        );
        dialog.pointer_move(point, preferred, resources)
    }

    fn network_chart_contains_point(&self, point: GuiPoint) -> bool {
        let (Some(dialog), Some(resources)) = (
            self.network_chart_dialog.as_ref(),
            self.assets.network_chart_resources(),
        ) else {
            return false;
        };
        let preferred = scoreboard_preferred_rect(
            self.graphics
                .preferred_dialog_rect(self.mouse_control.then_some(self.local_owner)),
        );
        let bounds = dialog.layout(preferred, resources).bounds;
        point.x >= bounds.x as f32
            && point.x < bounds.x.saturating_add(bounds.w) as f32
            && point.y >= bounds.y as f32
            && point.y < bounds.y.saturating_add(bounds.h) as f32
    }

    fn runtime_network_role(&self) -> RuntimeNetworkRole {
        let Some(network) = self.network.as_ref() else {
            return RuntimeNetworkRole::Offline;
        };
        match (self.network_mode.as_ref(), network.local_client_id()) {
            (Some(NetworkMode::Host(_)), 0) => RuntimeNetworkRole::Host,
            (Some(NetworkMode::Client(_)), local_client_id) if local_client_id != 0 => {
                RuntimeNetworkRole::Client
            }
            _ => RuntimeNetworkRole::Ambiguous,
        }
    }

    fn runtime_network_is_paused(&self) -> bool {
        debug_assert!(self.network.is_some());
        // C4Network2::isRunning requires both GS_Go and a fully acknowledged
        // status. Either an active PAUSE/GO barrier or stopped control is
        // therefore paused for TogglePause's immediate routing decision.
        self.runtime_network_status_barrier.is_some() || !self.network_control_running
    }

    fn runtime_halt_active(&self) -> bool {
        if self.network.is_some() {
            // The synchronized status barrier owns network HaltCount. Control
            // stops at the same reached/committed boundary that native tests
            // before Control.Execute and the simulation ticks.
            !self.network_control_running
        } else {
            self.offline_halt_count != 0
        }
    }

    fn request_host_runtime_pause(&mut self, paused: bool) {
        let target_tick = if paused {
            // C4Network2::Pause targets Control.getNextControlTick().
            self.next_network_control_tick()
        } else {
            // C4Network2::Start targets the current ControlTick, which Rust's
            // already-advanced cadence clock exposes through this projection.
            self.displayed_network_control_tick()
        };
        let status = clonk_network::NetworkStatus {
            state: if paused {
                clonk_network::NETWORK_STATE_PAUSE
            } else {
                clonk_network::NETWORK_STATE_GO
            },
            control_mode: self.league_vote_control_mode(),
            target_tick,
        };
        match self.change_runtime_network_status(status) {
            Ok(()) => {
                // ChangeGameStatus changes the advertised Status before the
                // synchronized halt is reached, just as C++ IsPaused does.
                self.host_reference_paused = paused;
                self.publish_running_host_reference();
            }
            Err(error) => tracing::error!(%error, paused, "failed to toggle host pause status"),
        }
    }

    fn set_runtime_pause(&mut self, paused: bool) {
        let role = self.runtime_network_role();
        let currently_paused = match role {
            RuntimeNetworkRole::Offline => self.offline_halt_count != 0,
            RuntimeNetworkRole::Host | RuntimeNetworkRole::Client => {
                self.runtime_network_is_paused()
            }
            RuntimeNetworkRole::Ambiguous => return,
        };
        if paused == currently_paused {
            return;
        }
        match role {
            RuntimeNetworkRole::Offline => {
                // C++ HaltCount is an integer for nested engine holds, but
                // Game::Pause and Game::Unpause assign true/false.
                self.offline_halt_count = i32::from(paused);
            }
            RuntimeNetworkRole::Host | RuntimeNetworkRole::Client
                if self.network_is_league && !self.game_over_handled =>
            {
                let _ = self.submit_own_league_vote(
                    LeagueVoteSubject {
                        vote_type: clonk_engine::VOTE_TYPE_PAUSE,
                        data: i32::from(paused),
                    },
                    true,
                );
            }
            RuntimeNetworkRole::Host => self.request_host_runtime_pause(paused),
            RuntimeNetworkRole::Client => {
                // Native non-host Pause/Unpause is a consumed no-op.
            }
            RuntimeNetworkRole::Ambiguous => unreachable!("handled above"),
        }
    }

    fn toggle_runtime_pause(&mut self) {
        // C4Game::TogglePause refuses while the evaluation dialog owns its
        // temporary halt. This guard applies to the console Pause key too.
        if self.game_over_dialog.is_some() {
            return;
        }
        let paused = match self.runtime_network_role() {
            RuntimeNetworkRole::Offline => self.offline_halt_count != 0,
            RuntimeNetworkRole::Host | RuntimeNetworkRole::Client => {
                self.runtime_network_is_paused()
            }
            RuntimeNetworkRole::Ambiguous => return,
        };
        self.set_runtime_pause(!paused);
    }

    fn apply_engine_pause_game_requests(&mut self) {
        let requests = self.engine.take_pause_game_requests();
        if !matches!(self.mode, AppMode::Running) || self.game_over_dialog.is_some() {
            // The evaluation dialog owns native's temporary game pause.
            // PauseGame(true) is guarded by TogglePause, while PauseGame()
            // sees the existing hold and is a no-op. Rust freezes evaluation
            // at the app boundary, so consume both without creating a hold
            // that would survive Continue.
            return;
        }
        for request in requests {
            match request {
                clonk_engine::PauseGameRequest::Halt => self.set_runtime_pause(true),
                clonk_engine::PauseGameRequest::Toggle => self.toggle_runtime_pause(),
            }
        }
    }

    fn runtime_help_columns(&self) -> Result<&RuntimeHelpColumns> {
        self.runtime_help_text_cache
            .get_or_init(|| {
                load_runtime_help_language_table(self.app_paths.as_ref())
                    .and_then(|table| build_runtime_help_columns(&table))
                    .map_err(|error| format!("{error:#}"))
            })
            .as_ref()
            .map_err(|detail| anyhow!(detail.clone()))
    }

    fn runtime_key_config(&self) -> Result<&RuntimeKeyConfig> {
        self.runtime_key_config_cache
            .get_or_init(|| {
                load_runtime_global_key_config(self.app_paths.as_ref())
                    .map_err(|error| format!("{error:#}"))
            })
            .as_ref()
            .map_err(|detail| anyhow!(detail.clone()))
    }

    fn runtime_keyboard_binding_matches(
        &self,
        name: &str,
        key: VirtualKeyCode,
        default_matches: bool,
    ) -> bool {
        self.runtime_key_config()
            .ok()
            .and_then(|config| {
                config.keyboard_override_matches(name, key, self.keyboard_modifiers)
            })
            .unwrap_or(default_matches)
    }

    fn runtime_control_candidates_for_keyboard(
        &self,
        key: VirtualKeyCode,
        state: ElementState,
    ) -> Vec<(usize, Option<ControlEvent>)> {
        let config = self.runtime_key_config().ok();
        let modifiers = self.keyboard_modifiers
            & (ModifiersState::ALT | ModifiersState::CTRL | ModifiersState::SHIFT);
        let mut candidates = Vec::new();
        for control_set in 0..KeyboardBindings::SET_COUNT {
            for (control_index, id) in ControlBindingId::ALL.into_iter().enumerate() {
                let name = format!("Kbd{}Key{}", control_set + 1, control_index + 1);
                let matches = config
                    .and_then(|config| config.override_for(&name))
                    .map(|codes| codes.iter().any(|code| code.matches(key, modifiers)))
                    .unwrap_or_else(|| {
                        modifiers.is_empty()
                            && self.bindings.key_for_set(control_set, id) == Some(key)
                    });
                if matches {
                    if let Some(candidate) =
                        KeyboardBindings::control_candidate_for_set(control_set, id, state)
                    {
                        candidates.push(candidate);
                    }
                }
            }
        }
        candidates
    }

    fn runtime_control_candidates_for_gamepad_button(
        &self,
        slot: u8,
        button: u8,
        state: ElementState,
    ) -> Vec<(usize, Option<ControlEvent>)> {
        let mut candidates = Vec::new();
        let Some(config) = self.runtime_key_config().ok() else {
            return candidates;
        };
        for control_set in 0..KeyboardBindings::SET_COUNT {
            for (control_index, id) in ControlBindingId::ALL.into_iter().enumerate() {
                let name = format!("Kbd{}Key{}", control_set + 1, control_index + 1);
                let matches = config.override_for(&name).is_some_and(|codes| {
                    codes.iter().any(|code| code.matches_gamepad_button(slot, button))
                });
                if matches {
                    if let Some(candidate) =
                        KeyboardBindings::control_candidate_for_set(control_set, id, state)
                    {
                        candidates.push(candidate);
                    }
                }
            }
        }
        candidates
    }

