    fn classic_lobby_option_rows_for(
        &self,
        mode: &NetworkMode,
        control_rate: i32,
        runtime_join_allowed: bool,
        active_player_count: i32,
        teams: Option<&clonk_engine::InitialNetworkTeamMetadata>,
    ) -> Vec<LobbyOptionRow> {
        let (role, control_mode) = match mode {
            NetworkMode::Host(HostSettings {
                prepared: Some(prepared),
                ..
            }) => (
                LobbyRole::Host,
                prepared.host_config().initial_status.control_mode,
            ),
            NetworkMode::Host(_) => (LobbyRole::Host, 0),
            NetworkMode::Client(_) => (
                LobbyRole::Client,
                self.pending_network_join_data
                    .as_ref()
                    .map_or(-1, |join| join.status.control_mode),
            ),
        };
        let labels = self.classic_lobby_option_labels();
        let mut rows = core_lobby_option_rows(
            role,
            &labels,
            control_mode,
            control_rate,
            runtime_join_allowed,
        );
        if let Some(teams) = teams {
            rows.extend(team_lobby_option_rows(
                role,
                &labels,
                LobbyTeamOptionState {
                    active: teams.active,
                    auto_generate_teams: teams.auto_generate_teams,
                    distribution: teams.team_distribution as i32,
                    team_colors: teams.team_colors,
                    random_team_count: teams.random_team_count,
                    active_player_count,
                    team_count: i32::try_from(teams.teams.len()).unwrap_or(i32::MAX),
                },
            ));
        }
        rows
    }

    fn current_classic_lobby_option_rows(&self) -> Option<Vec<LobbyOptionRow>> {
        let mode = self.network_mode.as_ref()?;
        let runtime_join_allowed = self
            .classic_host_lobby
            .as_ref()
            .map_or(false, |lobby| lobby.runtime_join_allowed);
        let control_rate = self
            .network_control_clock
            .map(NetworkControlClock::control_rate)
            .unwrap_or_else(|| self.engine.control_rate());
        let active_player_count = i32::try_from(
            self.control_player_infos
                .retained_rows_snapshot()
                .1
                .iter()
                .flat_map(|(_, _, players)| players)
                .filter(|player| player.flags & clonk_engine::PLAYER_INFO_FLAG_REMOVED == 0)
                .count(),
        )
        .unwrap_or(i32::MAX);
        let teams = match mode {
            NetworkMode::Host(_) => self
                .network_team_assignment
                .as_ref()
                .map(NetworkTeamAssignmentState::teams),
            NetworkMode::Client(_) => None,
        };
        Some(self.classic_lobby_option_rows_for(
            mode,
            control_rate,
            runtime_join_allowed,
            active_player_count,
            teams,
        ))
    }

    /// Mirrors `C4GameOptionsList::Activate`/its one-second callback. An
    /// activation calls through even when values compare equal; inactive
    /// sheets retain their last projection and do no periodic work.
    fn refresh_classic_lobby_options(&mut self, force: bool) -> bool {
        if !self.classic_host_lobby.as_ref().is_some_and(|lobby| {
            lobby.controller.active_sheet() == LobbySheet::Options
        }) {
            return false;
        }
        let Some(rows) = self.current_classic_lobby_option_rows() else {
            return false;
        };
        let Some(lobby) = self.classic_host_lobby.as_mut() else {
            return false;
        };
        let changed = lobby.controller.option_rows() != rows;
        if force || changed {
            lobby.controller.set_option_rows(rows);
        }
        if changed {
            self.close_stale_classic_lobby_team_combo();
        }
        changed
    }

    fn classic_host_lobby_roster_rows(
        &self,
        mode: &NetworkMode,
        local_name: &str,
        nick: &str,
    ) -> (Vec<LobbyRosterRow>, i32) {
        let parameters = match mode {
            NetworkMode::Host(HostSettings {
                prepared: Some(prepared),
                ..
            }) => prepared
                .host_config()
                .initial_join_snapshot
                .as_ref()
                .map(|snapshot| &snapshot.parameters),
            NetworkMode::Client(_) => self
                .pending_network_join_data
                .as_ref()
                .map(|join| &join.parameters),
            NetworkMode::Host(_) => None,
        };
        let teams = parameters.map(|parameters| &parameters.teams);
        let league_mode = parameters.is_some_and(synchronized_parameters_are_league);
        let default_player_icon = self
            .staged_network_host_scenario
            .as_ref()
            .map(|staged| &staged.default_player_icon);
        let default_crew_icon = self.staged_network_host_scenario.as_ref().map(|staged| {
            clonk_frontend::classic_gui::blacken_transparent_pixels(&staged.default_crew_icon)
        });
        let replay = self
            .staged_network_host_scenario
            .as_ref()
            .and_then(|staged| staged.scenario.lobby_metadata())
            .is_some_and(|metadata| metadata.head().is_replay());
        let (_, retained) = self.control_player_infos.retained_rows_snapshot();
        let retained_players = retained
            .iter()
            .flat_map(|(client_id, _, players)| {
                players.iter().map(move |player| (*client_id, player))
            })
            .collect::<Vec<_>>();
        let is_visible = |player: &clonk_engine::ControlPlayerInfoEntry| {
            player.flags
                & (clonk_engine::PLAYER_INFO_FLAG_REMOVED | clonk_engine::PLAYER_INFO_FLAG_INVISIBLE)
                == 0
        };
        let active_players = i32::try_from(
            retained_players
                .iter()
                .filter(|(_, player)| player.flags & clonk_engine::PLAYER_INFO_FLAG_REMOVED == 0)
                .count(),
        )
        .unwrap_or(i32::MAX);
        let player_name = |player: &clonk_engine::ControlPlayerInfoEntry| {
            if !player.league_account.is_empty() {
                let account = legacy_presentation_text(player.league_account.as_bytes());
                if player.clan_tag.is_empty() {
                    account
                } else {
                    format!(
                        "<c afafaf>{}</c> {account}",
                        legacy_presentation_text(player.clan_tag.as_bytes())
                    )
                }
            } else if !player.forced_name.is_empty() {
                legacy_presentation_text(player.forced_name.as_bytes())
            } else {
                legacy_presentation_text(player.name.as_bytes())
            }
        };
        let restore_player = |id: i32| {
            parameters.and_then(|parameters| {
                parameters
                    .restore_player_infos
                    .clients
                    .iter()
                    .flat_map(|client| &client.players)
                    .find(|player| player.id == id)
            })
        };
        let lobby_color = |player: &clonk_engine::ControlPlayerInfoEntry| {
            let random_invisible = teams.is_some_and(|teams| {
                teams.team_distribution == 4
                    && teams.team_colors != 0
                    && teams.teams.iter().any(|team| team.id == player.team)
                    && !player.is_joined()
                    && player.savegame_player == 0
            });
            if random_invisible {
                player.original_color
            } else {
                player.color
            }
        };
        let player_row = |client_id: i32,
                          player: &clonk_engine::ControlPlayerInfoEntry,
                          joined_player: Option<&clonk_engine::ControlPlayerInfoEntry>,
                          selectable: bool| {
            let color = lobby_color(player);
            let team = teams.filter(|teams| teams.active != 0).map(|teams| {
                let visible = teams.team_distribution != 4;
                let name = if visible {
                    teams
                        .teams
                        .iter()
                        .find(|team| team.id == player.team)
                        .map(|team| legacy_presentation_text(team.name.as_bytes()))
                        .unwrap_or_default()
                } else {
                    self.runtime_resource_text("IDS_MSG_RNDTEAM", "Random team")
                };
                LobbyTeamValue {
                    id: player.team,
                    name,
                    selectable: selectable
                        && visible
                        && classic_lobby_player_can_choose_team(
                            teams,
                            player,
                            joined_player.is_some(),
                        ),
                }
            });
            let league_score = (player.league_score != 0 || player.league_projected_gain >= 0)
                .then(|| {
                    if player.league_projected_gain >= 0
                        && teams.is_none_or(|teams| teams.team_distribution != 4)
                    {
                        format!(
                            "{} ({:+})",
                            player.league_score, player.league_projected_gain
                        )
                    } else {
                        player.league_score.to_string()
                    }
                });
            let icon = player
                .resource
                .as_ref()
                .filter(|_| player.flags & clonk_engine::PLAYER_INFO_FLAG_HAS_RESOURCE != 0)
                .and_then(|resource| self.admission_resources.complete_path(resource.id))
                .map(|path| {
                    if let Some(icon) = load_network_player_big_icon(path) {
                        LobbyRosterIcon::Raster(
                            clonk_frontend::classic_gui::blacken_transparent_pixels(&icon),
                        )
                    } else if let Some(default_player_icon) = default_player_icon {
                        LobbyRosterIcon::Raster(
                            clonk_frontend::game_lobby::compose_classic_lobby_player_fallback_icon(
                                default_player_icon,
                                Color::opaque(
                                    ((color >> 16) & 0xff) as u8,
                                    ((color >> 8) & 0xff) as u8,
                                    (color & 0xff) as u8,
                                ),
                            )
                            .expect("the staged active Player graphic is nonempty"),
                        )
                    } else {
                        LobbyRosterIcon::Standard(7)
                    }
                })
                .unwrap_or_else(|| {
                    LobbyRosterIcon::Standard(if player.is_script_player() { 4 } else { 7 })
                });
            LobbyRosterRow::Player(LobbyPlayerRow {
                id: player.id,
                client_id,
                name: player_name(player),
                color: [
                    ((color >> 16) & 0xff) as u8,
                    ((color >> 8) & 0xff) as u8,
                    (color & 0xff) as u8,
                    255,
                ],
                icon,
                joined_player_overlay: joined_player.and_then(|joined_player| {
                    default_crew_icon.as_ref().map(|crew| {
                        let color = lobby_color(joined_player);
                        LobbyJoinedPlayerOverlay {
                            crew: crew.clone(),
                            color: [
                                ((color >> 16) & 0xff) as u8,
                                ((color >> 8) & 0xff) as u8,
                                (color & 0xff) as u8,
                                255,
                            ],
                        }
                    })
                }),
                team,
                league_score,
                league_rank: (league_mode && player.league_rank_symbol != 0)
                    .then(|| player.league_rank_symbol.clamp(1, 9) as u8),
            })
        };
        let local_client_color = retained_players
            .iter()
            .find(|(client_id, player)| {
                *client_id == 0 && player.player_type == clonk_engine::PLAYER_INFO_TYPE_USER
            })
            .map(|(_, player)| lobby_color(player))
            .unwrap_or(0x00ff_ffff);

        let mut rows = Vec::new();
        if let Some(parameters) = parameters {
            let associated = retained_players
                .iter()
                .map(|(_, player)| player.savegame_player)
                .filter(|id| *id != 0)
                .collect::<HashSet<_>>();
            let has_restore_players = parameters
                .restore_player_infos
                .clients
                .iter()
                .flat_map(|client| &client.players)
                .any(|player| {
                    player.flags & clonk_engine::PLAYER_INFO_FLAG_REMOVED == 0
                        && !player.is_script_player()
                });
            let mut free_restore = parameters
                .restore_player_infos
                .clients
                .iter()
                .flat_map(|client| &client.players)
                .collect::<Vec<_>>();
            free_restore.sort_by_key(|player| player.id);
            free_restore.retain(|player| player.id > 0);
            free_restore.dedup_by_key(|player| player.id);
            free_restore
                .retain(|player| !player.is_script_player() && !associated.contains(&player.id));
            if has_restore_players {
                rows.push(LobbyRosterRow::Header(LobbyHeaderRow {
                    kind: LobbyRosterHeader::UnassignedSavegamePlayers,
                    label: self
                        .runtime_resource_text("IDS_MSG_FREESAVEGAMEPLRS", "Player assignment"),
                    icon: LobbyRosterIcon::Standard(12),
                    can_add_player: false,
                }));
                rows.extend(
                    free_restore
                        .into_iter()
                        .map(|player| player_row(-1, player, Some(player), false)),
                );
            }
        }

        if replay {
            rows.push(LobbyRosterRow::Header(LobbyHeaderRow {
                kind: LobbyRosterHeader::ReplayPlayers,
                label: self.runtime_resource_text("IDS_MSG_REPLAYPLRS", "Replay players"),
                icon: LobbyRosterIcon::Standard(21),
                can_add_player: false,
            }));
            // C++ first constructs every visible replay row with client -1.
            // UpdateScriptPlayers then moves each active script row by its
            // semantic ID, retaining that client ownership; removed scripts
            // stay in the replay group.
            let mut replay_players = retained_players
                .iter()
                .filter(|(_, player)| {
                    player.id > 0
                        && player.flags & clonk_engine::PLAYER_INFO_FLAG_INVISIBLE == 0
                        && !(player.is_script_player()
                            && player.flags & clonk_engine::PLAYER_INFO_FLAG_REMOVED == 0)
                })
                .copied()
                .collect::<Vec<_>>();
            replay_players.sort_by_key(|(_, player)| player.id);
            rows.extend(
                replay_players
                    .into_iter()
                    .map(|(_, player)| {
                        player_row(
                            -1,
                            player,
                            restore_player(player.savegame_player),
                            true,
                        )
                    }),
            );
        }

        let script_players = retained_players
            .iter()
            .filter(|(_, player)| player.is_script_player() && is_visible(player))
            .copied()
            .collect::<Vec<_>>();
        let active_script_players = retained_players
            .iter()
            .filter(|(_, player)| {
                player.is_script_player() && player.flags & clonk_engine::PLAYER_INFO_FLAG_REMOVED == 0
            })
            .count();
        let max_script_players = teams.map_or(0, |teams| teams.max_script_players);
        if max_script_players != 0 || !script_players.is_empty() {
            rows.push(LobbyRosterRow::Header(LobbyHeaderRow {
                kind: LobbyRosterHeader::ScriptPlayers,
                label: self.runtime_resource_text("IDS_CTL_SCRIPTPLAYERS", "Script players"),
                icon: LobbyRosterIcon::Standard(21),
                can_add_player: max_script_players
                    .saturating_sub(i32::try_from(active_script_players).unwrap_or(i32::MAX))
                    > 0,
            }));
            rows.extend(script_players.into_iter().map(|(client_id, player)| {
                player_row(
                    if replay { -1 } else { client_id },
                    player,
                    restore_player(player.savegame_player),
                    true,
                )
            }));
        }

        rows.push(LobbyRosterRow::Client(LobbyClientRow {
            id: 0,
            name: c4_presentation_text(local_name),
            nick: c4_presentation_text(nick),
            color: [
                ((local_client_color >> 16) & 0xff) as u8,
                ((local_client_color >> 8) & 0xff) as u8,
                (local_client_color & 0xff) as u8,
                255,
            ],
            status: LobbyClientStatus::Host,
            local: true,
            connected: false,
            resource_progress: None,
            ping_ms: None,
        }));
        if !replay {
            rows.extend(
                retained_players
                    .into_iter()
                    .filter(|(_, player)| !player.is_script_player() && is_visible(player))
                    .map(|(client_id, player)| {
                        player_row(
                            client_id,
                            player,
                            restore_player(player.savegame_player),
                            true,
                        )
                    }),
            );
        }
        (rows, active_players)
    }

    fn build_classic_host_lobby(
        &self,
        mode: &NetworkMode,
        manager: &NetworkManager,
    ) -> Result<(ClassicHostLobbyState, GameOptionButtons)> {
        let NetworkMode::Host(settings) = mode else {
            return Err(classic_game_lobby_error(ClassicGameLobbyBoundary::Model {
                detail: "client sessions do not have an app-wired classic lobby".to_string(),
            }));
        };
        if manager.local_client_id() != 0 {
            return Err(classic_game_lobby_error(ClassicGameLobbyBoundary::Model {
                detail: "classic host lobby requires local client ID zero".to_string(),
            }));
        }
        let staged = self.staged_network_host_scenario.as_ref().ok_or_else(|| {
            classic_game_lobby_error(ClassicGameLobbyBoundary::Model {
                detail: "host connection completed without a staged scenario".to_string(),
            })
        })?;
        if settings.player_name != staged.lobby.local_name {
            return Err(classic_game_lobby_error(ClassicGameLobbyBoundary::Model {
                detail: "connected host identity differs from the pre-bind accepted model"
                    .to_string(),
            }));
        }
        self.assets.game_lobby_resources().map_err(|error| {
            classic_game_lobby_error(ClassicGameLobbyBoundary::Resources {
                detail: error.to_string(),
            })
        })?;
        self.assets.game_option_resources().map_err(|error| {
            classic_game_lobby_error(ClassicGameLobbyBoundary::Resources {
                detail: error.to_string(),
            })
        })?;
        let loader = self.loader_screen.as_ref().ok_or_else(|| {
            classic_game_lobby_error(ClassicGameLobbyBoundary::Resources {
                detail: "staged scenario loader is not installed".to_string(),
            })
        })?;
        let (rows, active_players) =
            self.classic_host_lobby_roster_rows(mode, &staged.lobby.local_name, &staged.lobby.nick);
        let mut controller = ClassicGameLobby::new(
            LobbyRole::Host,
            loader.state().title(),
            active_players,
            staged.lobby.max_players,
            staged.lobby.has_teams,
            self.startup_irc_client_active(),
            self.admission_resources.lobby_ready_available(),
            false,
            staged.lobby.countdown_seconds,
            rows,
        );
        controller.set_labels(self.classic_lobby_labels());
        let preload = LobbyPreloadState::new(
            load_options_program_state(self.app_paths.as_ref()).preloading,
        );
        controller.set_preload_button_state(
            preload.manual_button_present,
            preload.eligible,
        );
        let runtime_join_allowed = settings
            .prepared
            .as_ref()
            .is_some_and(|prepared| prepared.admission().runtime_join_allowed());
        let control_rate = initial_network_control_clock(Some(mode))
            .map(NetworkControlClock::control_rate)
            .unwrap_or_else(|| self.engine.control_rate());
        let teams = match mode {
            NetworkMode::Host(HostSettings {
                prepared: Some(prepared),
                ..
            }) => Some(prepared.runtime_team_metadata()),
            NetworkMode::Host(_) | NetworkMode::Client(_) => None,
        };
        controller.set_option_rows(self.classic_lobby_option_rows_for(
            mode,
            control_rate,
            runtime_join_allowed,
            active_players,
            teams,
        ));
        controller.set_league_mode(initial_network_is_league(Some(mode)));
        let mut values = staged.options.clone();
        values.lobby_is_league = initial_network_is_league(Some(mode));
        values.selector_fair_crew_constraint = FairCrewConstraint::Free;
        values.lobby_fair_crew_forced = staged.lobby.fair_crew_forced;
        values.fair_crew = staged.lobby.fair_crew;
        values.fair_crew_strength = staged.lobby.fair_crew_strength;
        values.countdown = false;
        let mut options = GameOptionButtons::new(GameOptionContext::LobbyHost, values);
        let fonts = self.assets.clonk_fonts.as_deref().ok_or_else(|| {
            classic_game_lobby_error(ClassicGameLobbyBoundary::Resources {
                detail: "CStdFont-faithful lobby fonts are unavailable".to_string(),
            })
        })?;
        let surface = self.graphics.surface();
        let layout = controller.layout(surface.width() as i32, surface.height() as i32, fonts);
        options.set_bounds(layout.game_option_strip);
        // Prime scroll metrics before the first pointer or wheel event.
        let _ = controller.right_list_layout(&layout, fonts);
        let resource_rows = initial_classic_lobby_resource_rows(
            settings
                .prepared
                .as_ref()
                .and_then(|prepared| prepared.host_config().initial_join_snapshot.as_ref()),
        );
        Ok((
            ClassicHostLobbyState {
                controller,
                preload,
                pointer: None,
                last_roster_click: None,
                chat_history_index: -1,
                runtime_join_allowed,
                resource_rows,
                scenario_description: LobbyScenarioDescriptionState::default(),
            },
            options,
        ))
    }

    fn dismiss_startup_network_connect_progress(&mut self) {
        let Some(index) = self.message_dialogs.iter().rposition(|dialog| {
            matches!(
                dialog.continuation,
                MessageDialogContinuation::StartupNetworkConnectProgress
            )
        }) else {
            return;
        };
        self.remove_message_dialog_at(index);
        self.mark_menu_dirty();
    }

    fn finish_startup_network_failure(
        &mut self,
        purpose: StartupNetworkPurpose,
        message: String,
    ) -> Result<(), EngineError> {
        tracing::error!(?purpose, error = %message, "startup network session failed");
        self.startup_restart_diagnostics.mark_quit_with_error();
        self.startup_restart_diagnostics.add_fatal_error(message);
        self.finish_startup_network_restart(purpose)
    }

    fn present_startup_restart_diagnostics(&mut self) -> Result<(), EngineError> {
        self.status_text.clear();
        let caption = self.runtime_resource_text("IDS_DLG_LOG", "Error Log");
        self.runtime_client_list = None;
        self.runtime_client_list_consumed_keys.clear();
        self.runtime_client_list_above_game_over = false;
        let presentation = self
            .startup_restart_diagnostics
            .take_presentation()
            .expect("startup restart is entered only after an error flag or fatal diagnostic");
        let entries = match presentation {
            StartupRestartPresentation::Fatal(message) => {
                return self.push_message_dialog(
                    clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                        message,
                        caption,
                        clonk_frontend::message_dialog::MessageDialogIcon::ERROR,
                    ),
                    MessageDialogContinuation::None,
                );
            }
            StartupRestartPresentation::Empty => {
                return self.push_message_dialog(
                    clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                        "(no error)",
                        caption,
                        clonk_frontend::message_dialog::MessageDialogIcon::ERROR,
                    ),
                    MessageDialogContinuation::None,
                );
            }
            StartupRestartPresentation::Ringbuffer(entries) => entries,
        };

        Self::guard_gui_overlay_result(
            "C4GUI::InfoDialog",
            self.assets
                .static_info_dialog_resources()
                .context("exact C4GUI::InfoDialog resource set is absent")
                .and_then(|resources| resources.validate()),
        )?;
        let text = entries.join("|");
        let close_label = self.runtime_resource_text("IDS_DLG_CLOSE", "&Close");
        self.cancel_underlying_interaction();
        self.runtime_client_list = Some(
            clonk_frontend::runtime_client_list::RuntimeClientListDialog::new_static_info(
                caption,
                10,
                &text,
                close_label,
            ),
        );
        self.mark_menu_dirty();
        Ok(())
    }

    fn finish_startup_network_restart(
        &mut self,
        purpose: StartupNetworkPurpose,
    ) -> Result<(), EngineError> {
        // Failed C4Game::Init returns through QuitGame and constructs the
        // remembered startup dialog again in the same process. Clear every
        // partially installed network-game projection before doing likewise.
        self.restore_startup_fonts();
        self.restore_startup_gui_sheets();
        self.active_global_gui_failures.clear();
        self.clear_lobby_preload();
        self.classic_host_lobby = None;
        self.network_lobby = None;
        self.network_start_wait = None;
        self.staged_network_host_scenario = None;
        self.loader_screen = None;
        self.loader_error = None;
        self.abandon_live_masterserver_signup();
        self.clear_pending_league_player_auth();
        self.network_game_advertiser = None;
        self.advertised_game_reference = None;
        self.host_reference_paused = false;
        self.runtime_network_control_mode = None;
        self.runtime_network_committed_control_mode = None;
        self.runtime_network_committed_status = None;
        self.runtime_network_join_allowed = None;
        self.network = None;
        self.network_mode = None;
        self.host_join_snapshot = None;
        self.pending_runtime_dynamic_request = None;
        self.host_lobby_countdown = None;
        self.pending_local_lobby_countdown_echoes.clear();
        self.network_ticks.clear();
        self.network_sync.clear();
        self.offline_control_input.clear();
        self.sync_checks.clear();
        self.network_control_clock = None;
        self.host_local_alternate_colors_by_resource.clear();
        self.host_local_player_info_ids.clear();
        self.network_is_league = false;
        self.network_league_name.clear();
        self.network_stream_address = LegacyCString::default();
        self.control_player_infos = ControlPlayerInfoRegistry::default();
        self.clear_blocking_resource_wait();
        self.admission_resources.clear();
        seed_engine_player_info_parameters(
            &mut self.engine,
            &self.network_league_name,
            &self.control_player_infos,
        );
        self.network_control_running = true;
        self.runtime_network_status_barrier = None;
        self.control_clients = initial_control_clients(None, None);
        self.network_client_activity.clear();
        self.pending_network_join = None;
        self.pending_network_join_data = None;
        self.initial_lobby_status_ack_pending = false;
        self.client_start_barrier = ClientStartBarrier::default();
        self.pending_client_start_status = None;
        self.client_combined_scenario_path = None;
        self.client_combined_preload_file.clear();
        self.network_material_resource_groups = None;
        self.active_scenario = None;
        self.active_definition_load = None;
        self.active_description_definition_modules.clear();
        self.mode = AppMode::Menu;
        self.status_text.clear();

        // C4Application::QuitGame returns an ordinary failed startup host/join
        // through PreInit before C4Startup::DoStartup reconstructs the
        // remembered dialog. Explicit command-line and developer-console
        // starts have no such second application generation.
        self.resume_startup_music_after_failed_open_game();

        match purpose {
            StartupNetworkPurpose::StagedHost => {
                self.startup_game_search = None;
                self.startup_network_last_refresh = None;
                self.startup_masterserver_next_query_at = None;
                self.startup_network_dialog = None;
                self.restore_startup_dialog(StartupDialog::ScenarioBrowser(
                    ScenarioSelectorMode::NetworkHost,
                ));
            }
            StartupNetworkPurpose::Join => {
                self.restore_startup_dialog(StartupDialog::NetworkGame);
            }
        }
        // NetDlg discovery startup has its own native row presentation. It
        // must not displace the fatal diagnostic with a generic overlay.
        self.present_startup_restart_diagnostics()
    }

    fn poll_startup_network_connection(&mut self) -> Result<(), EngineError> {
        let Some(connection) = self.startup_network_connection.as_ref() else {
            return Ok(());
        };
        let selected_scenario = connection.selected_scenario.clone();
        let purpose = connection.purpose;
        let result = match connection
            .receiver
            .as_ref()
            .expect("installed startup network connection retains its receiver")
            .try_recv()
        {
            Ok(result) => Some(result),
            Err(TryRecvError::Empty) => return Ok(()),
            Err(TryRecvError::Disconnected) => None,
        };
        let mut connection = self
            .startup_network_connection
            .take()
            .expect("completed startup network connection remains installed");
        let mut authenticated_league_players =
            connection.authenticated_league_players.take();
        connection.finish_attempt();
        if purpose == StartupNetworkPurpose::Join {
            // Resolution owns silent dismissal. Finishing the dialog would
            // run its continuation and incorrectly turn success into abort.
            self.dismiss_startup_network_connect_progress();
        }
        self.mark_menu_dirty();
        let Some(result) = result else {
            let message = "network worker disconnected before reporting readiness";
            tracing::error!(?purpose, error = message, "startup network session failed");
            self.startup_restart_diagnostics.add_log_entry(message);
            self.startup_restart_diagnostics.mark_quit_with_error();
            return self.finish_startup_network_restart(purpose);
        };
        match result {
            Ok((mut mode, mut manager)) => {
                if let Some(response) = manager.take_league_start_response() {
                    if let NetworkMode::Host(HostSettings {
                        prepared: Some(prepared),
                        ..
                    }) = &mut mode
                    {
                        if let Err(error) = prepared.apply_league_start_response(&response) {
                            return self.finish_startup_network_failure(
                                purpose,
                                format!("Unable to apply league registration: {error}"),
                            );
                        }
                    }
                    if response.max_players != 0 {
                        if let Some(staged) = self.staged_network_host_scenario.as_mut() {
                            staged.lobby.max_players = response.max_players;
                        }
                    }
                }
                let needs_initial_host_league_auth = purpose == StartupNetworkPurpose::StagedHost
                    && authenticated_league_players.is_none()
                    && matches!(
                        &mode,
                        NetworkMode::Host(HostSettings {
                            prepared: Some(prepared),
                            ..
                        }) if prepared.pending_initial_league_players().is_some()
                            && prepared
                                .host_config()
                                .initial_join_snapshot
                                .as_ref()
                                .is_some_and(|snapshot| synchronized_parameters_are_league(
                                    &snapshot.parameters
                                ))
                    );
                if needs_initial_host_league_auth {
                    match self.begin_startup_host_league_auth(
                        mode,
                        manager,
                        selected_scenario,
                        purpose,
                    )? {
                        LeaguePlayerAuthStatus::Pending
                        | LeaguePlayerAuthStatus::Completed(true) => return Ok(()),
                        LeaguePlayerAuthStatus::Completed(false) => {
                            return self.finish_startup_network_failure(
                                purpose,
                                "Unable to finalize initial host player authentication"
                                    .to_string(),
                            );
                        }
                    }
                }
                if purpose == StartupNetworkPurpose::StagedHost {
                    if let NetworkMode::Host(HostSettings {
                        prepared: Some(prepared),
                        ..
                    }) = &mut mode
                    {
                        if let Some(staged) = self.staged_network_host_scenario.as_mut() {
                            if let Some(parameters) = prepared
                                .host_config()
                                .initial_join_snapshot
                                .as_ref()
                                .map(|snapshot| &snapshot.parameters)
                            {
                                staged.lobby.max_players = parameters.max_players;
                                staged.lobby.fair_crew = parameters.use_fair_crew;
                                staged.lobby.fair_crew_forced = parameters.fair_crew_forced;
                                staged.lobby.fair_crew_strength = parameters.fair_crew_strength;
                            } else {
                                staged.lobby.max_players = prepared.admission().max_players();
                            }
                        }
                        let is_league = prepared
                            .host_config()
                            .initial_join_snapshot
                            .as_ref()
                            .is_some_and(|snapshot| {
                                synchronized_parameters_are_league(&snapshot.parameters)
                            });
                        if prepared.pending_initial_league_players().is_some() {
                            if let Err(error) = self.finalize_prepared_host_players(
                                &manager,
                                prepared,
                                is_league,
                                authenticated_league_players.take(),
                            ) {
                                return self.finish_startup_network_failure(
                                    purpose,
                                    format!(
                                        "Unable to finalize initial host players: {error}"
                                    ),
                                );
                            }
                            if let Some(snapshot) =
                                prepared.host_config().initial_join_snapshot.clone()
                            {
                                if let Err(error) = manager.publish_join_snapshot(snapshot) {
                                    return self.finish_startup_network_failure(
                                        purpose,
                                        format!(
                                            "Unable to publish initial host players: {error}"
                                        ),
                                    );
                                }
                            }
                        }
                    }
                }
                if purpose == StartupNetworkPurpose::Join {
                    self.pending_network_join = None;
                    self.host_local_alternate_colors_by_resource.clear();
                    self.host_local_player_info_ids.clear();
                }
                // InitNetwork constructs a fresh C4Network2Client list; no
                // activity timestamp survives into the new socket session.
                self.network_client_activity.clear();
                if purpose == StartupNetworkPurpose::StagedHost {
                    let control_clients = initial_control_clients(Some(&manager), Some(&mode));
                    let network_control_clock = initial_network_control_clock(Some(&mode));
                    let mut previous_player_infos = None;
                    let mut previous_admission_resources = None;
                    let admission_ready = match &mode {
                        NetworkMode::Host(settings) => match settings.prepared.as_ref() {
                            Some(prepared) => {
                                // C4Network2Players::Init executes the host's
                                // Initial PlayerInfo directly before C4Game opens
                                // joining (src/C4Game.cpp:3869-3876;
                                // src/C4Network2Players.cpp:38-49,78-123).
                                previous_player_infos =
                                    Some(std::mem::take(&mut self.control_player_infos));
                                previous_admission_resources =
                                    Some(std::mem::take(&mut self.admission_resources));
                                let player_infos = &mut self.control_player_infos;
                                let resources = &mut self.admission_resources;
                                match prepared.install_initial_host_player_state(
                                    player_infos,
                                    |core, path| {
                                        resources.register_lobby_resource(core);
                                        resources.mark_complete(core.id, path.to_path_buf())
                                    },
                                ) {
                                    Ok(ready) => Some(ready),
                                    Err(error) => {
                                        self.control_player_infos = previous_player_infos
                                            .take()
                                            .expect("prepared install saved the previous registry");
                                        self.admission_resources =
                                            previous_admission_resources.take().expect(
                                                "prepared install saved the previous resources",
                                            );
                                        return self.finish_startup_network_failure(
                                            purpose,
                                            format!(
                                                "Unable to install prepared host PlayerInfo/resources: {error}"
                                            ),
                                        );
                                    }
                                }
                            }
                            None => None,
                        },
                        NetworkMode::Client(_) => None,
                    };
                    if let Some(admission_ready) = admission_ready {
                        if let Err(error) =
                            manager.set_join_allowed(admission_ready.lobby_join_allowed())
                        {
                            if let Some(previous_player_infos) = previous_player_infos.take() {
                                self.control_player_infos = previous_player_infos;
                            }
                            if let Some(previous_admission_resources) =
                                previous_admission_resources.take()
                            {
                                self.admission_resources = previous_admission_resources;
                            }
                            return self.finish_startup_network_failure(
                                purpose,
                                format!("Unable to open prepared host admission: {error}"),
                            );
                        }
                    }
                    self.host_local_alternate_colors_by_resource =
                        initial_host_local_alternate_colors(Some(&mode));
                    self.host_local_player_info_ids =
                        initial_host_local_player_info_ids(Some(&mode));
                    self.prune_host_local_alternate_colors();
                    if self.staged_network_host_scenario.is_none()
                        && matches!(
                            &mode,
                            NetworkMode::Host(HostSettings {
                                prepared: Some(_),
                                ..
                            })
                        )
                    {
                        if let Some((identifier, title)) = selected_scenario.as_ref() {
                            // Keep the prepared host's selected scenario and
                            // admission state alive in the established network
                            // lobby projection.
                            let mut lobby = NetworkLobbyState::new(
                                manager.local_client_id(),
                                self.player_name.clone(),
                                true,
                            )
                            .with_external_chat(self.startup_irc_client_active())
                            .with_preloading(
                                load_options_program_state(self.app_paths.as_ref()).preloading,
                                self.classic_lobby_labels(),
                            );
                            lobby.select_scenario(identifier, title);
                            self.scenario_label = lobby.scenario_label();
                            if let NetworkMode::Host(HostSettings {
                                prepared: Some(prepared),
                                ..
                            }) = &mode
                            {
                                self.start_prepared_network_game_advertiser(prepared, &manager);
                            }
                            self.network_max_players = initial_network_max_players(Some(&mode));
                            self.engine.set_max_players(
                                i32::try_from(self.network_max_players).unwrap_or(i32::MAX),
                            );
                            self.control_clients = control_clients;
                            self.host_join_snapshot = initial_host_join_snapshot(Some(&mode));
                            self.network_is_league = initial_network_is_league(Some(&mode));
                            self.network_league_name = initial_network_league_name(Some(&mode));
                            self.network_stream_address =
                                initial_network_stream_address(Some(&mode));
                            seed_engine_player_info_parameters(
                                &mut self.engine,
                                &self.network_league_name,
                                &self.control_player_infos,
                            );
                            self.network_team_assignment =
                                initial_network_team_assignment(
                                    Some(&mode),
                                    &self.generated_team_name_template,
                                );
                            self.network_mode = Some(mode);
                            self.network = Some(manager);
                            self.network_control_running = false;
                            self.network_control_clock = network_control_clock;
                            self.network_lobby = Some(lobby);
                            self.classic_host_lobby = None;
                            self.replace_startup_view(StartupView::NetworkLobby);
                            self.mode = AppMode::Menu;
                            self.status_text.clear();
                            self.menu_frame_cache = None;
                            self.restore_startup_fonts();
                            self.finish_classic_command_line_host_entry()?;
                            return Ok(());
                        }
                    }
                    match self.build_classic_host_lobby(&mode, &manager) {
                        Ok((lobby, options)) => {
                            match &mode {
                                NetworkMode::Host(HostSettings {
                                    prepared: Some(prepared),
                                    ..
                                }) => {
                                    self.start_prepared_network_game_advertiser(prepared, &manager)
                                }
                                NetworkMode::Host(_) | NetworkMode::Client(_) => {
                                    self.network_game_advertiser = None;
                                    self.advertised_game_reference = None;
                                    self.host_reference_paused = false;
                                }
                            }
                            self.network_max_players = initial_network_max_players(Some(&mode));
                            self.engine.set_max_players(
                                i32::try_from(self.network_max_players).unwrap_or(i32::MAX),
                            );
                            self.control_clients = control_clients;
                            self.host_join_snapshot = initial_host_join_snapshot(Some(&mode));
                            self.network_is_league = initial_network_is_league(Some(&mode));
                            self.network_league_name = initial_network_league_name(Some(&mode));
                            self.network_stream_address =
                                initial_network_stream_address(Some(&mode));
                            seed_engine_player_info_parameters(
                                &mut self.engine,
                                &self.network_league_name,
                                &self.control_player_infos,
                            );
                            self.network_team_assignment =
                                initial_network_team_assignment(
                                    Some(&mode),
                                    &self.generated_team_name_template,
                                );
                            self.network_mode = Some(mode);
                            self.network = Some(manager);
                            self.network_control_running = false;
                            self.network_control_clock = network_control_clock;
                            self.network_lobby = None;
                            self.classic_host_lobby = Some(lobby);
                            self.sync_classic_lobby_roster();
                            self.sync_classic_lobby_resource_ready();
                            self.scenario_game_options = options;
                            self.replace_startup_view(StartupView::NetworkLobby);
                            self.mode = AppMode::Menu;
                            self.status_text.clear();
                            self.menu_frame_cache = None;
                            if let Some(audio) = self.audio.as_mut() {
                                audio.stop_music();
                            }
                            self.finish_classic_command_line_host_entry()?;
                            return Ok(());
                        }
                        Err(error) => {
                            if let Some(previous_player_infos) = previous_player_infos.take() {
                                self.control_player_infos = previous_player_infos;
                            }
                            if let Some(previous_admission_resources) =
                                previous_admission_resources.take()
                            {
                                self.admission_resources = previous_admission_resources;
                            }
                            tracing::error!(%error, "cannot enter exact classic host lobby");
                            return self.finish_startup_network_failure(
                                purpose,
                                format!("Network lobby unavailable: {error}"),
                            );
                        }
                    }
                } else {
                    let lobby = NetworkLobbyState::new(
                        manager.local_client_id(),
                        self.player_name.clone(),
                        false,
                    )
                    .with_external_chat(self.startup_irc_client_active())
                    .with_preloading(
                        load_options_program_state(self.app_paths.as_ref()).preloading,
                        self.classic_lobby_labels(),
                    );
                    self.network_game_advertiser = None;
                    self.advertised_game_reference = None;
                    self.host_reference_paused = false;
                    self.network_max_players = initial_network_max_players(Some(&mode));
                    self.engine.set_max_players(
                        i32::try_from(self.network_max_players).unwrap_or(i32::MAX),
                    );
                    self.network_is_league = initial_network_is_league(Some(&mode));
                    self.network_league_name = initial_network_league_name(Some(&mode));
                    self.network_stream_address = initial_network_stream_address(Some(&mode));
                    seed_engine_player_info_parameters(
                        &mut self.engine,
                        &self.network_league_name,
                        &self.control_player_infos,
                    );
                    self.network_control_clock = initial_network_control_clock(Some(&mode));
                    self.control_clients = initial_control_clients(Some(&manager), Some(&mode));
                    self.host_join_snapshot = initial_host_join_snapshot(Some(&mode));
                    self.network_mode = Some(mode);
                    self.network = Some(manager);
                    self.network_control_running = false;
                    self.network_team_assignment = None;
                    self.network_lobby = Some(lobby);
                    self.classic_host_lobby = None;
                    self.host_lobby_countdown = None;
                    self.pending_local_lobby_countdown_echoes.clear();
                    self.mode = AppMode::Menu;
                    self.open_network_lobby();
                    return Ok(());
                }
            }
            Err(NetworkStartError::WrongPassword { .. })
                if purpose == StartupNetworkPurpose::Join
                    && self.pending_network_join.is_some() =>
            {
                self.mode = AppMode::Menu;
                if let Err(error) = self.open_network_join_password_dialog() {
                    return self.finish_startup_network_failure(
                        purpose,
                        format!("Unable to reopen the network password prompt: {error}"),
                    );
                }
            }
            Err(error) => {
                return self.finish_startup_network_failure(
                    purpose,
                    format!("Unable to start network session: {error}"),
                );
            }
        }
        Ok(())
    }

    fn start_prepared_network_game_advertiser(
        &mut self,
        prepared: &prepared_host_bootstrap::PreparedHostBootstrap,
        network: &NetworkManager,
    ) {
        // InitLocal snapshots the canonical parameters and live admission only
        // after Players.Init/AllowJoin, then the reference server exposes that
        // complete value (src/C4Network2Reference.cpp:49-109;
        // src/C4Game.cpp:3869-3876).
        let (game_ids, addresses) = network.netpuncher_state();
        let reference = match prepared
            .initial_host_game_reference(true, &addresses)
            .map_err(|error| error.to_string())
            .and_then(|reference| {
                reference
                    .replacing_netpuncher_state(game_ids, addresses)
                    .map_err(|error| error.to_string())
            })
        {
            Ok(reference) => reference,
            Err(error) => {
                tracing::warn!(%error, "exact network game reference unavailable");
                self.network_game_advertiser = None;
                self.advertised_game_reference = None;
                self.host_reference_paused = false;
                return;
            }
        };
        let config = load_network_advertiser_settings(self.app_paths.as_ref());
        self.start_network_game_advertiser_with_reference(config, reference);
    }

    fn start_network_game_advertiser_with_reference(
        &mut self,
        config: clonk_network::NetworkGameAdvertiserConfig,
        reference: clonk_network::HostGameReference,
    ) {
        // The validated InitLocal value is game state, not socket state. Keep
        // it even when the optional LAN/reference listener cannot bind so a
        // later runtime or game-over rebuild never falls back to stale data.
        self.advertised_game_reference = Some(reference.clone());
        self.host_reference_paused = false;
        match clonk_network::NetworkGameAdvertiser::start_exact(config, reference.clone()) {
            Ok(advertiser) => {
                self.network_game_advertiser = Some(advertiser);
            }
            Err(error) => {
                tracing::warn!(%error, "network game advertising unavailable");
                self.network_game_advertiser = None;
            }
        }
    }

    fn update_host_netpuncher_reference(
        &mut self,
        game_ids: clonk_network::NetpuncherGameIds,
        addresses: Vec<clonk_network::NetworkAddress>,
    ) {
        if !matches!(self.network_mode, Some(NetworkMode::Host(_))) {
            return;
        }
        if let Some(network) = self.network.as_ref() {
            if let Err(error) = network.invalidate_league_reference() {
                tracing::error!(%error, "failed to invalidate netpuncher league reference");
            }
        }
        let Some(reference) = self.advertised_game_reference.clone() else {
            return;
        };
        let updated = match reference.replacing_netpuncher_state(game_ids, addresses) {
            Ok(updated) => updated,
            Err(error) => {
                tracing::error!(%error, "failed to rebuild netpuncher host reference");
                return;
            }
        };
        self.advertised_game_reference = Some(updated.clone());
        if let Some(advertiser) = self.network_game_advertiser.as_ref() {
            if let Err(error) = advertiser.update_exact(&updated) {
                tracing::error!(%error, "failed to publish netpuncher host reference");
            }
        }
    }

    fn publish_running_host_reference(&mut self) {
        if !matches!(self.network_mode, Some(NetworkMode::Host(_))) {
            return;
        }
        let Some(template) = self.advertised_game_reference.clone() else {
            return;
        };
        let parameters = self
            .host_join_snapshot
            .as_ref()
            .map(|snapshot| snapshot.parameters.clone())
            .unwrap_or_else(|| template.parameters().clone());
        let max_players = self
            .engine
            .max_players()
            .unwrap_or_else(|| i32::try_from(self.network_max_players).unwrap_or(i32::MAX));
        let join_allowed = self
            .network_mode
            .as_ref()
            .and_then(|mode| match mode {
                NetworkMode::Host(HostSettings {
                    prepared: Some(prepared),
                    ..
                }) => Some(prepared.admission().runtime_join_allowed()),
                NetworkMode::Host(_) | NetworkMode::Client(_) => None,
            })
            .unwrap_or(template.summary().join_allowed);
        let control_mode = self.runtime_network_control_mode;
        let updated = match running_host_reference(
            &template,
            parameters,
            &self.control_clients,
            &self.control_player_infos,
            self.engine.teams(),
            max_players,
            if self.host_reference_paused {
                "Paused"
            } else {
                "Running"
            },
            join_allowed,
            &self.snapshot,
        )
        .and_then(|reference| match control_mode {
            Some(control_mode) => reference.replacing_control_mode(control_mode),
            None => Ok(reference),
        }) {
            Ok(reference) => reference,
            Err(error) => {
                tracing::error!(%error, "failed to rebuild running host reference");
                return;
            }
        };

        // Commit the validated state independently of advertiser I/O.
        self.advertised_game_reference = Some(updated.clone());
        if let Some(advertiser) = self.network_game_advertiser.as_ref() {
            if let Err(error) = advertiser.update_exact(&updated) {
                tracing::error!(%error, "failed to update running host reference");
            }
        }
    }

    fn publish_game_over_host_reference(&mut self) {
        let config = load_network_advertiser_settings(self.app_paths.as_ref());
        self.publish_game_over_host_reference_with_config(config);
    }

    fn publish_game_over_host_reference_with_config(
        &mut self,
        config: clonk_network::NetworkGameAdvertiserConfig,
    ) {
        if !matches!(self.network_mode, Some(NetworkMode::Host(_))) {
            return;
        }
        let Some(template) = self.advertised_game_reference.clone() else {
            return;
        };
        let parameters = self
            .host_join_snapshot
            .as_ref()
            .map(|snapshot| snapshot.parameters.clone())
            .unwrap_or_else(|| template.parameters().clone());
        let max_players = self
            .engine
            .max_players()
            .unwrap_or_else(|| i32::try_from(self.network_max_players).unwrap_or(i32::MAX));
        let updated = match game_over_host_reference(
            &template,
            parameters,
            &self.control_clients,
            &self.control_player_infos,
            self.engine.teams(),
            max_players,
            &self.snapshot,
        ) {
            Ok(reference) => reference,
            Err(error) => {
                tracing::error!(%error, "failed to rebuild game-over host reference");
                return;
            }
        };

        // The final reference is authoritative even if an optional listener
        // update or one-shot rebind fails.
        self.advertised_game_reference = Some(updated.clone());

        if let Some(advertiser) = self.network_game_advertiser.as_ref() {
            if let Err(error) = advertiser.update_exact(&updated) {
                tracing::error!(%error, "failed to update game-over host reference");
            }
        } else {
            match clonk_network::NetworkGameAdvertiser::start_exact(config, updated.clone()) {
                Ok(advertiser) => self.network_game_advertiser = Some(advertiser),
                Err(error) => {
                    tracing::warn!(%error, "game-over network advertising unavailable");
                }
            }
        }
    }

