    /// PlayerListItem's constructor restores a differing recorded team by
    /// cloning the complete owning client packet and submitting an update.
    /// Keep this side effect outside the pure row projector and run it once
    /// for each item construction, while authoritative state still waits for
    /// the network echo.
    fn submit_restart_restore_team_updates_for_new_roster_items(&mut self) {
        if self.restart_restore_infos.what & RESTART_RESTORE_PLAYER_TEAMS == 0
            || !matches!(self.network_mode, Some(NetworkMode::Host(_)))
            || self.network.is_none()
            || (self.classic_host_lobby.is_none() && self.network_lobby.is_none())
        {
            return;
        }

        let (_, packets) = self.control_player_infos.retained_rows_snapshot();
        let mut visible_items = HashSet::new();
        for (client_id, _, players) in &packets {
            if !self.control_clients.contains(*client_id)
                || self.control_clients.is_observer(*client_id)
            {
                continue;
            }
            visible_items.extend(players.iter().filter_map(|player| {
                (player.flags
                    & (clonk_engine::PLAYER_INFO_FLAG_REMOVED
                        | clonk_engine::PLAYER_INFO_FLAG_INVISIBLE)
                    == 0)
                    .then_some((*client_id, player.id))
            }));
        }
        self.restart_restore_roster_items
            .retain(|item| visible_items.contains(item));

        let mut requests = Vec::new();
        let mut restored_teams = Vec::new();
        for (client_id, flags, players) in packets {
            if !self.control_clients.contains(client_id)
                || self.control_clients.is_observer(client_id)
            {
                continue;
            }
            let mut working_players = players;
            for index in 0..working_players.len() {
                let player = &working_players[index];
                if player.flags
                    & (clonk_engine::PLAYER_INFO_FLAG_REMOVED
                        | clonk_engine::PLAYER_INFO_FLAG_INVISIBLE)
                    != 0
                    || !self
                        .restart_restore_roster_items
                        .insert((client_id, player.id))
                    || player.player_type != clonk_engine::PLAYER_INFO_TYPE_USER
                {
                    continue;
                }
                let lobby_name = restart_restore_lobby_name(player);
                let Some(restore) = self.restart_restore_infos.players.get(&lobby_name) else {
                    continue;
                };
                if restore.team == player.team {
                    continue;
                }
                let restored_team = restore.team;
                working_players[index].team = restored_team;
                restored_teams.push(restored_team);
                requests.push(clonk_network::PlayerInfoUpdateRequest {
                    client_id,
                    flags,
                    players: working_players.clone(),
                });
            }
        }

        let mut generated_team = false;
        if let Some(assignment) = self.network_team_assignment.as_mut() {
            for team in restored_teams {
                generated_team |= assignment.generate_team_for_id(team);
            }
        }
        if generated_team {
            if let (Some(assignment), Some(snapshot)) = (
                self.network_team_assignment.as_ref(),
                self.host_join_snapshot.as_mut(),
            ) {
                snapshot.parameters.teams =
                    clonk_network::join_team_list_snapshot(assignment.teams().clone());
            }
            self.publish_updated_host_join_snapshot();
        }

        let Some(network) = self.network.as_ref() else {
            return;
        };
        for request in requests {
            if let Err(error) = network.submit_player_info_update(request) {
                tracing::error!(%error, "failed to submit restart team PlayerInfo update");
            }
        }
    }

    fn refresh_classic_lobby_client_telemetry(&mut self) -> bool {
        if self.classic_host_lobby.is_none() && self.network_lobby.is_none() {
            return false;
        }
        let Some(network) = self.network.as_ref() else {
            return false;
        };
        let local_client_id = network.local_client_id();
        let mut client_ids = self
            .classic_host_lobby
            .as_ref()
            .into_iter()
            .flat_map(|lobby| lobby.controller.rows())
            .chain(
                self.network_lobby
                    .as_ref()
                    .into_iter()
                    .flat_map(|lobby| lobby.roster_rows.iter()),
            )
            .filter_map(|row| match row {
                LobbyRosterRow::Client(client) => ClientId::try_from(client.id).ok(),
                _ => None,
            })
            .chain(
                self.network_lobby
                    .as_ref()
                    .into_iter()
                    .flat_map(|lobby| lobby.participants.keys().copied()),
            )
            .filter(|client_id| *client_id != local_client_id)
            .collect::<Vec<_>>();
        client_ids.sort_unstable();
        client_ids.dedup();
        if client_ids.is_empty() {
            return false;
        }
        let telemetry = match network.lobby_client_telemetry(client_ids) {
            Ok(telemetry) => telemetry,
            Err(error) => {
                tracing::debug!(%error, "classic lobby client telemetry is not available");
                return false;
            }
        };

        let mut changed = false;
        if let Some(lobby) = self.classic_host_lobby.as_mut() {
            let mut rows = lobby.controller.rows().to_vec();
            if apply_classic_lobby_client_telemetry(
                &mut rows,
                local_client_id,
                &telemetry,
            ) {
                lobby.controller.set_rows(rows);
                changed = true;
            }
        }
        if let Some(lobby) = self.network_lobby.as_mut() {
            changed |= lobby.set_client_telemetry(telemetry);
        }
        changed
    }

    fn sync_classic_lobby_roster(&mut self) {
        self.submit_restart_restore_team_updates_for_new_roster_items();
        let active_sheet = self
            .classic_host_lobby
            .as_ref()
            .map(|lobby| lobby.controller.active_sheet())
            .or_else(|| {
                self.network_lobby
                    .as_ref()
                    .map(|lobby| lobby.controller.active_sheet())
            })
            .unwrap_or(LobbySheet::Players);
        let local_client_id = self
            .network
            .as_ref()
            .and_then(|network| i32::try_from(network.local_client_id()).ok())
            .unwrap_or(0);
        // The generic projection owns live client ordering, status, and team
        // authorization. Overlay the C4PlayerInfoListBox presentation built
        // from the same retained PlayerInfo state so a post-admission sync
        // does not discard BigIcon/fallback graphics, savegame crew overlays,
        // league metadata, localized headers, or unassigned restore rows.
        let (rich_rows, rich_active_players) = self
            .network_mode
            .as_ref()
            .map(|mode| self.classic_host_lobby_roster_rows(mode, "", ""))
            .unwrap_or_default();
        let has_rich_projection = !rich_rows.is_empty();
        let rich_players = rich_rows
            .iter()
            .filter_map(|row| match row {
                LobbyRosterRow::Player(player) => {
                    Some(((player.client_id, player.id), player.clone()))
                }
                _ => None,
            })
            .collect::<BTreeMap<_, _>>();
        let rich_script_header = rich_rows.iter().find_map(|row| match row {
            LobbyRosterRow::Header(header)
                if matches!(header.kind, LobbyRosterHeader::ScriptPlayers) =>
            {
                Some(header.clone())
            }
            _ => None,
        });
        let mut rich_replay_rows = Vec::new();
        let mut collecting_replay_rows = false;
        for row in &rich_rows {
            match row {
                LobbyRosterRow::Header(header)
                    if matches!(header.kind, LobbyRosterHeader::ReplayPlayers) =>
                {
                    collecting_replay_rows = true;
                    rich_replay_rows.push(row.clone());
                }
                LobbyRosterRow::Client(_) if collecting_replay_rows => break,
                _ if collecting_replay_rows => rich_replay_rows.push(row.clone()),
                _ => {}
            }
        }
        let mut rich_restore_rows = Vec::new();
        let mut collecting_restore_rows = false;
        for row in &rich_rows {
            match row {
                LobbyRosterRow::Header(header)
                    if matches!(
                        header.kind,
                        LobbyRosterHeader::UnassignedSavegamePlayers
                    ) =>
                {
                    collecting_restore_rows = true;
                    rich_restore_rows.push(row.clone());
                }
                LobbyRosterRow::Player(player)
                    if collecting_restore_rows && player.client_id == -1 =>
                {
                    rich_restore_rows.push(row.clone());
                }
                _ if collecting_restore_rows => break,
                _ => {}
            }
        }
        let joined_teams = self
            .pending_network_join_data
            .as_ref()
            .and_then(|join| initial_team_metadata_from_join_snapshot(&join.parameters.teams));
        let teams = self
            .network_team_assignment
            .as_ref()
            .map(NetworkTeamAssignmentState::teams)
            .or(joined_teams.as_ref());
        let has_teams = teams.is_some_and(|teams| teams.active);
        let (mut rows, generic_active_players) = classic_lobby_roster_projection(
            &self.control_clients,
            &self.control_player_infos,
            teams,
            local_client_id,
            active_sheet,
        );
        if active_sheet == LobbySheet::Teams {
            let random_team = self.runtime_resource_text("IDS_MSG_RNDTEAM", "Random team");
            for row in &mut rows {
                if let LobbyRosterRow::Header(LobbyHeaderRow {
                    kind: LobbyRosterHeader::RandomTeam,
                    label,
                    ..
                }) = row
                {
                    label.clone_from(&random_team);
                }
            }
        }
        if !rich_replay_rows.is_empty() && active_sheet == LobbySheet::Players {
            let live_player_teams = rows
                .iter()
                .filter_map(|row| match row {
                    LobbyRosterRow::Player(player) => Some((player.id, player.team.clone())),
                    _ => None,
                })
                .collect::<BTreeMap<_, _>>();
            for row in &mut rich_replay_rows {
                let LobbyRosterRow::Player(player) = row else {
                    continue;
                };
                if let Some(team) = live_player_teams.get(&player.id) {
                    player.team.clone_from(team);
                }
            }
            rows.retain(|row| matches!(row, LobbyRosterRow::Client(_)));
            rich_replay_rows.extend(rows);
            rows = rich_replay_rows;
        } else if !rich_replay_rows.is_empty()
            && active_sheet == LobbySheet::Teams
            && teams.is_some_and(|teams| {
                matches!(
                    teams.team_distribution,
                    clonk_engine::InitialNetworkTeamDistribution::RandomInvisible
                )
            })
        {
            rows.clear();
        }
        let active_players = if has_rich_projection {
            rich_active_players
        } else {
            generic_active_players
        };
        for row in &mut rows {
            match row {
                LobbyRosterRow::Player(player) => {
                    let Some(mut rich) = rich_players
                        .get(&(player.client_id, player.id))
                        .cloned()
                    else {
                        continue;
                    };
                    rich.team = player.team.clone();
                    *player = rich;
                }
                LobbyRosterRow::Header(header)
                    if matches!(header.kind, LobbyRosterHeader::ScriptPlayers) =>
                {
                    if let Some(rich) = rich_script_header.as_ref() {
                        let can_add_player = header.can_add_player;
                        *header = rich.clone();
                        header.can_add_player = can_add_player;
                    }
                }
                _ => {}
            }
        }
        if !rich_restore_rows.is_empty() {
            rich_restore_rows.extend(rows);
            rows = rich_restore_rows;
        }
        let previous_clients = self
            .classic_host_lobby
            .as_ref()
            .map(|lobby| lobby.controller.rows())
            .or_else(|| {
                self.network_lobby
                    .as_ref()
                    .map(|lobby| lobby.controller.rows())
            })
            .into_iter()
            .flatten()
            .filter_map(|row| match row {
                LobbyRosterRow::Client(client) => Some((client.id, client.clone())),
                _ => None,
            })
            .collect::<BTreeMap<_, _>>();
        for row in &mut rows {
            let LobbyRosterRow::Client(client) = row else {
                continue;
            };
            let Some(previous) = previous_clients.get(&client.id) else {
                continue;
            };
            if client.name.is_empty() {
                client.name.clone_from(&previous.name);
            }
            if client.nick.is_empty() {
                client.nick.clone_from(&previous.nick);
            }
            if client.id == 0
                && client.status == LobbyClientStatus::Unknown
                && previous.status == LobbyClientStatus::Host
            {
                // The staged controller is constructed from the prepared
                // host core before the empty initial PlayerInfo packet is
                // projected. Preserve that known host identity across this
                // transitional synchronization pass.
                client.status = LobbyClientStatus::Host;
            }
        }
        let maximum = i32::try_from(self.network_max_players).unwrap_or(i32::MAX);
        if let Some(lobby) = self.classic_host_lobby.as_mut() {
            lobby.controller.set_rows(rows.clone());
            lobby.controller.set_player_count(active_players, maximum);
        }
        if let Some(lobby) = self.network_lobby.as_mut() {
            lobby.roster_rows = rows.clone();
            lobby.roster_rows_authoritative = true;
            lobby.active_players = active_players;
            lobby.max_players = maximum;
            lobby.has_teams = has_teams;
            lobby.league_mode = self.network_is_league;
            lobby.controller.set_has_teams(has_teams);
            lobby.controller.set_league_mode(self.network_is_league);
            lobby.controller.set_rows(rows);
            lobby
                .controller
                .set_player_count(active_players, maximum);
        }
        self.close_stale_classic_lobby_team_combo();
        self.refresh_classic_lobby_client_telemetry();
    }

    fn sync_visible_classic_lobby_resources(&mut self) {
        let Some(lobby) = self.classic_host_lobby.as_mut() else {
            return;
        };
        if lobby.controller.resource_sheet_active() {
            lobby
                .controller
                .set_resource_rows(lobby.resource_rows.values().cloned().collect());
        }
    }

    fn lobby_resource_work_directory(&self) -> PathBuf {
        match self.network_mode.as_ref() {
            Some(NetworkMode::Client(settings)) => settings.resource_directory.clone(),
            Some(NetworkMode::Host(settings)) => settings
                .prepared
                .as_ref()
                .and_then(|prepared| prepared.host_config().resource_directory.clone())
                .or_else(|| {
                    self.app_paths
                        .as_ref()
                        .map(|paths| paths.cache_dir().join("Network"))
                })
                .unwrap_or_else(|| PathBuf::from("Network")),
            None => self
                .app_paths
                .as_ref()
                .map(|paths| paths.cache_dir().join("Network"))
                .unwrap_or_else(|| PathBuf::from("Network")),
        }
    }

    fn lobby_resource_exe_path(&self, work_directory: &Path) -> PathBuf {
        self.app_paths
            .as_ref()
            .map(|paths| paths.install_root().to_path_buf())
            .or_else(|| work_directory.parent().map(Path::to_path_buf))
            .unwrap_or_default()
    }

    fn lobby_resource_player_path(&self) -> PathBuf {
        let config = load_native_config_bytes(self.app_paths.as_ref());
        native_config_text(&config, "General", "PlayerPath")
            .map(|path| PathBuf::from(path.trim()))
            .unwrap_or_default()
    }

    fn lobby_allow_player_save(&self) -> bool {
        let config = load_native_config_bytes(self.app_paths.as_ref());
        native_config_text(&config, "Lobby", "AllowPlayerSave")
            .is_some_and(|value| parse_config_bool(value.trim()))
    }

    fn lobby_resource_save_possible(&self, resource_id: i32) -> bool {
        let Some(core) = self.admission_resources.resource_cores.get(&resource_id) else {
            return false;
        };
        let Some(AdmissionResourceState::Complete {
            path,
            removed: false,
            local,
        }) = self.admission_resources.status(resource_id)
        else {
            return false;
        };
        lobby_resource_save_possible(
            *local,
            true,
            core.resource_type,
            self.lobby_allow_player_save(),
            path,
            &self.lobby_resource_work_directory(),
        )
    }

    fn request_lobby_resource_save(
        &mut self,
        resource_id: i32,
        overwrite: bool,
    ) -> Result<(), EngineError> {
        let Some(core) = self
            .admission_resources
            .resource_cores
            .get(&resource_id)
            .cloned()
        else {
            return Ok(());
        };
        let Some(source) = self
            .admission_resources
            .complete_path(resource_id)
            .map(Path::to_path_buf)
        else {
            return Ok(());
        };
        let work_directory = self.lobby_resource_work_directory();
        let error_caption = self.runtime_resource_text(
            "IDS_NET_ERR_COPYFILE",
            "Error copying file",
        );
        if !path_has_raw_directory_prefix(&source, &work_directory) {
            let message = self.runtime_resource_text(
                "IDS_NET_ERR_COPYFILE_LOCAL",
                "The file is local already",
            );
            self.push_message_dialog(
                clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                    message,
                    error_caption,
                    clonk_frontend::message_dialog::MessageDialogIcon::ERROR,
                ),
                MessageDialogContinuation::None,
            )?;
            return Ok(());
        }
        let exe_path = self.lobby_resource_exe_path(&work_directory);
        let player_path = self.lobby_resource_player_path();
        let Some((target, basename)) =
            lobby_resource_save_target(&exe_path, &player_path, &core)
        else {
            return Ok(());
        };
        if !overwrite && fs::symlink_metadata(&target).is_ok() {
            let template = self.runtime_resource_text(
                "IDS_NET_RES_SAVE_OVERWRITE",
                "File %s exists. Overwrite?",
            );
            let caption = self.runtime_resource_text("IDS_NET_RES_SAVE", "Save resource");
            self.push_message_dialog(
                clonk_frontend::message_dialog::MessageDialogState::new(
                    format_resource_string(template, &[&basename]),
                    caption,
                    clonk_frontend::message_dialog::MessageDialogButtons::YES_NO,
                    clonk_frontend::message_dialog::MessageDialogIcon::CONFIRM,
                    clonk_frontend::message_dialog::MessageDialogSize::Regular,
                    false,
                ),
                MessageDialogContinuation::LobbyResourceOverwrite { resource_id },
            )?;
            return Ok(());
        }
        if let Err(error) = copy_lobby_resource_item(&source, &target) {
            tracing::warn!(
                resource_id,
                source = %source.display(),
                target = %target.display(),
                %error,
                "failed to save lobby resource"
            );
            self.push_message_dialog(
                clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                    error_caption.clone(),
                    error_caption,
                    clonk_frontend::message_dialog::MessageDialogIcon::ERROR,
                ),
                MessageDialogContinuation::None,
            )?;
            return Ok(());
        }
        let template = self.runtime_resource_text(
            "IDS_NET_RES_SAVED_DESC",
            "Resource successfully saved to %s",
        );
        let caption = self.runtime_resource_text("IDS_NET_RES_SAVED", "Resource saved");
        self.push_message_dialog(
            clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                format_resource_string(template, &[&basename]),
                caption,
                clonk_frontend::message_dialog::MessageDialogIcon::Standard(13),
            ),
            MessageDialogContinuation::None,
        )?;
        Ok(())
    }

    fn register_classic_lobby_resource(
        &mut self,
        core: &clonk_engine::NetworkResourceCore,
        present_percent: u8,
    ) {
        if core.id < 0 {
            return;
        }
        let save_possible = self.lobby_resource_save_possible(core.id);
        if let Some(lobby) = self.classic_host_lobby.as_mut() {
            lobby.resource_rows.insert(
                core.id,
                LobbyResourceRow {
                    id: core.id,
                    filename: legacy_presentation_text(core.filename.as_bytes()),
                    present_percent: present_percent.min(100),
                    save_possible,
                },
            );
        }
        if let Some(lobby) = self.network_lobby.as_mut() {
            lobby.resource_rows.insert(
                core.id,
                LobbyResourceRow {
                    id: core.id,
                    filename: legacy_presentation_text(core.filename.as_bytes()),
                    present_percent: present_percent.min(100),
                    save_possible,
                },
            );
        }
        self.sync_visible_classic_lobby_resources();
    }

    fn register_classic_lobby_player_resources(
        &mut self,
        players: &[clonk_engine::ControlPlayerInfoEntry],
    ) {
        let cores = players
            .iter()
            .filter(|player| {
                player.flags & clonk_engine::PLAYER_INFO_FLAG_HAS_RESOURCE != 0
                    && player.flags & clonk_engine::PLAYER_INFO_FLAG_REMOVED == 0
                    && player.flags & clonk_engine::PLAYER_INFO_FLAG_IN_SCENARIO_FILE == 0
            })
            .filter_map(|player| player.resource.as_ref())
            .filter_map(|core| {
                let available = matches!(
                    self.admission_resources.status(core.id),
                    Some(AdmissionResourceState::Loading { removed: false })
                        | Some(AdmissionResourceState::Complete { removed: false, .. })
                );
                available.then(|| {
                    let percent = self
                        .admission_resources
                        .present_percent
                        .get(&core.id)
                        .copied()
                        .unwrap_or(0);
                    (core.clone(), percent)
                })
            })
            .collect::<Vec<_>>();
        for (core, percent) in cores {
            self.register_classic_lobby_resource(&core, percent);
        }
    }

    fn update_classic_lobby_resource_progress(&mut self, resource_id: i32, percent: u8) {
        if let Some(row) = self
            .classic_host_lobby
            .as_mut()
            .and_then(|lobby| lobby.resource_rows.get_mut(&resource_id))
        {
            row.present_percent = percent.min(100);
        }
        if let Some(row) = self
            .network_lobby
            .as_mut()
            .and_then(|lobby| lobby.resource_rows.get_mut(&resource_id))
        {
            row.present_percent = percent.min(100);
        }
        self.sync_visible_classic_lobby_resources();
    }

    fn remove_classic_lobby_resource(&mut self, resource_id: i32) {
        if let Some(lobby) = self.classic_host_lobby.as_mut() {
            lobby.resource_rows.remove(&resource_id);
        }
        if let Some(lobby) = self.network_lobby.as_mut() {
            lobby.resource_rows.remove(&resource_id);
        }
        self.sync_visible_classic_lobby_resources();
    }

    fn remove_classic_lobby_resources_at_client(&mut self, client_id: i32) {
        let owned = |resource_id: &i32| *resource_id >= 0 && (*resource_id >> 16) == client_id;
        self.admission_resources
            .resources
            .retain(|resource_id, _| !owned(resource_id));
        self.admission_resources
            .resource_cores
            .retain(|resource_id, _| !owned(resource_id));
        self.admission_resources
            .present_percent
            .retain(|resource_id, _| !owned(resource_id));
        if let Some(lobby) = self.classic_host_lobby.as_mut() {
            lobby
                .resource_rows
                .retain(|resource_id, _| !owned(resource_id));
        }
        if let Some(lobby) = self.network_lobby.as_mut() {
            lobby
                .resource_rows
                .retain(|resource_id, _| !owned(resource_id));
        }
        self.sync_visible_classic_lobby_resources();
        self.sync_classic_lobby_resource_ready();
    }

    fn lobby_scenario_loading_text(&self, present_percent: u8) -> String {
        let present_percent = present_percent.to_string();
        let template = self.runtime_resource_text(
            "IDS_MSG_SCENARIODESC_LOADING",
            "Loading... (%d%%)",
        );
        format_resource_string(template, &[&present_percent]).replace("%%", "%")
    }

    fn completed_lobby_scenario_description(
        &self,
        path: &Path,
        title: String,
    ) -> LobbyScenarioText {
        let languages = startup_language_sequence(self.app_paths.as_ref());
        let language_packs = self
            .app_paths
            .as_ref()
            .map(classic_language_packs)
            .unwrap_or_default();
        match load_lobby_scenario_description(path, &languages, &language_packs) {
            Ok(Some(description)) => LobbyScenarioText::Description(description),
            Ok(None) => LobbyScenarioText::Title(title),
            Err(_) => LobbyScenarioText::Message("scenario file load error".to_string()),
        }
    }

    fn current_lobby_scenario_description_update(
        &self,
    ) -> Option<LobbyScenarioDescriptionUpdate> {
        match self.network_mode.as_ref()? {
            NetworkMode::Host(HostSettings {
                prepared: Some(prepared),
                ..
            }) => {
                let config = prepared.host_config();
                let snapshot = config.initial_join_snapshot.as_ref()?;
                let scenario = &snapshot.parameters.scenario;
                let title = legacy_presentation_text(snapshot.parameters.title.as_bytes());
                let path = config
                    .resource_files
                    .iter()
                    .find(|resource| resource.core.id == scenario.id)
                    .map(|resource| resource.path.clone())?;
                Some(LobbyScenarioDescriptionUpdate::Complete(
                    self.completed_lobby_scenario_description(&path, title),
                ))
            }
            NetworkMode::Client(_) => {
                let join_data = self.pending_network_join_data.as_ref()?;
                let scenario = &join_data.parameters.scenario;
                let resource_id = scenario.id;
                let title = legacy_presentation_text(join_data.parameters.title.as_bytes());
                match self.admission_resources.status(resource_id).cloned()? {
                    AdmissionResourceState::Loading { removed: false } => {
                        let percent = self
                            .admission_resources
                            .present_percent
                            .get(&resource_id)
                            .copied()
                            .unwrap_or(0);
                        Some(LobbyScenarioDescriptionUpdate::Loading(
                            self.lobby_scenario_loading_text(percent),
                        ))
                    }
                    AdmissionResourceState::Complete { path, .. } => {
                        Some(LobbyScenarioDescriptionUpdate::Complete(
                            self.completed_lobby_scenario_description(&path, title),
                        ))
                    }
                    AdmissionResourceState::Loading { removed: true }
                    | AdmissionResourceState::Unavailable(_) => None,
                }
            }
            NetworkMode::Host(_) => None,
        }
    }

    fn refresh_lobby_scenario_description(&mut self) -> bool {
        let host_active = self.classic_host_lobby.as_ref().is_some_and(|lobby| {
            lobby.controller.active_sheet() == LobbySheet::Scenario
                && !lobby.scenario_description.finished
        });
        let client_active = self.network_lobby.as_ref().is_some_and(|lobby| {
            lobby.active_sheet == LobbySheet::Scenario && !lobby.scenario_description.finished
        });
        if !host_active && !client_active {
            return false;
        }

        let update = self.current_lobby_scenario_description_update();
        let mut changed = false;
        if host_active {
            if let Some(lobby) = self.classic_host_lobby.as_mut() {
                let host_changed = lobby.scenario_description.apply(update.clone());
                if host_changed {
                    lobby
                        .controller
                        .set_scenario_text(lobby.scenario_description.text.clone());
                }
                changed |= host_changed;
            }
        }
        if client_active {
            if let Some(lobby) = self.network_lobby.as_mut() {
                changed |= lobby.scenario_description.apply(update);
            }
        }
        changed
    }

    fn exit_startup_lobby_to_main(&mut self) {
        self.restart_restore_roster_items.clear();
        self.show_main_menu();
        self.resume_startup_music_after_failed_open_game();
    }

    fn select_classic_lobby_sheet(&mut self, sheet: LobbySheet) -> bool {
        let has_teams = self
            .network_team_assignment
            .as_ref()
            .is_some_and(|assignment| assignment.teams().active);
        if sheet == LobbySheet::Teams && !has_teams {
            return false;
        }
        if (!sheet.is_roster()
            && (self.context_menu_lobby_team_player.is_some()
                || self.context_menu_lobby_kick_client.is_some()
                || self.context_menu_lobby_player.is_some()))
            || (sheet != LobbySheet::Options && self.context_menu_lobby_option.is_some())
        {
            self.close_context_menu_silently();
        }
        {
            let Some(lobby) = self.classic_host_lobby.as_mut() else {
                return false;
            };
            lobby.last_roster_click = None;
            lobby.controller.set_active_sheet(sheet);
            if sheet == LobbySheet::Resources {
                lobby
                    .controller
                    .set_resource_rows(lobby.resource_rows.values().cloned().collect());
            }
        }
        if sheet == LobbySheet::Options {
            let _ = self.refresh_classic_lobby_options(true);
        }
        if sheet.is_roster() {
            self.sync_classic_lobby_roster();
        }
        if sheet == LobbySheet::Scenario {
            let _ = self.refresh_lobby_scenario_description();
        }
        true
    }

    fn lobby_tab_context_entries(
        has_teams: bool,
        options_available: bool,
    ) -> Vec<ContextMenuEntry<AppContextMenuCommand>> {
        let mut entries = vec![
            ContextMenuEntry::new("Players")
                .with_icon(ContextMenuIcon::Phase(9))
                .with_action(AppContextMenuCommand::LobbySheet(LobbySheet::Players)),
        ];
        if has_teams {
            entries.push(
                ContextMenuEntry::new("Teams")
                    .with_icon(ContextMenuIcon::Phase(19))
                    .with_action(AppContextMenuCommand::LobbySheet(LobbySheet::Teams)),
            );
        }
        entries.push(
            ContextMenuEntry::new("Resources")
                .with_icon(ContextMenuIcon::Phase(10))
                .with_action(AppContextMenuCommand::LobbySheet(LobbySheet::Resources)),
        );
        if options_available {
            entries.push(
                ContextMenuEntry::new("Options")
                    .with_icon(ContextMenuIcon::Phase(14))
                    .with_action(AppContextMenuCommand::LobbySheet(LobbySheet::Options)),
            );
        }
        entries
    }

    fn open_lobby_tab_context(&mut self, position: GuiPoint) -> Result<bool, EngineError> {
        let (has_teams, options_available) = if self.classic_host_lobby_active() {
            (
                self.network_team_assignment
                    .as_ref()
                    .is_some_and(|assignment| assignment.teams().active),
                true,
            )
        } else if let Some(lobby) = self.network_lobby.as_ref() {
            // C++ always offers Options. Until the joined read-only Options
            // sheet is available, expose only actions this adapter can
            // dispatch instead of opening a typed child boundary.
            (lobby.has_teams, false)
        } else {
            return Ok(false);
        };
        self.open_context_menu_at(
            Self::lobby_tab_context_entries(has_teams, options_available),
            position,
        )
    }

    fn classic_lobby_player_is_owned(&self, client_id: i32) -> bool {
        matches!(self.network_mode, Some(NetworkMode::Host(_)))
            || !self.control_clients.contains(client_id)
            || self
                .network
                .as_ref()
                .and_then(|network| i32::try_from(network.local_client_id()).ok())
                == Some(client_id)
    }

    fn classic_lobby_takeover_entries(
        &self,
        savegame_player_id: i32,
    ) -> Vec<ContextMenuEntry<AppContextMenuCommand>> {
        let Some(local_client_id) = self
            .network
            .as_ref()
            .and_then(|network| i32::try_from(network.local_client_id()).ok())
        else {
            return Vec::new();
        };
        let Some(request) = self
            .control_player_infos
            .client_update_request(local_client_id)
        else {
            return Vec::new();
        };
        let using_player = self.runtime_resource_text("IDS_MSG_USINGPLR", "Using %s");
        let tooltip = self.runtime_resource_text(
            "IDS_MSG_USINGPLR_DESC",
            "Use this player to continue the savegame",
        );
        request
            .players
            .into_iter()
            .filter(|player| {
                player.flags
                    & (clonk_engine::PLAYER_INFO_FLAG_JOINED
                        | clonk_engine::PLAYER_INFO_FLAG_JOIN_ISSUED)
                    == 0
                    && player.savegame_player == 0
            })
            .map(|player| {
                let name = legacy_presentation_text(control_player_effective_name(&player));
                ContextMenuEntry::new(format_resource_string(
                    using_player.clone(),
                    &[&name],
                ))
                .with_tooltip(tooltip.clone())
                .with_icon(ContextMenuIcon::Phase(9))
                .with_action(AppContextMenuCommand::LobbyPlayerTakeOver {
                    savegame_player_id,
                    player_id: player.id,
                })
            })
            .collect()
    }

    fn classic_lobby_player_context_entries(
        &self,
        player_id: i32,
    ) -> Option<(i32, Vec<ContextMenuEntry<AppContextMenuCommand>>)> {
        let (client_id, free_savegame_player) =
            self.visible_classic_lobby_player_context_target(player_id)?;

        if free_savegame_player {
            if self
                .classic_lobby_restore_player(player_id)
                .is_some_and(clonk_engine::ControlPlayerInfoEntry::is_script_player)
            {
                return Some((client_id, Vec::new()));
            }
            return Some((
                client_id,
                // C++ attaches a CBContextHandler here and fills the children
                // in OnContextTakeOver only when the submenu opens
                // (src/C4PlayerInfoListBox.cpp:503-505,535-556), so the
                // candidate set reflects PlayerInfo updates that arrive while
                // the root menu is open.
                vec![ContextMenuEntry::new(
                    self.runtime_resource_text("IDS_MSG_TAKEOVERPLR", "&Take over"),
                )
                .with_tooltip(self.runtime_resource_text(
                    "IDS_MSG_TAKEOVERPLR_DESC",
                    "Control the player in the game",
                ))
                .with_icon(ContextMenuIcon::Phase(9))
                .with_deferred_submenu(AppContextMenuCommand::LobbyPlayerTakeOverSubmenu {
                    savegame_player_id: player_id,
                })],
            ));
        }

        let player = if client_id == -1 {
            // Replay rows deliberately use the synthetic client -1 while
            // looking up presentation data in the global PlayerInfos list.
            self.control_player_infos.get(player_id).cloned()
        } else {
            self.control_player_infos
                .client_update_request(client_id)
                .and_then(|request| {
                    request
                        .players
                        .into_iter()
                        .find(|player| player.id == player_id)
                })
        };
        let Some(player) = player else {
            return Some((client_id, Vec::new()));
        };
        if !self.classic_lobby_player_is_owned(client_id) {
            return Some((client_id, Vec::new()));
        }

        let mut entries = Vec::new();
        if !player.is_script_player() || player.savegame_player == 0 {
            entries.push(
                ContextMenuEntry::new(
                    self.runtime_resource_text("IDS_MSG_REMOVEPLR", "&Remove"),
                )
                .with_tooltip(self.runtime_resource_text(
                    "IDS_MSG_REMOVEPLR_DESC",
                    "Do not join with this player",
                ))
                .with_icon(ContextMenuIcon::Phase(34))
                .with_action(AppContextMenuCommand::LobbyPlayerRemove {
                    client_id,
                    player_id,
                }),
            );
        }
        let team_colors = self
            .visible_classic_lobby_team_metadata()
            .is_some_and(|teams| teams.team_colors);
        if player.color != player.original_color && (!team_colors || player.team == 0) {
            entries.push(
                ContextMenuEntry::new(
                    self.runtime_resource_text("IDS_MSG_NEWPLRCOLOR", "New &color"),
                )
                .with_tooltip(self.runtime_resource_text(
                    "IDS_MSG_NEWPLRCOLOR_DESC",
                    "Generate a new random player color",
                ))
                .with_icon(ContextMenuIcon::Phase(9))
                .with_action(AppContextMenuCommand::LobbyPlayerNewColor {
                    client_id,
                    player_id,
                }),
            );
        }
        Some((client_id, entries))
    }

    fn visible_lobby_client_is_local(&self, client_id: i32) -> Option<bool> {
        self.classic_host_lobby
            .as_ref()
            .and_then(|lobby| {
                lobby.controller.rows().iter().find_map(|row| match row {
                    LobbyRosterRow::Client(client) if client.id == client_id => {
                        Some(client.local)
                    }
                    _ => None,
                })
            })
            .or_else(|| {
                self.network_lobby
                    .as_ref()
                    .and_then(|lobby| lobby.visible_client_is_local(client_id))
            })
    }

    fn classic_lobby_client_context_entries(
        &self,
        client_id: i32,
    ) -> Option<Vec<ContextMenuEntry<AppContextMenuCommand>>> {
        if self.network.is_none() || !self.control_clients.contains(client_id) {
            return None;
        }
        let local = self.visible_lobby_client_is_local(client_id)?;
        let mut entries = Vec::new();
        if !local {
            let muted = self.control_messages.is_muted(client_id);
            entries.push(
                ContextMenuEntry::new(if muted {
                    self.runtime_resource_text("IDS_NET_UNMUTE", "&Unmute")
                } else {
                    self.runtime_resource_text("IDS_NET_MUTE", "&Mute")
                })
                .with_tooltip(if muted {
                    self.runtime_resource_text(
                        "IDS_NET_UNMUTE_DESC",
                        "Unmute /sound-commands by this client",
                    )
                } else {
                    self.runtime_resource_text(
                        "IDS_NET_MUTE_DESC",
                        "Mute /sound commands of by this client",
                    )
                })
                .with_action(AppContextMenuCommand::LobbyClientToggleMute(client_id)),
            );
        }
        if matches!(self.network_mode, Some(NetworkMode::Host(_))) {
            entries.push(
                ContextMenuEntry::new(
                    self.runtime_resource_text("IDS_NET_KICKCLIENT", "&Kick"),
                )
                .with_tooltip(self.runtime_resource_text(
                    "IDS_NET_KICKCLIENT_DESC",
                    "Disconnect this client",
                ))
                .with_action(AppContextMenuCommand::LobbyKick(client_id)),
            );
            let activated = self.control_clients.is_activated(client_id);
            entries.push(
                ContextMenuEntry::new(if activated {
                    self.runtime_resource_text("IDS_NET_DEACTIVATECLIENT", "De&activate")
                } else {
                    self.runtime_resource_text("IDS_NET_ACTIVATECLIENT", "&Activate")
                })
                .with_tooltip(self.runtime_resource_text(
                    "IDS_NET_ACTIVATECLIENT_DESC",
                    "Toggle player/observer-status",
                ))
                .with_action(AppContextMenuCommand::LobbyClientToggleActivate(client_id)),
            );
        }
        entries.push(
            ContextMenuEntry::new(self.runtime_resource_text("IDS_NET_CLIENTINFO", "&Info"))
                .with_tooltip(self.runtime_resource_text(
                    "IDS_NET_CLIENTINFO_DESC",
                    "Show extended info",
                ))
                .with_action(AppContextMenuCommand::LobbyClientInfo(client_id)),
        );
        Some(entries)
    }

    fn open_classic_lobby_roster_context(
        &mut self,
        row: LobbyRosterId,
        position: GuiPoint,
    ) -> Result<bool, EngineError> {
        match row {
            LobbyRosterId::Player(player_id) => {
                let Some((client_id, entries)) =
                    self.classic_lobby_player_context_entries(player_id)
                else {
                    return Ok(false);
                };
                let opened = self.open_context_menu_at(entries, position)?;
                if opened {
                    let opened_as_free_savegame = self
                        .visible_classic_lobby_player_context_target(player_id)
                        .is_some_and(|(_, free_savegame_player)| free_savegame_player);
                    self.context_menu_lobby_player =
                        Some((client_id, player_id, opened_as_free_savegame));
                }
                Ok(opened)
            }
            LobbyRosterId::Client(client_id) => {
                let Some(entries) = self.classic_lobby_client_context_entries(client_id) else {
                    return Ok(false);
                };
                let opened = self.open_context_menu_at(entries, position)?;
                if opened {
                    self.context_menu_lobby_kick_client = Some(client_id);
                }
                Ok(opened)
            }
            row @ LobbyRosterId::Header(_) => Err(classic_game_lobby_child_error(
                ClassicGameLobbyChild::RosterContext(row),
            )),
        }
    }

    fn toggle_classic_lobby_client_mute(&mut self, client_id: i32) {
        if self.control_clients.contains(client_id) {
            let muted = !self.control_messages.is_muted(client_id);
            self.control_messages.set_muted(client_id, muted);
        }
    }

    fn toggle_classic_lobby_client_activation(&mut self, client_id: i32) {
        if self.network.is_none()
            || !matches!(self.network_mode, Some(NetworkMode::Host(_)))
            || self.visible_lobby_client_is_local(client_id).is_none()
            || !self.control_clients.contains(client_id)
        {
            return;
        }
        let update = clonk_engine::ClientUpdateControlData {
            update_type: clonk_engine::CLIENT_UPDATE_ACTIVATE,
            client_id,
            data: i32::from(!self.control_clients.is_activated(client_id)),
            by_client: 0,
        };
        if let Some(Err(error)) = self
            .network
            .as_ref()
            .map(|network| network.submit_client_update(update))
        {
            tracing::error!(%error, client_id, "failed to toggle lobby client activation");
        }
    }

    fn open_classic_lobby_client_info(&mut self, client_id: i32) -> Result<bool, EngineError> {
        if self.network.is_none()
            || self.visible_lobby_client_is_local(client_id).is_none()
            || !self.control_clients.contains(client_id)
        {
            return Ok(false);
        }
        Self::guard_gui_overlay_result(
            "C4Network2ClientDlg",
            self.assets
                .runtime_client_list_resources()
                .context("exact C4Network2ClientDlg resource set is absent")
                .and_then(|resources| resources.validate()),
        )?;
        let (_, rows, _) = self.runtime_client_list_snapshot();
        let Some(row) = rows.into_iter().find(|row| row.client_id == client_id) else {
            return Ok(false);
        };
        self.cancel_underlying_interaction();
        self.runtime_client_list_consumed_keys.clear();
        self.runtime_client_list = Some(
            clonk_frontend::runtime_client_list::RuntimeClientListDialog::new_info(
                self.runtime_resource_string("IDS_NET_CLIENT_INFO"),
                row,
            ),
        );
        self.show_or_raise_runtime_default_dialog(RuntimeDefaultDialog::ClientList);
        self.mark_menu_dirty();
        Ok(true)
    }

    fn kick_classic_lobby_client(&mut self, client_id: i32) {
        if !matches!(self.network_mode, Some(NetworkMode::Host(_)))
            || client_id == 0
            || !self.control_clients.contains(client_id)
        {
            return;
        }
        let league_vote = self.network_is_league
            && self
                .control_player_infos
                .retained_rows_snapshot()
                .1
                .into_iter()
                .find(|(packet_client, _, _)| *packet_client == client_id)
                .is_some_and(|(_, _, players)| {
                    players.iter().any(|player| {
                        player.flags & clonk_engine::PLAYER_INFO_FLAG_REMOVED == 0
                    })
                });
        if league_vote {
            self.submit_own_league_vote(
                LeagueVoteSubject {
                    vote_type: clonk_engine::VOTE_TYPE_KICK,
                    data: client_id,
                },
                true,
            );
            return;
        }
        let remove = clonk_engine::ClientRemoveControlData {
            client_id,
            reason: LegacyCString::from_bytes(b"kicked from startup waiting dialog".to_vec())
                .unwrap_or_default(),
            by_client: 0,
        };
        if let Some(Err(error)) = self
            .network
            .as_ref()
            .map(|network| network.submit_client_remove(remove))
        {
            tracing::error!(%error, client_id, "failed to kick lobby client");
        }
    }

    fn report_classic_lobby_error(&mut self, detail: impl Into<String>) {
        let detail = detail.into();
        self.status_text.clone_from(&detail);
        self.append_control_message_log(detail, 0x00ff_1f1f, None);
    }

    fn open_classic_lobby_player_selector(
        &mut self,
        client_id: i32,
    ) -> Result<bool, EngineError> {
        let local_client_id = self
            .network
            .as_ref()
            .and_then(|network| i32::try_from(network.local_client_id()).ok());
        let local_row = self.visible_classic_lobby_controller().is_some_and(|controller| {
            controller.rows().iter().any(|row| {
                matches!(row, LobbyRosterRow::Client(client) if client.id == client_id && client.local)
            })
        });
        if local_client_id != Some(client_id) || !local_row {
            return Ok(false);
        }
        self.guard_classic_global_gui_bootstrap()?;
        Self::guard_gui_overlay_result(
            "C4PlayerSelDlg",
            self.assets
                .definition_sel_resources()
                .context("exact C4PlayerSelDlg resource set is absent")
                .and_then(|resources| {
                    resources.validate_for_mode(clonk_frontend::definition_sel::FileSelMode::Player)
                }),
        )?;
        let Some(paths) = self.app_paths.clone() else {
            let detail = "cannot open player selection without application paths";
            tracing::error!("{detail}");
            self.report_classic_lobby_error(detail);
            return Ok(false);
        };
        let config = match Config::load(paths.config_file()) {
            Ok(config) => config,
            Err(error) if error.kind() == io::ErrorKind::NotFound => Config::new(),
            Err(error) => {
                tracing::error!(%error, "failed to read player selector configuration");
                self.report_classic_lobby_error(format!(
                    "Unable to read player selection configuration: {error}"
                ));
                Config::new()
            }
        };
        let frozen_root = startup_player_search_paths(&paths, &config)
            .into_iter()
            .next()
            .unwrap_or_else(|| paths.install_root().to_path_buf());
        let (root, entries, candidates) = match discover_lobby_player_selector(&paths, &config) {
            Ok(selection) => selection,
            Err(error) => {
                tracing::error!(%error, "failed to enumerate lobby player files");
                self.report_classic_lobby_error(format!(
                    "Unable to enumerate player files: {error}"
                ));
                (frozen_root, Vec::new(), BTreeMap::new())
            }
        };
        let root = root.to_string_lossy().into_owned();
        self.close_context_menu_silently();
        if let Some(controller) = self.visible_classic_lobby_controller_mut() {
            controller.cancel_interaction();
        }
        self.startup_tooltip.pointer_left();
        self.definition_selector = Some(
            clonk_frontend::definition_sel::DefinitionSelController::new_player(root, entries),
        );
        self.pending_definition_selection = None;
        self.pending_lobby_player_selection = Some(PendingLobbyPlayerSelection {
            client_id,
            config,
            candidates,
        });
        self.definition_selector_last_click = None;
        self.definition_selector_consumed_keys.clear();
        self.definition_selector_pointer_capture = false;
        self.mark_menu_dirty();
        Ok(true)
    }

    fn submit_selected_classic_lobby_player(
        &mut self,
        client_id: i32,
        source_path: &Path,
        wire_filename: &str,
    ) {
        let local_client_id = self
            .network
            .as_ref()
            .and_then(|network| i32::try_from(network.local_client_id()).ok());
        if local_client_id != Some(client_id) || !self.control_clients.contains(client_id) {
            self.report_classic_lobby_error(
                "The selected lobby client is no longer available for adding a player.",
            );
            return;
        }
        if !source_path.exists() {
            self.report_classic_lobby_error(format!(
                "The selected player file no longer exists: {}",
                source_path.display()
            ));
            return;
        }
        let countdown_active = self
            .visible_classic_lobby_controller()
            .is_some_and(|controller| controller.countdown().is_locked());
        if countdown_active {
            if !matches!(self.network_mode, Some(NetworkMode::Host(_))) {
                return;
            }
            let abort = clonk_network::LobbyCountdownPacket::new(
                clonk_network::LobbyCountdownPacket::ABORT,
            );
            if let Some(Err(error)) = self
                .network
                .as_ref()
                .map(|network| network.submit_lobby_countdown(abort))
            {
                tracing::error!(%error, "failed to abort countdown before adding lobby player");
                self.report_classic_lobby_error(format!(
                    "Unable to abort the countdown before adding the player: {error}"
                ));
                return;
            }
            if let Some(controller) = self.visible_classic_lobby_controller_mut() {
                let _ = controller.apply_countdown_packet(
                    clonk_frontend::game_lobby::LobbyCountdownPacket::Abort,
                );
            }
        }
        if let Err(error) =
            self.submit_runtime_network_player_path(source_path, wire_filename)
        {
            tracing::error!(path = %source_path.display(), %error, "failed to add lobby player");
            self.report_classic_lobby_error(format!("Unable to add player: {error}"));
        }
    }

    fn add_classic_lobby_script_player(&mut self) {
        let request = {
            let _guard = lock_unpoisoned(&CLASSIC_SAFE_RANDOM_LOCK);
            self.classic_lobby_script_player_request_with_random(classic_safe_random_unlocked)
        };
        self.submit_classic_lobby_script_player_request(request);
    }

    #[cfg(test)]
    fn add_classic_lobby_script_player_with_random(
        &mut self,
        next_random: impl FnMut(usize) -> usize,
    ) {
        let request = self.classic_lobby_script_player_request_with_random(next_random);
        self.submit_classic_lobby_script_player_request(request);
    }

    fn classic_lobby_script_player_request_with_random(
        &self,
        mut next_random: impl FnMut(usize) -> usize,
    ) -> Option<clonk_engine::PlayerInfoUpdateRequest> {
        if !matches!(self.network_mode, Some(NetworkMode::Host(_))) {
            return None;
        }
        let Some(metadata) = self
            .network_team_assignment
            .as_ref()
            .map(|assignment| assignment.teams().clone())
        else {
            return None;
        };
        let (_, packets) = self.control_player_infos.retained_rows_snapshot();
        let active = packets
            .iter()
            .flat_map(|(_, _, players)| players)
            .filter(|player| player.flags & clonk_engine::PLAYER_INFO_FLAG_REMOVED == 0)
            .collect::<Vec<_>>();
        let active_script_players = active
            .iter()
            .filter(|player| player.is_script_player())
            .count();
        if metadata.max_script_players
            <= i32::try_from(active_script_players).unwrap_or(i32::MAX)
        {
            return None;
        }
        let active_names = active
            .iter()
            .map(|player| {
                if !player.league_account.is_empty() {
                    player.league_account.as_bytes()
                } else if !player.forced_name.is_empty() {
                    player.forced_name.as_bytes()
                } else {
                    player.name.as_bytes()
                }
            })
            .collect::<Vec<_>>();
        let name = classic_script_player_name(
            &metadata.script_player_names,
            &active_names,
            &mut next_random,
        );
        let color = classic_script_player_color(&mut next_random);
        let local_client_id = self
            .network
            .as_ref()
            .and_then(|network| i32::try_from(network.local_client_id()).ok())
            .unwrap_or(0);
        Some(clonk_engine::PlayerInfoUpdateRequest {
            client_id: local_client_id,
            flags: clonk_engine::CLIENT_PLAYER_INFO_FLAG_ADD_PLAYERS,
            players: vec![clonk_engine::ControlPlayerInfoEntry {
                name,
                player_type: clonk_engine::PLAYER_INFO_TYPE_SCRIPT,
                color,
                original_color: color,
                ..clonk_engine::ControlPlayerInfoEntry::default()
            }],
        })
    }

    fn submit_classic_lobby_script_player_request(
        &self,
        request: Option<clonk_engine::PlayerInfoUpdateRequest>,
    ) {
        let Some(request) = request else {
            return;
        };
        if let Some(Err(error)) = self
            .network
            .as_ref()
            .map(|network| network.submit_player_info_update(request))
        {
            tracing::error!(%error, "failed to submit lobby script player");
        }
    }

    fn open_classic_lobby_team_combo(
        &mut self,
        player_id: i32,
    ) -> Result<bool, EngineError> {
        let dismissed_player = self
            .context_menu_pointer_dismissed_lobby_team_player
            .take();
        if dismissed_player == Some(player_id) {
            // Screen::MouseInput already aborted this combo's menu on the
            // same left-down. ComboBox::MouseInput rechecks the last menu ID
            // and deliberately does not reopen it.
            return Ok(false);
        }
        if self.mode != AppMode::Menu
            || self.startup_view != StartupView::NetworkLobby
            || !self.message_dialogs.is_empty()
            || self.game_over_dialog.is_some()
            || self.context_menu.is_some()
        {
            return Ok(false);
        }

        let (_, roster) = self.visible_classic_lobby_layouts()?;
        let Some((client_id, current_team, anchor, minimum_width)) = self
            .visible_classic_lobby_controller()
            .and_then(|controller| {
                if controller.countdown().is_locked() {
                    return None;
                }
                let (index, player) = controller
                    .rows()
                    .iter()
                    .enumerate()
                    .find_map(|(index, row)| match row {
                        LobbyRosterRow::Player(player) if player.id == player_id => {
                            Some((index, player))
                        }
                        _ => None,
                    })?;
                let team = player.team.as_ref().filter(|team| team.selectable)?;
                let team_rect = roster
                    .rows
                    .iter()
                    .find(|row| row.index == index)?
                    .team?;
                Some((
                    player.client_id,
                    team.id,
                    GuiPoint::new(team_rect.x as f32, (team_rect.y + team_rect.h) as f32),
                    team_rect.w,
                ))
            })
        else {
            return Ok(false);
        };
        if !self.classic_lobby_team_change_is_allowed(player_id, client_id) {
            return Ok(false);
        }

        let select_template = load_runtime_language_table(self.app_paths.as_ref())
            .ok()
            .and_then(|table| table.entries.get("IDS_MSG_SELECT").cloned());
        let metadata = self.visible_classic_lobby_team_metadata();
        let entries = metadata
            .as_ref()
            .into_iter()
            .flat_map(|metadata| metadata.teams.iter())
            .filter(|team| {
                team.id == current_team
                    || team.max_players == 0
                    || i32::try_from(team.player_ids.len()).unwrap_or(i32::MAX)
                        < team.max_players
            })
            .map(|team| {
                let name = legacy_presentation_text(team.name.as_bytes());
                let tooltip = select_template
                    .as_deref()
                    .map(|template| template.replacen("%s", &name, 1))
                    .unwrap_or_else(|| format!("Select {name}"));
                ContextMenuEntry::new(name)
                    .with_tooltip(tooltip)
                    .with_icon(ContextMenuIcon::Empty)
                    .with_action(AppContextMenuCommand::LobbyTeam {
                        player_id,
                        team_id: team.id,
                    })
            })
            .collect();
        self.open_context_menu_at_with_minimum_width(
            entries,
            anchor,
            minimum_width,
            Some(player_id),
        )
    }

    fn classic_lobby_option_is_editable(&self, option: LobbyOptionKind) -> bool {
        self.classic_host_lobby.as_ref().is_some_and(|lobby| {
            lobby.controller.active_sheet() == LobbySheet::Options
                && lobby
                    .controller
                    .option_rows()
                    .iter()
                    .any(|row| row.kind == option && row.editable)
        })
    }

    fn classic_lobby_option_accepts_choice(
        &self,
        option: LobbyOptionKind,
        selected: i32,
    ) -> bool {
        self.classic_host_lobby.as_ref().is_some_and(|lobby| {
            lobby.controller.active_sheet() == LobbySheet::Options
                && lobby.controller.option_rows().iter().any(|row| {
                    row.kind == option
                        && row.editable
                        && row.choices.iter().any(|choice| choice.id == selected)
                })
        })
    }

    fn open_classic_lobby_option_combo(
        &mut self,
        option: LobbyOptionKind,
        anchor: GuiPoint,
        minimum_width: i32,
    ) -> Result<bool, EngineError> {
        if self.context_menu_pointer_dismissed_lobby_option.take() == Some(option) {
            // The outside click which closed this ComboBox is still being
            // delivered to the underlying sheet; do not reopen it.
            return Ok(false);
        }
        if self.mode != AppMode::Menu
            || self.startup_view != StartupView::NetworkLobby
            || !self.message_dialogs.is_empty()
            || self.game_over_dialog.is_some()
            || self.context_menu.is_some()
            || option == LobbyOptionKind::ControlMode
        {
            return Ok(false);
        }
        let Some(choices) = self.classic_host_lobby.as_ref().and_then(|lobby| {
            (lobby.controller.active_sheet() == LobbySheet::Options)
                .then(|| {
                    lobby
                        .controller
                        .option_rows()
                        .iter()
                        .find(|row| row.kind == option && row.editable)
                        .map(|row| row.choices.clone())
                })
                .flatten()
        }) else {
            return Ok(false);
        };
        let entries = choices
            .into_iter()
            .map(|choice| {
                let command = match option {
                    LobbyOptionKind::ControlRate => {
                        AppContextMenuCommand::LobbyControlRate(choice.id)
                    }
                    LobbyOptionKind::RuntimeJoin => {
                        AppContextMenuCommand::LobbyRuntimeJoin(choice.id != 0)
                    }
                    LobbyOptionKind::TeamDistribution => {
                        AppContextMenuCommand::LobbyTeamDistribution(choice.id)
                    }
                    LobbyOptionKind::TeamColors => {
                        AppContextMenuCommand::LobbyTeamColors(choice.id != 0)
                    }
                    LobbyOptionKind::RandomTeamCount => {
                        AppContextMenuCommand::LobbyRandomTeamCount(choice.id)
                    }
                    LobbyOptionKind::ControlMode => unreachable!("read-only lobby option"),
                };
                ContextMenuEntry::new(choice.label)
                    .with_tooltip(choice.tooltip)
                    .with_icon(ContextMenuIcon::Empty)
                    .with_action(command)
            })
            .collect();
        let opened = self.open_context_menu_at_with_minimum_width(
            entries,
            anchor,
            minimum_width,
            None,
        )?;
        if opened {
            self.set_context_menu_lobby_option(Some(option));
        }
        Ok(opened)
    }

    fn open_runtime_client_list_option_combo(
        &mut self,
        option: LobbyOptionKind,
        anchor: GuiPoint,
        minimum_width: i32,
    ) -> Result<bool, EngineError> {
        if self.context_menu_pointer_dismissed_lobby_option.take() == Some(option) {
            return Ok(false);
        }
        if self.mode != AppMode::Running || self.context_menu.is_some() {
            return Ok(false);
        }
        let Some(choices) = self.runtime_client_list.as_ref().and_then(|dialog| {
            (!dialog.is_info_only()).then(|| {
                dialog
                    .option_rows()
                    .iter()
                    .find(|row| row.kind == option && row.editable && !row.choices.is_empty())
                    .map(|row| row.choices.clone())
            })?
        }) else {
            return Ok(false);
        };
        let entries = choices
            .into_iter()
            .map(|choice| {
                ContextMenuEntry::new(choice.label)
                    .with_tooltip(choice.tooltip)
                    .with_icon(ContextMenuIcon::Empty)
                    .with_action(AppContextMenuCommand::RuntimeClientOption {
                        option,
                        value: choice.id,
                    })
            })
            .collect();
        let opened =
            self.open_context_menu_at_with_minimum_width(entries, anchor, minimum_width, None)?;
        if opened {
            self.set_context_menu_lobby_option(Some(option));
        }
        Ok(opened)
    }

    fn apply_runtime_client_list_option(
        &mut self,
        option: LobbyOptionKind,
        value: i32,
    ) -> Result<(), EngineError> {
        let valid_choice = self.runtime_client_list.as_ref().is_some_and(|dialog| {
            dialog.option_rows().iter().any(|row| {
                row.kind == option
                    && row.editable
                    && row.choices.iter().any(|choice| choice.id == value)
            })
        });
        if !valid_choice {
            return Ok(());
        }
        match option {
            LobbyOptionKind::ControlMode => {
                if self.engine.is_control_host()
                    && matches!(value, 0 | 1 | 2)
                    && (!self.network_is_league || value != 2)
                {
                    self.change_running_network_control_mode(value);
                }
            }
            LobbyOptionKind::ControlRate => {
                if self.engine.is_control_host()
                    && (1..=9).contains(&value)
                {
                    let current = self
                        .network_control_clock
                        .map(NetworkControlClock::control_rate)
                        .unwrap_or_else(|| self.engine.control_rate());
                    if value != current {
                        self.submit_or_execute_running_control_set(0, value - current)?;
                    }
                }
            }
            LobbyOptionKind::RuntimeJoin => {
                if matches!(self.runtime_network_role(), RuntimeNetworkRole::Host) {
                    let allowed = value != 0;
                    let result = self
                        .network
                        .as_ref()
                        .ok_or_else(|| anyhow!("runtime network is unavailable"))
                        .and_then(|network| network.set_join_allowed(allowed));
                    if let Err(error) = result {
                        tracing::error!(%error, allowed, "failed to change runtime join admission");
                        return Ok(());
                    }
                    self.runtime_network_join_allowed = Some(allowed);
                    if let Some(NetworkMode::Host(HostSettings {
                        prepared: Some(prepared),
                        ..
                    })) = self.network_mode.as_mut()
                    {
                        prepared.set_runtime_join_allowed(allowed);
                    }
                    self.persist_game_option_value(
                        "Network",
                        "NoRuntimeJoin",
                        if allowed { "0" } else { "1" }.to_string(),
                    );
                    self.publish_running_host_reference();
                    let labels = self.classic_lobby_option_labels();
                    let message = if allowed {
                        labels.runtime_join_free
                    } else {
                        labels.runtime_join_barred
                    };
                    let charset = load_runtime_language_table(self.app_paths.as_ref())
                        .map(|table| table.charset)
                        .unwrap_or(RuntimeHelpCharset::Windows1252);
                    match self.prepare_runtime_flash_message(&message, charset) {
                        Ok(message) => self.runtime_flash_message = message,
                        Err(error) => {
                            tracing::warn!(%error, "failed to prepare runtime-join flash message")
                        }
                    }
                }
            }
            LobbyOptionKind::TeamDistribution
            | LobbyOptionKind::TeamColors
            | LobbyOptionKind::RandomTeamCount => {}
        }
        self.refresh_runtime_client_list();
        Ok(())
    }

    fn submit_classic_lobby_control_rate(&mut self, selected: i32) {
        if !(1..=9).contains(&selected)
            || !self.classic_lobby_option_is_editable(LobbyOptionKind::ControlRate)
            || !matches!(self.network_mode, Some(NetworkMode::Host(_)))
            || !self
                .network
                .as_ref()
                .is_some_and(|network| network.local_client_id() == 0)
        {
            return;
        }
        // Native re-reads ControlRate when the menu action activates. A
        // control echoed before this click therefore changes the submitted
        // relative adjustment instead of applying a stale absolute value.
        let current = self
            .network_control_clock
            .map(NetworkControlClock::control_rate)
            .unwrap_or_else(|| self.engine.control_rate());
        if selected == current {
            return;
        }
        let result = self.network.as_ref().map(|network| {
            network.submit_control_set(clonk_network::LegacyControlSet {
                value_type: 0,
                data: selected - current,
                by_client: 0,
            })
        });
        if let Some(Err(error)) = result {
            tracing::error!(%error, "failed to submit lobby control-rate adjustment");
            self.report_classic_lobby_error(format!(
                "Unable to change the control rate: {error}"
            ));
        }
    }

    fn submit_classic_lobby_team_setting(
        &mut self,
        option: LobbyOptionKind,
        selected: i32,
    ) {
        let value_type = match option {
            LobbyOptionKind::TeamDistribution => 3,
            LobbyOptionKind::TeamColors => 4,
            _ => return,
        };
        if !self.classic_lobby_option_accepts_choice(option, selected)
            || !matches!(self.network_mode, Some(NetworkMode::Host(_)))
            || !self
                .network
                .as_ref()
                .is_some_and(|network| network.local_client_id() == 0)
        {
            return;
        }
        let result = self.network.as_ref().map(|network| {
            network.submit_control_set(clonk_network::LegacyControlSet {
                value_type,
                data: selected,
                by_client: 0,
            })
        });
        if let Some(Err(error)) = result {
            tracing::error!(%error, value_type, selected, "failed to submit lobby team setting");
            self.report_classic_lobby_error(format!(
                "Unable to change the team setting: {error}"
            ));
        }
    }

    fn set_classic_lobby_random_team_count(&mut self, selected: i32) {
        if !self.classic_lobby_option_accepts_choice(
            LobbyOptionKind::RandomTeamCount,
            selected,
        ) || !matches!(self.network_mode, Some(NetworkMode::Host(_)))
            || !self
                .network
                .as_ref()
                .is_some_and(|network| network.local_client_id() == 0)
        {
            return;
        }
        let has_or_will_have_lobby = self.has_or_will_have_network_lobby();
        let Some((metadata, updates)) = self.network_team_assignment.as_mut().map(|assignment| {
            let updates = assignment.set_random_team_count(
                &mut self.control_player_infos,
                selected,
                has_or_will_have_lobby,
            );
            (assignment.teams().clone(), updates)
        }) else {
            return;
        };

        let runtime_teams = runtime_teams_from_initial_metadata(&metadata);
        let team_snapshot = clonk_network::join_team_list_snapshot(metadata);
        self.engine.set_teams(runtime_teams.clone());
        if let Some(prepared) = self
            .loading_state
            .as_mut()
            .and_then(|loading| loading.prepared_go.as_mut())
        {
            prepared.team_registry = runtime_teams;
        }
        if let Some(join_data) = self.pending_network_join_data.as_mut() {
            join_data.parameters.teams = team_snapshot.clone();
        }
        let mut host_snapshot_changed = false;
        if let Some(snapshot) = self.host_join_snapshot.as_mut() {
            snapshot.parameters.teams = team_snapshot;
            host_snapshot_changed = true;
        }
        host_snapshot_changed |= self.refresh_current_host_player_infos();
        if let Some(network) = self.network.as_ref() {
            for update in updates {
                if let Err(error) = network.broadcast_player_info(update) {
                    tracing::error!(%error, "failed to broadcast RandomTeamCount PlayerInfo update");
                }
            }
        }
        if host_snapshot_changed {
            self.publish_updated_host_join_snapshot();
        }
        self.sync_classic_lobby_roster();
        if self.refresh_classic_lobby_options(true) {
            self.mark_menu_dirty();
        }
    }

    fn set_classic_lobby_runtime_join(&mut self, allowed: bool) {
        if !self.classic_lobby_option_is_editable(LobbyOptionKind::RuntimeJoin)
            || !matches!(self.network_mode, Some(NetworkMode::Host(_)))
            || !self
                .network
                .as_ref()
                .is_some_and(|network| network.local_client_id() == 0)
        {
            return;
        }
        let Some(lobby) = self.classic_host_lobby.as_mut() else {
            return;
        };
        lobby.runtime_join_allowed = allowed;
        if let Some(NetworkMode::Host(HostSettings {
            prepared: Some(prepared),
            ..
        })) = self.network_mode.as_mut()
        {
            prepared.set_runtime_join_allowed(allowed);
        }
        self.persist_game_option_value(
            "Network",
            "NoRuntimeJoin",
            if allowed { "0" } else { "1" }.to_string(),
        );
        // Lobby admission deliberately remains open. The retained prepared
        // policy is queued immediately after the Go status request when the
        // lobby exits, matching DoLobby's post-status admission update.
        let _ = self.refresh_classic_lobby_options(true);
    }

    fn classic_lobby_team_change_is_allowed(&self, player_id: i32, client_id: i32) -> bool {
        let player_is_eligible = self
            .control_player_infos
            .client_update_request(client_id)
            .and_then(|request| {
                request
                    .players
                    .into_iter()
                    .find(|player| player.id == player_id)
            })
            .is_some_and(|player| !player.is_joined() && player.savegame_player == 0);
        if !player_is_eligible {
            return false;
        }
        let Some(metadata) = self.visible_classic_lobby_team_metadata() else {
            return false;
        };
        let distribution_allows_change = match metadata.team_distribution {
            clonk_engine::InitialNetworkTeamDistribution::Free => true,
            clonk_engine::InitialNetworkTeamDistribution::Host => {
                matches!(self.network_mode, Some(NetworkMode::Host(_)))
            }
            clonk_engine::InitialNetworkTeamDistribution::None
            | clonk_engine::InitialNetworkTeamDistribution::Random
            | clonk_engine::InitialNetworkTeamDistribution::RandomInvisible => false,
        };
        if !metadata.active || !distribution_allows_change {
            return false;
        }
        if metadata.auto_generate_teams {
            return true;
        }
        let current_team = metadata
            .teams
            .iter()
            .find(|team| team.player_ids.contains(&player_id))
            .map(|team| team.id);
        metadata.teams.iter().any(|team| {
            Some(team.id) != current_team
                && (team.max_players == 0
                    || i32::try_from(team.player_ids.len()).unwrap_or(i32::MAX)
                        < team.max_players)
        })
    }

    fn submit_classic_lobby_team_selection(&mut self, player_id: i32, team_id: i32) {
        let Some(client_id) = self.visible_classic_lobby_controller().and_then(|controller| {
            if controller.countdown().is_locked() {
                return None;
            }
            controller.rows().iter().find_map(|row| match row {
                LobbyRosterRow::Player(player)
                    if player.id == player_id
                        && player.team.as_ref().is_some_and(|team| team.selectable) =>
                {
                    Some(player.client_id)
                }
                _ => None,
            })
        }) else {
            return;
        };
        if !self.classic_lobby_team_change_is_allowed(player_id, client_id) {
            return;
        }
        if !self
            .visible_classic_lobby_team_metadata()
            .is_some_and(|metadata| metadata.teams.iter().any(|team| team.id == team_id))
        {
            return;
        }
        let Some(mut request) = self.control_player_infos.client_update_request(client_id) else {
            return;
        };
        let Some(player) = request
            .players
            .iter_mut()
            .find(|player| player.id == player_id)
        else {
            return;
        };
        player.team = team_id;
        let Some(network) = self.network.as_ref() else {
            tracing::error!(player_id, team_id, "lobby team selection has no network session");
            return;
        };
        if let Err(error) = network.submit_player_info_update(request) {
            tracing::error!(%error, player_id, team_id, "failed to submit lobby team selection");
        }
    }

    fn move_local_classic_lobby_players_into_team(&mut self, team_id: i32) {
        if self
            .visible_classic_lobby_controller()
            .is_none_or(|controller| controller.countdown().is_locked())
        {
            return;
        }
        let Some(metadata) = self.visible_classic_lobby_team_metadata() else {
            return;
        };
        if !metadata.active {
            return;
        }
        let distribution_allows_change = match metadata.team_distribution {
            clonk_engine::InitialNetworkTeamDistribution::Free => true,
            clonk_engine::InitialNetworkTeamDistribution::Host => {
                matches!(self.network_mode, Some(NetworkMode::Host(_)))
            }
            clonk_engine::InitialNetworkTeamDistribution::None
            | clonk_engine::InitialNetworkTeamDistribution::Random
            | clonk_engine::InitialNetworkTeamDistribution::RandomInvisible => false,
        };
        let has_available_team = metadata.auto_generate_teams
            || metadata.teams.iter().any(|team| {
                team.max_players == 0
                    || i32::try_from(team.player_ids.len()).unwrap_or(i32::MAX)
                        < team.max_players
            });
        if !distribution_allows_change
            || !has_available_team
            || !metadata.teams.iter().any(|team| team.id == team_id)
        {
            return;
        }
        let Some(local_client_id) = self
            .network
            .as_ref()
            .and_then(|network| i32::try_from(network.local_client_id()).ok())
        else {
            return;
        };
        let Some(mut request) = self
            .control_player_infos
            .client_update_request(local_client_id)
        else {
            return;
        };
        let mut changed = false;
        for player in &mut request.players {
            if player.player_type == clonk_engine::PLAYER_INFO_TYPE_USER && player.team != team_id {
                player.team = team_id;
                changed = true;
            }
        }
        if !changed {
            return;
        }
        let Some(network) = self.network.as_ref() else {
            return;
        };
        if let Err(error) = network.submit_player_info_update(request) {
            tracing::error!(%error, team_id, "failed to move local lobby players into team");
        }
    }

    fn classic_lobby_player_action_is_allowed(&self, client_id: i32, player_id: i32) -> bool {
        player_id != 0
            && self.network.is_some()
            && self.classic_lobby_player_is_owned(client_id)
            && self.visible_classic_lobby_controller().is_some_and(|controller| {
                controller.rows().iter().any(|row| {
                    matches!(row, LobbyRosterRow::Player(player)
                        if player.id == player_id && player.client_id == client_id)
                })
            })
    }

    fn clear_remembered_league_password(&mut self) {
        if let Some(auth) = self.league_auth_session.as_mut() {
            auth.password = LegacyCString::default();
        }
        if let Some(NetworkMode::Client(settings)) = self.network_mode.as_mut() {
            settings.league_auth.password = LegacyCString::default();
        }
    }

    fn take_over_classic_lobby_savegame_player(
        &mut self,
        savegame_player_id: i32,
        player_id: i32,
    ) {
        let target_is_free = self
            .visible_classic_lobby_player_context_target(savegame_player_id)
            .is_some_and(|(client_id, free_savegame_player)| {
                client_id == -1 && free_savegame_player
            });
        if !target_is_free || player_id == 0 {
            return;
        }
        let Some(local_client_id) = self
            .network
            .as_ref()
            .and_then(|network| i32::try_from(network.local_client_id()).ok())
        else {
            return;
        };
        let Some(mut request) = self
            .control_player_infos
            .client_update_request(local_client_id)
        else {
            return;
        };
        let Some(player) = request
            .players
            .iter_mut()
            .find(|player| player.id == player_id)
        else {
            return;
        };
        player.savegame_player = savegame_player_id;
        let Some(network) = self.network.as_ref() else {
            return;
        };
        if let Err(error) = network.submit_player_info_update(request) {
            tracing::error!(
                %error,
                savegame_player_id,
                player_id,
                "failed to submit lobby savegame-player takeover"
            );
        }
    }

    fn remove_classic_lobby_player(&mut self, client_id: i32, player_id: i32) {
        if !self.classic_lobby_player_action_is_allowed(client_id, player_id) {
            return;
        }
        let countdown_locked = self
            .visible_classic_lobby_controller()
            .is_some_and(|controller| controller.countdown().is_locked());
        if countdown_locked {
            if !matches!(self.network_mode, Some(NetworkMode::Host(_))) {
                return;
            }
            if !self.abort_network_lobby_countdown() {
                self.submit_and_apply_lobby_countdown(clonk_network::LobbyCountdownPacket::new(
                    clonk_network::LobbyCountdownPacket::ABORT,
                ));
            }
        }

        let Some(mut request) = self.control_player_infos.client_update_request(client_id) else {
            return;
        };
        let Some(index) = request
            .players
            .iter()
            .position(|player| player.id == player_id)
        else {
            return;
        };
        request.players.swap_remove(index);
        let Some(network) = self.network.as_ref() else {
            return;
        };
        if let Err(error) = network.submit_player_info_update(request) {
            tracing::error!(%error, client_id, player_id, "failed to remove lobby player");
        }
        if self.network_is_league {
            // C++ clears this immediately after the void update request so
            // account changes require fresh authentication on the next join.
            self.clear_remembered_league_password();
        }
    }

    fn reset_classic_lobby_player_color(&mut self, client_id: i32, player_id: i32) {
        if !self.classic_lobby_player_action_is_allowed(client_id, player_id) {
            return;
        }
        let Some(mut request) = self.control_player_infos.client_update_request(client_id) else {
            return;
        };
        let Some(player) = request
            .players
            .iter_mut()
            .find(|player| player.id == player_id)
        else {
            return;
        };
        player.color = player.original_color;
        let Some(network) = self.network.as_ref() else {
            return;
        };
        if let Err(error) = network.submit_player_info_update(request) {
            tracing::error!(%error, client_id, player_id, "failed to reset lobby player color");
        }
    }

    fn open_startup_player_context_menu(
        &mut self,
        keyboard_trigger: bool,
    ) -> Result<bool, EngineError> {
        if self.mode != AppMode::Menu
            || self.startup_view != StartupView::PlayerSelection
            || !self.message_dialogs.is_empty()
            || self.game_over_dialog.is_some()
            || self.startup_player_properties_dialog.is_some()
            || self.game_option_input_dialog.is_some()
            || self.definition_selector.is_some()
            || self.context_menu.is_some()
        {
            return Ok(false);
        }
        let Some((index, anchor, crew_mode)) =
            self.startup_player_dialog.as_ref().and_then(|dialog| {
                if keyboard_trigger {
                    let (index, anchor) = dialog.keyboard_context_target()?;
                    Some((index, anchor, dialog.is_crew_mode()))
                } else {
                    let point = dialog.pointer_position()?;
                    dialog
                        .context_index_at(point)
                        .map(|index| (index, point, dialog.is_crew_mode()))
                }
            })
        else {
            return Ok(false);
        };
        if let Some(rename_index) = self
            .startup_crew_rename
            .as_ref()
            .map(|rename| rename.index)
        {
            if keyboard_trigger {
                return Ok(false);
            }
            if !crew_mode || index != rename_index {
                self.abort_startup_crew_rename();
            }
        }
        self.guard_classic_global_gui_bootstrap()?;
        Self::guard_gui_overlay_result(
            "C4GUI context menu",
            self.assets.context_menu_resources().map(|_| ()),
        )?;
        if !keyboard_trigger
            && !self
                .startup_player_dialog
                .as_mut()
                .is_some_and(|dialog| dialog.select_for_context(index))
        {
            tracing::error!(index, "startup player context menu references a stale row");
            return Ok(false);
        }

        let entries = if crew_mode {
            clonk_frontend::startup_plrsel::PlrSelCrewContextMenu::for_crew(index)
                .entries
                .into_iter()
                .map(|entry| {
                    let icon = match entry.icon {
                        clonk_frontend::startup_plrsel::PlrSelCrewContextIcon::None => {
                            ContextMenuIcon::None
                        }
                    };
                    let mut item = ContextMenuEntry::new(entry.label)
                        .with_icon(icon)
                        .with_action(AppContextMenuCommand::StartupCrew(entry.command));
                    if let Some(tooltip) = entry.tooltip {
                        item = item.with_tooltip(tooltip);
                    }
                    if let Some(hotkey) = entry.hotkey {
                        item = item.with_hotkey(hotkey);
                    }
                    item
                })
                .collect()
        } else {
            clonk_frontend::startup_plrsel::PlrSelPlayerContextMenu::for_player(index)
                .entries
                .into_iter()
                .map(|entry| {
                    let icon = match entry.icon {
                        clonk_frontend::startup_plrsel::PlrSelPlayerContextIcon::None => {
                            ContextMenuIcon::None
                        }
                    };
                    let mut item = ContextMenuEntry::new(entry.label)
                        .with_icon(icon)
                        .with_action(AppContextMenuCommand::StartupPlayer(entry.command));
                    if let Some(tooltip) = entry.tooltip {
                        item = item.with_tooltip(tooltip);
                    }
                    if let Some(hotkey) = entry.hotkey {
                        item = item.with_hotkey(hotkey);
                    }
                    item
                })
                .collect()
        };
        let opened = self.open_context_menu_at(entries, anchor)?;
        if keyboard_trigger && opened {
            if let Some(menu) = self.context_menu.as_mut() {
                menu.note_non_pointer_input();
            }
        }
        Ok(opened)
    }

    fn open_startup_participants_context_menu(&mut self) -> Result<bool, EngineError> {
        if self.mode != AppMode::Menu
            || self.startup_view != StartupView::MainMenu
            || !self.message_dialogs.is_empty()
            || self.game_over_dialog.is_some()
        {
            return Ok(false);
        }
        let Some(anchor) = self
            .main_menu_state
            .pointer_position()
            .filter(|point| self.main_menu_state.participants_contains(*point))
        else {
            return Ok(false);
        };
        let Some(paths) = self.app_paths.clone() else {
            return Err(Self::gui_overlay_engine_error(
                "startup participants context menu",
                "application paths are unavailable",
            ));
        };
        let add_paths = paths.clone();
        let remove_paths = paths;
        let entries = vec![
            ContextMenuEntry::new("Add")
                .with_tooltip("Add participant")
                .with_lazy_submenu(move || startup_participant_add_entries(&add_paths)),
            ContextMenuEntry::new("Remove")
                .with_tooltip("Remove participant")
                .with_lazy_submenu(move || startup_participant_remove_entries(&remove_paths)),
        ];
        self.open_context_menu_at(entries, anchor)
    }

    fn open_scenario_search_context_menu(
        &mut self,
        keyboard_trigger: bool,
    ) -> Result<bool, EngineError> {
        if self.mode != AppMode::Menu
            || self.startup_view != StartupView::ScenarioBrowser
            || !self.message_dialogs.is_empty()
            || self.game_over_dialog.is_some()
            || self.context_menu.is_some()
        {
            return Ok(false);
        }
        let Some(fonts) = self.assets.clonk_fonts.as_deref() else {
            return Err(Self::gui_overlay_engine_error(
                "scenario-search context menu",
                "classic GUI fonts are unavailable",
            ));
        };
        let search = clonk_frontend::startup_scensel::scen_sel_layout(
            self.graphics.surface().width() as i32,
            self.graphics.surface().height() as i32,
            fonts,
        )
        .search_edit;
        let anchor = if keyboard_trigger {
            if !self.menu_state.search_focused() {
                return Ok(false);
            }
            GuiPoint::new(
                (search.x + search.w / 2) as f32,
                (search.y + search.h / 2) as f32,
            )
        } else {
            let Some(point) = self.menu_state.pointer_position().filter(|point| {
                point.x >= search.x as f32
                    && point.x < (search.x + search.w) as f32
                    && point.y >= search.y as f32
                    && point.y < (search.y + search.h) as f32
            }) else {
                return Ok(false);
            };
            point
        };
        let entries = scensel_search_context_entries(
            &self.menu_state.search_edit,
            clipboard_text_available(),
        );
        self.open_context_menu_at(entries, anchor)
    }

    fn process_context_menu_outcome(
        &mut self,
        outcome: ContextMenuOutcome<AppContextMenuCommand>,
    ) -> Result<(), EngineError> {
        if !outcome.events.is_empty() {
            self.mark_menu_dirty();
        }
        for event in outcome.events {
            match event {
                ContextMenuEvent::Sound(sound) => self.play_ui_sound(match sound {
                    ContextMenuSound::DoorOpen => "DoorOpen",
                    ContextMenuSound::DoorClose => "DoorClose",
                    ContextMenuSound::Command => "Command",
                    ContextMenuSound::Click => "Click",
                }),
                ContextMenuEvent::Closed => {
                    self.startup_tooltip.pointer_left();
                    self.note_classic_lobby_non_pointer_input();
                    self.context_menu = None;
                    self.set_context_menu_lobby_team_player(None);
                    self.set_context_menu_lobby_option(None);
                    self.context_menu_lobby_kick_client = None;
                    self.context_menu_lobby_player = None;
                }
                ContextMenuEvent::Activated(command) => match command {
                    AppContextMenuCommand::StartupPlayer(
                        PlrSelPlayerContextCommand::PlayerProperties(index),
                    ) => {
                        self.open_existing_startup_player_properties(index);
                    }
                    AppContextMenuCommand::StartupPlayer(
                        PlrSelPlayerContextCommand::DeletePlayer(index),
                    ) => {
                        // ContextMenu already emitted the activation Click.
                        self.open_startup_player_delete_dialog(index)?;
                    }
                    AppContextMenuCommand::StartupCrew(
                        PlrSelCrewContextCommand::RenameCrew(index),
                    ) => {
                        self.abort_startup_crew_rename();
                        self.start_startup_crew_rename(index)?;
                    }
                    AppContextMenuCommand::StartupCrew(
                        PlrSelCrewContextCommand::DeleteCrew(index),
                    ) => {
                        self.abort_startup_crew_rename();
                        self.open_startup_crew_delete_dialog(index)?;
                    }
                    AppContextMenuCommand::StartupCrew(
                        PlrSelCrewContextCommand::SetCrewDeathMessage(index),
                    ) => {
                        self.open_startup_crew_death_message_dialog(index)?;
                    }
                    AppContextMenuCommand::AddStartupParticipant(reference) => {
                        self.set_startup_participant(&reference, true);
                    }
                    AppContextMenuCommand::RemoveStartupParticipant(index) => {
                        self.remove_startup_participant(index);
                    }
                    AppContextMenuCommand::OptionsLanguage(code) => {
                        let selected = self
                            .startup_options_dialog
                            .as_mut()
                            .is_some_and(|dialog| dialog.select_language(&code));
                        if !selected {
                            tracing::error!(code, "language combo selected a stale entry");
                            continue;
                        }
                        match self.persist_open_options_config() {
                            Some(Ok(())) => {
                                match self.reload_application_language_resources() {
                                    Ok(charset) => {
                                        if let Some(paths) = self.app_paths.as_ref() {
                                            if let Err(error) = persist_config_value(
                                                paths,
                                                "General",
                                                "LanguageCharset",
                                                charset,
                                            ) {
                                                tracing::warn!(
                                                    error = %error,
                                                    "failed to save selected language charset"
                                                );
                                            }
                                        }
                                    }
                                    Err(error) => tracing::error!(
                                        error = %error,
                                        "failed to reload selected application language"
                                    ),
                                }
                                self.begin_startup_dialog_fade(StartupDialog::Options);
                                self.open_options_menu();
                            }
                            Some(Err(error)) => tracing::warn!(
                                error = %error,
                                "failed to save selected options language"
                            ),
                            None => {
                                let _ = self.reload_application_language_resources();
                                self.begin_startup_dialog_fade(StartupDialog::Options);
                                self.open_options_menu();
                            }
                        }
                    }
                    AppContextMenuCommand::OptionsFontFace(face) => {
                        self.apply_options_font_selection(Some(face), None)?;
                    }
                    AppContextMenuCommand::OptionsFontSize(size) => {
                        self.apply_options_font_selection(None, Some(size))?;
                    }
                    AppContextMenuCommand::OptionsDisplayMode(mode) => {
                        let changed = self
                            .startup_options_dialog
                            .as_mut()
                            .and_then(|dialog| dialog.graphics_mut().set_display_mode(mode))
                            .is_some();
                        if changed {
                            self.queue_options_display_request(OptionsDisplayRequest::SetMode(
                                mode,
                            ));
                        }
                    }
                    AppContextMenuCommand::LobbyTeam { player_id, team_id } => {
                        self.submit_classic_lobby_team_selection(player_id, team_id);
                    }
                    AppContextMenuCommand::LobbyControlRate(control_rate) => {
                        self.submit_classic_lobby_control_rate(control_rate);
                    }
                    AppContextMenuCommand::LobbyRuntimeJoin(allowed) => {
                        self.set_classic_lobby_runtime_join(allowed);
                    }
                    AppContextMenuCommand::RuntimeClientOption { option, value } => {
                        self.apply_runtime_client_list_option(option, value)?;
                    }
                    AppContextMenuCommand::LobbyTeamDistribution(distribution) => {
                        self.submit_classic_lobby_team_setting(
                            LobbyOptionKind::TeamDistribution,
                            distribution,
                        );
                    }
                    AppContextMenuCommand::LobbyTeamColors(enabled) => {
                        self.submit_classic_lobby_team_setting(
                            LobbyOptionKind::TeamColors,
                            i32::from(enabled),
                        );
                    }
                    AppContextMenuCommand::LobbyRandomTeamCount(count) => {
                        self.set_classic_lobby_random_team_count(count);
                    }
                    AppContextMenuCommand::LobbyPlayerTakeOver {
                        savegame_player_id,
                        player_id,
                    } => {
                        self.take_over_classic_lobby_savegame_player(
                            savegame_player_id,
                            player_id,
                        );
                    }
                    AppContextMenuCommand::LobbyPlayerTakeOverSubmenu { .. } => {
                        // The deferred parent entry carries no menu handler;
                        // this request only arrives via SubmenuRequested.
                    }
                    AppContextMenuCommand::LobbyPlayerRemove {
                        client_id,
                        player_id,
                    } => {
                        self.remove_classic_lobby_player(client_id, player_id);
                    }
                    AppContextMenuCommand::LobbyPlayerNewColor {
                        client_id,
                        player_id,
                    } => {
                        self.reset_classic_lobby_player_color(client_id, player_id);
                    }
                    AppContextMenuCommand::LobbyClientToggleMute(client_id) => {
                        self.toggle_classic_lobby_client_mute(client_id);
                    }
                    AppContextMenuCommand::LobbyClientToggleActivate(client_id) => {
                        self.toggle_classic_lobby_client_activation(client_id);
                    }
                    AppContextMenuCommand::LobbyClientInfo(client_id) => {
                        self.open_classic_lobby_client_info(client_id)?;
                    }
                    AppContextMenuCommand::LobbyKick(client_id) => {
                        self.kick_classic_lobby_client(client_id);
                    }
                    AppContextMenuCommand::LobbySheet(sheet) => {
                        if self.classic_host_lobby_active() {
                            if !self.select_classic_lobby_sheet(sheet) {
                                return Err(classic_game_lobby_child_error(
                                    ClassicGameLobbyChild::Sheet(sheet),
                                ));
                            }
                        } else {
                            self.process_lobby_action(LobbyAction::SelectSheet(sheet))?;
                        }
                    }
                    AppContextMenuCommand::NetworkJoinEdit(command) => {
                        self.apply_network_join_edit_context_command(command)?;
                    }
                    AppContextMenuCommand::LeagueSignupEdit { field, command } => {
                        self.apply_league_signup_edit_context_command(field, command)?;
                    }
                    AppContextMenuCommand::LobbyChat(command) => {
                        self.process_classic_lobby_chat_request(
                            LobbyChatRequest::ContextCommand(command),
                        )?;
                    }
                    AppContextMenuCommand::ScenarioSearch(command) => {
                        self.execute_scenario_search_context_command(command)?;
                    }
                    AppContextMenuCommand::StartupCrewRename(command) => {
                        self.execute_startup_crew_rename_context_command(command);
                    }
                    AppContextMenuCommand::InputDialog(command) => {
                        self.apply_input_dialog_context_command(command)?;
                    }
                },
                // C4GUI fills a submenu when it opens: CheckOpenSubmenu runs
                // the entry's OnSubcontext callback and opens the returned
                // menu in the same dispatch (src/C4GuiMenu.cpp:469-506).
                ContextMenuEvent::SubmenuRequested(command) => {
                    let entries = match command {
                        AppContextMenuCommand::LobbyPlayerTakeOverSubmenu {
                            savegame_player_id,
                        } => self.classic_lobby_takeover_entries(savegame_player_id),
                        other => {
                            tracing::error!(
                                ?other,
                                "context submenu request without a live provider"
                            );
                            Vec::new()
                        }
                    };
                    if let Some(outcome) = self
                        .context_menu
                        .as_mut()
                        .map(|menu| menu.fill_requested_submenu(entries))
                    {
                        self.process_context_menu_outcome(outcome)?;
                    }
                }
            }
        }
        Ok(())
    }

    fn set_startup_participant(&mut self, reference: &str, active: bool) {
        let Some(paths) = self.app_paths.as_ref() else {
            tracing::error!(
                reference,
                "cannot update participant without application paths"
            );
            self.status_text = "Unable to update participants".to_string();
            return;
        };
        let result = update_startup_participant_config(paths, |entries| {
            if active {
                if !entries
                    .iter()
                    .any(|entry| entry.eq_ignore_ascii_case(reference))
                {
                    entries.push(reference.to_string());
                }
            } else {
                entries.retain(|entry| !entry.eq_ignore_ascii_case(reference));
            }
        });
        self.finish_startup_participant_update(result, reference);
    }

    fn remove_startup_participant(&mut self, raw_index: usize) {
        let Some(paths) = self.app_paths.as_ref() else {
            tracing::error!(
                raw_index,
                "cannot remove participant without application paths"
            );
            self.status_text = "Unable to update participants".to_string();
            return;
        };
        match remove_startup_participant_config(paths, raw_index) {
            Ok(removed) => self.finish_startup_participant_update(
                Ok(()),
                removed.as_deref().unwrap_or("<stale participant>"),
            ),
            Err(error) => self.finish_startup_participant_update(
                Err(error),
                "<unreadable participant configuration>",
            ),
        }
    }

    fn finish_startup_participant_update(&mut self, result: io::Result<()>, reference: &str) {
        match result {
            Ok(()) => {
                self.sync_startup_participant_models();
                self.refresh_participants_label();
                self.status_text.clear();
                self.mark_menu_dirty();
            }
            Err(error) => {
                tracing::error!(reference, %error, "failed to update startup participants");
                self.status_text = format!("Unable to update participants: {error}");
            }
        }
    }

    fn apply_startup_game_search_event(
        &mut self,
        event: clonk_network::StartupGameSearchEvent,
    ) -> Result<(), EngineError> {
        if self.startup_network_refresh_waiting_for_clear {
            if !matches!(&event, clonk_network::StartupGameSearchEvent::Cleared) {
                return Ok(());
            }
            self.startup_network_refresh_waiting_for_clear = false;
        }
        match event {
            clonk_network::StartupGameSearchEvent::Cleared => {
                let selected_query = self.selected_startup_direct_reference_query_id();
                let selected_discovery_query =
                    self.selected_startup_discovery_reference_query_id();
                self.startup_game_references.clear();
                self.sync_startup_network_game_rows();
                self.reset_startup_masterserver_entry();
                let masterserver_enabled = self
                    .startup_network_dialog
                    .as_ref()
                    .is_some_and(|dialog| dialog.config().masterserver_signup);
                self.startup_masterserver_next_query_at = if masterserver_enabled {
                    Instant::now().checked_add(clonk_network::GAME_SEARCH_INTERVAL)
                } else {
                    None
                };
                if let Some(id) = selected_query {
                    self.focus_startup_direct_reference_query(id);
                } else if let Some(id) = selected_discovery_query {
                    self.focus_startup_discovery_reference_query(id);
                }
            }
            clonk_network::StartupGameSearchEvent::ReferencesUpdated(references) => {
                let selected_reference = self.selected_startup_game_reference();
                let selected_query = self.selected_startup_direct_reference_query_id();
                let selected_discovery_query =
                    self.selected_startup_discovery_reference_query_id();
                self.startup_game_references = references;
                self.sync_startup_network_game_rows();
                if let Some(reference) = selected_reference.as_ref() {
                    self.focus_startup_game_reference(reference);
                } else if let Some(id) = selected_query {
                    self.focus_startup_direct_reference_query(id);
                } else if let Some(id) = selected_discovery_query {
                    self.focus_startup_discovery_reference_query(id);
                }
            }
            clonk_network::StartupGameSearchEvent::GameDiscoveryQueryStarted { address } => {
                self.begin_startup_discovery_reference_query(address);
            }
            clonk_network::StartupGameSearchEvent::GameDiscoveryQueryResolved {
                address,
                references,
                selected_index,
            } => {
                self.finish_startup_discovery_reference_query(
                    address,
                    references,
                    selected_index.is_some(),
                );
            }
            clonk_network::StartupGameSearchEvent::GameDiscoveryQueryFailed {
                address,
                message,
            } => {
                self.fail_startup_discovery_reference_query(address, message);
            }
            clonk_network::StartupGameSearchEvent::DirectQueryResolved {
                request_id,
                references,
                selected_index,
            } => {
                self.finish_startup_direct_reference_query(
                    request_id,
                    references,
                    selected_index,
                );
            }
            clonk_network::StartupGameSearchEvent::DirectQueryFailed {
                request_id,
                message,
            } => {
                self.fail_startup_direct_reference_query(request_id, message);
            }
            clonk_network::StartupGameSearchEvent::MasterserverReply(reply) => {
                self.apply_startup_masterserver_reply(reply)?;
            }
            clonk_network::StartupGameSearchEvent::SearchError { source, message } => {
                tracing::warn!(?source, %message, "network game search failed");
                if source == Some(clonk_network::ReferenceQuerySource::GameDiscovery) {
                    self.show_startup_discovery_error(&message)?;
                } else if source == Some(clonk_network::ReferenceQuerySource::Masterserver) {
                    self.set_startup_masterserver_error(message);
                } else {
                    self.status_text = message;
                }
            }
        }
        self.mark_menu_dirty();
        Ok(())
    }

    fn startup_network_dialog_is_covered_by_message(&self) -> bool {
        self.startup_view == StartupView::NetworkGame
            && self.startup_network_dialog.is_some()
            && !self.message_dialogs.is_empty()
    }

    fn next_startup_game_search_event(&mut self) -> Option<clonk_network::StartupGameSearchEvent> {
        #[cfg(test)]
        if let Some(event) = self.startup_game_search_test_events.pop_front() {
            return Some(event);
        }
        self.startup_game_search
            .as_ref()
            .and_then(|search| search.events().try_recv().ok())
    }

    fn poll_startup_game_search(&mut self) -> Result<(), EngineError> {
        // C4StartupNetDlg::OnSec1Timer stops before both DiscoverClient.Execute
        // and UpdateList while a message dialog owns the active-dialog slot.
        // Leave worker events queued as well as presentation timers untouched
        // until the network dialog becomes active again.
        if self.startup_network_dialog_is_covered_by_message() {
            return Ok(());
        }
        // Advance presentation timers before applying completions from the
        // query that began at this interval, so an immediate failure/success
        // remains visible instead of being overwritten by Query state.
        self.tick_startup_network_query_rows_at(Instant::now());
        loop {
            // Applying one event may itself open a message (for example a
            // masterserver redirect). Do not pre-drain later events: native
            // leaves the remainder pending as soon as NetDlg loses activity.
            if self.startup_network_dialog_is_covered_by_message() {
                break;
            }
            let Some(event) = self.next_startup_game_search_event() else {
                break;
            };
            self.apply_startup_game_search_event(event)?;
        }
        Ok(())
    }

    fn sync_startup_participant_models(&mut self) {
        let active = self
            .app_paths
            .as_ref()
            .and_then(|paths| startup_participant_references(paths).ok())
            .unwrap_or_default();
        for (file, model) in self
            .startup_player_files
            .iter_mut()
            .zip(self.startup_player_models.iter_mut())
        {
            let enabled = active
                .iter()
                .any(|entry| entry.eq_ignore_ascii_case(&file.file_name));
            file.set_activated(enabled);
            model.activated = enabled;
        }
        self.selected_player_file = active.iter().find_map(|reference| {
            self.startup_player_files
                .iter()
                .find(|player| player.file_name.eq_ignore_ascii_case(reference))
                .map(|player| player.player_file.clone())
        });
        if let Some(dialog) = self.startup_player_dialog.as_mut() {
            dialog.set_player_activations(
                self.startup_player_models
                    .iter()
                    .map(|player| player.activated)
                    .collect(),
            );
        }
    }

    fn handle_context_menu_pointer_move(&mut self, point: GuiPoint) -> Result<bool, EngineError> {
        let Some(menu) = self.context_menu.as_mut() else {
            return Ok(false);
        };
        let outcome = menu.handle_pointer_move(point);
        let captured = outcome.captured && !outcome.pass_through;
        self.process_context_menu_outcome(outcome)?;
        Ok(captured)
    }

    fn consume_closed_context_pointer_release(
        &mut self,
        state: ElementState,
        button: ContextMenuPointerButton,
    ) -> bool {
        if state == ElementState::Released
            && self.context_menu.is_none()
            && self.context_menu_pointer_capture == Some(button)
        {
            self.context_menu_pointer_capture = None;
            return true;
        }
        false
    }

    fn handle_context_menu_pointer_button(
        &mut self,
        state: ElementState,
        button: ContextMenuPointerButton,
    ) -> Result<bool, EngineError> {
        let retained_release =
            state == ElementState::Released && self.context_menu_pointer_capture == Some(button);
        if retained_release {
            self.context_menu_pointer_capture = None;
        }
        let Some(menu) = self.context_menu.as_mut() else {
            return Ok(retained_release);
        };
        let point = menu.pointer_position();
        let outcome = match state {
            ElementState::Pressed => menu.handle_pointer_down(point, button),
            ElementState::Released => menu.handle_pointer_up(point, button),
        };
        let dismissed_combo = state == ElementState::Pressed
            && button == ContextMenuPointerButton::Left
            && outcome.pass_through
            && outcome
                .events
                .iter()
                .any(|event| matches!(event, ContextMenuEvent::Closed));
        let dismissed_lobby_team_player = dismissed_combo
            .then_some(self.context_menu_lobby_team_player)
            .flatten();
        let dismissed_lobby_option = dismissed_combo
            .then_some(self.context_menu_lobby_option)
            .flatten();
        let captured = outcome.captured && !outcome.pass_through;
        if state == ElementState::Pressed && captured {
            self.context_menu_pointer_capture = Some(button);
        }
        self.process_context_menu_outcome(outcome)?;
        if let Some(player_id) = dismissed_lobby_team_player {
            self.context_menu_pointer_dismissed_lobby_team_player = Some(player_id);
        }
        if let Some(option) = dismissed_lobby_option {
            self.context_menu_pointer_dismissed_lobby_option = Some(option);
        }
        Ok(captured || retained_release)
    }

    fn handle_context_menu_key(
        &mut self,
        key: VirtualKeyCode,
        state: ElementState,
    ) -> Result<bool, EngineError> {
        if self.context_menu.is_none() {
            return Ok(false);
        }
        if state == ElementState::Released {
            return Ok(false);
        }
        let outcome = {
            let menu = self.context_menu.as_mut().expect("checked above");
            menu.note_non_pointer_input();
            if let Some(key) = context_menu_key_code(key) {
                menu.handle_key(key)
            } else if let Some(hotkey) = context_menu_hotkey(key) {
                menu.handle_hotkey(hotkey)
            } else {
                return Ok(false);
            }
        };
        let captured = outcome.captured && !outcome.pass_through;
        if captured {
            if self.running_chat_controller().is_some() {
                self.game_option_input_consumed_keys.insert(key);
            } else {
                self.message_dialog_consumed_keys.insert(key);
            }
        }
        self.process_context_menu_outcome(outcome)?;
        Ok(captured)
    }

    fn handle_context_menu_gamepad_event(
        &mut self,
        event: GamepadEvent,
    ) -> Result<bool, EngineError> {
        let outcome = self.context_menu.as_mut().and_then(|menu| {
            menu.note_non_pointer_input();
            match event {
                GamepadEvent::Direction {
                    button,
                    state: ElementState::Pressed,
                    ..
                } => Some(menu.handle_gamepad_direction(match button {
                    ControlButton::Up => ContextMenuDirection::Up,
                    ControlButton::Down => ContextMenuDirection::Down,
                    ControlButton::Left => ContextMenuDirection::Left,
                    ControlButton::Right => ContextMenuDirection::Right,
                })),
                GamepadEvent::GuiButton {
                    class: GuiButtonClass::Low,
                    state: ElementState::Pressed,
                    ..
                } => Some(menu.handle_gamepad_low()),
                GamepadEvent::GuiButton {
                    class: GuiButtonClass::High,
                    state: ElementState::Pressed,
                    ..
                } => Some(menu.handle_gamepad_high()),
                GamepadEvent::Clear { .. } => Some(menu.dismiss(false)),
                GamepadEvent::Axis { .. }
                | GamepadEvent::Direction { .. }
                | GamepadEvent::Button { .. }
                | GamepadEvent::Action { .. }
                | GamepadEvent::GuiButton { .. } => None,
            }
        });
        if let Some(outcome) = outcome {
            let captured = outcome.captured && !outcome.pass_through;
            self.process_context_menu_outcome(outcome)?;
            return Ok(captured);
        }
        Ok(false)
    }

    fn close_context_menu_silently(&mut self) {
        let Some(mut menu) = self.context_menu.take() else {
            self.set_context_menu_lobby_team_player(None);
            self.set_context_menu_lobby_option(None);
            self.context_menu_lobby_kick_client = None;
            self.context_menu_lobby_player = None;
            self.context_menu_pointer_dismissed_lobby_team_player = None;
            self.context_menu_pointer_dismissed_lobby_option = None;
            return;
        };
        let _ = menu.dismiss(false);
        self.startup_tooltip.pointer_left();
        self.note_classic_lobby_non_pointer_input();
        self.set_context_menu_lobby_team_player(None);
        self.set_context_menu_lobby_option(None);
        self.context_menu_lobby_kick_client = None;
        self.context_menu_lobby_player = None;
        self.context_menu_pointer_dismissed_lobby_team_player = None;
        self.context_menu_pointer_dismissed_lobby_option = None;
        self.context_menu_pointer_capture = None;
        self.mark_menu_dirty();
    }

    fn new_startup_player_properties_controller(
        &self,
        color_index: usize,
        portrait_index: usize,
    ) -> clonk_frontend::startup_plrproperties::PlayerPropertiesController {
        use clonk_frontend::startup_plrproperties::{PLAYER_COLORS, PlayerPropertiesController};

        let color_index = color_index % 8;
        let mut player = PlayerFile::default();
        player.pref_color = color_index as i32;
        player.pref_color_dw = PLAYER_COLORS[color_index];
        player.pref_control = 0;
        player.pref_control_style = true;
        player.pref_auto_context_menu = true;
        let comment = load_runtime_language_table(self.app_paths.as_ref())
            .ok()
            .and_then(|table| table.entries.get("IDS_PLR_NEWCOMMENT").cloned())
            .unwrap_or_else(|| "I'm new.".to_string());
        let portrait = self
            .assets
            .dialog_image(&format!("Portrait{}.png", portrait_index % 5 + 1))
            .or_else(|| {
                (1..=5).find_map(|index| {
                    self.assets
                        .dialog_image(&format!("Portrait{index}.png"))
                })
            });
        let big_icon = portrait
            .as_ref()
            .and_then(|portrait| startup_player_big_icon(portrait, player.pref_color_dw));
        let mut controller = PlayerPropertiesController::new_player(
            player,
            comment,
            portrait.and_then(|portrait| materialize_startup_player_image(&portrait, 150)),
            big_icon,
        );
        controller.resize(
            self.graphics.surface().width() as i32,
            self.graphics.surface().height() as i32,
        );
        controller
    }

    fn open_new_startup_player_properties(&mut self) {
        self.open_new_startup_player_properties_from(StartupPlayerPropertiesOrigin::SelectionNew);
    }

    fn open_new_startup_player_properties_from(
        &mut self,
        origin: StartupPlayerPropertiesOrigin,
    ) {
        self.close_context_menu_silently();
        self.startup_tooltip.pointer_left();
        let controller = self.new_startup_player_properties_controller(
            classic_safe_random(8),
            classic_safe_random(5),
        );
        self.startup_player_properties_dialog = Some(PendingStartupPlayerProperties {
            origin,
            controller,
        });
        self.status_text.clear();
        self.mark_menu_dirty();
    }

    fn open_existing_startup_player_properties(&mut self, index: usize) {
        let Some((path, was_activated, player, comment, portrait, big_icon)) = self
            .startup_player_files
            .get(index)
            .map(|entry| {
                (
                    entry.path.clone(),
                    entry.render_model.activated,
                    entry.player_file.clone(),
                    entry.render_model.comment.clone(),
                    entry.render_model.portrait.clone(),
                    entry.render_model.big_icon.clone(),
                )
            })
        else {
            tracing::error!(index, "player-properties action references a stale row");
            return;
        };
        self.close_context_menu_silently();
        self.startup_tooltip.pointer_left();
        let mut controller =
            clonk_frontend::startup_plrproperties::PlayerPropertiesController::edit_player(
                index, player, comment, portrait, big_icon,
            );
        controller.resize(
            self.graphics.surface().width() as i32,
            self.graphics.surface().height() as i32,
        );
        self.startup_player_properties_dialog = Some(PendingStartupPlayerProperties {
            origin: StartupPlayerPropertiesOrigin::SelectionEdit {
                path,
                was_activated,
            },
            controller,
        });
        self.status_text.clear();
        self.mark_menu_dirty();
    }

    fn process_startup_player_properties_actions(
        &mut self,
        actions: Vec<clonk_frontend::startup_plrproperties::PlayerPropertiesAction>,
    ) {
        use clonk_frontend::startup_plrproperties::PlayerPropertiesAction;

        for action in actions {
            match action {
                PlayerPropertiesAction::Cancel => {
                    self.startup_tooltip.pointer_left();
                    self.startup_player_properties_dialog = None;
                    self.status_text.clear();
                    self.mark_menu_dirty();
                }
                PlayerPropertiesAction::ChoosePicture => {
                    self.open_startup_player_portrait_selector();
                }
                PlayerPropertiesAction::PortraitLocationChanged { index, path } => {
                    if let Some(paths) = self.app_paths.as_ref() {
                        if let Err(error) = persist_startup_portrait_location(paths, index) {
                            tracing::warn!(%error, "failed to persist portrait location");
                        }
                    }
                    self.reload_startup_player_portrait_location(index, &path);
                }
                PlayerPropertiesAction::ApplyPicture(commit) => {
                    self.apply_startup_player_portrait_selection(commit);
                }
                PlayerPropertiesAction::Submit => self.save_open_startup_player_properties(),
            }
        }
    }

    fn open_startup_player_portrait_selector(&mut self) {
        let Some(paths) = self.app_paths.as_ref() else {
            if let Some(pending) = self.startup_player_properties_dialog.as_mut() {
                pending.controller.set_validation_error(Some(
                    "Application paths are unavailable".to_string(),
                ));
            }
            return;
        };
        extract_default_startup_portraits_once(paths);
        let user_path = paths.user_data_dir().to_path_buf();
        let program_path = paths.install_root().to_path_buf();
        let mut locations = vec![clonk_frontend::startup_portraitsel::PortraitLocation::new(
            "LegacyClonk User Path",
            user_path.clone(),
        )];
        if program_path != user_path {
            locations.push(clonk_frontend::startup_portraitsel::PortraitLocation::new(
                "LegacyClonk Program Directory",
                program_path,
            ));
        }
        let current_location = load_startup_last_portrait_folder_index(Some(paths))
            .filter(|index| *index < locations.len())
            .unwrap_or(0);
        let current_path = locations[current_location].path.clone();
        let entries =
            clonk_frontend::startup_portraitsel::portrait_files_in_location(&current_path);
        let (entries, scan_error) = match entries {
            Ok(entries) => (entries, None),
            Err(error) => (
                Vec::new(),
                Some(format!("failed to scan {}: {error}", current_path.display())),
            ),
        };
        if let Some(pending) = self.startup_player_properties_dialog.as_mut() {
            pending
                .controller
                .open_portrait_selector(locations, current_location, entries);
            pending.controller.clear_validation_error();
            if let Some(error) = scan_error {
                pending.controller.set_portrait_selector_error(error);
            }
        }
        self.startup_tooltip.pointer_left();
        self.mark_menu_dirty();
    }

    fn reload_startup_player_portrait_location(&mut self, index: usize, path: &Path) {
        match clonk_frontend::startup_portraitsel::portrait_files_in_location(path) {
            Ok(entries) => {
                if let Some(pending) = self.startup_player_properties_dialog.as_mut() {
                    pending
                        .controller
                        .replace_portrait_location_entries(index, entries);
                }
            }
            Err(error) => {
                if let Some(pending) = self.startup_player_properties_dialog.as_mut() {
                    pending.controller.fail_portrait_location_entries(
                        index,
                        format!("failed to scan {}: {error}", path.display()),
                    );
                }
            }
        }
        self.mark_menu_dirty();
    }

    fn apply_startup_player_portrait_selection(
        &mut self,
        commit: clonk_frontend::startup_portraitsel::PortraitSelCommit,
    ) {
        use clonk_frontend::startup_portraitsel::PortraitChoice;

        let color = self
            .startup_player_properties_dialog
            .as_ref()
            .map(|pending| pending.controller.player().pref_color_dw)
            .unwrap_or_default();
        let (portrait, big_icon) = match commit.choice {
            PortraitChoice::None => (None, None),
            PortraitChoice::File(path) => {
                if !commit.set_picture && !commit.set_big_icon {
                    (None, None)
                } else {
                    let image = match load_startup_portrait_image(&path) {
                        Ok(image) => image,
                        Err(error) => {
                            if let Some(pending) =
                                self.startup_player_properties_dialog.as_mut()
                            {
                                pending.controller.set_portrait_selector_error(error);
                            }
                            self.mark_menu_dirty();
                            return;
                        }
                    };
                    let portrait = commit
                        .set_picture
                        .then(|| materialize_startup_player_image(&image, 150))
                        .flatten();
                    let big_icon = commit
                        .set_big_icon
                        .then(|| startup_player_big_icon(&image, color))
                        .flatten();
                    (portrait, big_icon)
                }
            }
        };
        if let Some(pending) = self.startup_player_properties_dialog.as_mut() {
            pending.controller.apply_picture_selection(
                portrait,
                big_icon,
                commit.set_picture,
                commit.set_big_icon,
            );
            pending.controller.close_portrait_selector();
            pending.controller.clear_validation_error();
        }
        self.mark_menu_dirty();
    }

    fn advance_startup_player_portrait_thumbnail(&mut self) {
        let request = self
            .startup_player_properties_dialog
            .as_mut()
            .and_then(|pending| pending.controller.advance_portrait_selector_idle());
        let Some(request) = request else {
            return;
        };
        let thumbnail = load_startup_portrait_image(&request.path)
            .map(|image| resize_startup_player_image(&image, 100));
        if let Some(pending) = self.startup_player_properties_dialog.as_mut() {
            pending
                .controller
                .complete_portrait_thumbnail(&request, thumbnail);
        }
    }

    fn save_open_startup_player_properties(&mut self) {
        let Some((origin, player, comment, portrait, big_icon)) = self
            .startup_player_properties_dialog
            .as_ref()
            .map(|pending| {
                (
                    pending.origin.clone(),
                    pending.controller.player().clone(),
                    pending.controller.comment().to_string(),
                    startup_player_image_write(pending.controller.portrait_update()),
                    startup_player_image_write(pending.controller.big_icon_update()),
                )
            })
        else {
            return;
        };
        let existing_path = match &origin {
            StartupPlayerPropertiesOrigin::MainMenuFirstPlayer
            | StartupPlayerPropertiesOrigin::SelectionNew => None,
            StartupPlayerPropertiesOrigin::SelectionEdit { path, .. } => Some(path.as_path()),
        };
        let Some(paths) = self.app_paths.as_ref() else {
            let error = "application paths are unavailable".to_string();
            tracing::error!(%error, "failed to save startup player properties");
            self.finish_startup_player_properties_save_failure(
                error,
                &origin,
                &player.name,
            );
            return;
        };
        let result = save_player_properties(
            paths,
            existing_path,
            &player,
            &comment,
            &portrait,
            &big_icon,
            self.process_group_maker.as_bytes(),
        );
        match result {
            Ok(saved) => self.finish_startup_player_properties_save(saved, origin),
            Err(error @ (PlayerPropertiesSaveError::EmptyName
            | PlayerPropertiesSaveError::NameTaken { .. })) => {
                tracing::error!(%error, "startup player name validation failed");
                let message = match &error {
                    PlayerPropertiesSaveError::EmptyName => self.runtime_resource_text(
                        "IDS_ERR_PLRNAME_EMPTY",
                        "You must specify a player name!",
                    ),
                    PlayerPropertiesSaveError::NameTaken { name, .. } => format_resource_string(
                        self.runtime_resource_text(
                            "IDS_ERR_PLRNAME_TAKEN",
                            "%s is already taken",
                        ),
                        &[name],
                    ),
                    _ => unreachable!("guarded player-name validation error"),
                };
                if let Some(pending) = self.startup_player_properties_dialog.as_mut() {
                    pending.controller.clear_validation_error();
                }
                self.status_text.clear();
                if let Err(dialog_error) = self.push_message_dialog(
                    clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                        message.clone(),
                        "",
                        clonk_frontend::message_dialog::MessageDialogIcon::ERROR,
                    ),
                    MessageDialogContinuation::None,
                ) {
                    tracing::error!(%dialog_error, "failed to show player-name validation dialog");
                    self.record_startup_player_properties_save_failure(message);
                }
            }
            Err(error) => {
                tracing::error!(%error, "failed to save startup player properties");
                let message = self.startup_player_properties_save_failure_text(&error);
                self.finish_startup_player_properties_save_failure(
                    message,
                    &origin,
                    &player.name,
                );
            }
        }
    }

    /// Composes the classic modal body for a post-validation save failure.
    /// Each storage step keeps C++'s own string for that branch
    /// (`C4StartupPlrPropertiesDlg::OnClosed`: `IDS_FAIL_RENAME`,
    /// `IDS_FAIL_MODIFY`, and the `ShowErrorMessage`d group step errors) and
    /// names the affected path like the startup rename neighbors do with
    /// `IDS_ERR_RENAMEFILE`/`IDS_ERR_OPENFILE`.
    fn startup_player_properties_save_failure_text(
        &self,
        error: &PlayerPropertiesSaveError,
    ) -> String {
        match error {
            PlayerPropertiesSaveError::Rename { from, to, detail } => {
                let step = self.runtime_resource_text("IDS_FAIL_RENAME", "Rename failure.");
                let body = format_resource_string_with_opaque_arguments(
                    self.runtime_resource_text(
                        "IDS_ERR_RENAMEFILE",
                        "Error renaming file \"%s\" to \"%s\".",
                    ),
                    &[&from.display().to_string(), &to.display().to_string()],
                );
                format!("{step}\n{body}\n{detail}")
            }
            PlayerPropertiesSaveError::Open { path, detail } => {
                format_resource_string_with_opaque_arguments(
                    self.runtime_resource_text(
                        "IDS_ERR_OPENFILE",
                        "Error opening file \"%s\": %s",
                    ),
                    &[&path.display().to_string(), detail],
                )
            }
            PlayerPropertiesSaveError::WriteCore {
                path,
                entry,
                detail,
            } => {
                let step =
                    self.runtime_resource_text("IDS_FAIL_MODIFY", "File modification failure.");
                format!("{step}\n\"{}/{entry}\": {detail}", path.display())
            }
            PlayerPropertiesSaveError::WriteImage {
                path,
                entry,
                detail,
            } => format_resource_string_with_opaque_arguments(
                self.runtime_resource_text("IDS_PRC_NOGFXFILE", "Error at graphics file %s: %s"),
                &[&format!("{}/{entry}", path.display()), detail],
            ),
            // C++ surfaces a failed group flush as the raw "Close:"-step
            // C4Group error; carry the affected path with it.
            PlayerPropertiesSaveError::Close { path, detail } => {
                format!("Close: \"{}\": {detail}", path.display())
            }
            PlayerPropertiesSaveError::EmptyName | PlayerPropertiesSaveError::NameTaken { .. } => {
                error.to_string()
            }
        }
    }

    fn finish_startup_player_properties_save_failure(
        &mut self,
        error: String,
        origin: &StartupPlayerPropertiesOrigin,
        submitted_name: &str,
    ) {
        // C4GUI removes C4StartupPlrPropertiesDlg before OnClosed performs
        // persistence. The error dialog therefore belongs to the screen and
        // never leaves the properties form alive underneath it.
        self.startup_tooltip.pointer_left();
        self.startup_player_properties_dialog = None;
        self.reconcile_startup_player_list_after_properties_failure(origin, submitted_name);
        self.status_text.clear();

        let caption = self.runtime_resource_text("IDS_DLG_ERROR", "Error");
        if let Err(dialog_error) = self.push_message_dialog(
            clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                error.clone(),
                caption,
                clonk_frontend::message_dialog::MessageDialogIcon::ERROR,
            ),
            MessageDialogContinuation::None,
        ) {
            tracing::error!(%dialog_error, "failed to show player-properties save error dialog");
            self.record_startup_player_properties_save_failure(error);
        }
    }

    fn reconcile_startup_player_list_after_properties_failure(
        &mut self,
        origin: &StartupPlayerPropertiesOrigin,
        submitted_name: &str,
    ) {
        let previous_players = self
            .startup_player_files
            .iter()
            .map(|player| {
                (
                    player.path.clone(),
                    player.file_name.clone(),
                    player.render_model.activated,
                )
            })
            .collect::<Vec<_>>();
        let previous_selected = self
            .startup_player_dialog
            .as_ref()
            .and_then(|dialog| dialog.selected_index())
            .and_then(|index| self.startup_player_files.get(index))
            .map(|player| (player.path.clone(), player.file_name.clone()));
        let submitted_filename = player_group_filename(submitted_name).ok();
        let edit_paths = match (origin, submitted_filename.as_deref()) {
            (
                StartupPlayerPropertiesOrigin::SelectionEdit { path, .. },
                Some(filename),
            ) => Some((path.clone(), path.with_file_name(filename))),
            _ => None,
        };

        let Some(paths) = self.app_paths.as_ref() else {
            self.mark_menu_dirty();
            return;
        };
        let config_file = paths.config_file().to_path_buf();
        let mut players = match discover_player_files(paths) {
            Ok(players) => players,
            Err(error) => {
                tracing::error!(%error, "failed to reconcile startup players after properties save failure");
                self.mark_menu_dirty();
                return;
            }
        };

        let submitted_index = match (&edit_paths, submitted_filename.as_deref()) {
            (Some((old_path, target_path)), _) => players
                .iter()
                .position(|player| player.path == *old_path)
                .or_else(|| players.iter().position(|player| player.path == *target_path)),
            (None, Some(filename)) => players.iter().position(|player| {
                player
                    .path
                    .file_name()
                    .is_some_and(|name| name.to_string_lossy().eq_ignore_ascii_case(filename))
            }),
            (None, None) => None,
        };

        for (index, player) in players.iter_mut().enumerate() {
            // A file first seen by this reconciliation keeps its discover-time
            // activation, which C4StartupPlrSelDlg::UpdatePlayerList reads
            // from Config.General.Participants.
            let previous_activation = previous_players
                .iter()
                .find(|(path, file_name, _)| {
                    player.path == *path || player.file_name.eq_ignore_ascii_case(file_name)
                })
                .map(|(_, _, activated)| *activated)
                .unwrap_or(player.render_model.activated);
            let activated = if Some(index) == submitted_index {
                match origin {
                    StartupPlayerPropertiesOrigin::MainMenuFirstPlayer
                    | StartupPlayerPropertiesOrigin::SelectionNew => true,
                    StartupPlayerPropertiesOrigin::SelectionEdit { was_activated, .. } => {
                        *was_activated
                    }
                }
            } else {
                previous_activation
            };
            player.set_activated(activated);
        }

        let activation_refusals = match persist_activations(&config_file, &mut players) {
            Ok(refusals) => refusals,
            Err(error) => {
                tracing::warn!(%error, "failed to reconcile participants after properties save failure");
                Vec::new()
            }
        };
        // A failed edit leaves C++'s untouched list widget selected where it
        // was (following the item across a completed rename), while a failed
        // NewPlayer save rebuilds the list and reselects like
        // UpdatePlayerList: the saved file, else the first activated entry,
        // else the first entry.
        let previous_selected_index = previous_selected.as_ref().and_then(|(path, file_name)| {
            players.iter().position(|player| {
                player.path == *path || player.file_name.eq_ignore_ascii_case(file_name)
            })
        });
        let selected_index = match origin {
            StartupPlayerPropertiesOrigin::SelectionEdit { .. } => {
                previous_selected_index.or(submitted_index)
            }
            StartupPlayerPropertiesOrigin::MainMenuFirstPlayer
            | StartupPlayerPropertiesOrigin::SelectionNew => submitted_index,
        }
        .or_else(|| {
            players
                .iter()
                .position(|player| player.render_model.activated)
        })
        .or_else(|| (!players.is_empty()).then_some(0));
        self.startup_player_models = players
            .iter()
            .map(|player| player.render_model.clone())
            .collect();
        self.startup_player_files = players;
        self.selected_player_file = selected_index
            .and_then(|index| self.startup_player_files.get(index))
            .filter(|player| player.render_model.activated)
            .or_else(|| {
                self.startup_player_files
                    .iter()
                    .find(|player| player.render_model.activated)
            })
            .map(|player| player.player_file.clone());
        if let Some(dialog) = self.startup_player_dialog.as_mut() {
            dialog.set_player_count(self.startup_player_models.len());
            dialog.set_player_activations(
                self.startup_player_models
                    .iter()
                    .map(|player| player.activated)
                    .collect(),
            );
            dialog.set_selected_index(selected_index);
        }
        self.plrsel_last_click = None;
        self.menu_frame_cache = None;
        self.refresh_participants_label();
        if let Err(error) = self.show_startup_player_activation_refusals(&activation_refusals) {
            tracing::error!(%error, "failed to show participant overflow after properties save failure");
        }
        self.mark_menu_dirty();
    }

    fn record_startup_player_properties_save_failure(&mut self, error: String) {
        if let Some(pending) = self.startup_player_properties_dialog.as_mut() {
            pending.controller.set_validation_error(Some(error.clone()));
        }
        self.status_text = error;
        self.mark_menu_dirty();
    }

    fn finish_startup_player_properties_save(
        &mut self,
        saved: SavedStartupPlayer,
        origin: StartupPlayerPropertiesOrigin,
    ) {
        let previous_activations = self
            .startup_player_files
            .iter()
            .map(|player| (player.file_name.clone(), player.render_model.activated))
            .collect::<Vec<_>>();
        let Some(paths) = self.app_paths.as_ref() else {
            self.startup_tooltip.pointer_left();
            self.startup_player_properties_dialog = None;
            self.status_text = "Player saved, but application paths are unavailable".to_string();
            self.mark_menu_dirty();
            return;
        };
        let forced_participant_persistence = matches!(
            &origin,
            StartupPlayerPropertiesOrigin::MainMenuFirstPlayer
        )
        .then(|| {
            persist_config_value(
                paths,
                "General",
                "Participants",
                saved.file_name.clone(),
            )
        });
        let mut players = match discover_player_files(paths) {
            Ok(players) => players,
            Err(error) => {
                tracing::error!(%error, "failed to refresh startup players after save");
                self.startup_tooltip.pointer_left();
                self.startup_player_properties_dialog = None;
                self.refresh_participants_label();
                if let Some(persistence_error) =
                    forced_participant_persistence.and_then(Result::err)
                {
                    tracing::error!(%persistence_error, "failed to select the first saved player");
                    self.status_text = format!(
                        "Player saved, but participant selection failed: {persistence_error}"
                    );
                } else {
                    self.status_text =
                        format!("Player saved, but the list could not be refreshed: {error}");
                }
                self.mark_menu_dirty();
                return;
            }
        };
        let is_saved = |player: &StartupPlayerFile| {
            player.path == saved.path
                || player.file_name.eq_ignore_ascii_case(&saved.file_name)
        };
        let saved_index = players.iter().position(|player| is_saved(player));
        for player in &mut players {
            let was_activated = previous_activations
                .iter()
                .find(|(reference, _)| reference.eq_ignore_ascii_case(&player.file_name))
                .is_some_and(|(_, activated)| *activated);
            let activated = match &origin {
                StartupPlayerPropertiesOrigin::MainMenuFirstPlayer => is_saved(player),
                StartupPlayerPropertiesOrigin::SelectionNew => is_saved(player) || was_activated,
                StartupPlayerPropertiesOrigin::SelectionEdit {
                    was_activated: saved_was_activated,
                    ..
                } => {
                    if is_saved(player) {
                        *saved_was_activated
                    } else {
                        was_activated
                    }
                }
            };
            player.set_activated(activated);
        }
        let persistence = match forced_participant_persistence {
            Some(result) => result.map(|()| Vec::new()),
            None => persist_activations(&paths.config_file(), &mut players),
        };
        let (persistence_error, activation_refusals) = match persistence {
            Ok(refusals) => (None, refusals),
            Err(error) => (Some(error), Vec::new()),
        };
        self.startup_player_models = players
            .iter()
            .map(|player| player.render_model.clone())
            .collect();
        self.startup_player_files = players;
        self.selected_player_file = saved_index
            .and_then(|index| self.startup_player_files.get(index))
            .filter(|player| player.render_model.activated)
            .or_else(|| {
                self.startup_player_files
                    .iter()
                    .find(|player| player.render_model.activated)
            })
            .map(|player| player.player_file.clone());
        if let Some(dialog) = self.startup_player_dialog.as_mut() {
            dialog.set_player_count(self.startup_player_models.len());
            dialog.set_player_activations(
                self.startup_player_models
                    .iter()
                    .map(|player| player.activated)
                    .collect(),
            );
            dialog.set_selected_index(saved_index);
        }
        self.startup_tooltip.pointer_left();
        self.startup_player_properties_dialog = None;
        self.refresh_participants_label();
        if let Some(error) = persistence_error {
            tracing::error!(%error, "failed to refresh participants after player save");
            self.status_text = format!("Player saved, but participant selection failed: {error}");
        } else {
            self.status_text.clear();
        }
        if let Err(error) =
            self.show_startup_player_activation_refusals(&activation_refusals)
        {
            tracing::error!(%error, "failed to show participant overflow after player save");
        }
        self.mark_menu_dirty();
    }

    fn show_startup_player_activation_refusals(
        &mut self,
        refusals: &[PlayerActivationRefusal],
    ) -> Result<(), EngineError> {
        if refusals.is_empty() {
            return Ok(());
        }
        let template = self.runtime_resource_text(
            "IDS_ERR_PLAYERSTOOLONG",
            "Player \"%s\" has been deactivated: Too many activated players or path too long!",
        );
        let caption = self.runtime_resource_text("IDS_ERR_TITLE", "Error");
        for refusal in refusals {
            self.push_message_dialog(
                clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                    format_resource_string(template.clone(), &[&refusal.player_name]),
                    caption.clone(),
                    clonk_frontend::message_dialog::MessageDialogIcon::ERROR,
                ),
                MessageDialogContinuation::None,
            )?;
        }
        Ok(())
    }

    fn process_player_dialog_actions(
        &mut self,
        actions: Vec<clonk_frontend::startup_plrsel::PlrSelAction>,
    ) -> Result<(), EngineError> {
        use clonk_frontend::startup_plrsel::{PlrSelAction, PlrSelSound};

        let sounds = self
            .startup_player_dialog
            .as_mut()
            .map(|dialog| dialog.take_sound_events())
            .unwrap_or_default();
        for sound in sounds {
            self.play_ui_sound(match sound {
                PlrSelSound::Command => "Command",
                PlrSelSound::ArrowHit => "ArrowHit",
                PlrSelSound::Click => "Click",
            });
        }

        for action in actions {
            match action {
                PlrSelAction::SelectionChanged(_) => {
                    self.abort_startup_crew_rename();
                }
                PlrSelAction::FocusChanged(_) => {}
                PlrSelAction::Back => {
                    self.begin_startup_dialog_fade(StartupDialog::MainMenu);
                    self.show_main_menu();
                }
                PlrSelAction::NewPlayer => {
                    self.open_new_startup_player_properties();
                }
                PlrSelAction::ActivationChanged { index, activated } => {
                    let selected_before = self
                        .startup_player_dialog
                        .as_ref()
                        .and_then(|dialog| dialog.selected_index());
                    let old_activated = self
                        .startup_player_models
                        .get(index)
                        .map(|player| player.activated);
                    if let Some(player) = self.startup_player_files.get_mut(index) {
                        player.set_activated(activated);
                    }
                    if let Some(player) = self.startup_player_models.get_mut(index) {
                        player.activated = activated;
                    }
                    let persisted = self
                        .app_paths
                        .as_ref()
                        .ok_or_else(|| "application paths are unavailable".to_string())
                        .and_then(|paths| {
                            persist_activations(
                                &paths.config_file(),
                                &mut self.startup_player_files,
                            )
                            .map_err(|error| error.to_string())
                    });
                    match persisted {
                        Ok(refusals) => {
                            for refusal in &refusals {
                                if let Some(player) =
                                    self.startup_player_models.get_mut(refusal.index)
                                {
                                    player.activated = false;
                                }
                                if let Some(dialog) = self.startup_player_dialog.as_mut() {
                                    dialog.set_player_activation(refusal.index, false);
                                }
                            }
                            self.selected_player_file = self
                                .startup_player_files
                                .iter()
                                .find(|player| player.render_model.activated)
                                .map(|player| player.player_file.clone());
                            self.refresh_participants_label();
                            self.status_text.clear();
                            self.show_startup_player_activation_refusals(&refusals)?;
                        }
                        Err(error) => {
                            if let Some(old_activated) = old_activated {
                                if let Some(player) = self.startup_player_files.get_mut(index) {
                                    player.set_activated(old_activated);
                                }
                                if let Some(player) = self.startup_player_models.get_mut(index) {
                                    player.activated = old_activated;
                                }
                                if let Some(dialog) = self.startup_player_dialog.as_mut() {
                                    dialog.set_player_activations(
                                        self.startup_player_models
                                            .iter()
                                            .map(|player| player.activated)
                                            .collect(),
                                    );
                                    dialog.set_selected_index(selected_before);
                                }
                            }
                            self.status_text = format!("Unable to save player selection: {error}");
                        }
                    }
                }
                PlrSelAction::DeletePlayer(index) => {
                    self.open_startup_player_delete_dialog(index)?;
                }
                PlrSelAction::PlayerProperties(index) => {
                    self.open_existing_startup_player_properties(index);
                }
                PlrSelAction::ShowCrew(index) => {
                    self.enter_startup_crew_mode(index)?;
                }
                PlrSelAction::LeaveCrew => {
                    self.leave_startup_crew_mode();
                }
                PlrSelAction::CrewParticipationChanged {
                    index,
                    participating,
                } => {
                    self.set_startup_crew_participation(index, participating)?;
                    self.abort_startup_crew_rename();
                }
                PlrSelAction::DeleteCrew(index) => {
                    self.abort_startup_crew_rename();
                    self.open_startup_crew_delete_dialog(index)?;
                }
                PlrSelAction::RenameCrew(index) => {
                    self.abort_startup_crew_rename();
                    self.start_startup_crew_rename(index)?;
                }
                PlrSelAction::SetCrewDeathMessage(index) => {
                    self.open_startup_crew_death_message_dialog(index)?;
                }
            }
        }
        Ok(())
    }

    fn open_startup_player_delete_dialog(&mut self, index: usize) -> Result<(), EngineError> {
        let delete = self
            .startup_player_files
            .get(index)
            .zip(self.startup_player_models.get(index))
            .map(|(player_file, player)| {
                (
                    player_file.path.clone(),
                    clonk_frontend::startup_plrsel::player_delete_warning(player),
                )
            });
        let Some((path, warning)) = delete else {
            tracing::error!(index, "player-delete action references a stale row");
            return Ok(());
        };
        self.push_message_dialog(
            clonk_frontend::message_dialog::MessageDialogState::new(
                warning,
                "Delete",
                clonk_frontend::message_dialog::MessageDialogButtons::YES_NO,
                clonk_frontend::message_dialog::MessageDialogIcon::CONFIRM,
                clonk_frontend::message_dialog::MessageDialogSize::Regular,
                false,
            ),
            MessageDialogContinuation::DeleteStartupPlayer { path },
        )
    }

    fn enter_startup_crew_mode(&mut self, player_index: usize) -> Result<(), EngineError> {
        self.abort_startup_crew_rename();
        let Some(player) = self.startup_player_files.get(player_index) else {
            tracing::error!(player_index, "crew action references a stale player row");
            return Ok(());
        };
        let player_name = player.render_model.name.clone();
        let mut crew = match discover_crew_files(player) {
            Ok(crew) => crew,
            Err(error) => {
                tracing::error!(%error, path = %player.path.display(), "failed to open startup crew");
                return Ok(());
            }
        };
        self.hydrate_startup_crew_models(&mut crew);
        if crew.is_empty() {
            self.push_message_dialog(
                clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                    format!("{player_name} does not have a crew yet!"),
                    format!("Crew: {player_name}"),
                    clonk_frontend::message_dialog::MessageDialogIcon::PLAYER,
                ),
                MessageDialogContinuation::None,
            )?;
            return Ok(());
        }

        let participations = crew
            .iter()
            .map(|entry| entry.render_model.participating)
            .collect();
        let entered = self
            .startup_player_dialog
            .as_mut()
            .is_some_and(|dialog| {
                dialog.enter_crew_mode(player_index, player_name, participations)
            });
        if !entered {
            tracing::error!(player_index, "startup crew mode transition was rejected");
            return Ok(());
        }
        // UpdatePlayerList replaces the row controls on this same dialog.
        self.startup_tooltip.pointer_left();
        self.menu_frame_cache = None;
        self.startup_crew_models = crew
            .iter()
            .map(|entry| entry.render_model.clone())
            .collect();
        self.startup_crew_files = crew;
        self.startup_crew_player_index = Some(player_index);
        self.plrsel_last_click = None;
        self.status_text.clear();
        self.play_ui_sound("DoorOpen");
        self.mark_menu_dirty();
        Ok(())
    }

    fn leave_startup_crew_mode(&mut self) {
        self.abort_startup_crew_rename();
        self.close_context_menu_silently();
        if self
            .startup_player_dialog
            .as_mut()
            .and_then(|dialog| dialog.leave_crew_mode())
            .is_none()
        {
            return;
        }
        self.startup_tooltip.pointer_left();
        self.menu_frame_cache = None;
        self.startup_crew_files.clear();
        self.startup_crew_models.clear();
        self.startup_crew_player_index = None;
        self.plrsel_last_click = None;
        self.play_ui_sound("DoorClose");
        self.mark_menu_dirty();
    }

    fn reload_startup_crew_list(&mut self, select_file: Option<&str>) -> io::Result<()> {
        let player_index = self.startup_crew_player_index.ok_or_else(|| {
            io::Error::new(io::ErrorKind::NotFound, "startup crew player is unavailable")
        })?;
        let player = self.startup_player_files.get(player_index).ok_or_else(|| {
            io::Error::new(io::ErrorKind::NotFound, "startup crew player row is stale")
        })?;
        let mut crew = discover_crew_files(player)?;
        self.hydrate_startup_crew_models(&mut crew);
        self.startup_tooltip.pointer_left();
        self.menu_frame_cache = None;
        let selected = select_file.and_then(|file_name| {
            crew.iter()
                .position(|entry| entry.file_name.eq_ignore_ascii_case(file_name))
        });
        self.startup_crew_models = crew
            .iter()
            .map(|entry| entry.render_model.clone())
            .collect();
        self.startup_crew_files = crew;
        if let Some(dialog) = self.startup_player_dialog.as_mut() {
            dialog.set_crew_participations(
                self.startup_crew_models
                    .iter()
                    .map(|entry| entry.participating)
                    .collect(),
            );
            dialog.set_selected_index(
                selected.or_else(|| (!self.startup_crew_models.is_empty()).then_some(0)),
            );
        }
        self.plrsel_last_click = None;
        self.mark_menu_dirty();
        Ok(())
    }

    fn show_startup_crew_error(
        &mut self,
        message: impl Into<String>,
        caption: impl Into<String>,
    ) -> Result<(), EngineError> {
        self.push_message_dialog(
            clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                message,
                caption,
                clonk_frontend::message_dialog::MessageDialogIcon::ERROR,
            ),
            MessageDialogContinuation::None,
        )
    }

    fn set_startup_crew_participation(
        &mut self,
        index: usize,
        participating: bool,
    ) -> Result<(), EngineError> {
        let Some((player_path, file_name)) = self
            .startup_crew_files
            .get(index)
            .map(|entry| (entry.player_path.clone(), entry.file_name.clone()))
        else {
            tracing::error!(index, "crew-participation action references a stale row");
            return Ok(());
        };
        match set_crew_participation(
            &player_path,
            &file_name,
            participating,
            self.process_group_maker.as_bytes(),
        ) {
            Ok(()) => {
                if let Some(entry) = self.startup_crew_files.get_mut(index) {
                    entry.crew_info.participation = i32::from(participating);
                    entry.render_model.participating = participating;
                }
                if let Some(model) = self.startup_crew_models.get_mut(index) {
                    model.participating = participating;
                }
            }
            Err(error) => {
                tracing::error!(%error, path = %player_path.display(), %file_name, "failed to rewrite crew participation");
                if let Some(dialog) = self.startup_player_dialog.as_mut() {
                    dialog.set_crew_participations(
                        self.startup_crew_models
                            .iter()
                            .map(|entry| entry.participating)
                            .collect(),
                    );
                    dialog.set_selected_index(Some(index));
                }
                self.show_startup_crew_error("File modification failure.", "")?;
            }
        }
        self.mark_menu_dirty();
        Ok(())
    }

    fn open_startup_crew_delete_dialog(&mut self, index: usize) -> Result<(), EngineError> {
        let delete = self.startup_crew_files.get(index).map(|entry| {
            (
                entry.player_path.clone(),
                entry.file_name.clone(),
                clonk_frontend::startup_plrsel::crew_delete_warning(&entry.render_model),
            )
        });
        let Some((player_path, file_name, warning)) = delete else {
            tracing::error!(index, "crew-delete action references a stale row");
            return Ok(());
        };
        self.push_message_dialog(
            clonk_frontend::message_dialog::MessageDialogState::new(
                warning,
                "Delete",
                clonk_frontend::message_dialog::MessageDialogButtons::YES_NO,
                clonk_frontend::message_dialog::MessageDialogIcon::CONFIRM,
                clonk_frontend::message_dialog::MessageDialogSize::Regular,
                false,
            ),
            MessageDialogContinuation::DeleteStartupCrew {
                player_path,
                file_name,
            },
        )
    }

    fn startup_crew_rename_context_entries(
        &self,
        clipboard_available: bool,
    ) -> Vec<ContextMenuEntry<AppContextMenuCommand>> {
        use clonk_frontend::startup_netdlg::NetDlgEditContextCommand as Command;

        let Some(edit) = self
            .startup_crew_rename
            .as_ref()
            .map(|rename| &rename.edit)
        else {
            return Vec::new();
        };
        let item = |command, label_key, label, tooltip_key, tooltip| {
            ContextMenuEntry::new(self.runtime_resource_text(label_key, label))
                .with_tooltip(self.runtime_resource_text(tooltip_key, tooltip))
                .with_icon(ContextMenuIcon::None)
                .with_action(AppContextMenuCommand::StartupCrewRename(command))
        };
        let has_selection = edit.selection_range().is_some();
        let mut entries = Vec::new();
        if has_selection {
            entries.push(item(
                Command::Cut,
                "IDS_DLG_CUT",
                "Cut",
                "IDS_DLGTIP_CUT",
                "Moves the selection to the clipboard.",
            ));
            entries.push(item(
                Command::Copy,
                "IDS_DLG_COPY",
                "Copy",
                "IDS_DLGTIP_COPY",
                "Copies the selection to the clipboard.",
            ));
        }
        if clipboard_available {
            entries.push(item(
                Command::Paste,
                "IDS_DLG_PASTE",
                "Paste",
                "IDS_DLGTIP_PASTE",
                "Inserts the contents of the clipboard.",
            ));
        }
        if has_selection {
            entries.push(item(
                Command::Clear,
                "IDS_DLG_CLEAR",
                "Clear",
                "IDS_DLGTIP_CLEAR",
                "Clears the selection.",
            ));
        }
        let whole_text_selected = edit
            .selection_range()
            .is_some_and(|range| range.start == 0 && range.end == edit.text().len());
        if !edit.text().is_empty() && !whole_text_selected {
            entries.push(item(
                Command::SelectAll,
                "IDS_DLG_SELALL",
                "Select all",
                "IDS_DLGTIP_SELALL",
                "Selects the complete text",
            ));
        }
        entries
    }

    fn open_startup_crew_rename_context_menu(
        &mut self,
        anchor: GuiPoint,
    ) -> Result<bool, EngineError> {
        if self.startup_crew_rename.is_none() {
            return Ok(false);
        }
        let entries =
            self.startup_crew_rename_context_entries(clipboard_text_available());
        self.open_context_menu_at(entries, anchor)
    }

    fn execute_startup_crew_rename_context_command(
        &mut self,
        command: clonk_frontend::startup_netdlg::NetDlgEditContextCommand,
    ) {
        use clonk_frontend::startup_netdlg::NetDlgEditContextCommand as Command;

        let Some(rename) = self.startup_crew_rename.as_mut() else {
            tracing::error!(?command, "stale startup crew rename context command");
            return;
        };
        match command {
            Command::Cut | Command::Copy => {
                let cut = command == Command::Cut;
                if let Err(error) =
                    transfer_edit_selection(&mut rename.edit, cut, |selected| {
                        arboard::Clipboard::new()
                            .and_then(|mut clipboard| clipboard.set_text(selected.to_string()))
                    })
                {
                    tracing::warn!(%error, "failed to copy startup crew rename text");
                }
            }
            Command::Paste => {
                match arboard::Clipboard::new().and_then(|mut clipboard| clipboard.get_text()) {
                    Ok(text) => {
                        rename.edit.insert_text(&text);
                    }
                    Err(error) => {
                        tracing::warn!(%error, "failed to paste startup crew rename text");
                    }
                }
            }
            Command::Clear => {
                rename.edit.delete_selection();
            }
            Command::SelectAll => rename.edit.select_all(),
        }
        self.mark_menu_dirty();
    }

    fn start_startup_crew_rename(&mut self, index: usize) -> Result<(), EngineError> {
        if self.startup_crew_rename.is_some() {
            return Ok(());
        }
        let Some((initial_text, player_path, file_name)) = self
            .startup_crew_models
            .get(index)
            .zip(self.startup_crew_files.get(index))
            .map(|(model, file)| {
                (
                    model.name.clone(),
                    file.player_path.clone(),
                    file.file_name.clone(),
                )
            })
        else {
            tracing::error!(index, "crew-rename action references a stale row");
            return Ok(());
        };
        let Some(previous_focus) = self
            .startup_player_dialog
            .as_ref()
            .filter(|dialog| dialog.is_crew_mode())
            .map(|dialog| dialog.focused_control())
        else {
            tracing::error!(index, "crew-rename action received outside crew mode");
            return Ok(());
        };
        self.close_context_menu_silently();
        self.startup_tooltip.pointer_left();
        self.startup_crew_rename = Some(StartupCrewRenameState {
            index,
            player_path,
            file_name,
            edit: RenameEdit::new(initial_text, Some(previous_focus)),
            last_click: None,
            ignore_pointer_up: false,
        });
        self.mark_menu_dirty();
        Ok(())
    }

    fn restore_startup_crew_focus(&mut self, focus: Option<PlrSelControl>) {
        if let (Some(dialog), Some(focus)) = (self.startup_player_dialog.as_mut(), focus) {
            if dialog.is_crew_mode() {
                dialog.restore_focus(focus);
            }
        }
    }

    fn abort_startup_crew_rename(&mut self) -> bool {
        let Some(mut rename) = self.startup_crew_rename.take() else {
            return false;
        };
        rename.edit.abort();
        let previous_focus = rename.edit.take_previous_focus();
        self.restore_startup_crew_focus(previous_focus);
        self.mark_menu_dirty();
        true
    }

    fn resolve_startup_crew_rename(&mut self, result: RenameEditResult) -> bool {
        let Some(rename) = self.startup_crew_rename.as_mut() else {
            return false;
        };
        if rename.edit.resolve(result) == RenameEditResolution::KeepEditing {
            return false;
        }
        let mut rename = self
            .startup_crew_rename
            .take()
            .expect("finished crew rename state remains installed");
        let previous_focus = rename.edit.take_previous_focus();
        self.restore_startup_crew_focus(previous_focus);
        true
    }

    fn commit_startup_crew_rename(&mut self, focus_lost: bool) -> Result<bool, EngineError> {
        let Some((index, player_path, old_file_name, original_name, action)) = self
            .startup_crew_rename
            .as_mut()
            .map(|rename| {
                (
                    rename.index,
                    rename.player_path.clone(),
                    rename.file_name.clone(),
                    rename.edit.label_text().to_string(),
                    if focus_lost {
                        rename.edit.focus_lost()
                    } else {
                        rename.edit.finish_input()
                    },
                )
            })
        else {
            return Ok(false);
        };
        let RenameEditAction::Submit(new_name) = action else {
            self.abort_startup_crew_rename();
            return Ok(true);
        };
        if new_name == original_name {
            self.resolve_startup_crew_rename(RenameEditResult::Accepted);
            self.mark_menu_dirty();
            return Ok(true);
        }

        let new_file_name = crew_file_name_for_title(&new_name);
        match rename_crew(
            &player_path,
            &old_file_name,
            &new_name,
            self.process_group_maker.as_bytes(),
        ) {
            Ok(persisted_file_name) => {
                self.resolve_startup_crew_rename(RenameEditResult::Accepted);
                let reload_error = self
                    .reload_startup_crew_list(Some(persisted_file_name.as_str()))
                    .err();
                self.reconcile_startup_crew_rename_model(
                    index,
                    &player_path,
                    &old_file_name,
                    &persisted_file_name,
                    &new_name,
                    reload_error.is_some(),
                );
                if let Some(error) = reload_error {
                    tracing::error!(%error, "failed to reload renamed startup crew");
                    let message = self.runtime_resource_text(
                        "IDS_FAIL_MODIFY",
                        "File modification failure.",
                    );
                    self.show_startup_crew_error(message, "")?;
                }
                self.mark_menu_dirty();
                Ok(true)
            }
            Err(StartupCrewMutationError::NameCollision { file_name }) => {
                self.resolve_startup_crew_rename(RenameEditResult::Invalid);
                let template = self.runtime_resource_text(
                    "IDS_ERR_CLONKCOLLISION",
                    "A Clonk with the file name \"%s\" exists already.",
                );
                let caption =
                    self.runtime_resource_text("IDS_FAIL_RENAME", "Rename failure.");
                self.show_startup_crew_error(
                    format_resource_string(template, &[&file_name]),
                    caption,
                )?;
                self.mark_menu_dirty();
                Ok(false)
            }
            Err(StartupCrewMutationError::RenameAcceptedCoreRewriteFailed {
                file_name,
                source,
            }) => {
                tracing::error!(
                    error = %source,
                    path = %player_path.display(),
                    %old_file_name,
                    persisted_file_name = %file_name,
                    "startup crew filename changed but its core rewrite failed"
                );
                self.accept_startup_crew_rename_after_rewrite_failure(
                    index,
                    &player_path,
                    &old_file_name,
                    &file_name,
                    &new_name,
                )?;
                Ok(true)
            }
            Err(error) => {
                tracing::error!(%error, path = %player_path.display(), %old_file_name, %new_file_name, "failed to rename startup crew");
                self.resolve_startup_crew_rename(RenameEditResult::Invalid);
                let template = self.runtime_resource_text(
                    "IDS_ERR_RENAMEFILE",
                    "Error renaming file \"%s\" to \"%s\".",
                );
                let caption =
                    self.runtime_resource_text("IDS_FAIL_RENAME", "Rename failure.");
                self.show_startup_crew_error(
                    format_resource_string(template, &[&old_file_name, &new_file_name]),
                    caption,
                )?;
                self.mark_menu_dirty();
                Ok(false)
            }
        }
    }

    fn accept_startup_crew_rename_after_rewrite_failure(
        &mut self,
        original_index: usize,
        player_path: &Path,
        old_file_name: &str,
        persisted_file_name: &str,
        new_name: &str,
    ) -> Result<(), EngineError> {
        self.resolve_startup_crew_rename(RenameEditResult::Accepted);
        let reload_error = self
            .reload_startup_crew_list(Some(persisted_file_name))
            .err();
        if let Some(error) = reload_error.as_ref() {
            tracing::error!(%error, "failed to reload startup crew after partial rename");
        }
        self.reconcile_startup_crew_rename_model(
            original_index,
            player_path,
            old_file_name,
            persisted_file_name,
            new_name,
            reload_error.is_some(),
        );

        let message = self.runtime_resource_text("IDS_FAIL_MODIFY", "File modification failure.");
        self.show_startup_crew_error(message, "")?;
        self.mark_menu_dirty();
        Ok(())
    }

    fn reconcile_startup_crew_rename_model(
        &mut self,
        original_index: usize,
        player_path: &Path,
        old_file_name: &str,
        persisted_file_name: &str,
        new_name: &str,
        allow_index_fallback: bool,
    ) {
        let row = self
            .startup_crew_files
            .iter()
            .position(|entry| {
                entry.player_path == player_path
                    && entry
                        .file_name
                        .eq_ignore_ascii_case(persisted_file_name)
            })
            .or_else(|| {
                self.startup_crew_files.iter().position(|entry| {
                    entry.player_path == player_path
                        && entry.file_name.eq_ignore_ascii_case(old_file_name)
                })
            })
            .or_else(|| {
                (allow_index_fallback && original_index < self.startup_crew_files.len())
                    .then_some(original_index)
            });

        if let Some(index) = row {
            let mut core_name = clonk_script::c4_string_bytes(new_name);
            if let Some(nul) = core_name.iter().position(|byte| *byte == 0) {
                core_name.truncate(nul);
            }
            core_name.truncate(30);
            if let Some(entry) = self.startup_crew_files.get_mut(index) {
                entry.file_name = persisted_file_name.to_string();
                entry.crew_info.name = clonk_script::c4_string_from_bytes(&core_name);
                entry.render_model.name = new_name.to_string();
            }
            if let Some(model) = self.startup_crew_models.get_mut(index) {
                model.name = new_name.to_string();
            }
            if let Some(dialog) = self.startup_player_dialog.as_mut() {
                dialog.set_selected_index(Some(index));
            }
        } else {
            tracing::error!(
                path = %player_path.display(),
                %old_file_name,
                %persisted_file_name,
                "renamed startup crew row could not be reconciled"
            );
        }
    }

    fn open_startup_crew_death_message_dialog(
        &mut self,
        index: usize,
    ) -> Result<(), EngineError> {
        let Some(initial_text) = self.startup_crew_files.get(index).map(|entry| {
            clonk_resources::decode_legacy_script_text(&clonk_script::c4_string_bytes(
                &entry.crew_info.death_message,
            ))
        }) else {
            tracing::error!(index, "crew death-message action references a stale row");
            return Ok(());
        };
        self.guard_classic_global_gui_bootstrap()?;
        Self::guard_gui_overlay_result(
            "Crew death-message input",
            self.assets.input_dialog_resources().map(|_| ()),
        )?;
        self.close_context_menu_silently();
        let controller = InputDialogController::new(
            "Enter new death message:",
            "Set death message",
            InputDialogIcon::COMMENT,
        )
        .with_max_text(75)
        .with_input_text(&initial_text);
        self.startup_tooltip.pointer_left();
        self.game_option_input_dialog = Some(PendingGameOptionInputDialog {
            purpose: PendingInputDialogPurpose::StartupCrew(
                PendingCrewInputAction::SetDeathMessage { index },
            ),
            controller,
        });
        self.game_option_input_consumed_keys.clear();
        self.game_option_input_pointer_capture = None;
        self.game_option_input_pointer_position = None;
        self.game_option_input_last_click = None;
        self.mark_menu_dirty();
        Ok(())
    }

    fn complete_startup_crew_input(
        &mut self,
        action: PendingCrewInputAction,
        text: String,
    ) -> Result<(), EngineError> {
        match action {
            PendingCrewInputAction::SetDeathMessage { index } => {
                let Some((player_path, file_name)) = self
                    .startup_crew_files
                    .get(index)
                    .map(|entry| (entry.player_path.clone(), entry.file_name.clone()))
                else {
                    tracing::error!(index, "accepted crew death message references a stale row");
                    return Ok(());
                };
                let result = set_crew_death_message(
                    &player_path,
                    &file_name,
                    &text,
                    self.process_group_maker.as_bytes(),
                );
                if result.is_ok() {
                    if let Err(error) = self.reload_startup_crew_list(Some(&file_name)) {
                        tracing::error!(%error, "failed to reload startup crew death message");
                    }
                }
                // Native feedback is unconditional after RewriteCore.
                self.play_ui_sound("Connect");
                if let Err(error) = result {
                    tracing::error!(%error, path = %player_path.display(), %file_name, "failed to rewrite crew death message");
                    self.show_startup_crew_error("File modification failure.", "")?;
                }
            }
        }
        self.mark_menu_dirty();
        Ok(())
    }

    fn hydrate_startup_crew_models(&self, crew: &mut [StartupCrewFile]) {
        let rank_names = self.default_rank_names.as_deref().unwrap_or_default();
        let rank_sheet = self.assets.hud_graphics.rank.as_ref();
        for entry in crew {
            let next_rank = entry.crew_info.core.next_rank_info(
                entry.crew_info.rank,
                rank_names,
                1_000,
            );
            entry.render_model.next_rank = (next_rank.promotion_possible())
                .then(|| {
                    next_rank.name.map(|name| {
                        clonk_frontend::startup_plrsel::PlrSelCrewPromotion {
                            rank_name: clonk_resources::decode_legacy_script_text(
                                &clonk_script::c4_string_bytes(name),
                            ),
                            experience: next_rank.experience,
                        }
                    })
                })
                .flatten();
            entry.render_model.birthday = format_startup_crew_birthday(entry.crew_info.birthday);
            if entry.render_model.rank_icon.is_none() {
                entry.render_model.rank_icon = rank_sheet
                    .and_then(|sheet| startup_rank_icon(sheet, entry.crew_info.rank));
            }
        }
    }

    fn sync_options_gamepad_device(&mut self) {
        use clonk_frontend::startup_options_controls::ControlDevice;
        use clonk_frontend::startup_options_dlg::OptionsSheet;

        let selected = self.startup_options_dialog.as_ref().and_then(|dialog| {
            (self.mode == AppMode::Menu
                && self.startup_view == StartupView::Options
                && dialog.active_sheet() == OptionsSheet::Gamepad)
                .then(|| dialog.controls().selected_set(ControlDevice::Gamepad))
        });
        self.gamepads
            .set_options_open_slot(selected.and_then(GamepadSlot::from_index));
    }

    fn process_options_dialog_actions(
        &mut self,
        actions: Vec<clonk_frontend::startup_options_dlg::OptionsDlgAction>,
    ) -> Result<(), EngineError> {
        use clonk_frontend::startup_options_dlg::{
            OptionsDlgAction, OptionsSheet, SoundCheckboxId, SoundSheetAction, SoundVolumeId,
        };
        use clonk_frontend::startup_options_graphics::GraphicsSheetAction;
        use clonk_frontend::startup_options_network::{NetworkCheckboxId, NetworkValidationError};

        for action in actions {
            match action {
                OptionsDlgAction::Back => {
                    let validation = self
                        .startup_options_dialog
                        .as_ref()
                        .map(|dialog| dialog.network().validate_ports())
                        .unwrap_or(Ok(()));
                    match validation {
                        Ok(()) => self.close_options_menu()?,
                        Err(NetworkValidationError::TcpReferenceConflict) => {
                            let message = self.runtime_resource_text(
                                "IDS_NET_ERR_PORT_TCPREF",
                                "TCP port and reference port must be set to different values between 1 and 65535!",
                            );
                            self.show_options_network_validation_error(&message)?;
                        }
                        Err(NetworkValidationError::UdpDiscoveryConflict) => {
                            let message = self.runtime_resource_text(
                                "IDS_NET_ERR_PORT_UDPDISC",
                                "UDP port and discovery port must be set to different values between 1 and 65535!",
                            );
                            self.show_options_network_validation_error(&message)?;
                        }
                    }
                }
                OptionsDlgAction::SheetChanged(sheet) => {
                    self.sync_options_gamepad_device();
                    if sheet == OptionsSheet::Sound && self.audio.is_none() {
                        return Err(classic_parity_engine_error(report_classic_parity_boundary(
                            ClassicParityBoundary::RuntimeAudioSystem {
                                action: "the startup Options Sound sheet",
                            },
                        )));
                    }
                    self.play_ui_sound("Command");
                }
                OptionsDlgAction::ShowLogTimestampsChanged(enabled) => {
                    self.show_log_timestamps = enabled;
                    self.play_ui_sound("ArrowHit");
                }
                OptionsDlgAction::OpenLanguageCombo => {
                    self.open_options_language_combo()?;
                }
                OptionsDlgAction::OpenFontFaceCombo => {
                    self.open_options_font_face_combo()?;
                }
                OptionsDlgAction::OpenFontSizeCombo => {
                    self.open_options_font_size_combo()?;
                }
                OptionsDlgAction::WhiteChatIngameChanged(enabled) => {
                    self.display_flags.white_chat = enabled;
                    self.play_ui_sound("ArrowHit");
                }
                OptionsDlgAction::WhiteChatLobbyChanged(enabled) => {
                    self.white_lobby_chat = enabled;
                    self.play_ui_sound("ArrowHit");
                }
                OptionsDlgAction::PreloadingChanged(_) => {
                    self.play_ui_sound("ArrowHit");
                }
                OptionsDlgAction::ProgramGuiSound(sound) => {
                    self.play_options_sound(sound);
                }
                OptionsDlgAction::FairCrewStrengthChanged(_) => {}
                OptionsDlgAction::ResetConfiguration => {
                    self.play_ui_sound("Command");
                    self.show_options_reset_configuration()?;
                }
                OptionsDlgAction::OpenAdvancedSettings => {
                    self.play_ui_sound("Command");
                    self.show_options_advanced_warning()?;
                }
                OptionsDlgAction::Sound(action) => match action {
                    SoundSheetAction::GuiSound(sound) => self.play_options_sound(sound),
                    SoundSheetAction::TestSound(sound) => self.play_options_test_sound(sound),
                    SoundSheetAction::CheckboxChanged { id, checked } => match id {
                        SoundCheckboxId::FrontendMusic => {
                            self.set_frontend_music_option(checked)?;
                        }
                        SoundCheckboxId::FrontendSoundEffects => {
                            self.set_frontend_sound_option(checked)?;
                        }
                        SoundCheckboxId::GameMusic => {
                            self.set_startup_game_music_option(checked)?;
                        }
                        SoundCheckboxId::GameSoundEffects => {
                            self.set_startup_game_sound_option(checked)?;
                        }
                    },
                    SoundSheetAction::VolumeChanged { id, value } => match id {
                        SoundVolumeId::Music => {
                            self.set_startup_music_volume(i32::from(value))?;
                        }
                        SoundVolumeId::SoundEffects => {
                            self.set_startup_sound_volume(i32::from(value))?;
                        }
                    },
                },
                OptionsDlgAction::Graphics(action) => match action {
                    GraphicsSheetAction::OpenDisplayModeCombo => {
                        self.open_options_display_mode_combo()?;
                    }
                    GraphicsSheetAction::DisplayModeChanged(mode) => {
                        self.queue_options_display_request(OptionsDisplayRequest::SetMode(mode));
                    }
                    GraphicsSheetAction::CheckboxChanged { .. }
                    | GraphicsSheetAction::ScaleProposalChanged(_) => {
                        self.play_ui_sound("ArrowHit");
                    }
                    GraphicsSheetAction::SmokeLevelChanged(value) => {
                        self.graphics_smoke_level = value;
                        self.engine.set_smoke_level(value);
                        self.play_ui_sound("ArrowHit");
                    }
                    GraphicsSheetAction::TestScale {
                        old_percent,
                        new_percent,
                    } => {
                        self.begin_options_scale_test(old_percent, new_percent)?;
                    }
                },
                OptionsDlgAction::OpenGraphicsScaleText => {
                    self.open_options_graphics_scale_input()?;
                }
                OptionsDlgAction::BeginControlCapture(target) => {
                    self.open_options_control_capture(target)?;
                }
                OptionsDlgAction::ResetControlBindings(device) => {
                    self.reset_options_control_bindings(device);
                    self.play_ui_sound("Command");
                }
                OptionsDlgAction::GamepadDeviceSelected(set) => {
                    let valid_selection = self.mode == AppMode::Menu
                        && self.startup_view == StartupView::Options
                        && self.startup_options_dialog.as_ref().is_some_and(|dialog| {
                            dialog.active_sheet() == OptionsSheet::Gamepad
                                && dialog.controls().selected_set(
                                    clonk_frontend::startup_options_controls::ControlDevice::Gamepad,
                                ) == set
                                && set < dialog.controls().visible_sets(
                                    clonk_frontend::startup_options_controls::ControlDevice::Gamepad,
                                )
                        });
                    if valid_selection {
                        self.gamepads
                            .set_options_open_slot(GamepadSlot::from_index(set));
                    }
                }
                OptionsDlgAction::GamepadGuiControlChanged(enabled) => {
                    self.gamepad_gui_control = enabled;
                    self.play_ui_sound("ArrowHit");
                    self.begin_startup_dialog_fade(StartupDialog::Options);
                }
                OptionsDlgAction::OpenNetworkText(field) => {
                    self.open_options_network_input(field)?;
                }
                OptionsDlgAction::NetworkPortEnabledChanged { .. } => {
                    self.play_ui_sound("ArrowHit");
                }
                OptionsDlgAction::NetworkCheckboxChanged { id, checked } => {
                    self.play_ui_sound("ArrowHit");
                    if id == NetworkCheckboxId::UseAlternateServer && checked {
                        let hidden = self
                            .startup_options_dialog
                            .as_ref()
                            .is_some_and(|dialog| dialog.network().hide_no_official_league_notice);
                        if !hidden {
                            self.show_options_alternate_server_notice()?;
                        }
                    }
                }
            }
        }
        Ok(())
    }

    fn play_options_sound(&mut self, sound: clonk_frontend::startup_options_dlg::SoundSheetSound) {
        self.play_ui_sound(match sound {
            clonk_frontend::startup_options_dlg::SoundSheetSound::ArrowHit => "ArrowHit",
            clonk_frontend::startup_options_dlg::SoundSheetSound::Command => "Command",
        });
    }

    fn play_options_test_sound(
        &mut self,
        sound: clonk_frontend::startup_options_dlg::SoundSheetSound,
    ) {
        self.play_global_sound_effect(match sound {
            clonk_frontend::startup_options_dlg::SoundSheetSound::ArrowHit => "ArrowHit",
            clonk_frontend::startup_options_dlg::SoundSheetSound::Command => "Command",
        });
    }

    fn apply_options_font_selection(
        &mut self,
        selected_face: Option<String>,
        selected_size: Option<i32>,
    ) -> Result<(), EngineError> {
        self.apply_options_font_selection_with_system_fonts(
            selected_face,
            selected_size,
            system_fonts::installed_system_fonts(),
        )
    }

    fn apply_options_font_selection_with_system_fonts(
        &mut self,
        selected_face: Option<String>,
        selected_size: Option<i32>,
        system_fonts: &dyn system_fonts::SystemFontProvider,
    ) -> Result<(), EngineError> {
        let Some((current_face, current_size)) =
            self.startup_options_dialog.as_ref().map(|dialog| {
                (
                    dialog.program().font_face.clone(),
                    dialog
                        .program()
                        .font_size
                        .trim()
                        .parse::<i32>()
                        .unwrap_or(14),
                )
            })
        else {
            return Ok(());
        };
        let face = selected_face.unwrap_or_else(|| current_face.clone());
        let size = selected_size.unwrap_or(current_size);
        let Some(paths) = self.app_paths.as_ref() else {
            return self.show_options_font_error();
        };
        let resources = (|| -> Result<_> {
            let registrations = startup_loader_registrations(paths)?;
            let gui = resolve_classic_font_bundle_for_request_with_system_fonts(
                paths,
                &face,
                size,
                &registrations,
                &registrations,
                system_fonts,
            )?;
            let startup = resolve_classic_startup_font_bundle_for_request_with_system_fonts(
                paths,
                &face,
                size,
                &registrations,
                &registrations,
                system_fonts,
            )?;
            Ok((gui, startup))
        })();
        let (gui, startup) = match resources {
            Ok(resources) => resources,
            Err(error) => {
                tracing::warn!(%error, %face, size, "failed to apply selected options font");
                return self.show_options_font_error();
            }
        };

        if let Some(dialog) = self.startup_options_dialog.as_mut() {
            dialog.program_mut().set_font(face.clone(), size);
        }
        match self.persist_open_options_config() {
            Some(Ok(())) => {}
            Some(Err(error)) => {
                tracing::warn!(%error, "failed to save selected options font");
                if let Some(dialog) = self.startup_options_dialog.as_mut() {
                    dialog.program_mut().set_font(current_face, current_size);
                }
                return self.show_options_font_error();
            }
            None => {
                if let Some(dialog) = self.startup_options_dialog.as_mut() {
                    dialog.program_mut().set_font(current_face, current_size);
                }
                return self.show_options_font_error();
            }
        }

        self.begin_startup_dialog_fade(StartupDialog::Options);
        let ClassicFontBundle {
            fonts,
            tooltip,
            native_source,
        } = gui;
        let native_fonts = self.native_font_cache_for_source(native_source.as_ref());
        let player_selection_fonts = startup.player_selection.clone();
        {
            let assets = Arc::make_mut(&mut self.assets);
            assets.clonk_fonts = Some(fonts.clone());
            assets.startup_clonk_fonts = Some(fonts.clone());
            assets.global_tooltip_font = Some(tooltip.clone());
            assets.startup_global_tooltip_font = Some(tooltip);
            assets.startup_native_font_source = native_source;
            assets.book_fonts = Some(startup.book);
            assets.options_book_fonts = Some(startup.options);
            assets.plrsel_book_fonts = Some(startup.player_selection);
        }
        if let Some(dialog) = self.startup_player_dialog.as_mut() {
            dialog.set_layout_fonts(fonts.as_ref(), player_selection_fonts.as_ref());
        }
        self.graphics.set_clonk_fonts(Some(fonts.clone()));
        self.main_menu_state.menu.set_clonk_fonts(Some(fonts));
        self.native_startup_fonts = native_fonts;
        self.open_options_menu();
        self.mark_menu_dirty();
        Ok(())
    }

    fn show_options_font_error(&mut self) -> Result<(), EngineError> {
        let message = self.runtime_resource_text("IDS_ERR_INITFONTS", "Error initializing fonts");
        let caption = self.runtime_resource_text("IDS_DLG_ERROR", "Error");
        self.push_message_dialog(
            clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                message,
                caption,
                clonk_frontend::message_dialog::MessageDialogIcon::ERROR,
            ),
            MessageDialogContinuation::None,
        )
    }

    fn show_options_reset_configuration(&mut self) -> Result<(), EngineError> {
        let prompt = self.runtime_resource_text(
            "IDS_MSG_PROMPTRESETCONFIG",
            "Are you sure you want to reset all configuration values?",
        );
        let restart = self.runtime_resource_text(
            "IDS_MSG_RESTARTCHANGECFG",
            "For changes to take effect the program has to be restarted.",
        );
        let caption = self.runtime_resource_text("IDS_BTN_RESETCONFIG", "Reset configuration");
        self.push_message_dialog(
            clonk_frontend::message_dialog::MessageDialogState::new(
                format!("{prompt}|{restart}"),
                caption,
                clonk_frontend::message_dialog::MessageDialogButtons::YES_NO,
                clonk_frontend::message_dialog::MessageDialogIcon::NOTIFY,
                clonk_frontend::message_dialog::MessageDialogSize::Regular,
                false,
            ),
            MessageDialogContinuation::OptionsResetConfiguration,
        )
    }

    fn show_options_advanced_warning(&mut self) -> Result<(), EngineError> {
        let message = self.runtime_resource_text(
            "IDS_MSG_ADVANCED_SETTINGS_WARNING",
            "Some settings only apply after a restart.|Modifications may cause Clonk to stop working correctly. Proceed at your own risk!",
        );
        let caption = self.runtime_resource_text("IDS_DLG_WARNING", "Warning");
        self.push_message_dialog(
            clonk_frontend::message_dialog::MessageDialogState::new(
                message,
                caption,
                clonk_frontend::message_dialog::MessageDialogButtons::OK_CANCEL,
                clonk_frontend::message_dialog::MessageDialogIcon::None,
                clonk_frontend::message_dialog::MessageDialogSize::Regular,
                true,
            ),
            MessageDialogContinuation::OptionsAdvancedWarning,
        )
    }

    fn show_options_advanced_error(
        &mut self,
        detail: impl std::fmt::Display,
    ) -> Result<(), EngineError> {
        let caption = self.runtime_resource_text("IDS_DLG_ERROR", "Error");
        self.push_message_dialog(
            clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                format!("Unable to access advanced settings: {detail}"),
                caption,
                clonk_frontend::message_dialog::MessageDialogIcon::ERROR,
            ),
            MessageDialogContinuation::None,
        )
    }

    fn open_options_advanced_dialog(&mut self) -> Result<(), EngineError> {
        let Some(config_path) = self
            .app_paths
            .as_ref()
            .map(|paths| paths.config_file())
        else {
            self.show_options_advanced_error("application configuration is unavailable")?;
            return Ok(());
        };
        let mut config = match Config::load(&config_path) {
            Ok(config) => config,
            Err(error) if error.kind() == io::ErrorKind::NotFound => Config::new(),
            Err(error) => {
                tracing::warn!(%error, "failed to load advanced configuration");
                self.show_options_advanced_error(error)?;
                return Ok(());
            }
        };
        if self.apply_open_options_config(&mut config).is_none() {
            self.show_options_advanced_error("the Options dialog is unavailable")?;
            return Ok(());
        }
        let return_sheet = self
            .startup_options_dialog
            .as_ref()
            .map(|dialog| dialog.active_sheet())
            .unwrap_or_default();
        let mut controller =
            clonk_frontend::startup_options_advanced::AdvancedConfigController::new(
                advanced_config::sections(&config),
            );
        controller.set_labels(
            clonk_frontend::startup_options_advanced::AdvancedConfigLabels {
                caption: self
                    .runtime_resource_text("IDS_DLG_ADVANCED_SETTINGS", "Advanced settings"),
                save: self.runtime_resource_text("IDS_BTN_SAVE", "&Save"),
                cancel: self.runtime_resource_text("IDS_BTN_CANCEL", "Cancel"),
            },
        );
        controller.resize(
            self.graphics.surface().width() as i32,
            self.graphics.surface().height() as i32,
        );
        self.startup_options_advanced_dialog = Some(PendingOptionsAdvancedDialog {
            controller,
            return_sheet,
        });
        self.mark_menu_dirty();
        Ok(())
    }

    fn save_options_advanced_changes(
        &self,
        changes: &[clonk_frontend::startup_options_advanced::AdvancedConfigChange],
    ) -> io::Result<()> {
        let Some(paths) = self.app_paths.as_ref() else {
            return Err(io::Error::new(
                io::ErrorKind::NotFound,
                "application paths are unavailable",
            ));
        };
        let path = paths.config_file();
        let mut config = match Config::load(&path) {
            Ok(config) => config,
            Err(error) if error.kind() == io::ErrorKind::NotFound => Config::new(),
            Err(error) => return Err(error),
        };
        if self.apply_open_options_config(&mut config).is_none() {
            return Err(io::Error::new(
                io::ErrorKind::NotFound,
                "the Options dialog is unavailable",
            ));
        }
        advanced_config::canonicalize_existing(&mut config);
        advanced_config::apply_changes(&mut config, changes);
        let fair_crew = changes
            .iter()
            .rev()
            .find(|change| change.section == "General" && change.key == "NoCrew")
            .map(|change| parse_config_bool(&change.value));
        let always_debug = changes
            .iter()
            .rev()
            .find(|change| change.section == "General" && change.key == "DebugMode")
            .map(|change| parse_config_bool(&change.value));
        let gamepads_enabled = config
            .get_in(Some("General"), "GamepadEnabled")
            .map(parse_config_bool);
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)?;
        }
        save_config_preserving_native_general_booleans(
            &config,
            &path,
            gamepads_enabled,
            always_debug,
        )?;
        if let Some(enabled) = fair_crew {
            persist_native_config_values(
                paths,
                "General",
                &[(
                    "NoCrew",
                    clonk_app_netplay::NativeConfigValue::RawAscii(if enabled { "true" } else { "false" }),
                )],
            )?;
        }
        Ok(())
    }

    fn synchronize_advanced_options_runtime(&mut self) {
        let paths = self.app_paths.as_ref();
        let is_fullscreen = self.display_flags.is_fullscreen;
        self.display_flags = load_display_flags(paths);
        self.display_flags.is_fullscreen = is_fullscreen;
        self.white_lobby_chat = load_white_lobby_chat(paths);
        self.show_log_timestamps = load_show_log_timestamps(paths);
        self.show_folder_maps = load_show_folder_maps(paths);
        self.ready_check_toasts_enabled = load_ready_check_toasts_enabled(paths);
        let native_config = load_native_config_bytes(paths);
        self.allow_scripting_in_replays = configured_allow_scripting_in_replays(&native_config);
        self.max_refresh_delay_ms = configured_max_refresh_delay_ms(&native_config);
        let record = load_recording_flag(paths);
        self.startup_view_flags.record = record;
        self.recording_enabled = record && self.recordings_dir.is_some();
        self.startup_view_flags.fair_crew = load_fair_crew_flag(paths);
        self.graphics_smoke_level = load_graphics_smoke_level(paths);
        self.engine.set_smoke_level(self.graphics_smoke_level);
        self.mission_access = paths
            .and_then(|paths| match load_configured_mission_access(paths) {
                Ok(access) => Some(MissionAccessStore::new(access)),
                Err(error) => {
                    tracing::warn!(%error, "failed to reload General.MissionAccess");
                    None
                }
            })
            .unwrap_or_default();
        self.engine
            .set_mission_access_store(self.mission_access.clone());
        self.bindings = KeyboardBindings::load(paths);
        self.gamepad_bindings = GamepadBindings::load(paths);
        self.gamepads
            .set_axis_calibrations(self.gamepad_bindings.axis_calibrations());
        self.gamepads_enabled = load_gamepads_enabled(paths);
        self.gamepad_gui_control = load_gamepad_gui_control(paths);
        self.engine
            .set_control_key_names(configured_control_key_names(&self.bindings));

        let reloaded_audio = AudioOptions::load(paths);
        if let Some(audio) = self.audio.as_mut() {
            let music_volume = reloaded_audio.music_volume_percent();
            let sound_volume = reloaded_audio.sound_volume_percent();
            audio.options = reloaded_audio;
            audio.set_music_volume_percent(music_volume);
            audio.set_sound_volume_percent(sound_volume);
        }
        let point_filtering = DisplayOptions::load(paths).point_filtering;
        self.graphics.set_point_filtering(point_filtering);
        let advanced_renderer_config = load_advanced_renderer_config(&native_config);
        self.graphics
            .set_advanced_renderer_config(advanced_renderer_config);
        self.loader_gamma = load_classic_loader_gamma_from_native(&native_config);
        let main_menu_gamma = self.graphics.fragment_gamma_enabled().then(|| {
            Arc::new(
                self.loader_gamma
                    .clone()
                    .unwrap_or_else(clonk_graphics::GammaRamp::standard),
            )
        });
        self.main_menu_state.menu.set_gamma_ramp(main_menu_gamma);
        if let Some(config) = self.loader_render_config {
            self.configure_native_startup_fonts(config.application_scale(), point_filtering);
        }
        self.menu_frame_cache = None;
        self.menu_backdrop_cache = StartupBackdropCache::default();
        self.startup_dialog_fade = None;
        self.mark_menu_dirty();
    }

    fn process_options_advanced_actions(
        &mut self,
        actions: Vec<clonk_frontend::startup_options_advanced::AdvancedConfigAction>,
    ) -> Result<(), EngineError> {
        use clonk_frontend::startup_options_advanced::AdvancedConfigAction;

        let sounds = self
            .startup_options_advanced_dialog
            .as_mut()
            .map(|pending| pending.controller.take_sound_events())
            .unwrap_or_default();
        for sound in sounds {
            use clonk_frontend::startup_options_advanced::AdvancedConfigSound;
            self.play_ui_sound(match sound {
                AdvancedConfigSound::ArrowHit => "ArrowHit",
                AdvancedConfigSound::Click => "Click",
                AdvancedConfigSound::Command => "Command",
            });
        }

        for action in actions {
            match action {
                AdvancedConfigAction::Cancel => {
                    self.startup_tooltip.pointer_left();
                    self.startup_options_advanced_dialog = None;
                }
                AdvancedConfigAction::Save => {
                    let Some((changes, return_sheet)) =
                        self.startup_options_advanced_dialog.as_ref().map(|pending| {
                            (pending.controller.changes(), pending.return_sheet)
                        })
                    else {
                        continue;
                    };
                    let saved = self.save_options_advanced_changes(&changes);
                    match saved {
                        Ok(()) => {
                            self.startup_tooltip.pointer_left();
                            self.startup_options_advanced_dialog = None;
                            self.synchronize_advanced_options_runtime();
                            self.open_options_menu();
                            if let Some(dialog) = self.startup_options_dialog.as_mut() {
                                dialog.restore_sheet(return_sheet);
                            }
                            self.sync_options_gamepad_device();
                        }
                        Err(error) => {
                            tracing::warn!(%error, "failed to save advanced configuration");
                            self.show_options_advanced_error(error)?;
                        }
                    }
                }
            }
        }
        self.mark_menu_dirty();
        Ok(())
    }

    fn show_options_network_validation_error(&mut self, message: &str) -> Result<(), EngineError> {
        let caption = self.runtime_resource_text("IDS_ERR_CONFIG", "Configuration error");
        self.push_message_dialog(
            clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                message,
                caption,
                clonk_frontend::message_dialog::MessageDialogIcon::ERROR,
            ),
            MessageDialogContinuation::None,
        )
    }

    fn begin_options_scale_test(
        &mut self,
        old_percent: i32,
        new_percent: i32,
    ) -> Result<(), EngineError> {
        let dialog = clonk_frontend::message_dialog::MessageDialogState::new(
            "Keep this display scale?|12 seconds remaining.",
            "Test graphics scale",
            clonk_frontend::message_dialog::MessageDialogButtons::YES_NO,
            clonk_frontend::message_dialog::MessageDialogIcon::CONFIRM,
            clonk_frontend::message_dialog::MessageDialogSize::Regular,
            true,
        );
        self.push_message_dialog(
            dialog,
            MessageDialogContinuation::OptionsScaleTest {
                old_percent,
                new_percent,
                remaining_seconds: 12,
            },
        )?;
        self.queue_options_display_request(OptionsDisplayRequest::SetScale {
            percent: new_percent,
            persist: false,
        });
        Ok(())
    }

    fn open_options_control_capture(
        &mut self,
        target: clonk_frontend::startup_options_controls::ControlCaptureTarget,
    ) -> Result<(), EngineError> {
        let control = ControlBindingId::ALL
            .get(target.control)
            .copied()
            .map(binding_display_name)
            .unwrap_or("Unknown control");
        let (message, icon) = match target.device {
            clonk_frontend::startup_options_controls::ControlDevice::Keyboard => (
                format!(
                    "Press the key for \"{control}\" on keyboard block {}.",
                    target.set + 1
                ),
                clonk_frontend::message_dialog::MessageDialogIcon::Standard(24),
            ),
            clonk_frontend::startup_options_controls::ControlDevice::Gamepad => (
                format!(
                    "Press the button for \"{control}\" on gamepad {}.",
                    target.set + 1
                ),
                clonk_frontend::message_dialog::MessageDialogIcon::Standard(25),
            ),
        };
        self.push_message_dialog(
            clonk_frontend::message_dialog::MessageDialogState::new(
                message,
                "Assign key",
                clonk_frontend::message_dialog::MessageDialogButtons::CANCEL,
                icon,
                clonk_frontend::message_dialog::MessageDialogSize::Regular,
                false,
            ),
            MessageDialogContinuation::OptionsControlCapture(target),
        )
    }

    fn reset_options_control_bindings(
        &mut self,
        device: clonk_frontend::startup_options_controls::ControlDevice,
    ) {
        match device {
            clonk_frontend::startup_options_controls::ControlDevice::Keyboard => {
                self.bindings.reset_all();
            }
            clonk_frontend::startup_options_controls::ControlDevice::Gamepad => {
                self.gamepad_bindings.reset_all();
                self.gamepads
                    .set_axis_calibrations(self.gamepad_bindings.axis_calibrations());
            }
        }
        self.refresh_options_control_labels(device);
    }

    fn refresh_options_control_labels(
        &mut self,
        device: clonk_frontend::startup_options_controls::ControlDevice,
    ) {
        use clonk_frontend::startup_options_controls::{
            ControlCaptureTarget, CONTROL_KEY_COUNT, CONTROL_SET_COUNT,
        };
        let Some(dialog) = self.startup_options_dialog.as_mut() else {
            return;
        };
        for set in 0..CONTROL_SET_COUNT {
            for control in 0..CONTROL_KEY_COUNT {
                let Some(id) = ControlBindingId::ALL.get(control).copied() else {
                    continue;
                };
                let label = match device {
                    clonk_frontend::startup_options_controls::ControlDevice::Keyboard => self
                        .bindings
                        .key_for_set(set, id)
                        .map(format_key_label)
                        .unwrap_or_else(|| "Undefined".to_string()),
                    clonk_frontend::startup_options_controls::ControlDevice::Gamepad => {
                        self.gamepad_bindings.key_label_for_set(set, id)
                    }
                };
                dialog.controls_mut().set_label(
                    ControlCaptureTarget {
                        device,
                        set,
                        control,
                    },
                    label,
                );
            }
        }
        self.mark_menu_dirty();
    }

